INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-001', 'apsc-ae-civil', 1, 'Reinforced Concrete Structures', 'Limit State Design — Flexure', 'Limiting Neutral Axis Depth', 'As per IS 456:2000, what is the limiting depth of neutral axis (xu,max / d) for Fe 500 grade steel in limit state design of flexural members?', '[{"id":"A","text":"0.53"},{"id":"B","text":"0.48"},{"id":"C","text":"0.46"},{"id":"D","text":"0.44"}]'::jsonb, '0.53', '0.48', '0.46', '0.44', 'C', 'According to IS 456:2000 Clause 38.1 Note, linear strain compatibility gives xu,max/d = 0.53 for Fe 250, 0.48 for Fe 415, 0.46 for Fe 500, and 0.44 for Fe 550.', 'xu,max / d = 0.0035 / (0.0055 + 0.87 * fy / Es)', NULL, 'IS 456:2000, Clause 38.1', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-002', 'apsc-ae-civil', 2, 'Reinforced Concrete Structures', 'Shear and Bond', 'Development Length', 'The development length (Ld) of a tension reinforcing bar of nominal diameter φ is given by IS 456:2000 as:', '[{"id":"A","text":"Ld = (φ · σs) / (2 · τbd)"},{"id":"B","text":"Ld = (φ · σs) / (4 · τbd)"},{"id":"C","text":"Ld = (φ · σs) / (8 · τbd)"},{"id":"D","text":"Ld = (2 · φ · σs) / (3 · τbd)"}]'::jsonb, 'Ld = (φ · σs) / (2 · τbd)', 'Ld = (φ · σs) / (4 · τbd)', 'Ld = (φ · σs) / (8 · τbd)', 'Ld = (2 · φ · σs) / (3 · τbd)', 'B', 'Per IS 456:2000 Cl. 26.2.1, equating tensile bar force to bond resistance yields Ld = (φ · σs) / (4 · τbd). For deformed bars (HYSD), τbd is increased by 60%. For bars in compression, τbd is increased by 25%.', 'Ld = (φ · σs) / (4 · τbd)', NULL, 'IS 456:2000 Cl. 26.2.1', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-003', 'apsc-ae-civil', 3, 'Reinforced Concrete Structures', 'Beams & Slabs', 'Minimum Tensile Reinforcement', 'As per IS 456:2000, the minimum area of tension reinforcement in a rectangular beam shall not be less than:', '[{"id":"A","text":"As / (b · d) = 0.85 / fy"},{"id":"B","text":"As / (b · d) = 0.40 / fy"},{"id":"C","text":"As / (b · D) = 0.12%"},{"id":"D","text":"As / (b · d) = 0.04 · b · d"}]'::jsonb, 'As / (b · d) = 0.85 / fy', 'As / (b · d) = 0.40 / fy', 'As / (b · D) = 0.12%', 'As / (b · d) = 0.04 · b · d', 'A', 'IS 456:2000 Clause 26.5.1.1 specifies that the minimum area of tension reinforcement in beams is As,min = (0.85 · b · d) / fy, where b is width of beam, d is effective depth, and fy is characteristic steel strength.', 'As,min / (b · d) = 0.85 / fy', NULL, 'IS 456:2000 Cl. 26.5.1.1', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-004', 'apsc-ae-civil', 4, 'Reinforced Concrete Structures', 'Shear Design', 'Critical Section for Shear', 'In a simply supported RCC beam resting on masonry support subjected to uniformly distributed load, the critical section for checking nominal shear stress (τv) is located at a distance of:', '[{"id":"A","text":"d/2 from the face of support"},{"id":"B","text":"d from the face of support"},{"id":"C","text":"At the center of support"},{"id":"D","text":"2d from the face of support"}]'::jsonb, 'd/2 from the face of support', 'd from the face of support', 'At the center of support', '2d from the face of support', 'B', 'According to IS 456:2000 Clause 31.6.2 and 22.6.2, when the reaction introduces compression into the end regions of the member, the critical section for shear is taken at a distance d (effective depth) from the face of the support.', 'Critical section distance = effective depth (d) from support face', NULL, 'IS 456:2000 Cl. 22.6.2 & 31.6.2', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-005', 'apsc-ae-civil', 5, 'Reinforced Concrete Structures', 'Shear Reinforcement', 'Maximum Stirrup Spacing', 'As per IS 456:2000, the maximum spacing of vertical shear stirrups along the axis of the beam shall not exceed:', '[{"id":"A","text":"0.75 d or 300 mm, whichever is less"},{"id":"B","text":"d or 300 mm, whichever is less"},{"id":"C","text":"0.75 d or 450 mm, whichever is less"},{"id":"D","text":"0.50 d or 300 mm, whichever is less"}]'::jsonb, '0.75 d or 300 mm, whichever is less', 'd or 300 mm, whichever is less', '0.75 d or 450 mm, whichever is less', '0.50 d or 300 mm, whichever is less', 'A', 'Clause 26.5.1.5 of IS 456:2000 states that the spacing of stirrups measured along the member axis shall not exceed 0.75 d for vertical stirrups and d for inclined stirrups at 45°, but in no case shall it exceed 300 mm.', 'Spacing Sv ≤ min(0.75 d, 300 mm)', NULL, 'IS 456:2000 Cl. 26.5.1.5', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-006', 'apsc-ae-civil', 6, 'Reinforced Concrete Structures', 'Slab Design', 'Maximum Bar Diameter in Slabs', 'The diameter of reinforcing bars in a slab shall not exceed what fraction of the total thickness of the slab as per IS 456:2000?', '[{"id":"A","text":"One-fourth (1/4) of total thickness"},{"id":"B","text":"One-eighth (1/8) of total thickness"},{"id":"C","text":"One-tenth (1/10) of total thickness"},{"id":"D","text":"One-sixth (1/6) of total thickness"}]'::jsonb, 'One-fourth (1/4) of total thickness', 'One-eighth (1/8) of total thickness', 'One-tenth (1/10) of total thickness', 'One-sixth (1/6) of total thickness', 'B', 'According to IS 456:2000 Clause 26.5.2.2, the diameter of reinforcing bars shall not exceed one-eighth of the total thickness of the slab.', 'φ_bar ≤ D_slab / 8', NULL, 'IS 456:2000 Cl. 26.5.2.2', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-007', 'apsc-ae-civil', 7, 'Reinforced Concrete Structures', 'Durability & Concrete Mix', 'Minimum Grade for Severe Exposure', 'As per IS 456:2000 Table 5, what is the minimum grade of concrete recommended for reinforced concrete (RCC) exposed to ''Severe'' environmental conditions?', '[{"id":"A","text":"M 20"},{"id":"B","text":"M 25"},{"id":"C","text":"M 30"},{"id":"D","text":"M 35"}]'::jsonb, 'M 20', 'M 25', 'M 30', 'M 35', 'C', 'Per IS 456 Table 5, minimum grades for RCC under environmental exposure conditions are: Mild (M20), Moderate (M25), Severe (M30), Very Severe (M35), and Extreme (M40).', 'Severe exposure min grade = M 30', NULL, 'IS 456:2000 Table 5', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-008', 'apsc-ae-civil', 8, 'Reinforced Concrete Structures', 'Limit State Philosophy', 'Partial Safety Factors', 'In the limit state of collapse, the partial safety factors for concrete (γc) and steel (γs) are taken as:', '[{"id":"A","text":"1.15 and 1.50 respectively"},{"id":"B","text":"1.50 and 1.15 respectively"},{"id":"C","text":"1.50 and 1.00 respectively"},{"id":"D","text":"1.20 and 1.15 respectively"}]'::jsonb, '1.15 and 1.50 respectively', '1.50 and 1.15 respectively', '1.50 and 1.00 respectively', '1.20 and 1.15 respectively', 'B', 'Concrete has higher variability in material preparation and compaction on site compared to factory-controlled steel. Hence IS 456 adopts γc = 1.50 and γs = 1.15 in Limit State of Collapse (Clause 36.4.2).', 'γc = 1.50, γs = 1.15 (Collapse)', NULL, 'IS 456:2000 Cl. 36.4.2', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-009', 'apsc-ae-civil', 9, 'Reinforced Concrete Structures', 'Flexural Failure Modes', 'Under-reinforced Beam Characteristics', 'An under-reinforced RCC beam section is preferred in structural design because:', '[{"id":"A","text":"It undergoes sudden, brittle failure without prior warning"},{"id":"B","text":"Steel yields before concrete crushes, giving ample ductile deflection and crack warning"},{"id":"C","text":"It requires maximum amount of steel and minimizes beam depth"},{"id":"D","text":"Neutral axis depth exceeds the limiting neutral axis depth"}]'::jsonb, 'It undergoes sudden, brittle failure without prior warning', 'Steel yields before concrete crushes, giving ample ductile deflection and crack warning', 'It requires maximum amount of steel and minimizes beam depth', 'Neutral axis depth exceeds the limiting neutral axis depth', 'B', 'Under-reinforced sections ensure that the tensile steel reaches its yield point long before concrete reaches its ultimate crushing strain (0.0035). This produces large visible cracks and deflections, ensuring ductile failure and safety.', 'xu < xu,max; εs ≥ 0.87 fy / Es + 0.002 before concrete strain reaches 0.0035', NULL, 'IS 456:2000 Cl. 38.1', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-010', 'apsc-ae-civil', 10, 'Reinforced Concrete Structures', 'Columns', 'Minimum Eccentricity Check', 'As per IS 456:2000, all columns shall be designed for minimum eccentricity emin given by:', '[{"id":"A","text":"emin = L/500 + D/30, subject to a minimum of 20 mm"},{"id":"B","text":"emin = L/300 + D/20, subject to a minimum of 25 mm"},{"id":"C","text":"emin = L/500 + D/50, subject to a minimum of 15 mm"},{"id":"D","text":"emin = L/250 + D/30, subject to a minimum of 20 mm"}]'::jsonb, 'emin = L/500 + D/30, subject to a minimum of 20 mm', 'emin = L/300 + D/20, subject to a minimum of 25 mm', 'emin = L/500 + D/50, subject to a minimum of 15 mm', 'emin = L/250 + D/30, subject to a minimum of 20 mm', 'A', 'IS 456:2000 Clause 25.4 specifies that all columns shall be designed for an unsupported length L and lateral dimension D with minimum eccentricity emin = unsupported length/500 + lateral dimension/30, subject to a minimum of 20 mm.', 'emin = max(L/500 + D/30, 20 mm)', NULL, 'IS 456:2000 Cl. 25.4', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-011', 'apsc-ae-civil', 11, 'Reinforced Concrete Structures', 'Columns', 'Short vs Slender Column Criteria', 'A reinforced concrete column is classified as a ''Short Column'' if the ratio of effective length (Leff) to its least lateral dimension (D or b) is:', '[{"id":"A","text":"Greater than 12"},{"id":"B","text":"Less than 12"},{"id":"C","text":"Between 12 and 18"},{"id":"D","text":"Less than 3"}]'::jsonb, 'Greater than 12', 'Less than 12', 'Between 12 and 18', 'Less than 3', 'B', 'Clause 25.1.2 of IS 456 defines a short column as one where both effective length ratios (Lex / D and Ley / b) are less than 12. If either ratio is 12 or more, it is considered a slender (long) column.', 'Slenderness ratio λ = Leff / b < 12 => Short Column', NULL, 'IS 456:2000 Cl. 25.1.2', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-012', 'apsc-ae-civil', 12, 'Reinforced Concrete Structures', 'Detailing of Reinforcement', 'Nominal Cover for Footing', 'As per IS 456:2000, what is the minimum nominal clear cover required for footing reinforcement cast directly against earth?', '[{"id":"A","text":"25 mm"},{"id":"B","text":"40 mm"},{"id":"C","text":"50 mm"},{"id":"D","text":"75 mm"}]'::jsonb, '25 mm', '40 mm', '50 mm', '75 mm', 'C', 'Clause 26.4.2.2 and Table 16 specify that the minimum nominal cover for footings is 50 mm. When concrete is placed directly against untreated soil without blinding layer, cover is commonly increased to 75 mm.', 'Footing nominal cover = 50 mm', NULL, 'IS 456:2000 Cl. 26.4.2.2', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-013', 'apsc-ae-civil', 13, 'Reinforced Concrete Structures', 'Bond & Anchorage', 'Deformed Bars Bond Stress Increment', 'For deformed bars conforming to IS 1786 (HYSD bars), the design bond stress values given in IS 456:2000 for plain bars in tension shall be increased by:', '[{"id":"A","text":"25%"},{"id":"B","text":"40%"},{"id":"C","text":"50%"},{"id":"D","text":"60%"}]'::jsonb, '25%', '40%', '50%', '60%', 'D', 'IS 456:2000 Clause 26.2.1.1 states: For deformed bars conforming to IS 1786, the design bond stress values for plain bars shall be increased by 60%.', 'τbd(deformed) = 1.60 · τbd(plain)', NULL, 'IS 456:2000 Cl. 26.2.1.1', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-014', 'apsc-ae-civil', 14, 'Prestressed Concrete', 'Prestressing Losses', 'Losses in Pre-tensioned vs Post-tensioned', 'Which of the following losses of prestress does NOT occur in pre-tensioned concrete members?', '[{"id":"A","text":"Elastic shortening of concrete"},{"id":"B","text":"Shrinkage of concrete"},{"id":"C","text":"Friction between tendon and duct"},{"id":"D","text":"Creep of concrete"}]'::jsonb, 'Elastic shortening of concrete', 'Shrinkage of concrete', 'Friction between tendon and duct', 'Creep of concrete', 'C', 'In pre-tensioning, tendons are stressed before concrete is poured and there are no ducts or curved profiles involving duct friction. Hence friction and wobble losses occur strictly in post-tensioned members.', 'Friction loss occurs only in curved post-tensioned ducts (IS 1343)', NULL, 'IS 1343:2012 Prestressed Concrete Code', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-015', 'apsc-ae-civil', 15, 'Reinforced Concrete Structures', 'Torsion Design', 'Equivalent Bending Moment', 'As per IS 456:2000, under combined bending moment (M) and twisting moment (T), the equivalent bending moment (Me1) is expressed as:', '[{"id":"A","text":"Me1 = M + T · (1 + D/b) / 1.7"},{"id":"B","text":"Me1 = M + T · (1 + b/D)"},{"id":"C","text":"Me1 = M + (T / 1.7)"},{"id":"D","text":"Me1 = √(M² + T²)"}]'::jsonb, 'Me1 = M + T · (1 + D/b) / 1.7', 'Me1 = M + T · (1 + b/D)', 'Me1 = M + (T / 1.7)', 'Me1 = √(M² + T²)', 'A', 'Clause 41.4.2 of IS 456 specifies that longitudinal reinforcement in members subjected to combined bending and torsion shall be designed for an equivalent bending moment Me1 = M + Mt, where Mt = T · (1 + D/b) / 1.7.', 'Me1 = M + Mt = M + T · (1 + D/b) / 1.7', NULL, 'IS 456:2000 Cl. 41.4.2', 'HARD', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-016', 'apsc-ae-civil', 16, 'Structural Analysis', 'Determinate & Indeterminate Structures', 'Static Indeterminacy of Trusses', 'A 2D pin-jointed plane truss has m members, r external reaction components, and j joints. The degree of static indeterminacy (Ds) is given by:', '[{"id":"A","text":"Ds = m - (2j - 3)"},{"id":"B","text":"Ds = m + r - 2j"},{"id":"C","text":"Ds = 2j - m - 3"},{"id":"D","text":"Ds = m + 3 - 2j"}]'::jsonb, 'Ds = m - (2j - 3)', 'Ds = m + r - 2j', 'Ds = 2j - m - 3', 'Ds = m + 3 - 2j', 'B', 'For a 2D pin-jointed truss, total unknowns are m member forces plus r support reactions. Total equations of equilibrium are 2 per joint (2j). Hence static indeterminacy Ds = m + r - 2j.', 'Ds = (m + r) - 2j', NULL, 'Structural Analysis by Hibbeler', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-017', 'apsc-ae-civil', 17, 'Structural Analysis', 'Kinematic Indeterminacy', 'Degrees of Freedom in Fixed Beam', 'What is the kinematic indeterminacy (degrees of freedom) of a fixed beam AB of span L, neglecting axial deformations?', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"2"},{"id":"D","text":"3"}]'::jsonb, '0', '1', '2', '3', 'A', 'Both ends A and B are fixed supports, where translations (Δx = 0, Δy = 0) and rotation (θ = 0) are completely restrained. Neglecting axial deformations, all joint displacements are zero, so Dk = 0.', 'Dk = 0 for fixed beam with axial deformation neglected', NULL, 'Theory of Structures by Ramamrutham', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-018', 'apsc-ae-civil', 18, 'Structural Analysis', 'Moment Distribution Method', 'Carry-Over Factor', 'In Moment Distribution Method, the carry-over factor to a far end that is fixed is:', '[{"id":"A","text":"0"},{"id":"B","text":"0.50"},{"id":"C","text":"0.75"},{"id":"D","text":"1.00"}]'::jsonb, '0', '0.50', '0.75', '1.00', 'B', 'When a moment M is applied at the near end of a prismatic member with the far end fixed, a moment of M/2 with the same sign is induced at the fixed far end. Hence the carry-over factor is +1/2 or 0.50.', 'Carry Over Factor (COF) = +0.5 to a fixed far end', NULL, 'Structural Analysis by C.K. Wang', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-019', 'apsc-ae-civil', 19, 'Structural Analysis', 'Slope Deflection Method', 'Standard Equations', 'In a prismatic beam AB with span L, flexural rigidity EI, and end rotations θA and θB with sinking Δ, the slope deflection equation for end moment MAB is:', '[{"id":"A","text":"MAB = M_F_AB + (2EI/L) · [2θA + θB - 3Δ/L]"},{"id":"B","text":"MAB = M_F_AB + (4EI/L) · [θA + θB - Δ/L]"},{"id":"C","text":"MAB = M_F_AB + (2EI/L) · [θA + 2θB - 3Δ/L]"},{"id":"D","text":"MAB = M_F_AB + (3EI/L) · [θA - Δ/L]"}]'::jsonb, 'MAB = M_F_AB + (2EI/L) · [2θA + θB - 3Δ/L]', 'MAB = M_F_AB + (4EI/L) · [θA + θB - Δ/L]', 'MAB = M_F_AB + (2EI/L) · [θA + 2θB - 3Δ/L]', 'MAB = M_F_AB + (3EI/L) · [θA - Δ/L]', 'A', 'The classic slope-deflection equation derives directly from superposition of fixed-end moment, near-end rotation (4EI/L · θA), far-end rotation (2EI/L · θB), and relative chord rotation (-6EI/L² · Δ). Factoring out 2EI/L yields MAB = M_F_AB + (2EI/L)[2θA + θB - 3Δ/L].', 'MAB = M_F_AB + (2EI/L) · [2θA + θB - 3Δ/L]', NULL, 'Elementary Structural Analysis by Norris & Wilbur', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-020', 'apsc-ae-civil', 20, 'Structural Analysis', 'Influence Line Diagrams', 'Müller-Breslau Principle', 'Müller-Breslau’s Principle for constructing influence lines is applicable to:', '[{"id":"A","text":"Statically determinate structures only"},{"id":"B","text":"Statically indeterminate structures only"},{"id":"C","text":"Both statically determinate and indeterminate structures"},{"id":"D","text":"Pin-jointed trusses only"}]'::jsonb, 'Statically determinate structures only', 'Statically indeterminate structures only', 'Both statically determinate and indeterminate structures', 'Pin-jointed trusses only', 'C', 'Müller-Breslau principle is rooted in Maxwell-Betti reciprocal theorem and applies to all linear elastic structures, whether determinate or indeterminate. For determinate beams the ILD consists of straight line segments; for indeterminate beams it is curved.', 'Based on Betti’s reciprocal theorem', NULL, 'Structural Analysis by Devdas Menon', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-021', 'apsc-ae-civil', 21, 'Structural Analysis', 'Energy Theorems', 'Castigliano’s Second Theorem', 'Castigliano’s second theorem states that the partial derivative of total strain energy (U) with respect to an applied load (Pi) yields:', '[{"id":"A","text":"The force in member i"},{"id":"B","text":"The deflection (Δi) at the point and in the direction of load Pi"},{"id":"C","text":"The slope at the point of load Pi"},{"id":"D","text":"The reaction at the nearest support"}]'::jsonb, 'The force in member i', 'The deflection (Δi) at the point and in the direction of load Pi', 'The slope at the point of load Pi', 'The reaction at the nearest support', 'B', 'Castigliano’s theorem of least work / deflection states that in any linear elastic structure, ∂U/∂Pi = Δi, giving the displacement under load Pi along its line of action.', '∂U / ∂Pi = Δi', NULL, 'Strength of Materials by Timoshenko', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-022', 'apsc-ae-civil', 22, 'Structural Analysis', 'Energy Methods', 'Unit Load Method for Deflection', 'In the unit load method for determining beam deflection, the expression for deflection Δ at any point is:', '[{"id":"A","text":"Δ = ∫ (M · m / EI) dx"},{"id":"B","text":"Δ = ∫ (M² / 2EI) dx"},{"id":"C","text":"Δ = ∫ (m² / EI) dx"},{"id":"D","text":"Δ = ∫ (M · m / 2EI) dx"}]'::jsonb, 'Δ = ∫ (M · m / EI) dx', 'Δ = ∫ (M² / 2EI) dx', 'Δ = ∫ (m² / EI) dx', 'Δ = ∫ (M · m / 2EI) dx', 'A', 'Based on virtual work principle: 1 · Δ = ∫ (m · ε) dx = ∫ m · (M / EI) dx = ∫ (M · m / EI) dx, where M is bending moment from actual loads and m is bending moment due to a fictitious unit load applied at the desired deflection point.', 'Δ = ∫ (M · m / EI) dx', NULL, 'Structural Analysis by Hibbeler', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-023', 'apsc-ae-civil', 23, 'Structural Analysis', 'Arches', 'Three-Hinged Parabolic Arch', 'A three-hinged parabolic arch of span L and central rise h is subjected to a uniformly distributed load w over its entire span. The horizontal thrust (H) at the supports is:', '[{"id":"A","text":"w · L² / (8 · h)"},{"id":"B","text":"w · L² / (16 · h)"},{"id":"C","text":"w · L / (8 · h)"},{"id":"D","text":"w · L² / (4 · h)"}]'::jsonb, 'w · L² / (8 · h)', 'w · L² / (16 · h)', 'w · L / (8 · h)', 'w · L² / (4 · h)', 'A', 'Taking moments about the crown hinge C: Mc = (wL/2) · (L/2) - (w · (L/2)² / 2) - H · h = 0 => H · h = wL²/8 => H = wL² / (8h).', 'H = w · L² / (8 · h)', NULL, 'Theory of Structures by Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-024', 'apsc-ae-civil', 24, 'Structural Analysis', 'Arches', 'Bending Moment in Parabolic Arch', 'For a three-hinged parabolic arch carrying a uniformly distributed load over its entire span, the bending moment at any section of the arch is:', '[{"id":"A","text":"Zero everywhere"},{"id":"B","text":"Maximum at the quarter span"},{"id":"C","text":"Maximum at the crown"},{"id":"D","text":"Equal to wL²/8"}]'::jsonb, 'Zero everywhere', 'Maximum at the quarter span', 'Maximum at the crown', 'Equal to wL²/8', 'A', 'The parabolic profile y = 4hx(L-x)/L² exactly matches the bending moment shape of a simple beam under UDL. Hence the thrust moment (H · y) exactly cancels the beam moment (μx) at every cross section, resulting in zero bending moment throughout.', 'Mx = μx - H · y = 0', NULL, 'Structural Analysis by Negi', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-025', 'apsc-ae-civil', 25, 'Structural Analysis', 'Cables and Suspension Bridges', 'Maximum Tension in Cable', 'A flexible cable of span L and central sag h carries a uniformly distributed load w per unit horizontal length. The maximum tension in the cable occurs at:', '[{"id":"A","text":"The mid-span (lowest point)"},{"id":"B","text":"The supports"},{"id":"C","text":"Quarter-span points"},{"id":"D","text":"Uniform throughout the length"}]'::jsonb, 'The mid-span (lowest point)', 'The supports', 'Quarter-span points', 'Uniform throughout the length', 'B', 'Cable tension at any point is T = √(H² + Vy²). Since horizontal thrust H is constant throughout the cable and vertical shear Vy is maximum at the supports (V = wL/2), the resultant cable tension Tmax occurs at the supports.', 'Tmax = √(H² + V²) at support', NULL, 'Structural Analysis by Bhavikatti', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-026', 'apsc-ae-civil', 26, 'Structural Analysis', 'Portal Frames', 'Sway Analysis', 'In portal frames, side sway will NOT occur if which of the following conditions is satisfied?', '[{"id":"A","text":"The frame is symmetrical in geometry, member properties and loading"},{"id":"B","text":"The frame is subjected to unsymmetrical lateral load"},{"id":"C","text":"Columns have different cross sections and unequal lengths"},{"id":"D","text":"Supports are at different levels"}]'::jsonb, 'The frame is symmetrical in geometry, member properties and loading', 'The frame is subjected to unsymmetrical lateral load', 'Columns have different cross sections and unequal lengths', 'Supports are at different levels', 'A', 'Sway is induced by asymmetry in geometry, unequal column stiffness, uneven support levels, or unsymmetrical lateral/gravity loading. If geometry, stiffness, support levels, and loading are all perfectly symmetrical, no sway occurs.', 'No sway condition: Symmetry in frame geometry + stiffness + loading', NULL, 'Indeterminate Structural Analysis by Menon', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-027', 'apsc-ae-civil', 27, 'Structural Analysis', 'Plastic Analysis', 'Shape Factor of Rectangular Section', 'The shape factor (S = Zp / Ze) for a rectangular cross-section of width b and depth d is:', '[{"id":"A","text":"1.0"},{"id":"B","text":"1.18"},{"id":"C","text":"1.50"},{"id":"D","text":"1.70"}]'::jsonb, '1.0', '1.18', '1.50', '1.70', 'C', 'For a rectangular beam: Plastic section modulus Zp = (b · d/2) · (d/4) · 2 = b d² / 4. Elastic section modulus Ze = b d² / 6. Therefore, shape factor S = Zp / Ze = (b d² / 4) / (b d² / 6) = 1.50. For circular section S = 1.70, diamond S = 2.0, I-section S = 1.12 to 1.18.', 'Shape Factor S = Zp / Ze = (b d² / 4) / (b d² / 6) = 1.50', NULL, 'Plastic Analysis of Structures by Baker', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-028', 'apsc-ae-civil', 28, 'Strength of Materials', 'Stress and Strain', 'Elastic Constants Relationship', 'The relationship connecting Young''s modulus (E), Shear modulus (G), and Poisson''s ratio (μ) for an isotropic elastic material is:', '[{"id":"A","text":"E = 2G(1 + μ)"},{"id":"B","text":"E = 3G(1 - 2μ)"},{"id":"C","text":"E = 2G(1 - μ)"},{"id":"D","text":"G = 2E(1 + μ)"}]'::jsonb, 'E = 2G(1 + μ)', 'E = 3G(1 - 2μ)', 'E = 2G(1 - μ)', 'G = 2E(1 + μ)', 'A', 'From the theory of elasticity, the fundamental relationships among elastic constants are: E = 2G(1 + μ) = 3K(1 - 2μ) = 9KG / (3K + G).', 'E = 2G(1 + μ) and E = 3K(1 - 2μ)', NULL, 'Mechanics of Materials by Gere & Timoshenko', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-029', 'apsc-ae-civil', 29, 'Strength of Materials', 'Elastic Constants', 'Poisson''s Ratio Upper Bound', 'For a perfectly incompressible isotropic material, the theoretical value of Poisson''s ratio (μ) is:', '[{"id":"A","text":"0"},{"id":"B","text":"0.25"},{"id":"C","text":"0.33"},{"id":"D","text":"0.50"}]'::jsonb, '0', '0.25', '0.33', '0.50', 'D', 'Volumetric strain for isotropic material is given by εv = (σx+σy+σz)/E · (1 - 2μ). For an incompressible material, volume change is zero (εv = 0), which mathematically requires (1 - 2μ) = 0 => μ = 0.50. For cork μ ≈ 0; for rubber μ ≈ 0.49 - 0.50.', 'Volumetric strain εv = (σx + σy + σz)/E · (1 - 2μ) = 0 => μ = 0.50', NULL, 'Strength of Materials by Rajput', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-030', 'apsc-ae-civil', 30, 'Strength of Materials', 'Principal Stresses', 'Mohr''s Circle Radius', 'In a 2D stress system with normal stresses σx and σy and shear stress τxy, the radius of Mohr''s circle of stress is equal to:', '[{"id":"A","text":"(σx + σy) / 2"},{"id":"B","text":"√[((σx - σy)/2)² + τxy²]"},{"id":"C","text":"√[((σx + σy)/2)² + τxy²]"},{"id":"D","text":"(σx - σy) / 2"}]'::jsonb, '(σx + σy) / 2', '√[((σx - σy)/2)² + τxy²]', '√[((σx + σy)/2)² + τxy²]', '(σx - σy) / 2', 'B', 'The center of Mohr''s circle is located at ((σx + σy)/2, 0) and its radius R represents the maximum in-plane shear stress τmax = √[((σx - σy)/2)² + τxy²].', 'R = τmax = √[((σx - σy)/2)² + τxy²]', NULL, 'Strength of Materials by Sadhu Singh', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-031', 'apsc-ae-civil', 31, 'Strength of Materials', 'Principal Planes', 'Shear Stress on Principal Planes', 'On principal planes in a stressed body, the value of shear stress is always:', '[{"id":"A","text":"Maximum"},{"id":"B","text":"Minimum but non-zero"},{"id":"C","text":"Zero"},{"id":"D","text":"Equal to normal stress"}]'::jsonb, 'Maximum', 'Minimum but non-zero', 'Zero', 'Equal to normal stress', 'C', 'By definition, principal planes are planes of zero shear stress. The normal stresses acting on these planes are known as the principal stresses (major and minor).', 'τ = 0 on principal planes', NULL, 'Mechanics of Solids by Popov', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-032', 'apsc-ae-civil', 32, 'Strength of Materials', 'Shear Force & Bending Moment', 'Point of Contraflexure', 'A point of contraflexure (or inflection) in a loaded beam is a point where:', '[{"id":"A","text":"Shear force is zero"},{"id":"B","text":"Bending moment is zero or changes sign"},{"id":"C","text":"Bending moment is maximum"},{"id":"D","text":"Shear force changes sign"}]'::jsonb, 'Shear force is zero', 'Bending moment is zero or changes sign', 'Bending moment is maximum', 'Shear force changes sign', 'B', 'A point of contraflexure is defined as a point along the beam span where the bending moment curve crosses zero and changes sign (from sagging to hogging or vice-versa). The beam curvature changes direction at this point.', 'M(x) = 0 and d²M/dx² ≠ 0 (curvature changes sign)', NULL, 'Strength of Materials by B.C. Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-033', 'apsc-ae-civil', 33, 'Strength of Materials', 'Bending Stresses', 'Flexure Formula', 'In the simple bending theory (Euler-Bernoulli beam theory), the bending stress (σ) at a distance y from the neutral axis is given by:', '[{"id":"A","text":"σ = M · y / I"},{"id":"B","text":"σ = M · I / y"},{"id":"C","text":"σ = I · y / M"},{"id":"D","text":"σ = M / (I · y)"}]'::jsonb, 'σ = M · y / I', 'σ = M · I / y', 'σ = I · y / M', 'σ = M / (I · y)', 'A', 'The classic flexure equation is M/I = σ/y = E/R. Hence bending stress σ varies linearly across the cross-section, being zero at the neutral axis and maximum at the extreme fibers (y = ymax).', 'M / I = σ / y = E / R => σ = M · y / I', NULL, 'Strength of Materials by R.K. Bansal', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-034', 'apsc-ae-civil', 34, 'Strength of Materials', 'Shear Stresses in Beams', 'Maximum Shear Stress in Rectangular Section', 'For a beam of rectangular cross-section of width b and depth d, the maximum shear stress (τmax) is related to the average shear stress (τavg) by:', '[{"id":"A","text":"τmax = 1.20 τavg"},{"id":"B","text":"τmax = 1.33 τavg"},{"id":"C","text":"τmax = 1.50 τavg"},{"id":"D","text":"τmax = 2.00 τavg"}]'::jsonb, 'τmax = 1.20 τavg', 'τmax = 1.33 τavg', 'τmax = 1.50 τavg', 'τmax = 2.00 τavg', 'C', 'The parabolic shear stress distribution for a rectangle is τ = (V / 2I) · (d²/4 - y²). At the neutral axis (y = 0), τmax = 1.5 · (V / bd) = 1.50 · τavg.', 'τmax = 1.50 · τavg (Rectangular); τmax = 1.33 · τavg (Circular)', NULL, 'Mechanics of Materials by Beer & Johnston', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-035', 'apsc-ae-civil', 35, 'Strength of Materials', 'Torsion of Circular Shafts', 'Torsion Equation', 'A solid circular shaft of diameter D is subjected to a torque T. The maximum shear stress induced at the outer surface is:', '[{"id":"A","text":"16 T / (π D³)"},{"id":"B","text":"32 T / (π D³)"},{"id":"C","text":"64 T / (π D³)"},{"id":"D","text":"8 T / (π D³)"}]'::jsonb, '16 T / (π D³)', '32 T / (π D³)', '64 T / (π D³)', '8 T / (π D³)', 'A', 'From the torsion formula T/J = τ/r, for a solid circular shaft J = π D⁴ / 32 and r = D/2. Thus τmax = 16 T / (π D³). Polar section modulus Zp = π D³ / 16.', 'τmax = T · r / J = T · (D/2) / (π D⁴ / 32) = 16 T / (π D³)', NULL, 'Strength of Materials by S. Ramamrutham', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-036', 'apsc-ae-civil', 36, 'Strength of Materials', 'Deflection of Beams', 'Cantilever with Point Load', 'What is the maximum deflection at the free end of a cantilever beam of span L and flexural rigidity EI carrying a concentrated point load P at its free end?', '[{"id":"A","text":"P L³ / (3 EI)"},{"id":"B","text":"P L³ / (8 EI)"},{"id":"C","text":"P L³ / (48 EI)"},{"id":"D","text":"5 P L⁴ / (384 EI)"}]'::jsonb, 'P L³ / (3 EI)', 'P L³ / (8 EI)', 'P L³ / (48 EI)', '5 P L⁴ / (384 EI)', 'A', 'By moment area theorem or double integration: Deflection δ = P L³ / (3 EI). For UDL over entire span, δ = w L⁴ / (8 EI). For simply supported beam with central load, δ = P L³ / (48 EI).', 'δmax = P L³ / (3 EI); θmax = P L² / (2 EI)', NULL, 'Theory of Structures by Vazirani & Ratwani', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-037', 'apsc-ae-civil', 37, 'Strength of Materials', 'Columns & Struts', 'Euler Buckling Load & Effective Length', 'A long column of length L and flexural rigidity EI has both ends pinned (hinged). According to Euler''s formula, the critical crippling load (Pcr) is:', '[{"id":"A","text":"π² EI / L²"},{"id":"B","text":"4 π² EI / L²"},{"id":"C","text":"π² EI / (4 L²)"},{"id":"D","text":"2 π² EI / L²"}]'::jsonb, 'π² EI / L²', '4 π² EI / L²', 'π² EI / (4 L²)', '2 π² EI / L²', 'A', 'Euler crippling load Pcr = π² EI / Leff². For both ends hinged: Leff = L => Pcr = π² EI / L². For both ends fixed: Leff = L/2 => Pcr = 4 π² EI / L². For one fixed and one free: Leff = 2L => Pcr = π² EI / (4 L²). For one fixed and one hinged: Leff = L/√2 => Pcr = 2 π² EI / L².', 'Pcr = π² EI / Leff²; Leff = L (both ends hinged)', NULL, 'Mechanics of Materials by Gere', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-038', 'apsc-ae-civil', 38, 'Geotechnical Engineering', 'Soil Properties & Phase Relationships', 'Fundamental Relationship', 'In soil mechanics, which of the following equations correctly connects degree of saturation (S), void ratio (e), water content (w), and specific gravity (G)?', '[{"id":"A","text":"S · e = w · G"},{"id":"B","text":"S · w = e · G"},{"id":"C","text":"S · G = w · e"},{"id":"D","text":"w · e · S = G"}]'::jsonb, 'S · e = w · G', 'S · w = e · G', 'S · G = w · e', 'w · e · S = G', 'A', 'By definition, S = Vw / Vv and e = Vv / Vs => S · e = Vw / Vs = (Mw / ρw) / (Ms / (G · ρw)) = (Mw / Ms) · G = w · G. Hence S · e = w · G.', 'S · e = w · G', NULL, 'Soil Mechanics & Foundation Engineering by K.R. Arora', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-039', 'apsc-ae-civil', 39, 'Geotechnical Engineering', 'Soil Classification', 'Plasticity Chart & A-Line Equation', 'In the Indian Standard Soil Classification System (IS 1498), the equation of the ''A-line'' on the plasticity chart separating clays from silts and organic soils is:', '[{"id":"A","text":"IP = 0.73 · (wL - 20)"},{"id":"B","text":"IP = 0.90 · (wL - 8)"},{"id":"C","text":"IP = 0.73 · (wL - 10)"},{"id":"D","text":"IP = 0.50 · (wL - 20)"}]'::jsonb, 'IP = 0.73 · (wL - 20)', 'IP = 0.90 · (wL - 8)', 'IP = 0.73 · (wL - 10)', 'IP = 0.50 · (wL - 20)', 'A', 'Arthur Casagrande''s A-line equation is IP = 0.73 · (wL - 20). Inorganic clays lie above the A-line; inorganic silts and organic clays lie below the A-line. The U-line (upper limit) is IP = 0.90 · (wL - 8).', 'IP = 0.73 · (wL - 20)', NULL, 'IS 1498:1970 Soil Classification Code', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-040', 'apsc-ae-civil', 40, 'Geotechnical Engineering', 'Effective Stress Principle', 'Terzaghi''s Principle', 'According to Terzaghi''s effective stress principle, total stress (σ), effective stress (σ''), and pore water pressure (u) are related by:', '[{"id":"A","text":"σ'' = σ - u"},{"id":"B","text":"σ'' = σ + u"},{"id":"C","text":"σ'' = u - σ"},{"id":"D","text":"σ'' = σ / u"}]'::jsonb, 'σ'' = σ - u', 'σ'' = σ + u', 'σ'' = u - σ', 'σ'' = σ / u', 'A', 'The effective stress σ'' is the intergranular stress transmitted across grain contacts that governs shear strength and volume compressibility: σ'' = σ - u.', 'σ'' = σ - u', NULL, 'Theoretical Soil Mechanics by Terzaghi', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-041', 'apsc-ae-civil', 41, 'Geotechnical Engineering', 'Permeability of Soils', 'Constant vs Falling Head Permeameter', 'The falling head permeability test is primarily recommended for which type of soil?', '[{"id":"A","text":"Clean gravels"},{"id":"B","text":"Coarse sands"},{"id":"C","text":"Fine-grained soils like silts and clays"},{"id":"D","text":"Boulders and cobbles"}]'::jsonb, 'Clean gravels', 'Coarse sands', 'Fine-grained soils like silts and clays', 'Boulders and cobbles', 'C', 'Constant head permeameter is used for coarse-grained soils with high permeability (sands, gravels). Falling head permeameter is suitable for fine-grained soils (silts and clays) where discharge is very small.', 'k = (2.303 a L / (A t)) · log10(h1 / h2)', NULL, 'Basic and Applied Soil Mechanics by Gopal Ranjan', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-042', 'apsc-ae-civil', 42, 'Geotechnical Engineering', 'Seepage & Flow Nets', 'Seepage Discharge Equation', 'In a flow net constructed with Nf flow channels and Nd equipotential drops under total head loss H, the seepage discharge per unit length through soil of permeability k is:', '[{"id":"A","text":"q = k · H · (Nf / Nd)"},{"id":"B","text":"q = k · H · (Nd / Nf)"},{"id":"C","text":"q = k · H · (Nf · Nd)"},{"id":"D","text":"q = k · H / (Nf + Nd)"}]'::jsonb, 'q = k · H · (Nf / Nd)', 'q = k · H · (Nd / Nf)', 'q = k · H · (Nf · Nd)', 'q = k · H / (Nf + Nd)', 'A', 'Flow net discharge is given by q = k · H · (Nf / Nd) for square flow elements where aspect ratio b/a = 1. Shape factor is defined as (Nf / Nd).', 'q = k · H · (Nf / Nd)', NULL, 'Soil Mechanics by B.C. Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-043', 'apsc-ae-civil', 43, 'Geotechnical Engineering', 'Quick Sand Condition', 'Critical Hydraulic Gradient', 'The critical hydraulic gradient (icr) at which quicksand condition or boiling occurs in a saturated cohesionless soil is given by:', '[{"id":"A","text":"icr = (G - 1) / (1 + e)"},{"id":"B","text":"icr = (G + 1) / (1 + e)"},{"id":"C","text":"icr = (G - 1) / (1 - e)"},{"id":"D","text":"icr = (1 + e) / (G - 1)"}]'::jsonb, 'icr = (G - 1) / (1 + e)', 'icr = (G + 1) / (1 + e)', 'icr = (G - 1) / (1 - e)', 'icr = (1 + e) / (G - 1)', 'A', 'Quicksand occurs when upward seepage force balances submerged weight of soil particles (effective stress σ'' = 0). Thus i · γw = γ'' => icr = γ'' / γw = (G - 1) / (1 + e). For typical soils (G ≈ 2.65, e ≈ 0.65), icr ≈ 1.0.', 'icr = γ'' / γw = (G - 1) / (1 + e)', NULL, 'Soil Mechanics in Engineering Practice by Terzaghi & Peck', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-044', 'apsc-ae-civil', 44, 'Geotechnical Engineering', 'Consolidation of Soils', 'Time Factor and Drainage Path', 'In Terzaghi''s 1D consolidation theory, the non-dimensional time factor (Tv) is expressed as:', '[{"id":"A","text":"Tv = Cv · t / d²"},{"id":"B","text":"Tv = Cv · d² / t"},{"id":"C","text":"Tv = k · t / Cv"},{"id":"D","text":"Tv = mv · t / d²"}]'::jsonb, 'Tv = Cv · t / d²', 'Tv = Cv · d² / t', 'Tv = k · t / Cv', 'Tv = mv · t / d²', 'A', 'Time factor Tv = Cv · t / d², where Cv is coefficient of consolidation, t is time, and d is length of drainage path (d = H/2 for two-way double drainage, d = H for single one-way drainage).', 'Tv = Cv · t / d²', NULL, 'Geotechnical Engineering by C. Venkatramaiah', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-045', 'apsc-ae-civil', 45, 'Geotechnical Engineering', 'Consolidation of Soils', 'Compression Index Empirical Formula', 'For undisturbed clays of medium to low sensitivity, Skempton''s empirical formula for compression index (Cc) based on liquid limit (wL in %) is:', '[{"id":"A","text":"Cc = 0.009 · (wL - 10)"},{"id":"B","text":"Cc = 0.007 · (wL - 10)"},{"id":"C","text":"Cc = 0.009 · (wL - 20)"},{"id":"D","text":"Cc = 0.005 · (wL - 15)"}]'::jsonb, 'Cc = 0.009 · (wL - 10)', 'Cc = 0.007 · (wL - 10)', 'Cc = 0.009 · (wL - 20)', 'Cc = 0.005 · (wL - 15)', 'A', 'Skempton''s widely verified empirical relationship is: Cc = 0.009 · (wL - 10) for undisturbed clays, and Cc = 0.007 · (wL - 10) for remolded clays.', 'Cc = 0.009 · (wL - 10) for undisturbed clays', NULL, 'Soil Mechanics by Lambe & Whitman', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-046', 'apsc-ae-civil', 46, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Failure Criteria', 'The shear strength (τf) of a soil on any plane according to Mohr-Coulomb failure criterion is represented by:', '[{"id":"A","text":"τf = c + σ · tan φ"},{"id":"B","text":"τf = c - σ · tan φ"},{"id":"C","text":"τf = σ + c · tan φ"},{"id":"D","text":"τf = c · σ · tan φ"}]'::jsonb, 'τf = c + σ · tan φ', 'τf = c - σ · tan φ', 'τf = σ + c · tan φ', 'τf = c · σ · tan φ', 'A', 'Coulomb''s shear strength equation states that shear strength comprises apparent cohesion c and frictional resistance proportional to effective normal stress σ: τf = c + σ tan φ.', 'τf = c + σ · tan φ (Total) or τf = c'' + σ'' · tan φ'' (Effective)', NULL, 'Principles of Geotechnical Engineering by B.M. Das', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-047', 'apsc-ae-civil', 47, 'Geotechnical Engineering', 'Shear Strength Testing', 'Triaxial Drainage Conditions', 'In a Consolidated Undrained (CU) triaxial compression test, drainage is permitted during:', '[{"id":"A","text":"The application of cell pressure only"},{"id":"B","text":"The application of deviator stress only"},{"id":"C","text":"Both cell pressure and deviator stress stages"},{"id":"D","text":"Neither cell pressure nor deviator stress stage"}]'::jsonb, 'The application of cell pressure only', 'The application of deviator stress only', 'Both cell pressure and deviator stress stages', 'Neither cell pressure nor deviator stress stage', 'A', 'In Consolidated Undrained (CU) test: Consolidation stage has drainage valve open (dissipating excess pore pressure under confining pressure σ3); during the subsequent shearing stage (application of deviator stress Δσ), the drainage valve is closed.', 'CU test: Drainage open during cell pressure consolidation, closed during shearing', NULL, 'Soil Mechanics by Craig', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-048', 'apsc-ae-civil', 48, 'Geotechnical Engineering', 'Lateral Earth Pressure', 'Rankine''s Active Pressure Coefficient', 'For a cohesionless backfill with horizontal ground surface and angle of internal friction φ, Rankine''s coefficient of active earth pressure (Ka) is:', '[{"id":"A","text":"Ka = (1 - sin φ) / (1 + sin φ)"},{"id":"B","text":"Ka = (1 + sin φ) / (1 - sin φ)"},{"id":"C","text":"Ka = cos² φ / (1 + sin φ)"},{"id":"D","text":"Ka = (1 - cos φ) / (1 + cos φ)"}]'::jsonb, 'Ka = (1 - sin φ) / (1 + sin φ)', 'Ka = (1 + sin φ) / (1 - sin φ)', 'Ka = cos² φ / (1 + sin φ)', 'Ka = (1 - cos φ) / (1 + cos φ)', 'A', 'Rankine''s active coefficient is Ka = (1 - sin φ) / (1 + sin φ) = tan²(45° - φ/2). Conversely, passive pressure coefficient Kp = 1 / Ka = (1 + sin φ) / (1 - sin φ) = tan²(45° + φ/2).', 'Ka = (1 - sin φ) / (1 + sin φ) = tan²(45° - φ/2)', NULL, 'Foundation Engineering by Teng', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-049', 'apsc-ae-civil', 49, 'Geotechnical Engineering', 'Bearing Capacity of Foundations', 'Terzaghi''s Equation for Strip Footing', 'Terzaghi''s ultimate bearing capacity (qu) equation for a continuous strip footing of width B at depth Df in soil with parameters c, γ, and bearing capacity factors Nc, Nq, Nγ is:', '[{"id":"A","text":"qu = c Nc + q Nq + 0.5 γ B Nγ"},{"id":"B","text":"qu = 1.3 c Nc + q Nq + 0.4 γ B Nγ"},{"id":"C","text":"qu = 1.3 c Nc + q Nq + 0.3 γ B Nγ"},{"id":"D","text":"qu = c Nc + q Nq + γ B Nγ"}]'::jsonb, 'qu = c Nc + q Nq + 0.5 γ B Nγ', 'qu = 1.3 c Nc + q Nq + 0.4 γ B Nγ', 'qu = 1.3 c Nc + q Nq + 0.3 γ B Nγ', 'qu = c Nc + q Nq + γ B Nγ', 'A', 'For a strip footing: qu = c Nc + q Nq + 0.5 γ B Nγ. For a square footing: qu = 1.3 c Nc + q Nq + 0.4 γ B Nγ. For a circular footing: qu = 1.3 c Nc + q Nq + 0.3 γ B Nγ.', 'qu = c Nc + γ Df Nq + 0.5 γ B Nγ', NULL, 'Theoretical Soil Mechanics by Terzaghi', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-050', 'apsc-ae-civil', 50, 'Geotechnical Engineering', 'Bearing Capacity Definitions', 'Net Ultimate Bearing Capacity', 'The net ultimate bearing capacity (qnu) of a foundation is defined in terms of gross ultimate bearing capacity (qu) and effective surcharge (q = γ Df) as:', '[{"id":"A","text":"qnu = qu - γ · Df"},{"id":"B","text":"qnu = qu + γ · Df"},{"id":"C","text":"qnu = qu / (γ · Df)"},{"id":"D","text":"qnu = (qu - γ · Df) / FOS"}]'::jsonb, 'qnu = qu - γ · Df', 'qnu = qu + γ · Df', 'qnu = qu / (γ · Df)', 'qnu = (qu - γ · Df) / FOS', 'A', 'Net ultimate bearing capacity is the net intensity of pressure at the base of the footing in excess of the existing overburden pressure that the soil can support: qnu = qu - γ Df. Net safe bearing capacity qns = qnu / FOS.', 'qnu = qu - q = qu - γ · Df', NULL, 'Soil Mechanics by B.C. Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-051', 'apsc-ae-civil', 51, 'Geotechnical Engineering', 'Standard Penetration Test (SPT)', 'Dilatancy Correction', 'The dilatancy correction for observed SPT N-value in fine sands and silts below water table is applied only when the corrected value for overburden (N1) exceeds 15, using the formula:', '[{"id":"A","text":"N'''' = 15 + 0.5 · (N'' - 15)"},{"id":"B","text":"N'''' = 15 + 0.75 · (N'' - 15)"},{"id":"C","text":"N'''' = 15 + 0.25 · (N'' - 15)"},{"id":"D","text":"N'''' = 0.5 · (N'' + 15)"}]'::jsonb, 'N'''' = 15 + 0.5 · (N'' - 15)', 'N'''' = 15 + 0.75 · (N'' - 15)', 'N'''' = 15 + 0.25 · (N'' - 15)', 'N'''' = 0.5 · (N'' + 15)', 'A', 'As per IS 2131, negative pore water pressures during dynamic shearing increase resistance in dense saturated silts and fine sands. When N'' > 15, the dilatancy correction is N'''' = 15 + 0.5(N'' - 15).', 'N'''' = 15 + 0.5 · (N'' - 15) per IS 2131', NULL, 'IS 2131:1981 Standard Penetration Test Code', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-052', 'apsc-ae-civil', 52, 'Geotechnical Engineering', 'Pile Foundations', 'Negative Skin Friction', 'Negative skin friction on a driven pile occurs when:', '[{"id":"A","text":"The surrounding soil settles more than the pile itself"},{"id":"B","text":"The pile moves downward relative to the soil under structural load"},{"id":"C","text":"The pile is driven into very hard bedrock"},{"id":"D","text":"Groundwater level rises rapidly above the surface"}]'::jsonb, 'The surrounding soil settles more than the pile itself', 'The pile moves downward relative to the soil under structural load', 'The pile is driven into very hard bedrock', 'Groundwater level rises rapidly above the surface', 'A', 'Negative skin friction is a downward drag acting on pile shaft when consolidating compressible soil (soft clay, recent fill) settles faster than the pile, adding downward load to the pile instead of providing upward support.', 'Downward drag force Qnf = P · L · α · c', NULL, 'Foundation Engineering by Bowles', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-053', 'apsc-ae-civil', 53, 'Fluid Mechanics & Hydraulics', 'Fluid Properties', 'Kinematic Viscosity Units', 'The CGS unit of kinematic viscosity is ''Stokes''. 1 Stokes is equal to:', '[{"id":"A","text":"1 cm²/s (or 10⁻⁴ m²/s)"},{"id":"B","text":"1 m²/s"},{"id":"C","text":"10⁻³ m²/s"},{"id":"D","text":"1 N·s/m²"}]'::jsonb, '1 cm²/s (or 10⁻⁴ m²/s)', '1 m²/s', '10⁻³ m²/s', '1 N·s/m²', 'A', 'Kinematic viscosity is dynamic viscosity divided by fluid density (ν = μ / ρ) with dimensions [L² T⁻¹]. In SI units it is m²/s, and in CGS units 1 cm²/s = 1 Stokes = 10⁻⁴ m²/s. 1 Poise = 0.1 N·s/m² = 0.1 Pa·s.', '1 Stokes = 1 cm²/s = 10⁻⁴ m²/s; Kinematic viscosity ν = μ / ρ', NULL, 'Fluid Mechanics by Frank M. White', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-054', 'apsc-ae-civil', 54, 'Fluid Mechanics & Hydraulics', 'Hydrostatics', 'Center of Pressure', 'The center of pressure for a vertical rectangular plane surface of width b and depth d submerged vertically in water with its top edge in the free surface lies at a depth of:', '[{"id":"A","text":"d / 2"},{"id":"B","text":"2d / 3"},{"id":"C","text":"3d / 4"},{"id":"D","text":"d / 3"}]'::jsonb, 'd / 2', '2d / 3', '3d / 4', 'd / 3', 'B', 'From the hydrostatic pressure formula for vertical submerged surfaces, hc = h̄ + IG/(A·h̄). Substituting h̄ = d/2, IG = bd³/12, and A = bd gives hc = d/2 + d/6 = 2/3 d.', 'hc = h̄ + IG / (A · h̄) = d/2 + (b d³ / 12) / ((b d) · (d/2)) = d/2 + d/6 = 2d/3', NULL, 'Hydraulics & Fluid Mechanics by Modi & Seth', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-055', 'apsc-ae-civil', 55, 'Fluid Mechanics & Hydraulics', 'Buoyancy and Floatation', 'Metacentric Height & Stability', 'For a floating body to be in stable equilibrium, its metacentric height (GM) must be:', '[{"id":"A","text":"Positive (Metacenter M lies above center of gravity G)"},{"id":"B","text":"Zero (Metacenter M coincides with G)"},{"id":"C","text":"Negative (Metacenter M lies below G)"},{"id":"D","text":"Infinite"}]'::jsonb, 'Positive (Metacenter M lies above center of gravity G)', 'Zero (Metacenter M coincides with G)', 'Negative (Metacenter M lies below G)', 'Infinite', 'A', 'A floating body is in stable equilibrium when GM > 0 (M lies above G), neutral when GM = 0 (M coincides with G), and unstable when GM < 0 (M lies below G, producing an upsetting moment).', 'GM = BM - BG > 0 for stable equilibrium', NULL, 'Fluid Mechanics by A.K. Jain', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-056', 'apsc-ae-civil', 56, 'Fluid Mechanics & Hydraulics', 'Fluid Kinematics', 'Continuity Equation', 'The general continuity equation for steady, 3D incompressible flow in Cartesian coordinates is:', '[{"id":"A","text":"∂u/∂x + ∂v/∂y + ∂w/∂z = 0"},{"id":"B","text":"u · ∂u/∂x + v · ∂v/∂y + w · ∂w/∂z = 0"},{"id":"C","text":"∂u/∂x - ∂v/∂y + ∂w/∂z = 0"},{"id":"D","text":"∂²u/∂x² + ∂²v/∂y² + ∂²w/∂z² = 0"}]'::jsonb, '∂u/∂x + ∂v/∂y + ∂w/∂z = 0', 'u · ∂u/∂x + v · ∂v/∂y + w · ∂w/∂z = 0', '∂u/∂x - ∂v/∂y + ∂w/∂z = 0', '∂²u/∂x² + ∂²v/∂y² + ∂²w/∂z² = 0', 'A', 'Conservation of mass for a fluid with constant density ρ leads to the divergence of velocity vector being zero: div(V) = ∂u/∂x + ∂v/∂y + ∂w/∂z = 0.', '∇ · V = ∂u/∂x + ∂v/∂y + ∂w/∂z = 0', NULL, 'Fluid Mechanics by Som & Biswas', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-057', 'apsc-ae-civil', 57, 'Fluid Mechanics & Hydraulics', 'Fluid Dynamics', 'HGL and TEL Relationship', 'The vertical distance between the Total Energy Line (TEL) and Hydraulic Gradient Line (HGL) at any cross-section of a pipe flow represents the:', '[{"id":"A","text":"Pressure head (p / γ)"},{"id":"B","text":"Velocity head (v² / 2g)"},{"id":"C","text":"Datum head (z)"},{"id":"D","text":"Friction head loss (hf)"}]'::jsonb, 'Pressure head (p / γ)', 'Velocity head (v² / 2g)', 'Datum head (z)', 'Friction head loss (hf)', 'B', 'Total Energy Line = p/γ + z + v²/2g. Hydraulic Gradient Line = p/γ + z. The difference between TEL and HGL is strictly the kinetic velocity head v² / (2g).', 'TEL - HGL = v² / (2g)', NULL, 'Fluid Mechanics by Fox & McDonald', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-058', 'apsc-ae-civil', 58, 'Fluid Mechanics & Hydraulics', 'Flow Measurement', 'Venturimeter Discharge Coefficient', 'The coefficient of discharge (Cd) for a standard venturimeter typically ranges between:', '[{"id":"A","text":"0.60 to 0.65"},{"id":"B","text":"0.70 to 0.75"},{"id":"C","text":"0.80 to 0.85"},{"id":"D","text":"0.96 to 0.98"}]'::jsonb, '0.60 to 0.65', '0.70 to 0.75', '0.80 to 0.85', '0.96 to 0.98', 'D', 'Due to smooth streamlined gradual convergence and divergence in a venturimeter, boundary layer separation and eddy losses are minimal, yielding Cd = 0.96 to 0.98. Orifice meters have sudden contraction with vena contracta, giving Cd ≈ 0.60 - 0.65.', 'Cd(venturi) ≈ 0.96 - 0.98 vs Cd(orifice) ≈ 0.60 - 0.65', NULL, 'Hydraulics and Fluid Mechanics by Modi & Seth', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-059', 'apsc-ae-civil', 59, 'Fluid Mechanics & Hydraulics', 'Pipe Flow', 'Darcy-Weisbach Equation', 'The head loss due to friction in a pipe of length L, diameter D, carrying fluid at average velocity v is given by the Darcy-Weisbach equation as:', '[{"id":"A","text":"hf = f · L · v² / (2 · g · D)"},{"id":"B","text":"hf = 4 · f · L · v / (2 · g · D)"},{"id":"C","text":"hf = f · L · v / (g · D)"},{"id":"D","text":"hf = f · L² · v / (2 · g · D)"}]'::jsonb, 'hf = f · L · v² / (2 · g · D)', 'hf = 4 · f · L · v / (2 · g · D)', 'hf = f · L · v / (g · D)', 'hf = f · L² · v / (2 · g · D)', 'A', 'The Darcy-Weisbach equation is hf = f · L · v² / (2 g D). If Fanning friction factor f'' is used, hf = 4 f'' L v² / (2 g D), where f = 4 f''.', 'hf = f · L · v² / (2 · g · D) [where f is Darcy friction factor]', NULL, 'Fluid Mechanics by Yunus A. Cengel', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-060', 'apsc-ae-civil', 60, 'Fluid Mechanics & Hydraulics', 'Laminar Flow in Pipes', 'Hagen-Poiseuille Velocity Distribution', 'In fully developed laminar flow through a circular pipe, the ratio of maximum centerline velocity (umax) to average cross-sectional velocity (vavg) is:', '[{"id":"A","text":"1.25"},{"id":"B","text":"1.50"},{"id":"C","text":"2.00"},{"id":"D","text":"2.50"}]'::jsonb, '1.25', '1.50', '2.00', '2.50', 'C', 'Velocity distribution across a circular pipe is parabolic: u(r) = umax · (1 - r²/R²). Integrating over the cross-section yields vavg = umax / 2, meaning maximum centerline velocity is exactly twice the average velocity (umax = 2 vavg).', 'umax = 2 · vavg (Circular Pipe); umax = 1.5 · vavg (Parallel Plates)', NULL, 'Fluid Mechanics by Streeter & Wylie', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-061', 'apsc-ae-civil', 61, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Manning''s Formula', 'In SI units, Manning''s equation for uniform flow velocity (V) in an open channel of hydraulic radius R and bed slope S is:', '[{"id":"A","text":"V = (1 / n) · R^(2/3) · S^(1/2)"},{"id":"B","text":"V = (1 / n) · R^(1/2) · S^(2/3)"},{"id":"C","text":"V = n · R^(2/3) · S^(1/2)"},{"id":"D","text":"V = (1 / n) · R^(3/4) · S^(1/2)"}]'::jsonb, 'V = (1 / n) · R^(2/3) · S^(1/2)', 'V = (1 / n) · R^(1/2) · S^(2/3)', 'V = n · R^(2/3) · S^(1/2)', 'V = (1 / n) · R^(3/4) · S^(1/2)', 'A', 'Robert Manning''s empirical formula for uniform flow velocity is V = (1/n) · R^(2/3) · S^(1/2), where n is Manning''s roughness coefficient, R is hydraulic radius (Area / Wetted Perimeter), and S is longitudinal bed slope.', 'V = (1 / n) · R^(2/3) · S^(1/2)', NULL, 'Flow in Open Channels by K. Subramanya', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-062', 'apsc-ae-civil', 62, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Critical Depth in Rectangular Channel', 'For a rectangular open channel carrying discharge q per unit width, the critical depth (yc) is given by:', '[{"id":"A","text":"yc = (q² / g)^(1/3)"},{"id":"B","text":"yc = (q / g)^(1/2)"},{"id":"C","text":"yc = (q² / g)^(1/2)"},{"id":"D","text":"yc = (q / g²)^(1/3)"}]'::jsonb, 'yc = (q² / g)^(1/3)', 'yc = (q / g)^(1/2)', 'yc = (q² / g)^(1/2)', 'yc = (q / g²)^(1/3)', 'A', 'At critical flow condition, specific energy is minimum for a given discharge, giving Froude number Fr = v / √(g yc) = 1. Substituting v = q / yc leads directly to yc³ = q² / g => yc = (q² / g)^(1/3). Minimum specific energy Emin = 1.5 yc.', 'yc = (q² / g)^(1/3); Froude number Fr = 1 at critical depth', NULL, 'Open Channel Hydraulics by Ven Te Chow', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-063', 'apsc-ae-civil', 63, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Hydraulic Jump Sequent Depths', 'The relationship between pre-jump depth (y1) and post-jump sequent depth (y2) in a horizontal rectangular channel with initial Froude number Fr1 is:', '[{"id":"A","text":"y2 / y1 = 0.5 · [√(1 + 8 · Fr1²) - 1]"},{"id":"B","text":"y2 / y1 = 0.5 · [√(1 + 8 · Fr1²) + 1]"},{"id":"C","text":"y2 / y1 = √(1 + 8 · Fr1²)"},{"id":"D","text":"y2 / y1 = 0.5 · [√(1 + 4 · Fr1²) - 1]"}]'::jsonb, 'y2 / y1 = 0.5 · [√(1 + 8 · Fr1²) - 1]', 'y2 / y1 = 0.5 · [√(1 + 8 · Fr1²) + 1]', 'y2 / y1 = √(1 + 8 · Fr1²)', 'y2 / y1 = 0.5 · [√(1 + 4 · Fr1²) - 1]', 'A', 'Applying momentum equation across the hydraulic jump in a rectangular channel yields Belanger''s equation: y2 / y1 = 0.5 · (√(1 + 8 Fr1²) - 1). Energy loss in jump is ΔE = (y2 - y1)³ / (4 y1 y2).', 'y2 / y1 = 0.5 · [√(1 + 8 · Fr1²) - 1] (Belanger equation)', NULL, 'Flow in Open Channels by K. Subramanya', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-064', 'apsc-ae-civil', 64, 'Fluid Mechanics & Hydraulics', 'Hydraulic Machines', 'Specific Speed of Turbines', 'The specific speed (Ns) of a hydraulic turbine generating power P under head H at rotational speed N is defined as:', '[{"id":"A","text":"Ns = N · √P / H^(5/4)"},{"id":"B","text":"Ns = N · √P / H^(3/4)"},{"id":"C","text":"Ns = N · √Q / H^(3/4)"},{"id":"D","text":"Ns = N · P² / H^(5/4)"}]'::jsonb, 'Ns = N · √P / H^(5/4)', 'Ns = N · √P / H^(3/4)', 'Ns = N · √Q / H^(3/4)', 'Ns = N · P² / H^(5/4)', 'A', 'Turbine specific speed is Ns = N √P / H^(5/4). For Pelton wheel: Ns = 10-35 (low). For Francis turbine: Ns = 60-300 (medium). For Kaplan turbine: Ns = 300-1000 (high specific speed under low head).', 'Ns(turbine) = N · √P / H^(5/4); Ns(pump) = N · √Q / H^(3/4)', NULL, 'Hydraulic Machines by Jagdish Lal', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-065', 'apsc-ae-civil', 65, 'Environmental Engineering', 'Water Demand', 'Population Forecasting Methods', 'Which population forecasting method is most suitable for an old, mature, and densely populated city that has reached its saturation stage?', '[{"id":"A","text":"Arithmetical increase method"},{"id":"B","text":"Geometrical increase method"},{"id":"C","text":"Incremental increase method"},{"id":"D","text":"Decreasing rate of growth method"}]'::jsonb, 'Arithmetical increase method', 'Geometrical increase method', 'Incremental increase method', 'Decreasing rate of growth method', 'A', 'Arithmetical increase method assumes a constant rate of population growth (dP/dt = constant) and is suitable for old, large, established cities nearing saturation. Geometrical increase method is suited for rapidly developing young cities.', 'Pn = P0 + n · x̄', NULL, 'Water Supply Engineering by S.K. Garg', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-066', 'apsc-ae-civil', 66, 'Environmental Engineering', 'Water Quality Standards', 'Fluoride Limits per IS 10500', 'As per IS 10500:2012, what is the acceptable limit and permissible limit in the absence of alternate source for Fluoride in drinking water?', '[{"id":"A","text":"1.0 mg/L and 1.5 mg/L respectively"},{"id":"B","text":"0.5 mg/L and 1.0 mg/L respectively"},{"id":"C","text":"1.5 mg/L and 2.5 mg/L respectively"},{"id":"D","text":"0.05 mg/L and 0.1 mg/L respectively"}]'::jsonb, '1.0 mg/L and 1.5 mg/L respectively', '0.5 mg/L and 1.0 mg/L respectively', '1.5 mg/L and 2.5 mg/L respectively', '0.05 mg/L and 0.1 mg/L respectively', 'A', 'Under IS 10500:2012, acceptable Fluoride limit is 1.0 mg/L (prevents dental cavities). If fluoride exceeds 1.5 mg/L, it causes dental fluorosis (mottling of teeth) and skeletal fluorosis.', 'Acceptable limit = 1.0 mg/L; Max permissible = 1.5 mg/L', NULL, 'IS 10500:2012 Drinking Water Specification', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-067', 'apsc-ae-civil', 67, 'Environmental Engineering', 'Water Treatment', 'Alum Coagulation Chemistry', 'When filter alum [Al2(SO4)3 · 18 H2O] is added as a coagulant to water containing bicarbonate alkalinity, it forms an insoluble gelatinous precipitate of:', '[{"id":"A","text":"Aluminium hydroxide [Al(OH)3]"},{"id":"B","text":"Aluminium oxide [Al2O3]"},{"id":"C","text":"Calcium sulphate [CaSO4]"},{"id":"D","text":"Aluminium carbonate [Al2(CO3)3]"}]'::jsonb, 'Aluminium hydroxide [Al(OH)3]', 'Aluminium oxide [Al2O3]', 'Calcium sulphate [CaSO4]', 'Aluminium carbonate [Al2(CO3)3]', 'A', 'Alum reacts with calcium bicarbonate natural alkalinity in water to produce aluminium hydroxide Al(OH)3 floc precipitate, which traps and sweeps colloidal turbidity. It releases CO2, which increases acidity and decreases water pH.', 'Al2(SO4)3 + 3 Ca(HCO3)2 -> 2 Al(OH)3 ↓ + 3 CaSO4 + 6 CO2', NULL, 'Environmental Engineering by Peavy, Rowe & Tchobanoglous', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-068', 'apsc-ae-civil', 68, 'Environmental Engineering', 'Water Treatment', 'Sedimentation Tank Overflow Rate', 'In a continuous flow horizontal sedimentation tank of length L, width B, and depth H treating discharge Q, the surface overflow rate (SOR or Vo) is:', '[{"id":"A","text":"Vo = Q / (B · L)"},{"id":"B","text":"Vo = Q / (B · H)"},{"id":"C","text":"Vo = Q / (L · H)"},{"id":"D","text":"Vo = Q / (B · L · H)"}]'::jsonb, 'Vo = Q / (B · L)', 'Vo = Q / (B · H)', 'Vo = Q / (L · H)', 'Vo = Q / (B · L · H)', 'A', 'Surface overflow rate (SOR) is defined as discharge divided by plan surface area: Vo = Q / (B · L). Particles having settling velocity Vs ≥ Vo are 100% removed, while particles with Vs < Vo have removal efficiency η = (Vs / Vo) · 100%.', 'Vo = Q / (B · L) = Q / Plan Area', NULL, 'Water Supply Engineering by B.C. Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-069', 'apsc-ae-civil', 69, 'Environmental Engineering', 'Filtration', 'Rapid vs Slow Sand Filters', 'Compared to a slow sand filter, a rapid sand filter has a rate of filtration that is approximately:', '[{"id":"A","text":"30 times higher (3000 - 6000 L/m²/hr vs 100 - 200 L/m²/hr)"},{"id":"B","text":"Equal"},{"id":"C","text":"10 times lower"},{"id":"D","text":"2 times higher"}]'::jsonb, '30 times higher (3000 - 6000 L/m²/hr vs 100 - 200 L/m²/hr)', 'Equal', '10 times lower', '2 times higher', 'A', 'Rapid sand filters use coarser sand (effective size 0.45 - 0.70 mm) and operate at filtration rates of 3000 to 6000 L/m²/hr (about 30 times faster than slow sand filters). They require chemical coagulation pretreatment and backwashing.', 'Rapid Sand Filter rate = 3000 - 6000 L/hr/m²; Slow Sand Filter = 100 - 200 L/hr/m²', NULL, 'Water and Wastewater Technology by Hammer', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-070', 'apsc-ae-civil', 70, 'Environmental Engineering', 'Disinfection', 'Breakpoint Chlorination', 'In water treatment, ''Breakpoint Chlorination'' signifies the point where:', '[{"id":"A","text":"All chlorine added is completely absorbed without any residual"},{"id":"B","text":"All combined chlorine (chloramines) and organic matter are oxidized, and free available residual chlorine begins to appear"},{"id":"C","text":"Water pipes break due to high chemical corrosion"},{"id":"D","text":"Chlorine demand reaches infinity"}]'::jsonb, 'All chlorine added is completely absorbed without any residual', 'All combined chlorine (chloramines) and organic matter are oxidized, and free available residual chlorine begins to appear', 'Water pipes break due to high chemical corrosion', 'Chlorine demand reaches infinity', 'B', 'Up to the breakpoint, applied chlorine is consumed oxidising reducing compounds and forming chloramines. At the dip (breakpoint), chloramines are completely destroyed by oxidation. Beyond breakpoint, added chlorine appears as free residual chlorine (HOCl and OCl⁻).', 'Breakpoint: Free available chlorine (HOCl + OCl⁻) appears linearly with dosage', NULL, 'Water Supply Engineering by S.K. Garg', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-071', 'apsc-ae-civil', 71, 'Environmental Engineering', 'Wastewater Characteristics', 'BOD 5-Day Kinetics', 'The 5-day Biochemical Oxygen Demand (BOD5) at 20°C of domestic wastewater is approximately what percentage of its ultimate carbonaceous BOD (L0)?', '[{"id":"A","text":"50%"},{"id":"B","text":"68%"},{"id":"C","text":"85%"},{"id":"D","text":"99%"}]'::jsonb, '50%', '68%', '85%', '99%', 'B', 'Using first-order deoxygenation kinetics with standard deoxygenation constant k = 0.10 day⁻¹ (base 10) at 20°C: BOD5 = L0 · (1 - 10^(-0.1 · 5)) = L0 · (1 - 10^-0.5) = L0 · (1 - 0.316) ≈ 0.684 · L0 (approximately 68%).', 'BOD5 = L0 · (1 - 10^(-k · 5)) ≈ 0.68 · L0 for k = 0.1 day⁻¹ (base 10)', NULL, 'Wastewater Engineering by Metcalf & Eddy', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-072', 'apsc-ae-civil', 72, 'Environmental Engineering', 'Sewer Design', 'Self-Cleansing Velocity', 'To prevent deposition of suspended solids and silting in sanitary sewers, the minimum self-cleansing velocity recommended is approximately:', '[{"id":"A","text":"0.20 to 0.30 m/s"},{"id":"B","text":"0.60 to 0.75 m/s"},{"id":"C","text":"2.5 to 3.0 m/s"},{"id":"D","text":"5.0 m/s"}]'::jsonb, '0.20 to 0.30 m/s', '0.60 to 0.75 m/s', '2.5 to 3.0 m/s', '5.0 m/s', 'B', 'A minimum flow velocity of 0.60 m/s at present peak flow (and 0.75 m/s at design full flow) is required to scour silt and organic debris. Maximum velocity is limited to 2.5 - 3.0 m/s to prevent abrasive erosion of sewer pipes.', 'Vmin = 0.60 - 0.75 m/s; Vmax (non-scouring) = 2.5 - 3.0 m/s', NULL, 'Manual on Sewerage & Sewage Treatment (CPHEEO)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-073', 'apsc-ae-civil', 73, 'Environmental Engineering', 'Biological Treatment', 'Activated Sludge Process (ASP) F/M Ratio', 'In a conventional Activated Sludge Process (ASP), the food-to-microorganism ratio (F/M ratio) expressed in kg BOD per day per kg MLSS is typically maintained between:', '[{"id":"A","text":"0.2 to 0.4"},{"id":"B","text":"0.01 to 0.05"},{"id":"C","text":"1.0 to 2.0"},{"id":"D","text":"5.0 to 10.0"}]'::jsonb, '0.2 to 0.4', '0.01 to 0.05', '1.0 to 2.0', '5.0 to 10.0', 'A', 'In conventional aeration tanks, F/M ratio is maintained around 0.2 to 0.4 kg BOD/kg MLSS/day with a sludge retention time (sludge age) of 5 to 15 days, ensuring stable bio-oxidation and good sludge settling.', 'F/M = (Q · S0) / (V · X) ≈ 0.2 to 0.4 day⁻¹', NULL, 'Wastewater Engineering by Metcalf & Eddy', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-074', 'apsc-ae-civil', 74, 'Environmental Engineering', 'Onsite Sanitation', 'Septic Tank Detention Time', 'As per IS 2470, the liquid detention period for standard domestic septic tanks is usually designed for:', '[{"id":"A","text":"2 to 4 hours"},{"id":"B","text":"12 to 24 hours"},{"id":"C","text":"3 to 5 days"},{"id":"D","text":"7 to 10 days"}]'::jsonb, '2 to 4 hours', '12 to 24 hours', '3 to 5 days', '7 to 10 days', 'B', 'IS 2470 recommends a liquid detention time of 12 to 24 hours (commonly 24 hours) to allow solids settling, flotation of scum, and initiation of anaerobic sludge digestion.', 'Septic tank detention period = 12 - 24 hours', NULL, 'IS 2470 (Part 1):1985 Code of Practice for Septic Tanks', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-075', 'apsc-ae-civil', 75, 'Surveying & Geomatics', 'Principles of Surveying', 'Whole to Part Principle', 'The fundamental principle of ''working from whole to part'' is adopted in surveying primarily to:', '[{"id":"A","text":"Distribute work among more surveyors"},{"id":"B","text":"Prevent accumulation of local errors and localize measurement errors"},{"id":"C","text":"Minimize the number of instruments required"},{"id":"D","text":"Survey the perimeter before taking any inside readings"}]'::jsonb, 'Distribute work among more surveyors', 'Prevent accumulation of local errors and localize measurement errors', 'Minimize the number of instruments required', 'Survey the perimeter before taking any inside readings', 'B', 'By establishing a primary, highly accurate network of major control points covering the entire area first and then filling in minor details, errors occurring in minor measurements remain confined locally and do not magnify.', 'Working from whole to part localizes errors and prevents catastrophic error propagation', NULL, 'Surveying Vol. 1 by B.C. Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-076', 'apsc-ae-civil', 76, 'Surveying & Geomatics', 'Linear Measurements', 'Sag Correction for Tape', 'The correction for sag in a surveying tape suspended between two supports is:', '[{"id":"A","text":"Always additive (+)"},{"id":"B","text":"Always subtractive (-)"},{"id":"C","text":"Positive or negative depending on pull applied"},{"id":"D","text":"Zero for steel tapes"}]'::jsonb, 'Always additive (+)', 'Always subtractive (-)', 'Positive or negative depending on pull applied', 'Zero for steel tapes', 'B', 'A suspended tape sags into a catenary curve, so the curved distance along the tape is always longer than the true straight chord distance between supports. The measured distance is too long, so the sag correction is ALWAYS negative (-).', 'Cs = - W² · L / (24 · P²)', NULL, 'Surveying Vol. 1 by K.R. Arora', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-077', 'apsc-ae-civil', 77, 'Surveying & Geomatics', 'Compass Surveying', 'Local Attraction Detection', 'In compass surveying, a line is confirmed to be free from local attraction if the difference between its Fore Bearing (FB) and Back Bearing (BB) is exactly:', '[{"id":"A","text":"90°"},{"id":"B","text":"180°"},{"id":"C","text":"270°"},{"id":"D","text":"360°"}]'::jsonb, '90°', '180°', '270°', '360°', 'B', 'For any line AB, the back bearing and fore bearing must differ by exactly 180° if both station A and station B are free from magnetic disturbances (local attraction).', '|FB - BB| = 180°', NULL, 'Surveying and Levelling by N.N. Basak', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-078', 'apsc-ae-civil', 78, 'Surveying & Geomatics', 'Levelling', 'Arithmetical Checks in Levelling', 'Which of the following arithmetical checks is applicable to both Height of Instrument (HI) method and Rise & Fall method of levelling?', '[{"id":"A","text":"Σ BS - Σ FS = Last RL - First RL"},{"id":"B","text":"Σ Rise - Σ Fall = Last RL - First RL"},{"id":"C","text":"Σ BS - Σ FS = Σ Rise - Σ Fall = Last RL - First RL"},{"id":"D","text":"Σ IS - Σ FS = Last RL - First RL"}]'::jsonb, 'Σ BS - Σ FS = Last RL - First RL', 'Σ Rise - Σ Fall = Last RL - First RL', 'Σ BS - Σ FS = Σ Rise - Σ Fall = Last RL - First RL', 'Σ IS - Σ FS = Last RL - First RL', 'A', 'The check Σ BS - Σ FS = Last RL - First RL applies to both methods. The Rise and Fall method has the complete three-part check: Σ BS - Σ FS = Σ Rise - Σ Fall = Last RL - First RL, making it superior for checking intermediate sights.', 'Σ BS - Σ FS = Last RL - First RL (universal check)', NULL, 'Surveying by Duggal', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-079', 'apsc-ae-civil', 79, 'Surveying & Geomatics', 'Levelling', 'Curvature and Refraction Correction', 'In precise levelling over a sight distance of d (in km), the combined correction for curvature and refraction (in meters) is given by:', '[{"id":"A","text":"C = -0.0673 · d²"},{"id":"B","text":"C = +0.0785 · d²"},{"id":"C","text":"C = -0.0112 · d²"},{"id":"D","text":"C = -0.0562 · d²"}]'::jsonb, 'C = -0.0673 · d²', 'C = +0.0785 · d²', 'C = -0.0112 · d²', 'C = -0.0562 · d²', 'A', 'Earth''s curvature increases staff reading (Cc = -0.0785 d²), while atmospheric refraction bends light downward decreasing staff reading (Cr = +0.0112 d² = Cc/7). Combined correction is C = -0.0673 d² meters.', 'C = Cc + Cr = -0.0785 d² + 0.0112 d² = -0.0673 d² (m)', NULL, 'Higher Surveying by A.M. Chandra', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-080', 'apsc-ae-civil', 80, 'Surveying & Geomatics', 'Contouring', 'Contour Characteristics', 'Contour lines can cross each other only in the rare case of:', '[{"id":"A","text":"A vertical cliff"},{"id":"B","text":"An overhanging cliff or a natural cave"},{"id":"C","text":"A ridge line"},{"id":"D","text":"A saddle point"}]'::jsonb, 'A vertical cliff', 'An overhanging cliff or a natural cave', 'A ridge line', 'A saddle point', 'B', 'Contour lines can never cross or intersect except in the case of an overhanging cliff or a cave where two different elevations occur at the same plan coordinates. In a vertical cliff, contour lines unite to form a single line.', 'Contours cross each other ONLY at overhanging cliffs and caves', NULL, 'Surveying by Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-081', 'apsc-ae-civil', 81, 'Surveying & Geomatics', 'Theodolite & Traverse', 'Bowditch''s Rule', 'Bowditch''s rule for balancing a closed traverse is applied when:', '[{"id":"A","text":"Linear measurements and angular measurements are of equal precision"},{"id":"B","text":"Angular measurements are more precise than linear measurements"},{"id":"C","text":"Linear measurements are more precise than angular measurements"},{"id":"D","text":"Only astronomical bearings are observed"}]'::jsonb, 'Linear measurements and angular measurements are of equal precision', 'Angular measurements are more precise than linear measurements', 'Linear measurements are more precise than angular measurements', 'Only astronomical bearings are observed', 'A', 'Bowditch''s (compass) rule assumes that accidental errors in linear measurements are proportional to √L and in angular measurements are proportional to 1/√L. It balances traverse by distributing errors in latitude and departure proportional to side lengths.', 'Correction to Latitude = (Total Latitude Error) · (Length of side / Perimeter of traverse)', NULL, 'Surveying Vol. 2 by Punmia', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-082', 'apsc-ae-civil', 82, 'Surveying & Geomatics', 'Curves', 'Degree of Curve Definition', 'For a 30-meter chord or arc definition, the degree of circular curve (D in degrees) is related to radius of curve (R in meters) by:', '[{"id":"A","text":"D = 1718.9 / R"},{"id":"B","text":"D = 1145.9 / R"},{"id":"C","text":"D = 572.9 / R"},{"id":"D","text":"D = 2000 / R"}]'::jsonb, 'D = 1718.9 / R', 'D = 1145.9 / R', 'D = 572.9 / R', 'D = 2000 / R', 'A', 'For an arc length of 30 m: Arc = R · (D · π / 180) => 30 = R · D · 0.017453 => D = 30 / (0.017453 · R) = 1718.87 / R ≈ 1719 / R. For 20m arc, D = 1146 / R.', 'D = 1718.9 / R (for 30m chain); D = 1145.9 / R (for 20m chain)', NULL, 'Surveying by Kanetkar & Kulkarni', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-083', 'apsc-ae-civil', 83, 'Highway & Transportation Engineering', 'Highway Planning', 'Nagpur Road Plan Pattern', 'The First 20-Year Road Development Plan (Nagpur Road Plan 1943-1963) recommended which road network pattern for India?', '[{"id":"A","text":"Star and Grid pattern"},{"id":"B","text":"Radial and Circular pattern"},{"id":"C","text":"Hexagonal pattern"},{"id":"D","text":"Gridiron pattern"}]'::jsonb, 'Star and Grid pattern', 'Radial and Circular pattern', 'Hexagonal pattern', 'Gridiron pattern', 'A', 'Nagpur Road Congress classified roads into NH, SH, MDR, ODR, and VR, adopting the ''Star and Grid'' pattern with an overall target road density of 16 km / 100 km².', 'Target road density = 16 km per 100 sq km area', NULL, 'Highway Engineering by Khanna & Justo', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-084', 'apsc-ae-civil', 84, 'Highway & Transportation Engineering', 'Geometric Design', 'Stopping Sight Distance (SSD)', 'As per IRC guidelines, what is the design perception-reaction time (t) assumed in the calculation of Stopping Sight Distance (SSD) under PIEV theory?', '[{"id":"A","text":"2.5 seconds"},{"id":"B","text":"2.0 seconds"},{"id":"C","text":"1.5 seconds"},{"id":"D","text":"0.75 seconds"}]'::jsonb, '2.5 seconds', '2.0 seconds', '1.5 seconds', '0.75 seconds', 'A', 'IRC recommends a perception-reaction time of 2.5 seconds for SSD calculations based on PIEV (Perception, Intellection, Emotion, Volition) theory. For Overtaking Sight Distance (OSD), reaction time is taken as 2.0 seconds.', 'SSD = 0.278 · v · t + v² / (254 · f); t = 2.5 s', NULL, 'IRC:73-1980 Geometric Design Standards', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-085', 'apsc-ae-civil', 85, 'Highway & Transportation Engineering', 'Geometric Design', 'Super-elevation for Mixed Traffic', 'As per IRC recommendations for mixed traffic on plain and rolling terrain, super-elevation (e) is designed by neglecting lateral friction and considering what percentage of design speed (V)?', '[{"id":"A","text":"75% of design speed (e = V² / 225 R)"},{"id":"B","text":"100% of design speed (e = V² / 127 R)"},{"id":"C","text":"50% of design speed"},{"id":"D","text":"90% of design speed"}]'::jsonb, '75% of design speed (e = V² / 225 R)', '100% of design speed (e = V² / 127 R)', '50% of design speed', '90% of design speed', 'A', 'To accommodate slow-moving bullock carts and fast motor vehicles on Indian roads, IRC designs super-elevation to fully counter centrifugal force at 75% of design speed (f = 0): e = (0.75 V)² / (127 R) = V² / (225 R). Maximum e is capped at 7% for plain/rolling terrain.', 'e = (0.75 V)² / (127 R) = V² / (225 R)', NULL, 'Highway Engineering by Khanna & Justo', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-086', 'apsc-ae-civil', 86, 'Highway & Transportation Engineering', 'Geometric Design', 'Maximum Super-elevation Limits', 'As per IRC, what is the maximum permissible super-elevation (emax) on horizontal curves in plain and rolling terrain?', '[{"id":"A","text":"7.0% (1 in 14.3)"},{"id":"B","text":"10.0% (1 in 10)"},{"id":"C","text":"4.0% (1 in 25)"},{"id":"D","text":"12.0% (1 in 8.3)"}]'::jsonb, '7.0% (1 in 14.3)', '10.0% (1 in 10)', '4.0% (1 in 25)', '12.0% (1 in 8.3)', 'A', 'IRC caps super-elevation at 7% (0.07) for plain and rolling terrain. In hilly terrain not bound by snow, it is 10%. In urban areas with frequent intersections, it is limited to 4% to prevent toppling of slow tall vehicles.', 'emax = 7% (plain/rolling), 10% (hilly without snow), 4% (urban with frequent intersections)', NULL, 'IRC:73 Guidelines', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-087', 'apsc-ae-civil', 87, 'Highway & Transportation Engineering', 'Geometric Design', 'Extra Widening on Curves', 'The total extra widening (We) required on a two-lane horizontal curve of radius R with wheelbase l and design speed V (in km/h) is:', '[{"id":"A","text":"We = (n · l² / (2 · R)) + (V / (9.5 · √R))"},{"id":"B","text":"We = (n · l / (2 · R)) + (V / (225 · R))"},{"id":"C","text":"We = (n · l² / R) + (V / (9.5 · √R))"},{"id":"D","text":"We = n · l² / (2 · R)"}]'::jsonb, 'We = (n · l² / (2 · R)) + (V / (9.5 · √R))', 'We = (n · l / (2 · R)) + (V / (225 · R))', 'We = (n · l² / R) + (V / (9.5 · √R))', 'We = n · l² / (2 · R)', 'A', 'Total extra widening consists of Mechanical widening (off-tracking of rear axle Wm = n l² / 2R) plus Psychological widening (for driver ease and transverse clearances Wps = V / 9.5 √R).', 'We = Wm + Wps = (n · l² / (2 · R)) + (V / (9.5 · √R))', NULL, 'Highway Engineering by Kadiyali', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-088', 'apsc-ae-civil', 88, 'Highway & Transportation Engineering', 'Geometric Design', 'Ideal Transition Curve', 'The ideal shape of a transition curve adopted in Indian highway engineering practice is:', '[{"id":"A","text":"Clothoid (Euler''s Spiral)"},{"id":"B","text":"Cubic Parabola"},{"id":"C","text":"Lemniscate"},{"id":"D","text":"Circular Arc"}]'::jsonb, 'Clothoid (Euler''s Spiral)', 'Cubic Parabola', 'Lemniscate', 'Circular Arc', 'A', 'IRC recommends the Euler spiral (clothoid) because the rate of change of centrifugal acceleration is strictly uniform throughout, and radius decreases linearly with curve length from infinity to circular radius R.', 'Transition curve: Radius R is inversely proportional to length L (L · R = Constant)', NULL, 'Highway Engineering by Khanna & Justo', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-089', 'apsc-ae-civil', 89, 'Highway & Transportation Engineering', 'Pavement Materials', 'California Bearing Ratio (CBR) Test', 'In the standard CBR test on subgrade soil, what is the standard load on crushed stone corresponding to 2.5 mm plunger penetration?', '[{"id":"A","text":"1370 kg (13.44 kN)"},{"id":"B","text":"2055 kg (20.15 kN)"},{"id":"C","text":"1000 kg (9.81 kN)"},{"id":"D","text":"3000 kg (29.43 kN)"}]'::jsonb, '1370 kg (13.44 kN)', '2055 kg (20.15 kN)', '1000 kg (9.81 kN)', '3000 kg (29.43 kN)', 'A', 'CBR (%) = (Test load / Standard load) · 100. The standard loads on high quality crushed stone are 1370 kg for 2.5 mm penetration and 2055 kg for 5.0 mm penetration. Usually CBR at 2.5 mm is higher and taken as design CBR.', 'Standard load at 2.5 mm = 1370 kg (70 kg/cm²); Standard load at 5.0 mm = 2055 kg (105 kg/cm²)', NULL, 'IS 2720 (Part 16) CBR Test Code', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-090', 'apsc-ae-civil', 90, 'Highway & Transportation Engineering', 'Pavement Design', 'Flexible vs Rigid Pavements', 'Wheel load stresses in a flexible pavement are transferred to underlying layers predominantly through:', '[{"id":"A","text":"Grain-to-grain contact pressure distribution"},{"id":"B","text":"Slab flexural bending action"},{"id":"C","text":"Shear membrane action only"},{"id":"D","text":"Tension in bitumen layers"}]'::jsonb, 'Grain-to-grain contact pressure distribution', 'Slab flexural bending action', 'Shear membrane action only', 'Tension in bitumen layers', 'A', 'Flexible pavements distribute concentrated wheel loads downward over larger areas through inter-granular particle contact and friction, reducing stress intensity. Rigid pavements (PQC) carry loads through flexural slab action.', 'Flexible pavement: Grain-to-grain contact; Rigid pavement: Slab flexural rigidity', NULL, 'IRC:37-2018 Guidelines for Flexible Pavement Design', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-091', 'apsc-ae-civil', 91, 'Design of Steel Structures', 'General Design Requirements', 'Partial Safety Factors in IS 800:2007', 'As per IS 800:2007 Table 5, the partial safety factor for material strength against yielding (γm0) and against ultimate tensile strength (γm1) are:', '[{"id":"A","text":"1.10 and 1.25 respectively"},{"id":"B","text":"1.15 and 1.50 respectively"},{"id":"C","text":"1.25 and 1.10 respectively"},{"id":"D","text":"1.00 and 1.25 respectively"}]'::jsonb, '1.10 and 1.25 respectively', '1.15 and 1.50 respectively', '1.25 and 1.10 respectively', '1.00 and 1.25 respectively', 'A', 'Per IS 800:2007 Table 5, resistance governed by yielding of cross-section uses γm0 = 1.10; resistance governed by ultimate rupture at net section uses γm1 = 1.25; shop welds use γmw = 1.25, and field welds use γmw = 1.50.', 'γm0 = 1.10 (yielding); γm1 = 1.25 (ultimate tension / rupture)', NULL, 'IS 800:2007 Table 5', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-092', 'apsc-ae-civil', 92, 'Design of Steel Structures', 'Tension Members', 'Net Section Rupture & Shear Lag', 'When a single angle tension member is connected to a gusset plate by only one leg, the phenomenon causing non-uniform stress distribution across the angle section is known as:', '[{"id":"A","text":"Shear lag effect"},{"id":"B","text":"P-Delta effect"},{"id":"C","text":"Wobble effect"},{"id":"D","text":"Poisson expansion"}]'::jsonb, 'Shear lag effect', 'P-Delta effect', 'Wobble effect', 'Poisson expansion', 'A', 'Because tensile load is transferred through the connected leg, the outstanding leg does not participate fully at the connection. The resulting non-uniform tensile stress concentration is called the ''Shear Lag Effect''.', 'Tdn = 0.9 · Anc · fu / γm1 + β · Ago · fy / γm0 (IS 800 Cl. 6.3.3)', NULL, 'Design of Steel Structures by S.K. Duggal', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-093', 'apsc-ae-civil', 93, 'Design of Steel Structures', 'Compression Members', 'Maximum Slenderness Ratio Limits', 'As per IS 800:2007 Table 3, what is the maximum permissible slenderness ratio (λ = kL/r) for a member carrying compressive loads resulting from dead loads and superimposed live loads?', '[{"id":"A","text":"180"},{"id":"B","text":"250"},{"id":"C","text":"300"},{"id":"D","text":"350"}]'::jsonb, '180', '250', '300', '350', 'A', 'IS 800 Table 3 specifies: A member carrying compressive loads from dead loads and imposed loads shall have slenderness ratio λ ≤ 180. For wind/earthquake compression, λ ≤ 250. For members acting solely in tension (hangers), λ ≤ 400.', 'λmax = 180 (Dead Load + Imposed Load compression)', NULL, 'IS 800:2007 Table 3', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-094', 'apsc-ae-civil', 94, 'Design of Steel Structures', 'Welded Connections', 'Effective Throat Thickness of Fillet Weld', 'For a standard fillet weld with an angle between fusion faces of 90°, the effective throat thickness (t) is related to leg size (s) by:', '[{"id":"A","text":"t = 0.70 · s"},{"id":"B","text":"t = 0.50 · s"},{"id":"C","text":"t = 0.60 · s"},{"id":"D","text":"t = 1.00 · s"}]'::jsonb, 't = 0.70 · s', 't = 0.50 · s', 't = 0.60 · s', 't = 1.00 · s', 'A', 'Per IS 800:2007 Clause 10.5.3, effective throat thickness is t = k · s. For angles between fusion faces: 60°-90°: k = 0.70; 91°-100°: k = 0.65; 101°-106°: k = 0.60; 107°-113°: k = 0.55; 114°-120°: k = 0.50.', 't = k · s, where k = 0.70 for 60°-90° fusion angle', NULL, 'IS 800:2007 Cl. 10.5.3', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-095', 'apsc-ae-civil', 95, 'Design of Steel Structures', 'Bolted Connections', 'Minimum Pitch and Edge Distance', 'As per IS 800:2007, the minimum pitch distance between centers of fasteners shall not be less than:', '[{"id":"A","text":"2.5 times the nominal diameter of fastener (2.5 d)"},{"id":"B","text":"1.5 times the diameter"},{"id":"C","text":"3.0 times the diameter"},{"id":"D","text":"50 mm"}]'::jsonb, '2.5 times the nominal diameter of fastener (2.5 d)', '1.5 times the diameter', '3.0 times the diameter', '50 mm', 'A', 'Clause 10.2.2 of IS 800 specifies that the distance between centers of fasteners (pitch) shall not be less than 2.5 times the nominal diameter of the fastener to avoid bearing failure between adjacent holes.', 'pmin = 2.5 · d', NULL, 'IS 800:2007 Cl. 10.2.2', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2021, 'Testbook Model / APSC AE Civil 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-096', 'apsc-ae-civil', 96, 'Building Materials & Construction Management', 'Cement & Concrete', 'Bogue Compounds Hydration', 'Which Bogue compound in Portland cement is responsible for early strength development within the first 7 to 14 days?', '[{"id":"A","text":"Tricalcium Silicate (C3S - Alite)"},{"id":"B","text":"Dicalcium Silicate (C2S - Belite)"},{"id":"C","text":"Tricalcium Aluminate (C3A - Celite)"},{"id":"D","text":"Tetracalcium Aluminoferrite (C4AF - Felite)"}]'::jsonb, 'Tricalcium Silicate (C3S - Alite)', 'Dicalcium Silicate (C2S - Belite)', 'Tricalcium Aluminate (C3A - Celite)', 'Tetracalcium Aluminoferrite (C4AF - Felite)', 'A', 'C3S (Alite, 3CaO·SiO2) hydrates rapidly and contributes to early strength up to 14 days. C2S hydrates slowly and imparts progressive long-term strength. C3A causes flash setting and produces the highest heat of hydration.', 'C3S imparts early strength; C2S imparts progressive late strength after 28 days', NULL, 'Concrete Technology by M.S. Shetty', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-097', 'apsc-ae-civil', 97, 'Building Materials & Construction Management', 'Cement Testing', 'Setting Times of OPC per IS 4031', 'As per Indian Standards, the initial and final setting times for Ordinary Portland Cement (OPC) shall be:', '[{"id":"A","text":"Not less than 30 minutes and not more than 600 minutes (10 hours)"},{"id":"B","text":"Not less than 60 minutes and not more than 300 minutes"},{"id":"C","text":"Not less than 15 minutes and not more than 120 minutes"},{"id":"D","text":"Not less than 45 minutes and not more than 720 minutes"}]'::jsonb, 'Not less than 30 minutes and not more than 600 minutes (10 hours)', 'Not less than 60 minutes and not more than 300 minutes', 'Not less than 15 minutes and not more than 120 minutes', 'Not less than 45 minutes and not more than 720 minutes', 'A', 'Per IS 269 and IS 4031: Initial setting time (measured with 1 mm square needle) must be ≥ 30 minutes. Final setting time (measured with annular collar needle) must be ≤ 600 minutes (10 hours).', 'Initial setting ≥ 30 mins; Final setting ≤ 600 mins (10 hrs) (Vicat apparatus)', NULL, 'IS 269:2015 Specification for OPC', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-098', 'apsc-ae-civil', 98, 'Building Materials & Construction Management', 'Concrete Technology', 'Workability Measurement', 'For very low workability concrete (such as stiff dry mixes used for road roller-compacted concrete), the most appropriate test is:', '[{"id":"A","text":"Vee-Bee consistometer test"},{"id":"B","text":"Slump cone test"},{"id":"C","text":"Compacting factor test"},{"id":"D","text":"Flow table test"}]'::jsonb, 'Vee-Bee consistometer test', 'Slump cone test', 'Compacting factor test', 'Flow table test', 'A', 'Slump test is unreliable for dry/lean mixes. Compacting factor test is suitable for low-to-medium workability. Vee-Bee consistometer measures the time (in seconds) required for vibration to transform a conical slump into a flat surface, ideal for stiff dry mixes.', 'Very low workability: Vee-Bee test (time in seconds); High workability: Slump test', NULL, 'Concrete Technology by Gambhir', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2022, 'Testbook Model / APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-099', 'apsc-ae-civil', 99, 'Building Materials & Construction Management', 'Network Analysis (CPM/PERT)', 'Expected Time Duration in PERT', 'In PERT analysis, given optimistic time (to), most likely time (tm), and pessimistic time (tp), the expected activity time (te) assuming a Beta distribution is:', '[{"id":"A","text":"te = (to + 4 · tm + tp) / 6"},{"id":"B","text":"te = (to + tm + tp) / 3"},{"id":"C","text":"te = (to + 2 · tm + tp) / 4"},{"id":"D","text":"te = (to + 6 · tm + tp) / 8"}]'::jsonb, 'te = (to + 4 · tm + tp) / 6', 'te = (to + tm + tp) / 3', 'te = (to + 2 · tm + tp) / 4', 'te = (to + 6 · tm + tp) / 8', 'A', 'PERT assumes a Beta probability distribution for activity duration. The weighted mean is te = (to + 4 tm + tp) / 6, and standard deviation is σ = (tp - to) / 6.', 'te = (to + 4 · tm + tp) / 6; Variance σ² = ((tp - to) / 6)²', NULL, 'Project Management with CPM/PERT by Punmia & Khandelwal', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2024, 'Testbook Model / APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ce-q-100', 'apsc-ae-civil', 100, 'Building Materials & Construction Management', 'CPM Project Scheduling', 'Total Float Definition', 'In Critical Path Method (CPM), the ''Total Float'' of an activity represents:', '[{"id":"A","text":"The maximum time by which an activity can be delayed without delaying project completion date"},{"id":"B","text":"The time by which an activity can be delayed without delaying the start of succeeding activity"},{"id":"C","text":"The float that affects preceding activities only"},{"id":"D","text":"The minimum contingency reserve duration"}]'::jsonb, 'The maximum time by which an activity can be delayed without delaying project completion date', 'The time by which an activity can be delayed without delaying the start of succeeding activity', 'The float that affects preceding activities only', 'The minimum contingency reserve duration', 'A', 'Total Float is the total margin of time available to delay an activity without extending the project completion deadline. Free float delays neither the project nor succeeding activities. Critical activities have Total Float = 0.', 'Total Float = LFT - EFT = LST - EST; Free Float = EST(j) - EFT(ij)', NULL, 'Construction Planning & Management by U.K. Shrivastava', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', 2023, 'Testbook Model / APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-bm-001', 'apsc-ae-civil', 301, 'Building Materials & Construction', 'Cement & Concrete Technology', 'Bogue Compounds & Hydration', 'Which of the following Bogue compounds of Portland cement hydrates most rapidly and is primarily responsible for the initial setting time of concrete?', '[{"id":"A","text":"Tricalcium silicate (C3S)"},{"id":"B","text":"Dicalcium silicate (C2S)"},{"id":"C","text":"Tricalcium aluminate (C3A)"},{"id":"D","text":"Tetracalcium aluminoferrite (C4AF)"}]'::jsonb, 'Tricalcium silicate (C3S)', 'Dicalcium silicate (C2S)', 'Tricalcium aluminate (C3A)', 'Tetracalcium aluminoferrite (C4AF)', 'C', 'Tricalcium aluminate (C3A) hydrates within the first 24 hours, releasing high heat of hydration (~865 J/g) and causing flash set if gypsum is not added. C3S provides early strength (first 7-28 days), while C2S hydrates slowly and provides progressive ultimate strength.', 'Hydration Rate: C3A > C4AF > C3S > C2S', NULL, 'IS 269:2015 & Shetty Concrete Technology', 'EASY', 'CONCEPTUAL', 'MODELLED', 2024, 'APSC AE Civil 2024 / Testbook State AE Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-bm-002', 'upsc-ies-civil', 302, 'Building Materials & Construction', 'Concrete Mix & Testing', 'Workability & Testing Methods', 'Consider the following statements regarding the workability measurement of fresh concrete:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-bm-003', 'apsc-ae-civil', 303, 'Building Materials & Construction', 'Aggregates & Tests', 'Flakiness and Elongation', 'As per IS 2386 (Part 1), an aggregate particle is defined as "flaky" if its least dimension (thickness) is less than:', '[{"id":"A","text":"0.6 times its mean sieve dimension"},{"id":"B","text":"0.8 times its mean sieve dimension"},{"id":"C","text":"1.8 times its mean sieve dimension"},{"id":"D","text":"0.5 times its mean sieve dimension"}]'::jsonb, '0.6 times its mean sieve dimension', '0.8 times its mean sieve dimension', '1.8 times its mean sieve dimension', '0.5 times its mean sieve dimension', 'A', 'According to IS 2386 (Part 1), an aggregate particle is classified as flaky if its thickness is less than 0.6 (or 3/5) of its mean sieve dimension. It is elongated if its length exceeds 1.8 (or 9/5) times the mean sieve dimension.', 'Flakiness: t < 0.6 · d_mean ; Elongation: L > 1.8 · d_mean', NULL, 'IS 2386 (Part 1):1963, Cl. 4.2', 'EASY', 'CODE_RULE_BASED', 'MODELLED', 2023, 'APSC CCE / Testbook Civil AE Pack') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-bm-004', 'upsc-ies-civil', 304, 'Building Materials & Construction', 'Timber & Defects', 'Seasoning & Moisture Content', 'In the context of timber technology, what is the Fiber Saturation Point (FSP), and what happens when timber dries below the FSP?', '[{"id":"A","text":"FSP is around 12% moisture; drying below it increases weight without shrinkage"},{"id":"B","text":"FSP is around 25-30% moisture; drying below it initiates dimensional shrinkage and increases strength"},{"id":"C","text":"FSP is 100% moisture; drying below it causes fungal decay"},{"id":"D","text":"FSP is 50% moisture; drying below it reduces modulus of elasticity"}]'::jsonb, 'FSP is around 12% moisture; drying below it increases weight without shrinkage', 'FSP is around 25-30% moisture; drying below it initiates dimensional shrinkage and increases strength', 'FSP is 100% moisture; drying below it causes fungal decay', 'FSP is 50% moisture; drying below it reduces modulus of elasticity', 'B', 'The Fiber Saturation Point is the moisture content (usually 25% to 30%) at which all free water from cell cavities has evaporated, while cell walls remain fully saturated. Removal of bound water below the FSP causes shrinkage, warping, and an increase in strength and elastic modulus.', 'Moisture content at FSP ≈ 25% to 30%', NULL, 'IS 399 & UPSC ESE 2021', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'UPSC ESE / Testbook Technical Test') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-som-001', 'apsc-ae-civil', 305, 'Strength of Materials', 'Elastic Constants', 'Interrelationships of E, G, K, μ', 'For an isotropic, linearly elastic material with Young''s modulus E = 200 GPa and Poisson''s ratio μ = 0.25, the Bulk Modulus (K) and Shear Modulus (G) are respectively:', '[{"id":"A","text":"K = 133.3 GPa, G = 80 GPa"},{"id":"B","text":"K = 80 GPa, G = 133.3 GPa"},{"id":"C","text":"K = 100 GPa, G = 80 GPa"},{"id":"D","text":"K = 133.3 GPa, G = 100 GPa"}]'::jsonb, 'K = 133.3 GPa, G = 80 GPa', 'K = 80 GPa, G = 133.3 GPa', 'K = 100 GPa, G = 80 GPa', 'K = 133.3 GPa, G = 100 GPa', 'A', '1. G = E / [2(1 + μ)] = 200 / [2(1 + 0.25)] = 200 / 2.5 = 80 GPa.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-som-002', 'upsc-ies-civil', 306, 'Strength of Materials', 'Principal Stresses & Mohr''s Circle', 'Pure Shear State', 'A state of plane stress is represented by σx = +80 MPa, σy = -80 MPa, and τxy = 0. What is the maximum in-plane shear stress and the orientation of the maximum shear stress plane?', '[{"id":"A","text":"τ_max = 80 MPa at 45° to the principal axes"},{"id":"B","text":"τ_max = 160 MPa at 90° to the principal axes"},{"id":"C","text":"τ_max = 40 MPa at 45° to the principal axes"},{"id":"D","text":"τ_max = 0 MPa"}]'::jsonb, 'τ_max = 80 MPa at 45° to the principal axes', 'τ_max = 160 MPa at 90° to the principal axes', 'τ_max = 40 MPa at 45° to the principal axes', 'τ_max = 0 MPa', 'A', 'The given stresses σx and σy are principal stresses (since τxy = 0). The center of Mohr''s circle is at (σx + σy)/2 = (80 - 80)/2 = 0. The radius R = (σ1 - σ2)/2 = 80 MPa. Maximum shear stress equals the radius, τ_max = 80 MPa, occurring at 2θ = 90° on Mohr''s circle, i.e., θ = 45° in the physical element.', 'τ_max = (σ1 - σ2) / 2 = [80 - (-80)] / 2 = 80 MPa', NULL, 'UPSC ESE 2020 / Testbook Strength of Materials', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'UPSC ESE / Testbook Advanced Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-som-003', 'upsc-ies-civil', 307, 'Strength of Materials', 'Columns & Struts', 'Euler''s Critical Buckling Load', 'A solid circular steel column of diameter D and length L is fixed at both ends. If the boundary conditions are changed such that one end is fixed and the other end is hinged, by what ratio does the Euler buckling load change?', '[{"id":"A","text":"Reduces by a factor of 2.0"},{"id":"B","text":"Decreases by approximately 49% (ratio ≈ 0.505)"},{"id":"C","text":"Increases by 25%"},{"id":"D","text":"Decreases to exactly 0.25 of its original value"}]'::jsonb, 'Reduces by a factor of 2.0', 'Decreases by approximately 49% (ratio ≈ 0.505)', 'Increases by 25%', 'Decreases to exactly 0.25 of its original value', 'B', 'For both ends fixed: L_e1 = 0.5 L → P1 = π²EI / (0.5L)² = 4 π²EI / L².
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-sa-001', 'apsc-ae-civil', 308, 'Structural Analysis', 'Static & Kinematic Indeterminacy', 'Plane Frames', 'A symmetrical single-bay, two-story rigid plane frame has fixed supports at the base. Neglecting axial deformations, what is the degree of kinematic indeterminacy (Dk)?', '[{"id":"A","text":"Dk = 4"},{"id":"B","text":"Dk = 6"},{"id":"C","text":"Dk = 8"},{"id":"D","text":"Dk = 12"}]'::jsonb, 'Dk = 4', 'Dk = 6', 'Dk = 8', 'Dk = 12', 'B', 'Number of joints j = 6 (2 base joints + 4 elevated beam-column joints).
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-sa-002', 'upsc-ies-civil', 309, 'Structural Analysis', 'Moment Distribution Method', 'Stiffness & Carry-Over Factors', 'In the Moment Distribution Method (Hardy Cross), when a moment M is applied at the near joint A of a uniform prismatic member AB, what is the rotational stiffness and carry-over factor to far end B if B is hinged?', '[{"id":"A","text":"Stiffness = 4EI/L, Carry-Over Factor = 0.5"},{"id":"B","text":"Stiffness = 3EI/L, Carry-Over Factor = 0"},{"id":"C","text":"Stiffness = 2EI/L, Carry-Over Factor = 0.5"},{"id":"D","text":"Stiffness = 4EI/L, Carry-Over Factor = -1.0"}]'::jsonb, 'Stiffness = 4EI/L, Carry-Over Factor = 0.5', 'Stiffness = 3EI/L, Carry-Over Factor = 0', 'Stiffness = 2EI/L, Carry-Over Factor = 0.5', 'Stiffness = 4EI/L, Carry-Over Factor = -1.0', 'B', 'When the far end is hinged, it cannot resist any bending moment (M_B = 0). Thus, no moment is carried over (COF = 0). The moment required to produce unit rotation at joint A is K = 3EI/L. If far end B were fixed, stiffness would be 4EI/L with COF = +1/2.', 'Far end hinged: K = 3EI/L, COF = 0 ; Far end fixed: K = 4EI/L, COF = 1/2', NULL, 'Ramamrutham Structural Analysis & UPSC ESE 2019', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2019, 'UPSC ESE / Testbook Advanced Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-rcc-001', 'apsc-ae-civil', 310, 'Reinforced Concrete Structures', 'IS 456:2000 Limit State Design', 'Maximum Shear Stress & Critical Section', 'As per IS 456:2000 Clause 40.2.3, the maximum shear stress in concrete with shear reinforcement (τc,max) for M25 grade concrete is:', '[{"id":"A","text":"2.5 MPa"},{"id":"B","text":"2.8 MPa"},{"id":"C","text":"3.1 MPa"},{"id":"D","text":"3.5 MPa"}]'::jsonb, '2.5 MPa', '2.8 MPa', '3.1 MPa', '3.5 MPa', 'C', 'Per IS 456:2000 Table 20:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-rcc-002', 'upsc-ies-civil', 311, 'Reinforced Concrete Structures', 'Prestressed Concrete IS 1343:2012', 'Prestress Losses & Load Balancing', 'A post-tensioned prestressed concrete beam of span 12 m is prestressed with a parabolic tendon having zero eccentricity at supports and an eccentricity "e" at midspan. If the tendon carries an effective prestressing force P, what upward equivalent distributed load does the tendon exert on the concrete beam?', '[{"id":"A","text":"w_eq = 4 P e / L²"},{"id":"B","text":"w_eq = 8 P e / L²"},{"id":"C","text":"w_eq = 12 P e / L²"},{"id":"D","text":"w_eq = 2 P e / L²"}]'::jsonb, 'w_eq = 4 P e / L²', 'w_eq = 8 P e / L²', 'w_eq = 12 P e / L²', 'w_eq = 2 P e / L²', 'B', 'By the load balancing concept (T.Y. Lin), a parabolic tendon profile with dip e acts as a suspended cable. From cable statics, the upward balancing pressure exerted on the concrete beam is w_eq = 8 P e / L². When w_eq matches the dead load of the beam, the member is subjected to pure axial compression without bending.', 'Equivalent upward load: w_eq = 8 P e / L²', NULL, 'IS 1343:2012 & Krishna Raju Prestressed Concrete', 'MEDIUM', 'FORMULA_RECALL', 'MODELLED', 2023, 'UPSC ESE / Testbook Advanced Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-steel-001', 'apsc-ae-civil', 312, 'Design of Steel Structures', 'Compression Members', 'Slenderness Ratio Limits', 'As per IS 800:2007 Table 3, what is the maximum permissible slenderness ratio (KL/r) for a tension member in which reversal of direct stress occurs due to loads other than wind or seismic loads?', '[{"id":"A","text":"180"},{"id":"B","text":"250"},{"id":"C","text":"350"},{"id":"D","text":"400"}]'::jsonb, '180', '250', '350', '400', 'A', 'According to Table 3 of IS 800:2007:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-steel-002', 'upsc-ies-civil', 313, 'Design of Steel Structures', 'Plastic Analysis', 'Shape Factors of Standard Sections', 'Match List-I (Cross Section) with List-II (Shape Factor in Plastic Bending) and select the correct answer:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-geo-001', 'apsc-ae-civil', 314, 'Geotechnical Engineering', 'Permeability & Seepage', 'Critical Hydraulic Gradient & Quicksand', 'A cohesionless soil has a specific gravity G = 2.65 and a void ratio e = 0.65. What is the critical hydraulic gradient (ic) at which boiling or quicksand condition takes place?', '[{"id":"A","text":"0.80"},{"id":"B","text":"1.00"},{"id":"C","text":"1.25"},{"id":"D","text":"0.65"}]'::jsonb, '0.80', '1.00', '1.25', '0.65', 'B', 'The critical hydraulic gradient occurs when upward seepage pressure balances submerged unit weight (effective stress σ'' = 0):
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-geo-002', 'upsc-ies-civil', 315, 'Geotechnical Engineering', 'Lateral Earth Pressure', 'Rankine Active Earth Pressure with Cohesion', 'A vertical retaining wall supports a cohesive soil backfill with unit weight γ = 18 kN/m³, cohesion c = 20 kPa, and friction angle φ = 0°. At what depth below the ground surface is the net active lateral earth pressure zero (tension crack depth)?', '[{"id":"A","text":"1.11 m"},{"id":"B","text":"2.22 m"},{"id":"C","text":"3.33 m"},{"id":"D","text":"4.44 m"}]'::jsonb, '1.11 m', '2.22 m', '3.33 m', '4.44 m', 'B', 'For pure clay (φ = 0°), Rankine active pressure coefficient K_a = (1 - sin 0°)/(1 + sin 0°) = 1.0.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-fm-001', 'apsc-ae-civil', 316, 'Fluid Mechanics & Hydraulics', 'Fluid Statics & Buoyancy', 'Metacentric Height & Stability', 'For a floating body to be in stable equilibrium, which condition regarding the Metacenter (M), Center of Gravity (G), and Center of Buoyancy (B) must be satisfied?', '[{"id":"A","text":"Metacenter M must lie above Center of Gravity G (GM > 0)"},{"id":"B","text":"Center of Buoyancy B must lie above Center of Gravity G"},{"id":"C","text":"Metacenter M must coincide with Center of Buoyancy B"},{"id":"D","text":"Metacenter M must lie below Center of Gravity G"}]'::jsonb, 'Metacenter M must lie above Center of Gravity G (GM > 0)', 'Center of Buoyancy B must lie above Center of Gravity G', 'Metacenter M must coincide with Center of Buoyancy B', 'Metacenter M must lie below Center of Gravity G', 'A', 'For a floating body, the restoring couple is generated when the metacenter M lies above the center of gravity G (GM > 0). If M is below G (GM < 0), an overturning couple develops causing unstable equilibrium. For fully submerged bodies, stability requires B to lie above G.', 'GM = (I / V) - BG ; Stable when GM > 0 (M above G)', NULL, 'Modi & Seth Fluid Mechanics & APSC AE 2023', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'APSC AE Civil 2023 / Testbook Fluid Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-fm-002', 'upsc-ies-civil', 317, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Hydraulic Jump & Energy Dissipation', 'In a horizontal rectangular open channel, a hydraulic jump occurs with initial depth y1 = 0.5 m and upstream Froude number Fr1 = 4.0. The post-jump sequent depth y2 is:', '[{"id":"A","text":"2.08 m"},{"id":"B","text":"2.59 m"},{"id":"C","text":"3.14 m"},{"id":"D","text":"1.75 m"}]'::jsonb, '2.08 m', '2.59 m', '3.14 m', '1.75 m', 'B', 'Applying the Belanger momentum equation for rectangular channels:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-hydro-001', 'apsc-ae-civil', 318, 'Hydrology & Irrigation', 'Crop Water Requirements', 'Duty, Delta & Base Period', 'If the base period of a crop is 120 days and the total delta required is 108 cm, what is the duty of irrigation water at the field head?', '[{"id":"A","text":"960 hectares/cumec"},{"id":"B","text":"1152 hectares/cumec"},{"id":"C","text":"864 hectares/cumec"},{"id":"D","text":"1200 hectares/cumec"}]'::jsonb, '960 hectares/cumec', '1152 hectares/cumec', '864 hectares/cumec', '1200 hectares/cumec', 'A', 'Given: Base period B = 120 days, Delta Δ = 108 cm = 1.08 m.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-hydro-002', 'upsc-ies-civil', 319, 'Hydrology & Irrigation', 'Canal Design Theories', 'Lacey''s Silt Theory', 'As per Lacey''s regime theory for alluvium canals, if the design discharge Q is 64 m³/s, the regime wetted perimeter (P) of the stable channel is:', '[{"id":"A","text":"38.0 m"},{"id":"B","text":"42.5 m"},{"id":"C","text":"47.5 m"},{"id":"D","text":"30.4 m"}]'::jsonb, '38.0 m', '42.5 m', '47.5 m', '30.4 m', 'A', 'Lacey''s regime equation for wetted perimeter is P = 4.75 √Q.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-env-001', 'apsc-ae-civil', 320, 'Environmental Engineering', 'Water Quality Parameters', 'Drinking Water Standards IS 10500:2012', 'As per IS 10500:2012, what is the acceptable limit and the permissible limit in the absence of an alternate source for Total Dissolved Solids (TDS) in drinking water?', '[{"id":"A","text":"Acceptable: 200 mg/L; Permissible: 500 mg/L"},{"id":"B","text":"Acceptable: 500 mg/L; Permissible: 2000 mg/L"},{"id":"C","text":"Acceptable: 250 mg/L; Permissible: 1000 mg/L"},{"id":"D","text":"Acceptable: 100 mg/L; Permissible: 600 mg/L"}]'::jsonb, 'Acceptable: 200 mg/L; Permissible: 500 mg/L', 'Acceptable: 500 mg/L; Permissible: 2000 mg/L', 'Acceptable: 250 mg/L; Permissible: 1000 mg/L', 'Acceptable: 100 mg/L; Permissible: 600 mg/L', 'B', 'Under IS 10500:2012:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-env-002', 'upsc-ies-civil', 321, 'Environmental Engineering', 'Biological Wastewater Treatment', 'Activated Sludge Process Kinetics', 'An activated sludge aeration tank has a volume of 1200 m³. It treats wastewater flowing at 3000 m³/day with an influent BOD of 200 mg/L. The Mixed Liquor Suspended Solids (MLSS) concentration in the tank is maintained at 2500 mg/L. Calculate the Food-to-Microorganism (F/M) ratio.', '[{"id":"A","text":"0.20 kg BOD / kg MLSS·day"},{"id":"B","text":"0.35 kg BOD / kg MLSS·day"},{"id":"C","text":"0.50 kg BOD / kg MLSS·day"},{"id":"D","text":"0.15 kg BOD / kg MLSS·day"}]'::jsonb, '0.20 kg BOD / kg MLSS·day', '0.35 kg BOD / kg MLSS·day', '0.50 kg BOD / kg MLSS·day', '0.15 kg BOD / kg MLSS·day', 'A', '1. Food applied per day = Q × S0 = 3000 m³/day × 200 g/m³ = 600,000 g/day = 600 kg BOD/day.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-trans-001', 'apsc-ae-civil', 322, 'Transportation Engineering', 'Geometric Design of Highways', 'Superelevation for Mixed Traffic', 'As per Indian Roads Congress (IRC 73 / IRC 86), what is the design formula for equilibrium superelevation (e) on horizontal curves when designing for mixed traffic conditions (accounting for 75% of design speed)?', '[{"id":"A","text":"e = V² / (127 R)"},{"id":"B","text":"e = V² / (225 R)"},{"id":"C","text":"e = V² / (254 R)"},{"id":"D","text":"e = (0.75 V)² / (127 R)"}]'::jsonb, 'e = V² / (127 R)', 'e = V² / (225 R)', 'e = V² / (254 R)', 'e = (0.75 V)² / (127 R)', 'B', 'IRC recommends designing superelevation neglecting lateral friction (f = 0) and considering 75% of design speed V (in km/h) to cater to slow mixed traffic.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-trans-002', 'upsc-ies-civil', 323, 'Transportation Engineering', 'Traffic Engineering', 'Greenshields Model & Capacity', 'A highway traffic stream obeys the Greenshields linear speed-density model with a free-flow speed of Vf = 80 km/h and a jam density of kj = 120 vehicles/km. What is the maximum traffic capacity (q_max) of this single lane?', '[{"id":"A","text":"1800 vehicles/hour"},{"id":"B","text":"2400 vehicles/hour"},{"id":"C","text":"3600 vehicles/hour"},{"id":"D","text":"4800 vehicles/hour"}]'::jsonb, '1800 vehicles/hour', '2400 vehicles/hour', '3600 vehicles/hour', '4800 vehicles/hour', 'B', 'In the Greenshields linear model v = V_f (1 - k / k_j):
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-sur-001', 'apsc-ae-civil', 324, 'Surveying & Geomatics', 'Compass Surveying', 'Magnetic Declination', 'The magnetic bearing of a line AB is observed as S 42° 30'' E. If the magnetic declination at the station is 3° 15'' West, what is the True Bearing of line AB in Whole Circle Bearing (WCB)?', '[{"id":"A","text":"134° 15''"},{"id":"B","text":"140° 45''"},{"id":"C","text":"137° 30''"},{"id":"D","text":"144° 15''"}]'::jsonb, '134° 15''', '140° 45''', '137° 30''', '144° 15''', 'A', '1. Convert Reduced Bearing S 42° 30'' E to WCB:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-sur-002', 'upsc-ies-civil', 325, 'Surveying & Geomatics', 'Leveling & Curvature Correction', 'Reciprocal Leveling', 'Reciprocal leveling is a specialized method employed when leveling across a wide river or ravine. Which of the following errors does reciprocal leveling completely eliminate?
