INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-cpm-002', 'upsc-ies-civil', 327, 'Construction Management & Estimating', 'Valuation & Real Estate Economics', 'Sinking Fund & Capitalized Value', 'A newly constructed building with an estimated useful life of 50 years produces a net annual rental income of ₹1,80,000. If the prevailing market rate of interest on capital is 6% per annum, what is the capitalized value of the property (neglecting sinking fund)?', '[{"id":"A","text":"₹25,00,000"},{"id":"B","text":"₹30,00,000"},{"id":"C","text":"₹36,00,000"},{"id":"D","text":"₹18,00,000"}]'::jsonb, '₹25,00,000', '₹30,00,000', '₹36,00,000', '₹18,00,000', 'B', 'Year''s Purchase (YP) = 1 / i = 1 / 0.06 = 16.667 (or 100 / 6).
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-bm-005', 'apsc-ae-civil', 328, 'Building Materials & Construction', 'Bricks & Masonry', 'Compressive Strength & Water Absorption', 'As per IS 1077, what is the minimum compressive strength and maximum 24-hour water absorption for First Class burnt clay bricks?', '[{"id":"A","text":"Min strength: 10.5 N/mm²; Max water absorption: 20% by dry weight"},{"id":"B","text":"Min strength: 7.0 N/mm²; Max water absorption: 22% by dry weight"},{"id":"C","text":"Min strength: 3.5 N/mm²; Max water absorption: 25% by dry weight"},{"id":"D","text":"Min strength: 14.0 N/mm²; Max water absorption: 15% by dry weight"}]'::jsonb, 'Min strength: 10.5 N/mm²; Max water absorption: 20% by dry weight', 'Min strength: 7.0 N/mm²; Max water absorption: 22% by dry weight', 'Min strength: 3.5 N/mm²; Max water absorption: 25% by dry weight', 'Min strength: 14.0 N/mm²; Max water absorption: 15% by dry weight', 'A', 'According to IS 1077:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-som-004', 'upsc-ies-civil', 329, 'Strength of Materials', 'Deflection of Beams', 'Macaulay & Moment-Area Theorems', 'A simply supported prismatic beam of span L carries a concentrated load W at midspan. Using Mohr''s Moment-Area theorems, what are the slope at supports (θ_A) and deflection at midspan (δ_C)?', '[{"id":"A","text":"θ_A = W L² / (16 EI) ; δ_C = W L³ / (48 EI)"},{"id":"B","text":"θ_A = W L² / (24 EI) ; δ_C = 5 W L³ / (384 EI)"},{"id":"C","text":"θ_A = W L² / (8 EI)  ; δ_C = W L³ / (24 EI)"},{"id":"D","text":"θ_A = W L² / (16 EI) ; δ_C = W L³ / (32 EI)"}]'::jsonb, 'θ_A = W L² / (16 EI) ; δ_C = W L³ / (48 EI)', 'θ_A = W L² / (24 EI) ; δ_C = 5 W L³ / (384 EI)', 'θ_A = W L² / (8 EI)  ; δ_C = W L³ / (24 EI)', 'θ_A = W L² / (16 EI) ; δ_C = W L³ / (32 EI)', 'A', 'By Mohr''s First Theorem: The slope at A relative to midspan C (where slope is zero by symmetry) equals the area of M/EI diagram between A and C:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-rcc-003', 'apsc-ae-civil', 330, 'Reinforced Concrete Structures', 'Columns & Compression Members', 'Minimum Eccentricity & Short Column Criteria', 'As per IS 456:2000 Clause 25.4, all columns must be designed for a minimum eccentricity (e_min). For an unsupported length L = 3.0 m and lateral dimension D = 400 mm, what is e_min?', '[{"id":"A","text":"19.3 mm"},{"id":"B","text":"20.0 mm"},{"id":"C","text":"23.3 mm"},{"id":"D","text":"25.0 mm"}]'::jsonb, '19.3 mm', '20.0 mm', '23.3 mm', '25.0 mm', 'B', 'Calculating formula value:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-geo-003', 'upsc-ies-civil', 331, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation Equation', 'In Terzaghi''s 1-D consolidation theory, if the degree of consolidation U is less than 60%, the relationship between Time Factor (Tv) and degree of consolidation (U) is given by:', '[{"id":"A","text":"Tv = (π / 4) · U²"},{"id":"B","text":"Tv = 1.781 - 0.933 · log10(100 - U%)"},{"id":"C","text":"Tv = (4 / π) · U"},{"id":"D","text":"Tv = (π / 2) · U³"}]'::jsonb, 'Tv = (π / 4) · U²', 'Tv = 1.781 - 0.933 · log10(100 - U%)', 'Tv = (4 / π) · U', 'Tv = (π / 2) · U³', 'A', 'For U ≤ 60% (i.e. U ≤ 0.60), the parabolic isochrone approximation gives Tv = (π/4) U². For example at U = 50% (0.50): Tv = (π/4)(0.5)² = 0.196. For U > 60%, the logarithmic formula Tv = 1.781 - 0.933 log10(100 - U) is used.', 'For U ≤ 60%: Tv = (π/4) · U² ; For U > 60%: Tv = 1.781 - 0.933 log10(100 - U%)', NULL, 'UPSC ESE 2022 & Gopal Ranjan Basic Soil Mechanics', 'EASY', 'FORMULA_RECALL', 'MODELLED', 2022, 'UPSC ESE / Testbook Geotech Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-fm-003', 'apsc-ae-civil', 332, 'Fluid Mechanics & Hydraulics', 'Boundary Layer Theory', 'Displacement and Momentum Thickness', 'The ratio of momentum thickness (θ) to displacement thickness (δ*) for a boundary layer velocity profile is known as the:', '[{"id":"A","text":"Friction coefficient"},{"id":"B","text":"Shape factor (H)"},{"id":"C","text":"Drag coefficient"},{"id":"D","text":"Roughness factor"}]'::jsonb, 'Friction coefficient', 'Shape factor (H)', 'Drag coefficient', 'Roughness factor', 'B', 'The shape factor H is defined as the ratio of displacement thickness to momentum thickness: H = δ* / θ. For a laminar Blasius boundary layer, H ≈ 2.59. For turbulent boundary layers, H drops to between 1.3 and 1.4. A higher shape factor indicates increased susceptibility to flow separation.', 'Shape factor H = δ* / θ  (or its inverse θ / δ*)', NULL, 'Schlichting Boundary Layer Theory & APSC AE 2023', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'APSC AE Civil 2023 / Testbook Fluid Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-env-003', 'upsc-ies-civil', 333, 'Environmental Engineering', 'Air Pollution & Meteorology', 'Plume Behavior & Atmospheric Stability', 'When an inversion layer exists both below and above the smokestack emission height, resulting in smoke dispersing horizontally within a shallow confined layer without mixing upwards or downwards, the plume behavior is termed:', '[{"id":"A","text":"Looping plume"},{"id":"B","text":"Fanning plume"},{"id":"C","text":"Trapping plume"},{"id":"D","text":"Fumigation plume"}]'::jsonb, 'Looping plume', 'Fanning plume', 'Trapping plume', 'Fumigation plume', 'C', '- Trapping plume: Inversion layers both above and below the stack trap the plume within a narrow zone, causing dangerously high ground concentrations downwind.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-trans-003', 'apsc-ae-civil', 334, 'Transportation Engineering', 'Pavement Design IRC 37 & IRC 58', 'Rigid Pavement Stresses', 'As per Westergaard''s analysis of concrete pavements (IRC 58), during a hot summer afternoon, where do the maximum combined stresses (wheel load + temperature warping) occur in a concrete slab?', '[{"id":"A","text":"Interior region of the slab"},{"id":"B","text":"Edge region of the slab"},{"id":"C","text":"Corner region of the slab"},{"id":"D","text":"Expansion joint"}]'::jsonb, 'Interior region of the slab', 'Edge region of the slab', 'Corner region of the slab', 'Expansion joint', 'B', 'In the afternoon, the top of the slab is hotter than the bottom, causing the slab edges to warp downward and inducing tensile warping stress at the bottom of the slab. Wheel load at the edge also induces maximum tensile stress at the bottom. Since both stresses are additive at the edge, the EDGE region governs the thickness design under summer day conditions.', 'Critical stress combination: Edge stress = σ_load + σ_warping', NULL, 'IRC 58:2015 & Khanna & Justo Highway Engineering', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'APSC AE Civil 2024 / Testbook Highway Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-apsc-steel-003', 'upsc-ies-civil', 335, 'Design of Steel Structures', 'Connections', 'High Strength Friction Grip (HSFG) Bolts', 'Which of the following statements regarding High-Strength Friction Grip (HSFG) bolted connections as per IS 800:2007 is INCORRECT?', '[{"id":"A","text":"HSFG bolts transmit load across connecting plates by interfacial friction rather than bearing on the bolt shank"},{"id":"B","text":"HSFG bolts are subjected to initial tensioning (pre-stressing) during installation"},{"id":"C","text":"The slip factor (coefficient of friction) μ is independent of surface treatment and is fixed at 0.55"},{"id":"D","text":"HSFG connections eliminate stress concentration around bolt holes and exhibit superior fatigue resistance"}]'::jsonb, 'HSFG bolts transmit load across connecting plates by interfacial friction rather than bearing on the bolt shank', 'HSFG bolts are subjected to initial tensioning (pre-stressing) during installation', 'The slip factor (coefficient of friction) μ is independent of surface treatment and is fixed at 0.55', 'HSFG connections eliminate stress concentration around bolt holes and exhibit superior fatigue resistance', 'C', 'Statement C is incorrect: The slip factor μ heavily depends on surface preparation (Table 8 of IS 800:2007). It is 0.55 only for blast-cleaned surfaces with spray metal coating; for clean mill scale it is 0.33, and for red lead painted surfaces it drops to 0.20.', 'IS 800:2007 Table 8: Slip factor μ varies from 0.20 to 0.55 depending on surface condition', NULL, 'IS 800:2007 Cl. 10.4 & Table 8', 'MEDIUM', 'CODE_RULE_BASED', 'MODELLED', 2023, 'UPSC ESE / Testbook Steel Series') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-001', 'upsc-ies-civil', 336, 'Strength of Materials', 'Flexural Stresses in Beams', 'Euler-Bernoulli Bending & Section Modulus', 'A rectangular simply supported beam having a width of 100 mm and an overall depth of 200 mm is subjected to a maximum bending moment of 20 kN·m. Based on the Euler-Bernoulli beam theory, what is the maximum bending stress induced in the extreme fibers of the beam?', '[{"id":"A","text":"20 MPa"},{"id":"B","text":"30 MPa"},{"id":"C","text":"45 MPa"},{"id":"D","text":"60 MPa"}]'::jsonb, '20 MPa', '30 MPa', '45 MPa', '60 MPa', 'B', '1. Moment of inertia about the neutral axis: I = (b · d³) / 12 = (100 × 200³) / 12 = 66.67 × 10⁶ mm⁴.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-002', 'upsc-ies-civil', 337, 'Strength of Materials', 'Torsion of Circular Shafts', 'Torsion Equation & Diameter Scaling', 'A solid circular shaft of diameter d transmits a torque T, inducing a maximum shear stress τ at its outer fibers. If the shaft diameter is doubled to 2d while transmitting the identical torque T, what will be the new maximum shear stress induced in the shaft?', '[{"id":"A","text":"τ / 2"},{"id":"B","text":"τ / 4"},{"id":"C","text":"τ / 8"},{"id":"D","text":"τ / 16"}]'::jsonb, 'τ / 2', 'τ / 4', 'τ / 8', 'τ / 16', 'C', 'From the torsion equation:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-003', 'upsc-ies-civil', 338, 'Strength of Materials', 'Columns and Struts', 'Euler Buckling & Boundary Conditions', 'Two long, slender columns A and B have identical length L, Young''s modulus E, and uniform circular cross-section. Column A has both ends rigidly fixed (Fixed-Fixed), whereas Column B has one end fixed and the other end completely free (Fixed-Free/Cantilever). What is the ratio of their critical Euler buckling loads (P_cr,A / P_cr,B)?', '[{"id":"A","text":"4 : 1"},{"id":"B","text":"8 : 1"},{"id":"C","text":"16 : 1"},{"id":"D","text":"32 : 1"}]'::jsonb, '4 : 1', '8 : 1', '16 : 1', '32 : 1', 'C', '1. For Column A (Both ends fixed): Effective length L_eff,A = L / 2 = 0.5 L.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-004', 'upsc-ies-civil', 339, 'Strength of Materials', 'Simple Stress & Strain', 'Axial Elongation of Standard & Tapered Bars', 'Consider the axial elongation of bars of length L and modulus of elasticity E. Which of the following statements regarding standard elongation cases is INCORRECT?', '[{"id":"A","text":"The elongation of a uniform prismatic bar under its own self-weight (unit weight γ) is ΔL = γL² / (2E) = WL / (2AE)"},{"id":"B","text":"The elongation of a circular bar tapering linearly from diameter d1 to d2 subjected to axial pull P is ΔL = 4PL / (π · d1 · d2 · E)"},{"id":"C","text":"The elongation of a rectangular plate of constant thickness t tapering linearly in width from b1 to b2 is ΔL = [PL / (E · t · (b1 - b2))] · ln(b1 / b2)"},{"id":"D","text":"A vertically suspended conical bar of height L elongates under its self-weight by exactly half (1/2) the elongation of a uniform prismatic cylinder of the same height"}]'::jsonb, 'The elongation of a uniform prismatic bar under its own self-weight (unit weight γ) is ΔL = γL² / (2E) = WL / (2AE)', 'The elongation of a circular bar tapering linearly from diameter d1 to d2 subjected to axial pull P is ΔL = 4PL / (π · d1 · d2 · E)', 'The elongation of a rectangular plate of constant thickness t tapering linearly in width from b1 to b2 is ΔL = [PL / (E · t · (b1 - b2))] · ln(b1 / b2)', 'A vertically suspended conical bar of height L elongates under its self-weight by exactly half (1/2) the elongation of a uniform prismatic cylinder of the same height', 'D', 'Statement D is INCORRECT:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-005', 'apsc-ae-civil', 340, 'Strength of Materials', 'Shear Stress in Beams', 'Shear Stress Distribution Across Cross-Sections', 'Consider the distribution of transverse shear stress τ = (V · Q) / (I · b) across various beam cross-sections:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-006', 'apsc-ae-civil', 341, 'Strength of Materials', 'Thin Cylinders & Spheres', 'Circumferential vs Longitudinal Stress & Failure Plane', 'A thin-walled cylindrical pipe of internal diameter d and wall thickness t (with t < d/20) contains fluid at internal gauge pressure P. What is the ratio of circumferential (hoop) stress to longitudinal stress in the cylinder shell, and why do pressurized thin pipes invariably burst longitudinally rather than circumferentially?', '[{"id":"A","text":"Ratio is 1 : 2; because longitudinal stress produces larger axial strain"},{"id":"B","text":"Ratio is 2 : 1; because hoop stress is double the longitudinal stress, inducing failure along longitudinal seams"},{"id":"C","text":"Ratio is 1 : 1; failure is governed purely by internal fluid velocity"},{"id":"D","text":"Ratio is 4 : 1; because shear stress on 45° planes exceeds the ultimate tensile strength"}]'::jsonb, 'Ratio is 1 : 2; because longitudinal stress produces larger axial strain', 'Ratio is 2 : 1; because hoop stress is double the longitudinal stress, inducing failure along longitudinal seams', 'Ratio is 1 : 1; failure is governed purely by internal fluid velocity', 'Ratio is 4 : 1; because shear stress on 45° planes exceeds the ultimate tensile strength', 'B', '1. Circumferential (Hoop) Stress: σ_h = P·d / (2t), acting circumferentially on longitudinal cross-sections.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-007', 'upsc-ies-civil', 342, 'Strength of Materials', 'Strain Energy & Springs', 'Close-Coiled Helical Spring Deflection & Stiffness', 'A close-coiled helical spring is made of wire of diameter d wound into n coils of mean coil radius R. When subjected to an axial compressive load P, what are the axial deflection δ and the spring stiffness k (where G is the shear modulus of the spring material)?', '[{"id":"A","text":"δ = (64 P R³ n) / (G d⁴)  and  k = (G d⁴) / (64 R³ n)"},{"id":"B","text":"δ = (32 P R³ n) / (G d⁴)  and  k = (G d⁴) / (32 R³ n)"},{"id":"C","text":"δ = (64 P R⁴ n) / (G d³)  and  k = (G d³) / (64 R⁴ n)"},{"id":"D","text":"δ = (16 P R² n) / (G d⁴)  and  k = (G d⁴) / (16 R² n)"}]'::jsonb, 'δ = (64 P R³ n) / (G d⁴)  and  k = (G d⁴) / (64 R³ n)', 'δ = (32 P R³ n) / (G d⁴)  and  k = (G d⁴) / (32 R³ n)', 'δ = (64 P R⁴ n) / (G d³)  and  k = (G d³) / (64 R⁴ n)', 'δ = (16 P R² n) / (G d⁴)  and  k = (G d⁴) / (16 R² n)', 'A', 'In a close-coiled helical spring, the wire is primarily subjected to torsion T = P·R.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-008', 'apsc-ae-civil', 343, 'Strength of Materials', 'Elastic Constants', 'Limiting Poisson''s Ratio & Bulk Modulus', 'If an ideal isotropic linear elastic material undergoes deformation such that its volumetric strain is identically zero (incompressible material, e.g., ideal rubber or saturated clay under undrained loading), what are the theoretical values of its Poisson''s ratio (μ) and its Bulk Modulus (K)?', '[{"id":"A","text":"μ = 0 and K = 0"},{"id":"B","text":"μ = 0.25 and K = E"},{"id":"C","text":"μ = 0.50 and K → ∞ (infinitely rigid in hydrostatic compression)"},{"id":"D","text":"μ = -1.0 and K = G"}]'::jsonb, 'μ = 0 and K = 0', 'μ = 0.25 and K = E', 'μ = 0.50 and K → ∞ (infinitely rigid in hydrostatic compression)', 'μ = -1.0 and K = G', 'C', '1. For a triaxial stress system, volumetric strain is given by:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-009', 'upsc-ies-civil', 344, 'Strength of Materials', 'Deflection of Beams', 'Superposition Method & Propped Cantilever', 'A cantilever beam AB of uniform flexural rigidity EI and span L is fixed at A and carries a uniformly distributed load (UDL) of intensity w per unit length over its entire length. A rigid vertical prop is placed at the free end B to prevent any vertical deflection (δ_B = 0). What is the magnitude of the prop reaction R_B?', '[{"id":"A","text":"R_B = (1/2) w·L"},{"id":"B","text":"R_B = (3/8) w·L"},{"id":"C","text":"R_B = (5/8) w·L"},{"id":"D","text":"R_B = (1/3) w·L"}]'::jsonb, 'R_B = (1/2) w·L', 'R_B = (3/8) w·L', 'R_B = (5/8) w·L', 'R_B = (1/3) w·L', 'B', 'Using the principle of superposition at free end B:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-010', 'upsc-ies-civil', 345, 'Strength of Materials', 'Principal Stresses & Mohr''s Circle', 'Pure Shear Stress State & Mohr''s Circle Geometry', 'An element in a structural member is subjected to a state of pure shear stress τ_xy = τ (with normal stresses σ_x = 0 and σ_y = 0). What are the principal stresses (σ1, σ2), their planes of inclination, and the radius of the resulting Mohr''s circle of stress?', '[{"id":"A","text":"σ1 = +τ, σ2 = -τ; planes at 45° and 135°; Mohr''s radius R = τ centered at origin (0, 0)"},{"id":"B","text":"σ1 = +2τ, σ2 = -2τ; planes at 90°; Mohr''s radius R = 2τ centered at origin (0, 0)"},{"id":"C","text":"σ1 = +τ, σ2 = 0; planes at 30° and 60°; Mohr''s radius R = τ/2 centered at (τ/2, 0)"},{"id":"D","text":"σ1 = 0, σ2 = -τ; planes at 0° and 90°; Mohr''s radius R = τ centered at (-τ/2, 0)"}]'::jsonb, 'σ1 = +τ, σ2 = -τ; planes at 45° and 135°; Mohr''s radius R = τ centered at origin (0, 0)', 'σ1 = +2τ, σ2 = -2τ; planes at 90°; Mohr''s radius R = 2τ centered at origin (0, 0)', 'σ1 = +τ, σ2 = 0; planes at 30° and 60°; Mohr''s radius R = τ/2 centered at (τ/2, 0)', 'σ1 = 0, σ2 = -τ; planes at 0° and 90°; Mohr''s radius R = τ centered at (-τ/2, 0)', 'A', 'For pure shear (σ_x = 0, σ_y = 0, τ_xy = τ):
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-som-011', 'apsc-ae-civil', 346, 'Strength of Materials', 'Shear Force & Bending Moment Diagrams', 'Differential Relations & Point of Contraflexure', 'Regarding the mathematical relationships governing Shear Force (V), Bending Moment (M), and Distributed Load (w) along a horizontally loaded beam, which of the following statements is INCORRECT?', '[{"id":"A","text":"The rate of change of shear force equals the negative of the load intensity: dV/dx = -w"},{"id":"B","text":"The rate of change of bending moment equals the shear force: dM/dx = V"},{"id":"C","text":"A point of contraflexure (or point of inflection) is defined as a point where the bending moment is zero and changes sign, corresponding to a change in curvature of the beam"},{"id":"D","text":"The maximum bending moment always occurs at a point where the shear force attains its absolute maximum value"}]'::jsonb, 'The rate of change of shear force equals the negative of the load intensity: dV/dx = -w', 'The rate of change of bending moment equals the shear force: dM/dx = V', 'A point of contraflexure (or point of inflection) is defined as a point where the bending moment is zero and changes sign, corresponding to a change in curvature of the beam', 'The maximum bending moment always occurs at a point where the shear force attains its absolute maximum value', 'D', 'Statement D is INCORRECT:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-001', 'upsc-ies-civil', 347, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Most Economical Trapezoidal Channel Section', 'For a trapezoidal open channel section to be hydraulically most efficient (most economical section delivering maximum discharge for a given area), which of the following geometric conditions must be satisfied?
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-002', 'upsc-ies-civil', 348, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Hydraulic Jump Energy Dissipation', 'A hydraulic jump forms in a horizontal rectangular open channel. If the pre-jump initial depth is y1 = 0.20 m and the post-jump sequent depth is y2 = 1.20 m, what is the head loss (energy dissipation ΔE_L) caused by the jump?', '[{"id":"A","text":"0.854 m"},{"id":"B","text":"1.042 m"},{"id":"C","text":"1.250 m"},{"id":"D","text":"0.521 m"}]'::jsonb, '0.854 m', '1.042 m', '1.250 m', '0.521 m', 'B', 'The energy loss in a hydraulic jump in a rectangular horizontal channel is given by:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-003', 'upsc-ies-civil', 349, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Specific Energy in Non-Rectangular Channels', 'In a symmetrical triangular open channel with side slopes 1:m (1 vertical to m horizontal), what is the ratio of the minimum specific energy (E_c) to the critical depth (y_c)?', '[{"id":"A","text":"1.50 (or 3/2)"},{"id":"B","text":"1.25 (or 5/4)"},{"id":"C","text":"1.33 (or 4/3)"},{"id":"D","text":"1.75 (or 7/4)"}]'::jsonb, '1.50 (or 3/2)', '1.25 (or 5/4)', '1.33 (or 4/3)', '1.75 (or 7/4)', 'B', 'For any channel shape at critical flow, V_c² / (2g) = D_c / 2, where D_c is the hydraulic depth (A_c / T_c).
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-004', 'apsc-ae-civil', 350, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Gradually Varied Flow (GVF) Profiles', 'When a barrage or storage dam is constructed across a wide river channel having a mild bed slope (S_0 < S_c), the water level upstream is backed up such that actual depth exceeds the normal depth (y > y_n > y_c). Which type of Gradually Varied Flow (GVF) surface profile is produced upstream of the structure?', '[{"id":"A","text":"M1 profile (Backwater curve)"},{"id":"B","text":"M2 profile (Drawdown curve)"},{"id":"C","text":"S1 profile"},{"id":"D","text":"H2 profile"}]'::jsonb, 'M1 profile (Backwater curve)', 'M2 profile (Drawdown curve)', 'S1 profile', 'H2 profile', 'A', 'On a mild slope channel (where normal depth y_n > critical depth y_c):
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-005', 'apsc-ae-civil', 351, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Most Economical Triangular Channel Section', 'For a symmetrical triangular open channel with side slopes 1:m (1 vertical to m horizontal) to carry maximum discharge for a given cross-sectional area (most efficient hydraulic section), what should be the side slope angle with the vertical and the hydraulic radius R?', '[{"id":"A","text":"Side slope angle with vertical = 45° (m = 1), and R = y / (2√2)"},{"id":"B","text":"Side slope angle with vertical = 60° (m = √3), and R = y / 2"},{"id":"C","text":"Side slope angle with vertical = 30° (m = 1/√3), and R = y / 4"},{"id":"D","text":"Side slope angle with vertical = 45° (m = 1), and R = y / 2"}]'::jsonb, 'Side slope angle with vertical = 45° (m = 1), and R = y / (2√2)', 'Side slope angle with vertical = 60° (m = √3), and R = y / 2', 'Side slope angle with vertical = 30° (m = 1/√3), and R = y / 4', 'Side slope angle with vertical = 45° (m = 1), and R = y / 2', 'A', 'For a triangular channel with flow depth y and side slopes 1:m:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ies-gate-ocf-006', 'apsc-ae-civil', 352, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow', 'Chezy and Manning Roughness Coefficients', 'In open channel hydraulics, what is the exact relationship between Chezy''s coefficient C and Manning''s roughness coefficient n in SI units?', '[{"id":"A","text":"C = (1 / n) · R^(1/6)"},{"id":"B","text":"C = (1 / n) · R^(2/3)"},{"id":"C","text":"C = n · R^(1/6)"},{"id":"D","text":"C = (1 / n) · R^(1/2)"}]'::jsonb, 'C = (1 / n) · R^(1/6)', 'C = (1 / n) · R^(2/3)', 'C = n · R^(1/6)', 'C = (1 / n) · R^(1/2)', 'A', 'Equating the uniform flow velocity from Chezy''s formula and Manning''s formula in SI units:
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-001', 'apsc-ae-civil', 201, 'Reinforced Concrete Structures', 'Limit State Design — Flexure', 'Limiting Moment of Resistance', 'A singly reinforced rectangular beam of width 300 mm and effective depth 500 mm is cast with M20 concrete and Fe 415 steel. Determine its limiting moment of resistance.', '[{"id":"A","text":"172.5 kN·m"},{"id":"B","text":"207.0 kN·m"},{"id":"C","text":"240.0 kN·m"},{"id":"D","text":"155.3 kN·m"}]'::jsonb, '172.5 kN·m', '207.0 kN·m', '240.0 kN·m', '155.3 kN·m', 'B', 'For Fe 415 the limiting moment coefficient is 0.138, giving M_u,lim = 0.138 × 20 × 300 × 500² = 207 kN·m. Options A and C use wrong limiting coefficients; D corresponds to Fe 500 (0.133).', 'M_u,lim = 0.138 · f_ck · b · d²  (Fe 415)', '["Step 1 — Identify the coefficient: for Fe 415, M_u,lim = 0.138 · f_ck · b · d².","Step 2 — Substitute: M_u,lim = 0.138 × 20 × 300 × (500)² N·mm.","Step 3 — (500)² = 250,000 mm². So M_u,lim = 0.138 × 20 × 300 × 250,000 = 207 × 10⁶ N·mm.","Step 4 — Convert: 207 × 10⁶ N·mm = 207 kN·m."]'::jsonb, 'IS 456:2000, Cl. 38.1 & Annex G', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-002', 'apsc-ae-civil', 202, 'Reinforced Concrete Structures', 'Limit State Design — Shear', 'Nominal Shear Stress', 'A beam section 250 mm wide and 450 mm effective deep carries a factored shear force of 150 kN. Calculate the nominal shear stress τ_v.', '[{"id":"A","text":"1.33 MPa"},{"id":"B","text":"2.67 MPa"},{"id":"C","text":"1.20 MPa"},{"id":"D","text":"0.67 MPa"}]'::jsonb, '1.33 MPa', '2.67 MPa', '1.20 MPa', '0.67 MPa', 'A', 'τ_v = 150 × 10³ / (250 × 450) = 1.33 N/mm². Option C uses overall depth 500 mm; B and D are halving/doubling errors in the denominator.', 'τ_v = V_u / (b · d)', '["Step 1 — Formula: τ_v = V_u / (b · d), with V_u in newtons.","Step 2 — Denominator: 250 × 450 = 112,500 mm².","Step 3 — τ_v = 150,000 / 112,500 = 1.333 N/mm² = 1.33 MPa."]'::jsonb, 'IS 456:2000, Cl. 40.1', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-003', 'apsc-ae-civil', 203, 'Reinforced Concrete Structures', 'Bond, Anchorage & Development Length', 'Development Length of a Deformed Bar', 'A 16 mm diameter Fe 415 deformed bar in tension is embedded in M20 concrete. Using τ_bd = 1.2 × 1.6 N/mm² for deformed bars in tension, compute the development length required.', '[{"id":"A","text":"376 mm"},{"id":"B","text":"564 mm"},{"id":"C","text":"752 mm"},{"id":"D","text":"1504 mm"}]'::jsonb, '376 mm', '564 mm', '752 mm', '1504 mm', 'C', 'σ_s = 0.87 × 415 = 361.05 N/mm² and τ_bd = 1.92 N/mm², so L_d = 16 × 361.05 / (4 × 1.92) = 752 mm. Option D doubles the divisor effect by using 2τ_bd; A uses 8τ_bd.', 'L_d = φ · σ_s / (4 · τ_bd),  σ_s = 0.87 f_y', '["Step 1 — Stress in the bar: σ_s = 0.87 · f_y = 0.87 × 415 = 361.05 N/mm².","Step 2 — Design bond stress for deformed bars in tension: τ_bd = 1.2 × 1.6 = 1.92 N/mm².","Step 3 — L_d = φ σ_s / (4 τ_bd) = (16 × 361.05) / (4 × 1.92).","Step 4 — Numerator = 5,776.8; denominator = 7.68 → L_d = 752.2 mm ≈ 752 mm."]'::jsonb, 'IS 456:2000, Cl. 26.2.1', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-004', 'apsc-ae-civil', 204, 'Structural Analysis', 'Three-Hinged and Two-Hinged Arches', 'Horizontal Thrust in a Parabolic Arch', 'A three-hinged parabolic arch of span 40 m with a central rise of 5 m carries a uniformly distributed load of 20 kN/m over the entire span. Calculate the horizontal thrust developed at the supports.', '[{"id":"A","text":"400 kN"},{"id":"B","text":"800 kN"},{"id":"C","text":"200 kN"},{"id":"D","text":"1600 kN"}]'::jsonb, '400 kN', '800 kN', '200 kN', '1600 kN', 'B', 'For a three-hinged parabolic arch under full-span UDL, bending moment everywhere is zero and H = wL²/(8h) = 20 × 1600 / 40 = 800 kN. Option A uses 16h instead of 8h.', 'H = w · L² / (8 · h)', '["Step 1 — Formula for full-span UDL on a parabolic arch: H = w L² / (8h).","Step 2 — L² = 40² = 1600 m²; w = 20 kN/m; h = 5 m.","Step 3 — H = (20 × 1600) / (8 × 5) = 32,000 / 40 = 800 kN."]'::jsonb, 'Theory of Structures — Vazirani & Ratwani', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-005', 'apsc-ae-civil', 205, 'Structural Analysis', 'Indeterminate Structures — Fixed Beams', 'Fixed End Moments', 'A beam fixed at both ends spans 6 m and carries a uniformly distributed load of 30 kN/m over its whole length. Determine the magnitude of the fixed end moment at each support.', '[{"id":"A","text":"67.5 kN·m"},{"id":"B","text":"90.0 kN·m"},{"id":"C","text":"135.0 kN·m"},{"id":"D","text":"180.0 kN·m"}]'::jsonb, '67.5 kN·m', '90.0 kN·m', '135.0 kN·m', '180.0 kN·m', 'B', 'FEM = wL²/12 = 30 × 36 / 12 = 90 kN·m. Option C is the simply-supported mid-span moment wL²/8, a common mix-up.', 'FEM = w · L² / 12', '["Step 1 — For a fixed beam with full UDL, both end moments are hogging and equal: FEM = wL²/12.","Step 2 — L² = 6² = 36 m².","Step 3 — FEM = (30 × 36) / 12 = 1080 / 12 = 90 kN·m."]'::jsonb, 'Structural Analysis — Hibbeler', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-006', 'apsc-ae-civil', 206, 'Structural Analysis', 'Static and Kinematic Indeterminacy', 'Degree of Static Indeterminacy', 'A plane portal frame consists of 3 members and 4 joints, and is rigidly fixed at both column bases (6 reaction components). Determine its degree of static indeterminacy.', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"3"},{"id":"D","text":"6"}]'::jsonb, '0', '1', '3', '6', 'C', 'D_s = 3(3) + 6 − 3(4) = 15 − 12 = 3. This is the classic fixed-base portal frame result: 3 redundants (one per support moment/tie).', 'D_s = 3m + r − 3j  (plane frame)', '["Step 1 — For a plane frame: D_s = 3m + r − 3j.","Step 2 — m = 3 members, j = 4 joints, r = 6 reactions.","Step 3 — D_s = 3×3 + 6 − 3×4 = 9 + 6 − 12 = 3."]'::jsonb, 'Structural Analysis — Hibbeler', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-007', 'apsc-ae-civil', 207, 'Strength of Materials', 'Principal Stresses & Mohr''s Circle', 'Radius of Mohr Circle', 'At a point in a stressed body, σ_x = 100 MPa, σ_y = 20 MPa and τ_xy = 30 MPa. Calculate the radius of the Mohr circle.', '[{"id":"A","text":"30 MPa"},{"id":"B","text":"40 MPa"},{"id":"C","text":"50 MPa"},{"id":"D","text":"70 MPa"}]'::jsonb, '30 MPa', '40 MPa', '50 MPa', '70 MPa', 'C', 'R = √(40² + 30²) = 50 MPa. The 3-4-5 triangle makes this a favourite exam item; options A and B are the individual components.', 'R = √( ((σ_x − σ_y)/2)² + τ_xy² )', '["Step 1 — Centre of the circle: (σ_x + σ_y)/2 = (100 + 20)/2 = 60 MPa.","Step 2 — Half-difference: (σ_x − σ_y)/2 = 80/2 = 40 MPa.","Step 3 — R = √(40² + 30²) = √(1600 + 900) = √2500 = 50 MPa.","Step 4 — Principal stresses would then be 60 ± 50, i.e. 110 MPa and 10 MPa."]'::jsonb, 'Mechanics of Materials — Gere & Timoshenko', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-008', 'apsc-ae-civil', 208, 'Strength of Materials', 'Euler''s Column Buckling Theory', 'Effect of End Conditions', 'A column with both ends hinged has a critical buckling load of 200 kN. If the same column is re-supported with both ends fixed, what will be its critical load?', '[{"id":"A","text":"100 kN"},{"id":"B","text":"200 kN"},{"id":"C","text":"400 kN"},{"id":"D","text":"800 kN"}]'::jsonb, '100 kN', '200 kN', '400 kN', '800 kN', 'D', 'Fixed-fixed halves the effective length, and P_cr varies inversely as L_eff², so the load multiplies by (2)² = 4 → 800 kN.', 'P_cr = π²EI / L_eff²,  with L_eff = L/2 for fixed-fixed', '["Step 1 — Hinged-hinged: L_eff = L, so P_cr = π²EI/L² = 200 kN.","Step 2 — Fixed-fixed: L_eff = L/2.","Step 3 — P_cr scales as 1/L_eff², a factor of (L / (L/2))² = 4.","Step 4 — New critical load = 4 × 200 = 800 kN."]'::jsonb, 'Strength of Materials — B.C. Punmia', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-009', 'apsc-ae-civil', 209, 'Strength of Materials', 'Shear Stress Distribution in Beams', 'Maximum vs Average Shear Stress', 'A rectangular beam section carries an average shear stress of 30 MPa. Determine the maximum shear stress developed in the section.', '[{"id":"A","text":"30 MPa"},{"id":"B","text":"45 MPa"},{"id":"C","text":"60 MPa"},{"id":"D","text":"50 MPa"}]'::jsonb, '30 MPa', '45 MPa', '60 MPa', '50 MPa', 'B', 'For a rectangular section the shear stress diagram is parabolic with τ_max = 3V/(2bd) = 1.5 × average. So 1.5 × 30 = 45 MPa.', 'τ_max = 1.5 · τ_avg = 1.5 · V/(b·d)  (rectangular section)', '["Step 1 — Shear stress in a rectangular section is parabolic, zero at the extreme fibres.","Step 2 — Average stress = V/(b·d); maximum occurs at the neutral axis.","Step 3 — τ_max = 1.5 × τ_avg = 1.5 × 30 = 45 MPa."]'::jsonb, 'Strength of Materials — B.C. Punmia', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-010', 'apsc-ae-civil', 210, 'Geotechnical Engineering', 'Soil Phase Relationships & Index Properties', 'Void Ratio of a Saturated Soil', 'A saturated soil sample has a water content of 25% and a specific gravity of solids of 2.65. Determine its void ratio.', '[{"id":"A","text":"0.38"},{"id":"B","text":"0.66"},{"id":"C","text":"0.94"},{"id":"D","text":"1.33"}]'::jsonb, '0.38', '0.66', '0.94', '1.33', 'B', 'e = wG/S = 0.25 × 2.65 / 1.0 = 0.6625 ≈ 0.66. A saturated soil cannot have S < 1 used in the denominator by mistake — option C comes from dividing by 0.7.', 'S · e = w · G  →  e = w·G/S ; for saturated soil S = 1', '["Step 1 — Phase relation: S · e = w · G.","Step 2 — Fully saturated: S = 1 → e = w · G.","Step 3 — e = 0.25 × 2.65 = 0.6625 ≈ 0.66.","Step 4 — Check: for G = 2.65 and e = 0.6625, γ_sat ≈ ((2.65 + 0.6625)/1.6625) × 9.81 ≈ 19.5 kN/m³ — realistic."]'::jsonb, 'Soil Mechanics — B.C. Punmia', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-011', 'apsc-ae-civil', 211, 'Geotechnical Engineering', 'Terzaghi 1D Consolidation & Settlement', 'Effect of Drainage Path', 'A clay layer reached 50% consolidation in 2 years when it could drain from both top and bottom. How long would the same layer take to reach 50% consolidation if drainage were possible from the top only?', '[{"id":"A","text":"2 years"},{"id":"B","text":"4 years"},{"id":"C","text":"8 years"},{"id":"D","text":"16 years"}]'::jsonb, '2 years', '4 years', '8 years', '16 years', 'C', 'The drainage path doubles (d/2 → d), and since t ∝ d² the time becomes 2² = 4 times the original: 4 × 2 = 8 years.', 'T_v = c_v · t / d²  →  t ∝ d²', '["Step 1 — At the same degree of consolidation, T_v is unchanged.","Step 2 — T_v = c_v t / d², so t ∝ d² (d = drainage path).","Step 3 — Double drainage: d = H/2. Single drainage: d = H — the path doubles.","Step 4 — Time multiplies by 2² = 4 → t = 4 × 2 = 8 years."]'::jsonb, 'Theoretical Soil Mechanics — Terzaghi', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-012', 'apsc-ae-civil', 212, 'Geotechnical Engineering', 'Lateral Earth Pressure & Bearing Capacity', 'Terzaghi Bearing Capacity in Clay', 'A strip footing rests on a purely cohesive saturated clay with cohesion c = 40 kPa (φ = 0). Determine the net ultimate bearing capacity of the footing as per Terzaghi.', '[{"id":"A","text":"114 kPa"},{"id":"B","text":"160 kPa"},{"id":"C","text":"228 kPa"},{"id":"D","text":"342 kPa"}]'::jsonb, '114 kPa', '160 kPa', '228 kPa', '342 kPa', 'C', 'For φ = 0 the Terzaghi bearing capacity factors are N_c = 5.7, N_q = 1 and N_γ = 0 for a strip footing, so q_nu = 5.7 × 40 = 228 kPa. q_nu excludes the surcharge depth term.', 'q_nu = c · N_c  (strip, φ = 0) → N_c = 5.7', '["Step 1 — Terzaghi strip footing: q_nu = c·N_c + γD_f(N_q − 1) + 0.5γBN_γ.","Step 2 — For φ = 0 clay: N_c = 5.7, N_q = 1, N_γ = 0 → surcharge term (N_q − 1) = 0.","Step 3 — q_nu = c · N_c = 40 × 5.7 = 228 kPa."]'::jsonb, 'Theoretical Soil Mechanics — Terzaghi', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-013', 'apsc-ae-civil', 213, 'Fluid Mechanics & Hydraulics', 'Hydrostatic Forces & Centre of Pressure', 'Centre of Pressure of a Vertical Gate', 'A vertical rectangular sluice gate 2 m wide and 3 m high has its top edge exactly at the water surface. Determine the depth of the centre of pressure below the water surface.', '[{"id":"A","text":"1.50 m"},{"id":"B","text":"2.00 m"},{"id":"C","text":"2.50 m"},{"id":"D","text":"3.00 m"}]'::jsonb, '1.50 m', '2.00 m', '2.50 m', '3.00 m', 'B', 'h_cp = d/2 + d/6 = 2d/3 = 2.0 m. The centre of pressure always lies below the centroid, so 1.5 m (the centroid) is wrong on principle.', 'h_cp = h_cg + I_cg / (A · h_cg) ; for a rectangle with one edge at the surface h_cp = 2d/3', '["Step 1 — Centroid of the wetted rectangle: h_cg = d/2 = 1.5 m.","Step 2 — I_cg = b·d³/12 = 2 × 27/12 = 4.5 m⁴; area A = 6 m².","Step 3 — h_cp = h_cg + I_cg/(A·h_cg) = 1.5 + 4.5/(6 × 1.5) = 1.5 + 0.5 = 2.0 m.","Step 4 — Shortcut: for a rectangle with one edge at the free surface, h_cp = 2d/3 = 2 m."]'::jsonb, 'Fluid Mechanics — R.K. Bansal', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-014', 'apsc-ae-civil', 214, 'Fluid Mechanics & Hydraulics', 'Bernoulli Equation, Pipe Friction & Losses', 'Darcy Friction Factor in Laminar Flow', 'Oil flows through a pipe at a Reynolds number of 1600. Calculate the Darcy–Weisbach friction factor for this flow.', '[{"id":"A","text":"0.016"},{"id":"B","text":"0.040"},{"id":"C","text":"0.050"},{"id":"D","text":"0.320"}]'::jsonb, '0.016', '0.040', '0.050', '0.320', 'B', 'Laminar flow (Re < 2000) gives f = 64/Re = 64/1600 = 0.04. Option C is the Blasius turbulent result 0.316/Re^0.25, which is invalid at this Reynolds number.', 'f = 64 / Re  (laminar, Re < 2000)', '["Step 1 — Check the regime: Re = 1600 < 2000, so the flow is laminar.","Step 2 — For laminar flow the Hagen–Poiseuille result gives f = 64/Re.","Step 3 — f = 64 / 1600 = 0.04."]'::jsonb, 'Fluid Mechanics — R.K. Bansal', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-015', 'apsc-ae-civil', 215, 'Fluid Mechanics & Hydraulics', 'Open Channel Flow & Hydraulic Jumps', 'Minimum Specific Energy', 'In a rectangular channel the critical depth is 2.0 m. Determine the minimum specific energy of the flow.', '[{"id":"A","text":"1.50 m"},{"id":"B","text":"2.00 m"},{"id":"C","text":"3.00 m"},{"id":"D","text":"4.00 m"}]'::jsonb, '1.50 m', '2.00 m', '3.00 m', '4.00 m', 'C', 'At critical depth the velocity head equals half the depth, so E_min = y_c + y_c/2 = 1.5 y_c = 3.0 m.', 'E_min = (3/2) · y_c  (rectangular channel)', '["Step 1 — Specific energy: E = y + V²/2g.","Step 2 — For a rectangular channel at critical flow, V²/2g = y_c/2.","Step 3 — E_min = y_c + y_c/2 = 1.5 × 2.0 = 3.0 m."]'::jsonb, 'Flow in Open Channels — K. Subramanya', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-016', 'apsc-ae-civil', 216, 'Environmental Engineering', 'BOD Kinetics & Biological Wastewater Treatment', 'Ultimate BOD from 5-Day BOD', 'The 5-day BOD of a wastewater sample at 20 °C is 200 mg/L, and it is known that BOD₅ is 68% of the ultimate BOD. Determine the ultimate BOD (L₀).', '[{"id":"A","text":"68 mg/L"},{"id":"B","text":"136 mg/L"},{"id":"C","text":"200 mg/L"},{"id":"D","text":"294 mg/L"}]'::jsonb, '68 mg/L', '136 mg/L', '200 mg/L', '294 mg/L', 'D', 'L₀ = 200 / 0.68 = 294.1 ≈ 294 mg/L. The ultimate BOD must always exceed the 5-day BOD, which rules out options A, B and C.', 'BOD₅ = 0.68 · L₀  →  L₀ = BOD₅ / 0.68', '["Step 1 — Given: BOD₅ = 200 mg/L = 68% of L₀.","Step 2 — Therefore 0.68 · L₀ = 200.","Step 3 — L₀ = 200 / 0.68 = 294.1 mg/L ≈ 294 mg/L."]'::jsonb, 'Wastewater Engineering — Metcalf & Eddy', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-017', 'apsc-ae-civil', 217, 'Environmental Engineering', 'Water Treatment: Sedimentation & Filtration', 'Surface Area of a Sedimentation Tank', 'A circular primary sedimentation tank treats 1800 m³/day with an intended surface overflow rate of 30 m³/m²/day. Determine the required diameter of the tank.', '[{"id":"A","text":"4.4 m"},{"id":"B","text":"8.7 m"},{"id":"C","text":"12.4 m"},{"id":"D","text":"60.0 m"}]'::jsonb, '4.4 m', '8.7 m', '12.4 m', '60.0 m', 'B', 'A = 1800/30 = 60 m², so D = √(4 × 60/π) = 8.74 m ≈ 8.7 m. Option A is the *radius* (√(A/π) = 4.37 m) — the classic slip.', 'A = Q / overflow rate ;  D = √(4A/π)', '["Step 1 — Surface area from overflow rate: A = Q / SOR = 1800 / 30 = 60 m².","Step 2 — For a circular tank: A = πD²/4.","Step 3 — D² = 4A/π = 240/π = 76.39 → D = 8.74 m ≈ 8.7 m.","Step 4 — Cross-check the trap: √(A/π) = 4.37 m is the radius, not the diameter."]'::jsonb, 'Water Supply Engineering — S.K. Garg', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-018', 'apsc-ae-civil', 218, 'Environmental Engineering', 'BOD Kinetics & Biological Wastewater Treatment', 'First-Order BOD Exertion', 'A wastewater has an ultimate BOD of 300 mg/L and a first-order deoxygenation constant k = 0.23 per day (base e at 20 °C). Calculate the BOD exerted in 3 days.', '[{"id":"A","text":"100 mg/L"},{"id":"B","text":"150 mg/L"},{"id":"C","text":"180 mg/L"},{"id":"D","text":"210 mg/L"}]'::jsonb, '100 mg/L', '150 mg/L', '180 mg/L', '210 mg/L', 'B', 'e^(−0.69) = 0.5016, so BOD₃ = 300 × (1 − 0.5016) = 149.5 ≈ 150 mg/L. Note k·t = 0.23 × 3 = 0.69, which is close to ln 2 — half the ultimate BOD is exerted.', 'BOD_t = L₀ (1 − e^(−k·t))', '["Step 1 — Formula: BOD_t = L₀ (1 − e^(−k t)).","Step 2 — k·t = 0.23 × 3 = 0.69.","Step 3 — e^(−0.69) = 0.5016 → (1 − 0.5016) = 0.4984.","Step 4 — BOD₃ = 300 × 0.4984 = 149.5 ≈ 150 mg/L."]'::jsonb, 'Wastewater Engineering — Metcalf & Eddy', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-019', 'apsc-ae-civil', 219, 'Surveying & Geomatics', 'Fundamental Principles & Differential Levelling', 'Curvature and Refraction Correction', 'A levelling staff is held 2 km away from the instrument. Determine the combined correction for curvature and refraction that must be applied to the observed staff reading.', '[{"id":"A","text":"0.067 m"},{"id":"B","text":"0.134 m"},{"id":"C","text":"0.269 m"},{"id":"D","text":"0.538 m"}]'::jsonb, '0.067 m', '0.134 m', '0.269 m', '0.538 m', 'C', 'C_cr = 0.0673 × 2² = 0.269 m, and the correction is subtractive. Curvature alone would be 0.0785d² = 0.314 m before applying the refraction allowance of 1/7.', 'C_cr = 0.0673 · d²   (d in km, result in m)', '["Step 1 — Curvature correction C_c = 0.0785 d² = 0.0785 × 4 = 0.314 m.","Step 2 — Refraction correction is 1/7 of curvature and opposite in effect: C_r = 0.314/7 = 0.0449 m.","Step 3 — Combined correction C_cr = C_c − C_r = 0.269 m ≈ 0.0673 d².","Step 4 — Apply it as negative to the observed reading."]'::jsonb, 'Surveying Vol. I — B.C. Punmia', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-020', 'apsc-ae-civil', 220, 'Surveying & Geomatics', 'Curves, Tacheometry & Total Station', 'Radius of a Simple Curve', 'A simple circular curve is designated as a 3° curve on the basis of a 30 m chord. Determine its radius.', '[{"id":"A","text":"191 m"},{"id":"B","text":"286 m"},{"id":"C","text":"573 m"},{"id":"D","text":"1146 m"}]'::jsonb, '191 m', '286 m', '573 m', '1146 m', 'C', 'R = 1719/3 = 573 m. If the designation were on a 20 m chord the constant would be 1146, giving option D — reading the chord basis correctly matters.', 'R = 1719 / D   (D = degree of curve on 30 m chord)', '["Step 1 — Degree of curve on a 30 m chord: R = 1719/D.","Step 2 — R = 1719 / 3 = 573 m.","Step 3 — Cross-check with geometry: chord = 2R sin(D/2) = 2 × 573 × sin 1.5° = 30.0 m ✓."]'::jsonb, 'Surveying Vol. I — B.C. Punmia', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-021', 'apsc-ae-civil', 221, 'Surveying & Geomatics', 'Curves, Tacheometry & Total Station', 'Horizontal Distance in Tacheometry', 'A tacheometer with multiplying constant 100 and additive constant zero sights a levelling staff held vertically. The staff intercept is 2.0 m and the angle of elevation is 10°. Determine the horizontal distance from the instrument to the staff.', '[{"id":"A","text":"188 m"},{"id":"B","text":"194 m"},{"id":"C","text":"197 m"},{"id":"D","text":"200 m"}]'::jsonb, '188 m', '194 m', '197 m', '200 m', 'B', 'D = 100 × 2.0 × cos²10° = 194 m. Option C uses cos θ instead of cos²θ — the single most common tacheometry error.', 'D = 100 · s · cos²θ  (for a vertical staff)', '["Step 1 — Formula: D = K·s·cos²θ + C·cosθ, with K = 100, C = 0.","Step 2 — cos 10° = 0.9848 → cos²10° = 0.9698.","Step 3 — D = 100 × 2.0 × 0.9698 = 193.96 m ≈ 194 m.","Step 4 — Trap: using cos θ gives 196.96 m, a 3 m error at just 10° of inclination."]'::jsonb, 'Surveying Vol. I — B.C. Punmia', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-022', 'apsc-ae-civil', 222, 'Design of Steel Structures', 'Bolted & Welded Connections', 'Effective Throat Thickness of a Fillet Weld', 'A shop fillet weld of 10 mm size is used to connect two plates. Determine the effective throat thickness of the weld.', '[{"id":"A","text":"5.0 mm"},{"id":"B","text":"7.0 mm"},{"id":"C","text":"10.0 mm"},{"id":"D","text":"14.0 mm"}]'::jsonb, '5.0 mm', '7.0 mm', '10.0 mm', '14.0 mm', 'B', 'Effective throat thickness = 0.7 × size = 7 mm. A size of 10 mm is the leg length; the throat is measured perpendicular to the weld axis.', 't_t = 0.7 · s  (shop fillet weld)', '["Step 1 — Weld size s = leg length = 10 mm.","Step 2 — Effective throat = 0.7 s for a fillet weld in a plane at 45°.","Step 3 — t_t = 0.7 × 10 = 7 mm."]'::jsonb, 'IS 800:2007, Cl. 10.5.2', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-023', 'apsc-ae-civil', 223, 'Design of Steel Structures', 'Plastic Analysis & Shape Factor', 'Shape Factor of a Solid Circular Section', 'Determine the shape factor of a solid circular steel cross-section.', '[{"id":"A","text":"1.27"},{"id":"B","text":"1.50"},{"id":"C","text":"1.70"},{"id":"D","text":"2.00"}]'::jsonb, '1.27', '1.50', '1.70', '2.00', 'C', 'For a circle Z_p = d³/6 and Z_e = πd³/32, so S = 32/(6π) = 1.698 ≈ 1.70. Option B is the rectangle (1.5), and 1.27 is the diamond/typical I-section value.', 'S = Z_p / Z_e = 16/(3π) = 1.70  (solid circle)', '["Step 1 — Plastic section modulus of a circle: Z_p = d³/6.","Step 2 — Elastic section modulus: Z_e = πd³/32.","Step 3 — S = Z_p/Z_e = (d³/6) ÷ (πd³/32) = 32/(6π) = 1.698 ≈ 1.70."]'::jsonb, 'Design of Steel Structures — S.K. Duggal', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-024', 'apsc-ae-civil', 224, 'Design of Steel Structures', 'Plastic Analysis & Shape Factor', 'Plastic Moment Capacity', 'A rectangular steel section 100 mm wide and 300 mm deep is made of steel with yield stress 250 MPa. Calculate its plastic moment of resistance.', '[{"id":"A","text":"281.3 kN·m"},{"id":"B","text":"375.0 kN·m"},{"id":"C","text":"450.0 kN·m"},{"id":"D","text":"562.5 kN·m"}]'::jsonb, '281.3 kN·m', '375.0 kN·m', '450.0 kN·m', '562.5 kN·m', 'D', 'Z_p = bd²/4 = 2.25 × 10⁶ mm³, so M_p = 250 × 2.25 × 10⁶ = 562.5 kN·m. Option B is the *yield* moment f_y·Z_e (375 kN·m) — the elastic limit, not the plastic one.', 'M_p = f_y · Z_p = f_y · b·d²/4', '["Step 1 — For a rectangle the plastic modulus Z_p = b·d²/4.","Step 2 — Z_p = 100 × 300²/4 = 100 × 90,000/4 = 2.25 × 10⁶ mm³.","Step 3 — M_p = f_y · Z_p = 250 × 2.25 × 10⁶ = 562.5 × 10⁶ N·mm = 562.5 kN·m.","Step 4 — Cross-check with the shape factor: Z_e = bd²/6 = 1.5 × 10⁶ mm³, S = 2.25/1.5 = 1.5 ✓ (rectangle)."]'::jsonb, 'IS 800:2007 — Plastic Analysis, Annex B', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-025', 'apsc-ae-civil', 225, 'Building Materials & Construction', 'Concrete Properties, Workability & Abram''s Law', 'Flexural Tensile Strength of Concrete', 'Determine the characteristic flexural tensile strength (modulus of rupture) of M25 grade concrete as per IS 456:2000.', '[{"id":"A","text":"2.5 MPa"},{"id":"B","text":"3.5 MPa"},{"id":"C","text":"4.0 MPa"},{"id":"D","text":"5.0 MPa"}]'::jsonb, '2.5 MPa', '3.5 MPa', '4.0 MPa', '5.0 MPa', 'B', 'f_cr = 0.7 × √25 = 0.7 × 5 = 3.5 MPa. Option D is √f_ck, which is the *direct* tensile strength, not the modulus of rupture.', 'f_cr = 0.7 · √f_ck', '["Step 1 — IS 456 gives the modulus of rupture as f_cr = 0.7 √f_ck.","Step 2 — √25 = 5 MPa.","Step 3 — f_cr = 0.7 × 5 = 3.5 MPa."]'::jsonb, 'IS 456:2000, Cl. 6.2.2', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-026', 'apsc-ae-civil', 226, 'Building Materials & Construction', 'Standard Laboratory Tests on Cement', 'Water for the Le-Chatelier Soundness Test', 'The standard consistency of a cement sample is 30%. Calculate the quantity of water required to prepare the paste from a 300 g cement sample for the Le-Chatelier soundness test.', '[{"id":"A","text":"54.0 ml"},{"id":"B","text":"70.2 ml"},{"id":"C","text":"90.0 ml"},{"id":"D","text":"23.4 ml"}]'::jsonb, '54.0 ml', '70.2 ml', '90.0 ml', '23.4 ml', 'B', 'Water = 0.78 × 30% = 23.4% of 300 g = 70.2 ml. Option C wrongly uses the consistency percentage P directly (30% of 300 g = 90 ml).', 'Water for soundness test = 0.78 · P (percent of cement mass)', '["Step 1 — For the Le-Chatelier test the paste is made with 0.78 P of water, where P = standard consistency.","Step 2 — 0.78 × 30 = 23.4% by mass of cement.","Step 3 — Water = 0.234 × 300 g = 70.2 g ≈ 70.2 ml (density of water = 1 g/ml)."]'::jsonb, 'IS 4031 (Part 3) — Soundness of Cement', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-027', 'apsc-ae-civil', 227, 'Building Materials & Construction', 'Aggregates — Grading & Testing', 'Fineness Modulus of Fine Aggregate', 'A sand sample has cumulative percentages retained of 2, 8, 18, 38, 68 and 92 on the 4.75 mm, 2.36 mm, 1.18 mm, 600 µm, 300 µm and 150 µm sieves respectively. Determine its fineness modulus.', '[{"id":"A","text":"1.13"},{"id":"B","text":"2.26"},{"id":"C","text":"3.78"},{"id":"D","text":"4.52"}]'::jsonb, '1.13', '2.26', '3.78', '4.52', 'B', 'Σ = 2 + 8 + 18 + 38 + 68 + 92 = 226, so FM = 226/100 = 2.26. Sand in the 2.2–2.6 band is medium sand, well suited to concrete.', 'FM = (Σ cumulative % retained) / 100', '["Step 1 — Add the cumulative percentages retained on the standard sieves: 2 + 8 + 18 + 38 + 68 + 92 = 226.","Step 2 — FM = Σ / 100 = 226/100 = 2.26.","Step 3 — Interpretation: FM < 2 is fine sand, 2–2.6 medium, > 3 coarse — so this is medium sand."]'::jsonb, 'IS 383 — Coarse and Fine Aggregate Grading', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-028', 'apsc-ae-civil', 228, 'Construction Management', 'CPM vs PERT & Activity Times', 'Expected Activity Duration', 'An activity has an optimistic time of 4 days, a most likely time of 7 days and a pessimistic time of 16 days. Determine its expected duration in PERT.', '[{"id":"A","text":"7.0 days"},{"id":"B","text":"8.0 days"},{"id":"C","text":"9.0 days"},{"id":"D","text":"10.0 days"}]'::jsonb, '7.0 days', '8.0 days', '9.0 days', '10.0 days', 'B', 't_e = (4 + 4×7 + 16)/6 = 48/6 = 8 days. The expected time exceeds the most likely time whenever the distribution is skewed to the right, as here.', 't_e = (t_o + 4·t_m + t_p) / 6', '["Step 1 — Formula: t_e = (t_o + 4 t_m + t_p)/6.","Step 2 — t_e = (4 + 28 + 16)/6.","Step 3 — t_e = 48/6 = 8 days."]'::jsonb, 'PERT and CPM — L.S. Srinath', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-029', 'apsc-ae-civil', 229, 'Construction Management', 'CPM vs PERT & Activity Times', 'Standard Deviation of an Activity', 'For the same activity (optimistic 4 days, most likely 7 days, pessimistic 16 days), determine the standard deviation of the activity duration.', '[{"id":"A","text":"2.0 days"},{"id":"B","text":"3.0 days"},{"id":"C","text":"6.0 days"},{"id":"D","text":"12.0 days"}]'::jsonb, '2.0 days', '3.0 days', '6.0 days', '12.0 days', 'A', 'σ = (16 − 4)/6 = 2 days. The variance is σ² = 4 days², which is the quantity actually summed along the critical path.', 'σ = (t_p − t_o) / 6', '["Step 1 — Range for one standard deviation: t_o to t_p spans 6σ.","Step 2 — σ = (t_p − t_o)/6 = (16 − 4)/6.","Step 3 — σ = 12/6 = 2 days, so variance = 4 days²."]'::jsonb, 'PERT and CPM — L.S. Srinath', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-030', 'apsc-ae-civil', 230, 'Construction Management', 'Network Analysis — Floats & Critical Path', 'Total Float of an Activity', 'In a network, node 1 links to node 3 directly by an activity of 12 days, and also through node 2 by activities of 4 days (1–2) and 5 days (2–3). Determine the total float of the activity 1–2.', '[{"id":"A","text":"0 days"},{"id":"B","text":"3 days"},{"id":"C","text":"5 days"},{"id":"D","text":"7 days"}]'::jsonb, '0 days', '3 days', '5 days', '7 days', 'B', 'The path 1–2–3 takes 4 + 5 = 9 days against 12 days on 1–3, so activity 1–2 can be delayed by 12 − 9 = 3 days without delaying the project.', 'Total float = LFT − EFT (or LST − EST)', '["Step 1 — Critical path is 1–3 with duration 12 days (the longest path).","Step 2 — Project duration = 12 days; EFT of 1–2 = 4 days.","Step 3 — For 1–2 to finish without delaying 2–3, it must complete by 12 − 5 = 7 days.","Step 4 — Total float = 7 − 4 = 3 days."]'::jsonb, 'PERT and CPM — L.S. Srinath', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-031', 'apsc-ae-civil', 231, 'Hydrology & Irrigation Engineering', 'Crop Water Requirements: Duty, Delta & Base Period', 'Duty of Canal Water', 'A crop with a base period of 120 days requires a total depth of water (Δ) of 96 cm. Determine the duty of the canal water at the field outlet.', '[{"id":"A","text":"108 ha/cumec"},{"id":"B","text":"960 ha/cumec"},{"id":"C","text":"1080 ha/cumec"},{"id":"D","text":"864 ha/cumec"}]'::jsonb, '108 ha/cumec', '960 ha/cumec', '1080 ha/cumec', '864 ha/cumec', 'C', 'D = 864 × 120 / 96 = 1080 ha/cumec. Duty rises with base period and falls with the depth of water required — the two are inversely related.', 'D = 864 · B / Δ   (B in days, Δ in cm)', '["Step 1 — Relation between duty, base period and delta: D = 864 B / Δ.","Step 2 — D = (864 × 120) / 96.","Step 3 — 864 × 120 = 103,680; ÷ 96 = 1080 ha/cumec."]'::jsonb, 'Irrigation Engineering — S.K. Garg', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-032', 'apsc-ae-civil', 232, 'Hydrology & Irrigation Engineering', 'Lacey''s Regime Theory vs Kennedy''s Silt Theory', 'Wetted Perimeter by Lacey', 'A stable regime channel carries a discharge of 64 cumecs. Calculate its wetted perimeter as per Lacey’s theory.', '[{"id":"A","text":"24 m"},{"id":"B","text":"38 m"},{"id":"C","text":"43 m"},{"id":"D","text":"76 m"}]'::jsonb, '24 m', '38 m', '43 m', '76 m', 'B', 'P = 4.75 × √64 = 4.75 × 8 = 38 m. Lacey’s regime equations give silt factor dependent quantities; here f = 1 was implied by the standard form.', 'P = 4.75 · √Q', '["Step 1 — Lacey wetted perimeter: P = 4.75 √Q.","Step 2 — √64 = 8.","Step 3 — P = 4.75 × 8 = 38 m."]'::jsonb, 'Irrigation Engineering — S.K. Garg', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-033', 'apsc-ae-civil', 233, 'Hydrology & Irrigation Engineering', 'Unit Hydrograph Theory & S-Curve Synthesis', 'Volume of Direct Runoff from a Unit Hydrograph', 'A 4-hour unit hydrograph belongs to a catchment of 360 km² and has a peak of 60 m³/s. Determine the total volume of direct runoff represented by this unit hydrograph.', '[{"id":"A","text":"0.36 × 10⁶ m³"},{"id":"B","text":"3.6 × 10⁶ m³"},{"id":"C","text":"36 × 10⁶ m³"},{"id":"D","text":"3.6 × 10³ m³"}]'::jsonb, '0.36 × 10⁶ m³', '3.6 × 10⁶ m³', '36 × 10⁶ m³', '3.6 × 10³ m³', 'B', 'A unit hydrograph represents 1 cm of direct runoff. 1 cm over 1 km² = 10⁴ m³, so over 360 km² the volume = 360 × 10⁴ = 3.6 × 10⁶ m³. The peak value is not needed — it is a deliberate distractor.', 'V = A × (1 cm) ;  1 cm over 1 km² = 10⁴ m³', '["Step 1 — By definition, a unit hydrograph represents 1 cm of direct runoff over the catchment.","Step 2 — 1 cm over 1 km² = 0.01 m × 10⁶ m² = 10⁴ m³.","Step 3 — Over 360 km²: V = 360 × 10⁴ = 3.6 × 10⁶ m³ (3.6 Mm³).","Step 4 — Cross-check the base time: V = ∫Q dt, so a 60 m³/s peak with this volume needs a base of roughly 17 hours — consistent."]'::jsonb, 'Engineering Hydrology — K. Subramanya', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-034', 'apsc-ae-civil', 234, 'Prestressed Concrete', 'The 6 Losses of Prestress', 'Loss Due to Anchorage Slip', 'A post-tensioned tendon 30 m long is stressed from one end and slips 3 mm into the anchorage. Taking E_s = 200 GPa, calculate the loss of prestress due to anchorage slip.', '[{"id":"A","text":"2 MPa"},{"id":"B","text":"6 MPa"},{"id":"C","text":"20 MPa"},{"id":"D","text":"60 MPa"}]'::jsonb, '2 MPa', '6 MPa', '20 MPa', '60 MPa', 'C', 'Δf = (3 × 200,000)/30,000 = 20 MPa. Keep units consistent: millimetres for slip, N/mm² for E_s, millimetres for length.', 'Δf = (Δ_slip · E_s) / L', '["Step 1 — Formula: Δf = (Δ · E_s)/L, where Δ is the anchorage slip.","Step 2 — Convert: E_s = 200 GPa = 200,000 N/mm²; L = 30 m = 30,000 mm.","Step 3 — Δf = (3 mm × 200,000 N/mm²) / 30,000 mm = 600,000/30,000.","Step 4 — Δf = 20 N/mm² = 20 MPa."]'::jsonb, 'Prestressed Concrete — N. Krishna Raju', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-035', 'apsc-ae-civil', 235, 'Prestressed Concrete', 'Lin''s Load Balancing Concept', 'Upward Balanced Load', 'A prestressed beam of 10 m span has a parabolic tendon with a prestressing force of 500 kN and a central sag of 100 mm. Determine the upward balanced load per metre from Lin’s load balancing concept.', '[{"id":"A","text":"0.4 kN/m"},{"id":"B","text":"4.0 kN/m"},{"id":"C","text":"8.0 kN/m"},{"id":"D","text":"40.0 kN/m"}]'::jsonb, '0.4 kN/m', '4.0 kN/m', '8.0 kN/m', '40.0 kN/m', 'B', 'w_up = 8 × 500 × 0.1 / 100 = 4.0 kN/m. The tendon’s sag profile of 0.1 m must be used in metres throughout.', 'w_up = 8 · P · e / L²', '["Step 1 — Load balancing: a parabolic tendon exerts a uniform upward load w_up = 8Pe/L².","Step 2 — P = 500 kN, e = 100 mm = 0.1 m, L = 10 m → L² = 100 m².","Step 3 — w_up = (8 × 500 × 0.1)/100 = 400/100 = 4.0 kN/m.","Step 4 — Balanced load equals this upward value; the beam then carries only the net downward load."]'::jsonb, 'Prestressed Concrete — N. Krishna Raju', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-036', 'apsc-ae-civil', 236, 'Prestressed Concrete', 'Analysis of Prestress & Effective Force', 'Effective Prestressing Force After Losses', 'A tendon of cross-sectional area 500 mm² is initially stressed to 1200 MPa. If the total losses are estimated at 18%, determine the effective prestressing force.', '[{"id":"A","text":"460 kN"},{"id":"B","text":"492 kN"},{"id":"C","text":"520 kN"},{"id":"D","text":"600 kN"}]'::jsonb, '460 kN', '492 kN', '520 kN', '600 kN', 'B', 'P_i = 1200 × 500 = 600 kN, and with 18% losses P_e = 0.82 × 600 = 492 kN. Option D is the initial force before losses.', 'P_e = (1 − loss fraction) · P_i ;  P_i = σ_i · A_p', '["Step 1 — Initial prestressing force: P_i = σ_i · A_p = 1200 N/mm² × 500 mm².","Step 2 — P_i = 600,000 N = 600 kN.","Step 3 — Losses = 18%, so the effective force is 82% of the initial: P_e = 0.82 × 600.","Step 4 — P_e = 492 kN."]'::jsonb, 'Prestressed Concrete — N. Krishna Raju', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-037', 'apsc-ae-civil', 237, 'Estimating & Costing', 'Methods of Building Measurement & IS 1200 Rules', 'Centreline Method with T-Junctions', 'A building’s walls are 30 cm thick and have a total centreline length of 50 m. If the plan contains 4 T-junctions, determine the net length used for estimating the masonry.', '[{"id":"A","text":"45.0 m"},{"id":"B","text":"48.8 m"},{"id":"C","text":"50.0 m"},{"id":"D","text":"51.2 m"}]'::jsonb, '45.0 m', '48.8 m', '50.0 m', '51.2 m', 'B', 'Each junction is counted twice along the centreline, so deduct half the thickness per junction per side: 50 − 4 × 0.3 = 48.8 m. Option D adds instead of deducting.', 'Net length = Total centreline length − (number of junctions × half wall thickness × 2)', '["Step 1 — In the centreline method, the centreline of a wall is measured once and junctions are deducted.","Step 2 — Deduction per T-junction = half the thickness from each side = 2 × (0.3/2) = 0.3 m.","Step 3 — For 4 junctions: deduction = 4 × 0.3 = 1.2 m.","Step 4 — Net length = 50 − 1.2 = 48.8 m."]'::jsonb, 'Estimating, Costing & Valuation — B.N. Dutta', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-038', 'apsc-ae-civil', 238, 'Estimating & Costing', 'Valuation, Depreciation & Sinking Fund', 'Capitalized Value of a Property', 'A property yields a net annual income of ₹60,000 and the prevailing rate of interest is 6% per annum. Calculate its capitalized value.', '[{"id":"A","text":"₹1,00,000"},{"id":"B","text":"₹3,60,000"},{"id":"C","text":"₹10,00,000"},{"id":"D","text":"₹12,00,000"}]'::jsonb, '₹1,00,000', '₹3,60,000', '₹10,00,000', '₹12,00,000', 'C', 'Capitalized value = 60,000/0.06 = ₹10,00,000. Option B is 6 × the income, i.e. dividing by 0.1 instead of 0.06.', 'Capitalized value = Net annual income / Rate of interest (as a decimal)', '["Step 1 — Capitalized value is the present worth of the perpetual net income.","Step 2 — Rate as a decimal: 6% = 0.06.","Step 3 — Capitalized value = 60,000 / 0.06 = ₹10,00,000."]'::jsonb, 'Estimating, Costing & Valuation — B.N. Dutta', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-039', 'apsc-ae-civil', 239, 'Estimating & Costing', 'Methods of Building Measurement & IS 1200 Rules', 'Volume of Plastering', 'A wall 5 m long and 3 m high is to be plastered 12 mm thick on both faces. Calculate the volume of plastering work.', '[{"id":"A","text":"0.18 m³"},{"id":"B","text":"0.36 m³"},{"id":"C","text":"0.72 m³"},{"id":"D","text":"3.60 m³"}]'::jsonb, '0.18 m³', '0.36 m³', '0.72 m³', '3.60 m³', 'B', 'One face = 5 × 3 = 15 m²; both faces = 30 m². Volume = 30 × 0.012 = 0.36 m³. Option A forgets the second face.', 'Volume = Area × Thickness', '["Step 1 — Area of one face: 5 m × 3 m = 15 m².","Step 2 — Both faces: 2 × 15 = 30 m².","Step 3 — Thickness = 12 mm = 0.012 m.","Step 4 — Volume = 30 × 0.012 = 0.36 m³."]'::jsonb, 'IS 1200 (Part 12) — Plastering', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-040', 'apsc-ae-civil', 240, 'Highway & Transportation Engineering', 'Highway Geometric Design & Cross-Section', 'Stopping Sight Distance', 'Calculate the stopping sight distance for a design speed of 80 km/h on a level road with a coefficient of longitudinal friction of 0.35 and a driver reaction time of 2.5 seconds.', '[{"id":"A","text":"55.6 m"},{"id":"B","text":"71.9 m"},{"id":"C","text":"127.5 m"},{"id":"D","text":"143.8 m"}]'::jsonb, '55.6 m', '71.9 m', '127.5 m', '143.8 m', 'C', 'Lag = 22.22 × 2.5 = 55.6 m; braking = 22.22²/(2 × 9.81 × 0.35) = 71.9 m; SSD = 127.5 m. Options A and B are the two components, not the total.', 'SSD = v·t + v²/(2·g·f)  (v in m/s)', '["Step 1 — Convert the design speed: v = 80 km/h = 80/3.6 = 22.22 m/s.","Step 2 — Reaction (lag) distance = v·t = 22.22 × 2.5 = 55.56 m.","Step 3 — Braking distance = v²/(2 g f) = (22.22)²/(2 × 9.81 × 0.35) = 493.8/6.867 = 71.9 m.","Step 4 — SSD = 55.56 + 71.9 = 127.5 m."]'::jsonb, 'Highway Engineering — Khanna & Justo', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-041', 'apsc-ae-civil', 241, 'Highway & Transportation Engineering', 'Highway Geometric Design & Cross-Section', 'Superelevation', 'A horizontal curve of radius 300 m is to be designed for a speed of 80 km/h. Determine the superelevation required, neglecting friction.', '[{"id":"A","text":"0.056"},{"id":"B","text":"0.084"},{"id":"C","text":"0.168"},{"id":"D","text":"0.210"}]'::jsonb, '0.056', '0.084', '0.168', '0.210', 'C', 'e = 80²/(127 × 300) = 6400/38100 = 0.168, i.e. about 1 in 6 — above the practical maximum of 0.07, so in practice a larger radius or a lower design speed (superelevation with friction) would be needed.', 'e = V² / (127 · R)   (V in km/h, R in m)', '["Step 1 — Formula with speed in km/h: e = V²/(127 R).","Step 2 — e = (80)²/(127 × 300) = 6400/38,100.","Step 3 — e = 0.168.","Step 4 — Interpretation: 0.168 far exceeds the 0.07 limit, so the full centrifugal force cannot be balanced by superelevation alone."]'::jsonb, 'IRC 73 — Geometric Design of Hill Roads', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-ce-042', 'apsc-ae-civil', 242, 'Highway & Transportation Engineering', 'Highway Geometric Design & Cross-Section', 'Extra Widening on Horizontal Curves', 'A two-lane highway curves with a radius of 300 m and is designed for 80 km/h. Taking a wheelbase of 6 m, calculate the total extra widening required.', '[{"id":"A","text":"0.12 m"},{"id":"B","text":"0.49 m"},{"id":"C","text":"0.61 m"},{"id":"D","text":"0.73 m"}]'::jsonb, '0.12 m', '0.49 m', '0.61 m', '0.73 m', 'C', 'Mechanical widening = 2 × 6²/(2 × 300) = 0.12 m; psychological widening = 80/(9.5√300) = 0.49 m; total = 0.61 m. Options A and B are the individual components.', 'W_e = n·l²/(2R) + V/(9.5·√R)', '["Step 1 — Mechanical widening (off-tracking) for n = 2 lanes, l = 6 m: W_m = nl²/(2R) = (2 × 36)/600 = 0.12 m.","Step 2 — Psychological widening: W_ps = V/(9.5√R) = 80/(9.5 × 17.32).","Step 3 — √300 = 17.32 → 9.5 × 17.32 = 164.5 → W_ps = 80/164.5 = 0.49 m.","Step 4 — Total extra widening = 0.12 + 0.49 = 0.61 m."]'::jsonb, 'Highway Engineering — Khanna & Justo', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-001', 'apsc-ae-civil', 243, 'Geotechnical Engineering', 'Soil Phase Relations & Index Properties', 'Void Ratio from Porosity', 'A soil sample has a measured porosity n = 0.40 and specific gravity G = 2.70. Compute the void ratio (e) of the soil.', '[{"id":"A","text":"0.400"},{"id":"B","text":"0.667"},{"id":"C","text":"0.286"},{"id":"D","text":"1.500"}]'::jsonb, '0.400', '0.667', '0.286', '1.500', 'B', 'Void ratio e = n / (1 - n) = 0.40 / (1 - 0.40) = 0.40 / 0.60 = 0.667. Option C uses n / (1 + n); D inverts the formula.', 'e = n / (1 - n)', '["Step 1 — Formula relating void ratio and porosity: e = n / (1 - n).","Step 2 — Substitute n = 0.40: e = 0.40 / (1 - 0.40).","Step 3 — e = 0.40 / 0.60 = 2/3 = 0.667."]'::jsonb, 'Soil Mechanics & Foundation Engineering — K.R. Arora', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-002', 'apsc-ae-civil', 244, 'Geotechnical Engineering', 'Soil Phase Relations & Index Properties', 'Degree of Saturation Calculation', 'A soil specimen has moisture content w = 20%, specific gravity G = 2.65, and void ratio e = 0.65. Determine its degree of saturation.', '[{"id":"A","text":"68.5%"},{"id":"B","text":"81.5%"},{"id":"C","text":"92.0%"},{"id":"D","text":"100.0%"}]'::jsonb, '68.5%', '81.5%', '92.0%', '100.0%', 'B', 'From phase relationship S_r = (w · G) / e = (0.20 × 2.65) / 0.65 = 0.53 / 0.65 = 0.8154 = 81.5%. Option A divides by G; C uses G = 3.0.', 'S_r · e = w · G', '["Step 1 — Fundamental identity: S_r · e = w · G.","Step 2 — Solve for S_r: S_r = (w · G) / e.","Step 3 — Numerator: 0.20 × 2.65 = 0.53.","Step 4 — S_r = 0.53 / 0.65 = 0.8154 = 81.54% ≈ 81.5%."]'::jsonb, 'Basic and Applied Soil Mechanics — Gopal Ranjan & Rao', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-003', 'apsc-ae-civil', 245, 'Geotechnical Engineering', 'Permeability & Seepage', 'Critical Hydraulic Gradient & Quick Sand', 'A stratum of clean sand has specific gravity G = 2.67 and void ratio e = 0.67. Calculate the critical hydraulic gradient (i_cr) at which quicksand condition initiates.', '[{"id":"A","text":"0.85"},{"id":"B","text":"1.00"},{"id":"C","text":"1.25"},{"id":"D","text":"1.67"}]'::jsonb, '0.85', '1.00', '1.25', '1.67', 'B', 'i_cr = (G - 1) / (1 + e) = (2.67 - 1) / (1 + 0.67) = 1.67 / 1.67 = 1.00. At this gradient, upward seepage force exactly balances buoyant submerged soil weight.', 'i_cr = (G - 1) / (1 + e)', '["Step 1 — Critical hydraulic gradient formula: i_cr = (G - 1) / (1 + e).","Step 2 — Numerator: 2.67 - 1 = 1.67.","Step 3 — Denominator: 1 + 0.67 = 1.67.","Step 4 — i_cr = 1.67 / 1.67 = 1.00."]'::jsonb, 'IS 6403 & Terzaghi Geotechnical Principles', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-004', 'apsc-ae-civil', 246, 'Geotechnical Engineering', 'Effective Stress Principle', 'Effective Vertical Stress at Depth', 'A soil profile consists of 2 m dry sand (γ_d = 16 kN/m³) overlying 4 m saturated sand (γ_sat = 20 kN/m³). Water table is 2 m below surface. Taking γ_w = 9.81 kN/m³, compute effective vertical stress at 6 m depth.', '[{"id":"A","text":"112.00 kPa"},{"id":"B","text":"72.76 kPa"},{"id":"C","text":"53.14 kPa"},{"id":"D","text":"92.38 kPa"}]'::jsonb, '112.00 kPa', '72.76 kPa', '53.14 kPa', '92.38 kPa', 'B', 'Total stress σ = (2 × 16) + (4 × 20) = 32 + 80 = 112 kPa. Pore pressure u = 4 × 9.81 = 39.24 kPa. Effective stress σ'' = 112 - 39.24 = 72.76 kPa.', 'σ'' = σ - u = Σ(γ · z) - γ_w · z_w', '["Step 1 — Total vertical stress σ: (2 m × 16 kN/m³) + (4 m × 20 kN/m³) = 32 + 80 = 112.0 kPa.","Step 2 — Pore water pressure u at 6 m (head = 4 m): u = 4 m × 9.81 kN/m³ = 39.24 kPa.","Step 3 — Effective vertical stress: σ'' = σ - u = 112.0 - 39.24 = 72.76 kPa."]'::jsonb, 'Soil Mechanics — Lambe & Whitman', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-005', 'apsc-ae-civil', 247, 'Geotechnical Engineering', 'Permeability & Seepage', 'Seepage Flow Net Discharge', 'A diversion weir retains a head H = 6.0 m of water. The constructed flow net has N_f = 4 flow channels and N_d = 12 potential drops. If permeability k = 3 × 10⁻⁵ m/s, calculate seepage discharge per meter run of weir.', '[{"id":"A","text":"6.0 × 10⁻⁵ m³/s/m"},{"id":"B","text":"1.8 × 10⁻⁴ m³/s/m"},{"id":"C","text":"2.0 × 10⁻⁵ m³/s/m"},{"id":"D","text":"7.2 × 10⁻⁴ m³/s/m"}]'::jsonb, '6.0 × 10⁻⁵ m³/s/m', '1.8 × 10⁻⁴ m³/s/m', '2.0 × 10⁻⁵ m³/s/m', '7.2 × 10⁻⁴ m³/s/m', 'A', 'Seepage discharge q = k · H · (N_f / N_d) = (3 × 10⁻⁵) × 6 × (4 / 12) = 1.8 × 10⁻⁴ × (1/3) = 6.0 × 10⁻⁵ m³/s/m.', 'q = k · H · (N_f / N_d)', '["Step 1 — Flow net formula: q = k · H · (N_f / N_d).","Step 2 — Shape factor: N_f / N_d = 4 / 12 = 1/3.","Step 3 — Multiply: q = 3 × 10⁻⁵ × 6.0 × (1/3) = 6.0 × 10⁻⁵ m³/s/m."]'::jsonb, 'Irrigation Engineering & Hydraulic Structures — S.K. Garg', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-006', 'apsc-ae-civil', 248, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity for Strip Footing on Clay', 'A strip footing 2.0 m wide is founded at 1.5 m depth in saturated clay having undrained cohesion c_u = 40 kPa, φ = 0°, and γ = 18 kN/m³. For φ = 0°, N_c = 5.7, N_q = 1.0, N_γ = 0. Determine ultimate bearing capacity (q_ult).', '[{"id":"A","text":"228.0 kPa"},{"id":"B","text":"255.0 kPa"},{"id":"C","text":"282.0 kPa"},{"id":"D","text":"310.0 kPa"}]'::jsonb, '228.0 kPa', '255.0 kPa', '282.0 kPa', '310.0 kPa', 'B', 'q_ult = c · N_c + γ · D_f · N_q = (40 × 5.7) + (18 × 1.5 × 1.0) = 228 + 27 = 255 kPa. Option A neglects the surcharge term γ·Df.', 'q_ult = c · N_c + γ · D_f · N_q', '["Step 1 — Terzaghi equation for strip footing: q_ult = c · N_c + γ · D_f · N_q + 0.5 · γ · B · N_γ.","Step 2 — For φ = 0: N_γ = 0, N_c = 5.7, N_q = 1.0.","Step 3 — Cohesion term: c · N_c = 40 × 5.7 = 228.0 kPa.","Step 4 — Surcharge term: γ · D_f · N_q = 18 × 1.5 × 1.0 = 27.0 kPa.","Step 5 — q_ult = 228.0 + 27.0 = 255.0 kPa."]'::jsonb, 'IS 6403:1981 — Determination of Bearing Capacity of Shallow Foundations', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-007', 'apsc-ae-civil', 249, 'Geotechnical Engineering', 'Lateral Earth Pressure & Retaining Structures', 'Rankine Active Earth Pressure Coefficient', 'A vertical retaining wall supports cohesionless backfill with an angle of internal friction φ = 30°. Determine the Rankine active earth pressure coefficient (K_a).', '[{"id":"A","text":"0.333"},{"id":"B","text":"0.500"},{"id":"C","text":"3.000"},{"id":"D","text":"0.250"}]'::jsonb, '0.333', '0.500', '3.000', '0.250', 'A', 'K_a = (1 - sin 30°) / (1 + sin 30°) = (1 - 0.5) / (1 + 0.5) = 0.5 / 1.5 = 1/3 = 0.333. Option C is passive coefficient K_p = 1/K_a = 3.0.', 'K_a = (1 - sin φ) / (1 + sin φ)', '["Step 1 — Rankine active coefficient: K_a = (1 - sin φ) / (1 + sin φ).","Step 2 — sin 30° = 0.5.","Step 3 — K_a = (1 - 0.5) / (1 + 0.5) = 0.5 / 1.5 = 1/3 ≈ 0.333."]'::jsonb, 'Foundation Engineering — P.C. Varghese', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-008', 'apsc-ae-civil', 250, 'Geotechnical Engineering', 'Lateral Earth Pressure & Retaining Structures', 'Total Active Thrust on Wall', 'A smooth vertical wall 6.0 m high retains dry sand with unit weight γ = 18 kN/m³ and internal friction angle φ = 30° (K_a = 1/3). Calculate total active horizontal thrust per meter run of wall.', '[{"id":"A","text":"54 kN/m"},{"id":"B","text":"108 kN/m"},{"id":"C","text":"216 kN/m"},{"id":"D","text":"324 kN/m"}]'::jsonb, '54 kN/m', '108 kN/m', '216 kN/m', '324 kN/m', 'B', 'P_a = 0.5 × (1/3) × 18 × 6² = 0.5 × 6 × 36 = 108 kN/m acting at H/3 = 2.0 m above base. Option C forgets 0.5 factor; A uses H instead of H².', 'P_a = 0.5 · K_a · γ · H²', '["Step 1 — Active thrust formula: P_a = 0.5 · K_a · γ · H².","Step 2 — Substitute: P_a = 0.5 × (1/3) × 18 × (6.0)².","Step 3 — 0.5 × 6 × 36 = 108 kN/m."]'::jsonb, 'Soil Mechanics in Engineering Practice — Terzaghi & Peck', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-009', 'apsc-ae-civil', 251, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Shear Strength Criterion', 'In a direct shear test on compacted clayey sand, cohesion c = 25 kPa and friction angle φ = 24° (tan 24° = 0.445). Under an effective normal stress σ'' = 120 kPa, compute shear strength (τ_f).', '[{"id":"A","text":"53.4 kPa"},{"id":"B","text":"78.4 kPa"},{"id":"C","text":"95.2 kPa"},{"id":"D","text":"112.0 kPa"}]'::jsonb, '53.4 kPa', '78.4 kPa', '95.2 kPa', '112.0 kPa', 'B', 'τ_f = c + σ'' · tan φ = 25 + (120 × 0.445) = 25 + 53.4 = 78.4 kPa. Option A is the frictional resistance alone without cohesion.', 'τ_f = c + σ'' · tan φ', '["Step 1 — Mohr-Coulomb equation: τ_f = c + σ'' · tan φ.","Step 2 — Frictional component: 120 kPa × 0.445 = 53.4 kPa.","Step 3 — Add cohesion: τ_f = 25.0 + 53.4 = 78.4 kPa."]'::jsonb, 'IS 2720 (Part 13) — Direct Shear Test', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-010', 'apsc-ae-civil', 252, 'Geotechnical Engineering', 'Soil Compressibility & Consolidation', 'Primary Consolidation Settlement', 'A 4.0 m thick saturated clay layer has initial void ratio e₀ = 0.80 and compression index C_c = 0.30. Effective overburden stress increases from σ₀'' = 100 kPa to σ_f'' = 200 kPa. Calculate primary consolidation settlement.', '[{"id":"A","text":"125 mm"},{"id":"B","text":"201 mm"},{"id":"C","text":"280 mm"},{"id":"D","text":"360 mm"}]'::jsonb, '125 mm', '201 mm', '280 mm', '360 mm', 'B', 'S_c = [(0.30 × 4.0) / (1 + 0.80)] × log₁₀(200 / 100) = (1.20 / 1.80) × 0.3010 = 0.667 × 0.3010 = 0.2008 m = 200.8 mm ≈ 201 mm.', 'S_c = [C_c · H₀ / (1 + e₀)] · log₁₀(σ_f'' / σ₀'')', '["Step 1 — Settlement equation: S_c = [C_c · H₀ / (1 + e₀)] · log₁₀(σ_f'' / σ₀'').","Step 2 — Lead coefficient: (0.30 × 4.0) / 1.80 = 1.20 / 1.80 = 0.667 m.","Step 3 — Logarithm factor: log₁₀(200 / 100) = log₁₀(2.0) = 0.3010.","Step 4 — S_c = 0.667 × 0.3010 = 0.2008 m = 200.8 mm ≈ 201 mm."]'::jsonb, 'Geotechnical Engineering — Braja M. Das', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-011', 'apsc-ae-civil', 253, 'Geotechnical Engineering', 'Soil Compressibility & Consolidation', 'Coefficient of Consolidation from Laboratory Test', 'In an oedometer test, a clay sample of thickness 20 mm with double drainage reaches 50% consolidation (T_v = 0.197) in 15 minutes. Determine the coefficient of consolidation C_v.', '[{"id":"A","text":"2.19 × 10⁻⁴ cm²/s"},{"id":"B","text":"8.76 × 10⁻⁴ cm²/s"},{"id":"C","text":"1.31 × 10⁻³ cm²/s"},{"id":"D","text":"5.48 × 10⁻⁵ cm²/s"}]'::jsonb, '2.19 × 10⁻⁴ cm²/s', '8.76 × 10⁻⁴ cm²/s', '1.31 × 10⁻³ cm²/s', '5.48 × 10⁻⁵ cm²/s', 'A', 'Double drainage means drainage path d = 20 / 2 = 10 mm = 1.0 cm. Time t = 15 × 60 = 900 s. C_v = (0.197 × 1.0²) / 900 = 2.19 × 10⁻⁴ cm²/s. Option B uses single drainage (d = 2.0 cm).', 'C_v = (T_v · d²) / t', '["Step 1 — Drainage path length for double drainage: d = H / 2 = 20 mm / 2 = 10 mm = 1.0 cm.","Step 2 — Convert time: t = 15 min × 60 s/min = 900 s.","Step 3 — C_v = (T_v · d²) / t = (0.197 × 1.0²) / 900 = 0.197 / 900 = 2.189 × 10⁻⁴ cm²/s ≈ 2.19 × 10⁻⁴ cm²/s."]'::jsonb, 'IS 2720 (Part 15) — One-dimensional Consolidation Properties', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-012', 'apsc-ae-civil', 254, 'Geotechnical Engineering', 'Permeability & Seepage', 'Seepage Velocity vs Discharge Velocity', 'A saturated sand stratum has void ratio e = 0.60 and hydraulic conductivity k = 4.0 × 10⁻⁴ m/s. Under a hydraulic gradient i = 0.05, calculate the actual seepage velocity (v_s).', '[{"id":"A","text":"2.00 × 10⁻⁵ m/s"},{"id":"B","text":"3.33 × 10⁻⁵ m/s"},{"id":"C","text":"5.33 × 10⁻⁵ m/s"},{"id":"D","text":"8.00 × 10⁻⁵ m/s"}]'::jsonb, '2.00 × 10⁻⁵ m/s', '3.33 × 10⁻⁵ m/s', '5.33 × 10⁻⁵ m/s', '8.00 × 10⁻⁵ m/s', 'C', 'Porosity n = e / (1 + e) = 0.60 / 1.60 = 0.375. Discharge velocity v = k · i = (4 × 10⁻⁴) × 0.05 = 2.0 × 10⁻⁵ m/s. Seepage velocity v_s = v / n = (2.0 × 10⁻⁵) / 0.375 = 5.33 × 10⁻⁵ m/s. Option A is discharge velocity.', 'v_s = v / n,  where v = k · i and n = e / (1 + e)', '["Step 1 — Porosity n = e / (1 + e) = 0.60 / 1.60 = 0.375.","Step 2 — Discharge velocity (Darcy law): v = k · i = 4.0 × 10⁻⁴ × 0.05 = 2.0 × 10⁻⁵ m/s.","Step 3 — Seepage velocity through pore channels: v_s = v / n = 2.0 × 10⁻⁵ / 0.375 = 5.333 × 10⁻⁵ m/s."]'::jsonb, 'Soil Mechanics — Craig', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-013', 'apsc-ae-civil', 255, 'Geotechnical Engineering', 'Site Exploration & Deep Foundations', 'SPT Dilatancy Correction', 'During standard penetration testing in saturated fine silty sand below the water table, the recorded blow count is N_0 = 31. Determine the corrected SPT blow count (N_cor) after applying the Terzaghi-Peck dilatancy correction.', '[{"id":"A","text":"21"},{"id":"B","text":"23"},{"id":"C","text":"26"},{"id":"D","text":"31"}]'::jsonb, '21', '23', '26', '31', 'B', 'Dilatancy correction applies for saturated fine sands when N_0 > 15 due to transient negative pore water pressures. N_cor = 15 + 0.5 × (31 - 15) = 15 + 0.5 × 16 = 15 + 8 = 23.', 'N_cor = 15 + 0.5 · (N_0 - 15)  [for N_0 > 15]', '["Step 1 — Check condition: N_0 = 31 > 15 in saturated fine sand.","Step 2 — Formula: N_cor = 15 + 0.5 · (N_0 - 15).","Step 3 — N_cor = 15 + 0.5 × (31 - 15) = 15 + 8 = 23."]'::jsonb, 'IS 2131:1981 — Method for Standard Penetration Test for Soils', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-014', 'apsc-ae-civil', 256, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Unconfined Compressive Strength & Undrained Cohesion', 'An undisturbed cylindrical clay specimen fails in an unconfined compression test at an axial failure stress q_u = 140 kPa. What is the undrained shear strength (cohesion c_u) of the clay?', '[{"id":"A","text":"35 kPa"},{"id":"B","text":"70 kPa"},{"id":"C","text":"140 kPa"},{"id":"D","text":"280 kPa"}]'::jsonb, '35 kPa', '70 kPa', '140 kPa', '280 kPa', 'B', 'For purely cohesive saturated soil in unconfined compression (φ = 0), the radius of Mohr circle equals shear strength: c_u = q_u / 2 = 140 / 2 = 70 kPa.', 'c_u = q_u / 2', '["Step 1 — For saturated clay (φ_u = 0), unconfined compressive strength q_u = 2 · c_u.","Step 2 — Undrained cohesion c_u = q_u / 2 = 140 / 2 = 70 kPa."]'::jsonb, 'IS 2720 (Part 10) — Unconfined Compression Test', 'EASY', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-015', 'apsc-ae-civil', 257, 'Geotechnical Engineering', 'Soil Phase Relations & Index Properties', 'Submerged Unit Weight Calculation', 'A soil has specific gravity G = 2.70 and void ratio e = 0.70. Taking γ_w = 9.81 kN/m³, compute the submerged (buoyant) unit weight (γ'') of the soil.', '[{"id":"A","text":"7.85 kN/m³"},{"id":"B","text":"9.81 kN/m³"},{"id":"C","text":"15.58 kN/m³"},{"id":"D","text":"19.62 kN/m³"}]'::jsonb, '7.85 kN/m³', '9.81 kN/m³', '15.58 kN/m³', '19.62 kN/m³', 'B', 'γ'' = [(G - 1) / (1 + e)] · γ_w = [(2.70 - 1) / (1 + 0.70)] × 9.81 = (1.70 / 1.70) × 9.81 = 1.00 × 9.81 = 9.81 kN/m³.', 'γ'' = [(G - 1) / (1 + e)] · γ_w', '["Step 1 — Submerged unit weight formula: γ'' = [(G - 1) / (1 + e)] · γ_w.","Step 2 — Numerator: 2.70 - 1 = 1.70.","Step 3 — Denominator: 1 + 0.70 = 1.70.","Step 4 — Ratio: 1.70 / 1.70 = 1.00.","Step 5 — γ'' = 1.00 × 9.81 = 9.81 kN/m³."]'::jsonb, 'Engineering Properties of Soils — Bowles', 'MEDIUM', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('num-geo-016', 'apsc-ae-civil', 258, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity for Square Footing on Sand', 'A square footing 2.0 m × 2.0 m is placed at 1.0 m depth in dry cohesionless sand (c = 0, γ = 18 kN/m³). Bearing capacity factors are N_q = 20 and N_γ = 20. Calculate the ultimate bearing capacity (q_ult).', '[{"id":"A","text":"360 kPa"},{"id":"B","text":"504 kPa"},{"id":"C","text":"648 kPa"},{"id":"D","text":"720 kPa"}]'::jsonb, '360 kPa', '504 kPa', '648 kPa', '720 kPa', 'C', 'For square footing in sand (c = 0): q_ult = γ · D_f · N_q + 0.4 · γ · B · N_γ = (18 × 1.0 × 20) + (0.4 × 18 × 2.0 × 20) = 360 + 288 = 648 kPa. Option A omits the width term (surcharge only); B uses strip factor 0.5 without square correction.', 'q_ult = γ · D_f · N_q + 0.4 · γ · B · N_γ', '["Step 1 — Terzaghi equation for square footing in sand (c = 0): q_ult = γ · D_f · N_q + 0.4 · γ · B · N_γ.","Step 2 — Surcharge term: γ · D_f · N_q = 18 kN/m³ × 1.0 m × 20 = 360 kPa.","Step 3 — Width term: 0.4 · γ · B · N_γ = 0.4 × 18 × 2.0 × 20 = 288 kPa.","Step 4 — Total ultimate bearing capacity: q_ult = 360 + 288 = 648 kPa."]'::jsonb, 'IS 6403 & Terzaghi Theory', 'HARD', 'NUMERICAL', 'MODELLED', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
