INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-001', 'upsc-ies-civil', 1, 'Construction Management & CPM', 'PERT & CPM Fundamentals', 'Time Estimates in PERT', 'In a PERT network, the optimistic time (to), most likely time (tm), and pessimistic time (tp) for an activity are 4 days, 7 days, and 16 days respectively. The expected activity duration (te) and its variance (σ²) are respectively:', '[{"id":"A","text":"8.0 days and 4.0 days²"},{"id":"B","text":"7.0 days and 2.0 days²"},{"id":"C","text":"8.0 days and 2.0 days²"},{"id":"D","text":"9.0 days and 4.0 days²"}]'::jsonb, '8.0 days and 4.0 days²', '7.0 days and 2.0 days²', '8.0 days and 2.0 days²', '9.0 days and 4.0 days²', 'A', 'Expected duration te = (4 + 4(7) + 16) / 6 = (4 + 28 + 16) / 6 = 48 / 6 = 8 days. Standard deviation σ = (16 - 4) / 6 = 12 / 6 = 2 days. Therefore, variance σ² = 2² = 4 days².', 'te = (to + 4*tm + tp) / 6 ; σ = (tp - to) / 6 ; σ² = [(tp - to) / 6]²', NULL, 'UPSC ESE 2023 & B.C. Punmia Project Planning', 'EASY', 'NUMERICAL', 'MODELLED', 2023, 'UPSC ESE / GATE Civil') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-002', 'gate-ce', 2, 'Construction Management & CPM', 'Network Analysis', 'Float Interrelationships', 'For an activity in a CPM project network, which of the following inequalities correctly represents the relationship between Total Float (TF), Free Float (FF), and Independent Float (IF)?', '[{"id":"A","text":"IF ≥ FF ≥ TF"},{"id":"B","text":"TF ≥ FF ≥ IF"},{"id":"C","text":"FF ≥ TF ≥ IF"},{"id":"D","text":"TF ≥ IF ≥ FF"}]'::jsonb, 'IF ≥ FF ≥ TF', 'TF ≥ FF ≥ IF', 'FF ≥ TF ≥ IF', 'TF ≥ IF ≥ FF', 'B', 'By definition, Total Float (TF = LFT - EST - t) allows maximum permissible delay without affecting project completion. Free Float (FF = EFT_j - EFT_i - t) allows delay without affecting succeeding activities (FF = TF - Head Slack). Independent Float (IF = EST_j - LFT_i - t = FF - Tail Slack) allows delay without affecting preceding or succeeding activities. Hence, TF ≥ FF ≥ IF holds unconditionally.', 'Total Float (TF) ≥ Free Float (FF) ≥ Independent Float (IF)', NULL, 'GATE CE 2022 / IS 15883', 'EASY', 'CONCEPTUAL', 'MODELLED', 2022, 'GATE CE / State PSC AE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-003', 'apsc-ae-civil', 3, 'Construction Management & CPM', 'Critical Path Method', 'Critical Path Characteristics', 'In CPM network analysis, the critical path is defined as the sequence of critical activities having:', '[{"id":"A","text":"Maximum duration and minimum total float (usually zero)"},{"id":"B","text":"Minimum duration and maximum total float"},{"id":"C","text":"Maximum cost and zero free float"},{"id":"D","text":"Shortest path through the network"}]'::jsonb, 'Maximum duration and minimum total float (usually zero)', 'Minimum duration and maximum total float', 'Maximum cost and zero free float', 'Shortest path through the network', 'A', 'The critical path is the longest continuous chain of activities through the project network connecting the start event to the end event. It dictates the minimum overall time required to complete the project. Any delay in critical activities directly delays project completion, which is why total float along the critical path is zero (or minimum if target date is fixed).', 'Critical Path = Longest path in time through network; Total Float = 0', NULL, 'APSC AE Civil & Srinath PERT & CPM', 'EASY', 'CONCEPTUAL', 'MODELLED', 2024, 'APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-004', 'upsc-ies-civil', 4, 'Construction Management & CPM', 'Project Crashing & Economics', 'Cost Slope Formula', 'The cost slope of an activity in project network optimization represents:', '[{"id":"A","text":"Direct cost decrease per unit increase in activity duration"},{"id":"B","text":"Direct cost increase per unit reduction in activity duration"},{"id":"C","text":"Indirect cost incurred per day of delay"},{"id":"D","text":"Total cost saved per day of crashing"}]'::jsonb, 'Direct cost decrease per unit increase in activity duration', 'Direct cost increase per unit reduction in activity duration', 'Indirect cost incurred per day of delay', 'Total cost saved per day of crashing', 'B', 'Cost slope represents the rate of increase in direct cost per unit decrease in duration as an activity is compressed from its normal time to crash time: Cost Slope = (Cc - Cn) / (Tn - Tc). When crashing a project, activities on the critical path with the lowest cost slope are crashed first to achieve time reduction at minimum expense.', 'Cost Slope = (Crash Cost - Normal Cost) / (Normal Time - Crash Time) = ΔC / Δt', NULL, 'UPSC ESE 2021', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'UPSC ESE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-005', 'gate-ce', 5, 'Construction Management & CPM', 'Project Crashing & Economics', 'Optimum Project Duration', 'During time-cost optimization of a construction project, as project duration is progressively compressed, what happens to direct and indirect costs?', '[{"id":"A","text":"Direct cost increases while indirect cost decreases"},{"id":"B","text":"Both direct and indirect costs increase"},{"id":"C","text":"Direct cost decreases while indirect cost increases"},{"id":"D","text":"Both direct and indirect costs decrease"}]'::jsonb, 'Direct cost increases while indirect cost decreases', 'Both direct and indirect costs increase', 'Direct cost decreases while indirect cost increases', 'Both direct and indirect costs decrease', 'A', 'Direct costs (overtime labor, specialized equipment, multiple shifts) increase as activity duration is crashed. Conversely, indirect costs (site overheads, supervision, equipment rent, administrative expenses) decrease as project duration shortens because they are time-dependent. The optimum project duration corresponds to the minimum point on the Total Cost curve.', 'Total Cost = Direct Cost (increases with crashing) + Indirect Cost (proportional to time)', NULL, 'GATE CE & IS 15883', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'GATE CE 2020') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-006', 'upsc-ies-civil', 6, 'Construction Management & CPM', 'PERT vs CPM Comparison', 'Probabilistic vs Deterministic Approaches', 'Statement 1: PERT is an event-oriented probabilistic model suited for R&D and non-repetitive projects.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-007', 'apsc-ae-civil', 7, 'Construction Management & CPM', 'Network Rules & Logic', 'Dummy Activities', 'In an Activity-on-Arrow (AOA) project network, a dummy activity is introduced to:', '[{"id":"A","text":"Represent an activity consuming minimal time and zero cost"},{"id":"B","text":"Maintain grammatical network logic and establish unique event identification without consuming time or resources"},{"id":"C","text":"Account for weather delays in external construction works"},{"id":"D","text":"Provide contingency float for critical path activities"}]'::jsonb, 'Represent an activity consuming minimal time and zero cost', 'Maintain grammatical network logic and establish unique event identification without consuming time or resources', 'Account for weather delays in external construction works', 'Provide contingency float for critical path activities', 'B', 'In AOA networks, dummy activities consume zero time and zero resources. They are required for two distinct purposes: (1) Grammatical/Uniqueness: preventing two concurrent activities from sharing both identical start and end node numbers; (2) Logical: showing precedence where an activity depends on one predecessor but not another.', 'Dummy Activity: Duration = 0, Cost = 0; shown by dashed arrow (- - ->)', NULL, 'APSC AE 2023 & B.C. Punmia', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-008', 'gate-ce', 8, 'Construction Management & CPM', 'Network Calculations', 'Interfering Float', 'In CPM network analysis, Interfering Float is mathematically defined as:', '[{"id":"A","text":"Total Float minus Free Float (equal to head event slack)"},{"id":"B","text":"Free Float minus Independent Float"},{"id":"C","text":"Total Float minus Independent Float"},{"id":"D","text":"Earliest Start Time minus Latest Finish Time"}]'::jsonb, 'Total Float minus Free Float (equal to head event slack)', 'Free Float minus Independent Float', 'Total Float minus Independent Float', 'Earliest Start Time minus Latest Finish Time', 'A', 'Interfering Float is that portion of Total Float which, if consumed, does not delay the overall project completion but delays the start of subsequent activities. It is mathematically equal to the slack of the head event: Interfering Float = TF - FF = Sj = LFTj - ESTj.', 'Interfering Float = Total Float - Free Float = Sj (Head Event Slack)', NULL, 'GATE CE 2021', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'GATE CE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-009', 'upsc-ies-civil', 9, 'Construction Management & CPM', 'PERT Statistical Analysis', 'Central Limit Theorem & Project Completion Probability', 'The critical path of a project consists of 4 independent activities with variances 9, 16, 4, and 36 days² respectively. The standard deviation of the entire project duration is:', '[{"id":"A","text":"8.06 days"},{"id":"B","text":"16.0 days"},{"id":"C","text":"65.0 days"},{"id":"D","text":"11.0 days"}]'::jsonb, '8.06 days', '16.0 days', '65.0 days', '11.0 days', 'A', 'According to the Central Limit Theorem for PERT networks, project variance along the critical path is the sum of the variances of individual critical activities: σ_project² = 9 + 16 + 4 + 36 = 65 days². The project standard deviation is σ = √65 ≈ 8.062 days.', 'σ_project = √(Σ σ_i²) = √(9 + 16 + 4 + 36) = √65 ≈ 8.06 days', NULL, 'UPSC ESE 2020', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2020, 'UPSC ESE / State AE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-010', 'apsc-ae-civil', 10, 'Construction Management & CPM', 'Resource Management', 'Resource Leveling vs Resource Smoothing', 'Which of the following statements correctly distinguishes between Resource Leveling and Resource Smoothing?', '[{"id":"A","text":"Resource leveling keeps project duration fixed, while resource smoothing allows duration to extend"},{"id":"B","text":"Resource leveling allows project duration to extend to stay within resource limits, whereas resource smoothing adjusts non-critical activities within available float without extending project duration"},{"id":"C","text":"Resource smoothing increases total float, whereas leveling decreases independent float"},{"id":"D","text":"Both techniques inevitably extend project completion date"}]'::jsonb, 'Resource leveling keeps project duration fixed, while resource smoothing allows duration to extend', 'Resource leveling allows project duration to extend to stay within resource limits, whereas resource smoothing adjusts non-critical activities within available float without extending project duration', 'Resource smoothing increases total float, whereas leveling decreases independent float', 'Both techniques inevitably extend project completion date', 'B', 'Resource Leveling is applied when resources are strictly capped; the critical path may be altered and project duration extended to prevent demand spikes. Resource Smoothing is applied when the project completion date is fixed; activities are shifted strictly within their allowable float so peak demand is reduced without extending project duration.', 'Resource Leveling: Resource-constrained (Time extends); Resource Smoothing: Time-constrained (Float used)', NULL, 'IS 15883 (Part 2) & APSC AE', 'HARD', 'CONCEPTUAL', 'MODELLED', 2022, 'APSC AE Civil 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-011', 'gate-ce', 11, 'Construction Management & CPM', 'CPM Calculations', 'Independent Float Calculation', 'An activity (i-j) has duration dij = 6 days. The earliest and latest event times are: Node i: Ei = 4, Li = 7; Node j: Ej = 15, Lj = 18. The Independent Float of activity (i-j) is:', '[{"id":"A","text":"5 days"},{"id":"B","text":"2 days"},{"id":"C","text":"8 days"},{"id":"D","text":"0 days"}]'::jsonb, '5 days', '2 days', '8 days', '0 days', 'B', 'Independent Float (IF) is calculated as IF = Ej - Li - dij. Here, Ej = 15, Li = 7, and dij = 6. Thus, IF = 15 - 7 - 6 = 2 days. (Total Float = Lj - Ei - dij = 18 - 4 - 6 = 8 days; Free Float = Ej - Ei - dij = 15 - 4 - 6 = 5 days).', 'Independent Float = Ej - Li - dij', NULL, 'GATE CE 2019', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2019, 'GATE CE 2019') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-012', 'upsc-ies-civil', 12, 'Construction Management & CPM', 'Construction Equipment', 'Compaction Rollers Selection', 'Which type of compaction roller is most effective for compacting highly plastic clayey soils (such as impervious core of earthen dams)?', '[{"id":"A","text":"Smooth wheeled roller"},{"id":"B","text":"Pneumatic tyred roller"},{"id":"C","text":"Sheepsfoot roller"},{"id":"D","text":"Vibratory roller"}]'::jsonb, 'Smooth wheeled roller', 'Pneumatic tyred roller', 'Sheepsfoot roller', 'Vibratory roller', 'C', 'Sheepsfoot rollers compact soil through kneading and tamping action under high contact pressures (1.5 to 3.5 MPa) delivered by projecting feet. They are specifically suited for cohesive, plastic clays and silts. Vibratory rollers are used for cohesionless granular sands and gravels, while smooth-wheeled rollers are used for finishing base courses.', 'Sheepsfoot: Kneading action for cohesive clays; Vibratory: Dynamic pulse for cohesionless sands', NULL, 'UPSC ESE 2023 & Peurifoy Construction Equipment', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'UPSC ESE / State AE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-013', 'apsc-ae-civil', 13, 'Construction Management & CPM', 'Contracts & Tenders', 'Earnest Money vs Security Deposit', 'In government engineering contracts, Earnest Money Deposit (EMD) and Security Deposit (SD) are typically what percentage of the estimated tender value?', '[{"id":"A","text":"EMD: 1% to 2%; SD: 5% to 10%"},{"id":"B","text":"EMD: 10% to 15%; SD: 1% to 2%"},{"id":"C","text":"EMD: 5% to 8%; SD: 20%"},{"id":"D","text":"EMD: 0.5%; SD: 25%"}]'::jsonb, 'EMD: 1% to 2%; SD: 5% to 10%', 'EMD: 10% to 15%; SD: 1% to 2%', 'EMD: 5% to 8%; SD: 20%', 'EMD: 0.5%; SD: 25%', 'A', 'Earnest Money Deposit (1% to 2% of estimated contract value) is submitted with the tender to guarantee that the bidder will not withdraw their offer before tender validity expires. Security Deposit (typically 5% to 10%, often deducted in installments from running bills) is held until the defect liability period expires to secure defect-free execution.', 'EMD ≈ 1-2% of tender cost (guarantees tender seriousness); SD ≈ 5-10% (guarantees performance)', NULL, 'CPWD Works Manual 2024 & APSC AE', 'EASY', 'CODE_RULE_BASED', 'MODELLED', 2024, 'APSC AE Civil / State CCE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-014', 'gate-ce', 14, 'Construction Management & CPM', 'Earned Value Management', 'Cost Variance and Cost Performance Index', 'A project milestone has Planned Value PV = ₹10 Lakh, Earned Value EV = ₹8 Lakh, and Actual Cost AC = ₹12 Lakh. The Cost Variance (CV) and Schedule Performance Index (SPI) are:', '[{"id":"A","text":"CV = −₹4 Lakh and SPI = 0.80"},{"id":"B","text":"CV = +₹2 Lakh and SPI = 1.25"},{"id":"C","text":"CV = −₹2 Lakh and SPI = 0.67"},{"id":"D","text":"CV = +₹4 Lakh and SPI = 0.80"}]'::jsonb, 'CV = −₹4 Lakh and SPI = 0.80', 'CV = +₹2 Lakh and SPI = 1.25', 'CV = −₹2 Lakh and SPI = 0.67', 'CV = +₹4 Lakh and SPI = 0.80', 'A', 'Cost Variance CV = EV - AC = ₹8 L - ₹12 L = -₹4 Lakh (negative indicates over budget). Schedule Performance Index SPI = EV / PV = 8 / 10 = 0.80 (less than 1.0 indicates behind schedule).', 'CV = EV - AC ; SPI = EV / PV', NULL, 'GATE CE 2023 / Project Management Body of Knowledge', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2023, 'GATE CE 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-015', 'upsc-ies-civil', 15, 'Construction Management & CPM', 'Network Analysis', 'Fulkerson''s Rule for Node Numbering', 'According to Fulkerson''s rule for numbering nodes in a project network:', '[{"id":"A","text":"Initial event is assigned number 1; arrows must always lead from lower-numbered nodes to higher-numbered nodes"},{"id":"B","text":"Arrows always lead from higher-numbered nodes to lower-numbered nodes"},{"id":"C","text":"Nodes are numbered alphabetically based on duration"},{"id":"D","text":"Critical path nodes are assigned even numbers only"}]'::jsonb, 'Initial event is assigned number 1; arrows must always lead from lower-numbered nodes to higher-numbered nodes', 'Arrows always lead from higher-numbered nodes to lower-numbered nodes', 'Nodes are numbered alphabetically based on duration', 'Critical path nodes are assigned even numbers only', 'A', 'Fulkerson''s rule prevents looping and maintains chronological precedence. The initial event (having only outgoing arrows) is numbered 1. Deleting all arrows emerging from 1 reveals new initial events, which are numbered 2, 3, etc. This guarantees that for every arrow representing an activity (i, j), node number i < node number j.', 'Fulkerson''s Rule: For any arrow (i -> j), i < j always', NULL, 'UPSC ESE 2021 / B.C. Punmia', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'UPSC ESE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-016', 'gate-ce', 16, 'Construction Management & CPM', 'PERT Statistical Distribution', 'Beta Distribution Characteristics', 'In PERT analysis, activity duration is assumed to follow a Beta distribution because:', '[{"id":"A","text":"It is a continuous probability distribution with finite endpoints and can model skewed (unimodal) activity durations"},{"id":"B","text":"It is symmetric about the median for all activities"},{"id":"C","text":"It has infinite tails matching normal distributions"},{"id":"D","text":"It eliminates the need for calculating variance"}]'::jsonb, 'It is a continuous probability distribution with finite endpoints and can model skewed (unimodal) activity durations', 'It is symmetric about the median for all activities', 'It has infinite tails matching normal distributions', 'It eliminates the need for calculating variance', 'A', 'Activity times in real-life projects have definite non-negative lower bounds (optimistic time to) and realistic upper bounds (pessimistic time tp). The Beta distribution has finite endpoints and can accommodate both positive and negative skewness with a mode at tm, making it mathematically ideal for PERT modeling.', 'Beta distribution: bounded between to and tp, unimodal with peak at tm', NULL, 'GATE CE & Moder & Phillips Project Management', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'GATE CE 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-017', 'apsc-ae-civil', 17, 'Construction Management & CPM', 'Earthmoving Equipment', 'Dragline vs Power Shovel', 'Which earthmoving excavating equipment is most suitable for excavating trenches and digging canals below its own track level, particularly in soft or marshy ground?', '[{"id":"A","text":"Power shovel"},{"id":"B","text":"Dragline"},{"id":"C","text":"Bulldozer"},{"id":"D","text":"Elevating grader"}]'::jsonb, 'Power shovel', 'Dragline', 'Bulldozer', 'Elevating grader', 'B', 'A dragline operates with a long boom and cable-suspended bucket, allowing it to dig well below the machine''s supporting level and deposit spoil at a long radius without entering wet or muddy excavations. Power shovels, in contrast, are designed to dig upward against hard vertical faces above track level.', 'Dragline: Operates from firm ground, digs below track level; Power shovel: Digs above track level into firm banks', NULL, 'APSC AE Civil 2023 & Peurifoy', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-018', 'upsc-ies-civil', 18, 'Construction Management & CPM', 'Contracts & Specifications', 'Liquidated Damages vs Penalty', 'In construction contracts, ''Liquidated Damages'' refers to:', '[{"id":"A","text":"A pre-agreed, genuine pre-estimate of loss incurred by the owner due to contractor delay"},{"id":"B","text":"A punitive fine intended to penalize the contractor arbitrarily"},{"id":"C","text":"Compensation paid by the owner to the contractor for site hindrances"},{"id":"D","text":"Cost of dewatering during foundation excavation"}]'::jsonb, 'A pre-agreed, genuine pre-estimate of loss incurred by the owner due to contractor delay', 'A punitive fine intended to penalize the contractor arbitrarily', 'Compensation paid by the owner to the contractor for site hindrances', 'Cost of dewatering during foundation excavation', 'A', 'Under Section 74 of the Indian Contract Act, 1872, liquidated damages represent a reasonable, genuine pre-estimate of damages agreed upon by both parties at contract signing to compensate for delays in completion. Unlike a penalty (which aims to punish or terrorize), courts enforce liquidated damages up to the reasonable loss actually suffered.', 'Liquidated damages = Genuine pre-estimate of loss (enforceable under Indian Contract Act §74)', NULL, 'Indian Contract Act §74 & UPSC ESE', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'UPSC ESE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-019', 'gate-ce', 19, 'Construction Management & CPM', 'PERT Statistical Analysis', 'Z-Score & Project Completion Probability', 'A project has an expected completion time of 40 days with a standard deviation of 5 days. The standard normal variate (Z) to achieve a scheduled completion time of 45 days is:', '[{"id":"A","text":"Z = +1.0 (approx 84.1% probability)"},{"id":"B","text":"Z = +2.0 (approx 97.7% probability)"},{"id":"C","text":"Z = 0.0 (50.0% probability)"},{"id":"D","text":"Z = −1.0 (approx 15.9% probability)"}]'::jsonb, 'Z = +1.0 (approx 84.1% probability)', 'Z = +2.0 (approx 97.7% probability)', 'Z = 0.0 (50.0% probability)', 'Z = −1.0 (approx 15.9% probability)', 'A', 'The standard normal variate Z = (Ts - Te) / σ = (45 - 40) / 5 = +1.0. Looking up the cumulative normal distribution table, Z = +1.0 gives P(Z ≤ 1.0) = 0.5 + 0.3413 = 84.13% probability of completion within 45 days.', 'Z = (Ts - Te) / σ_project = (45 - 40) / 5 = +1.0', NULL, 'GATE CE 2021', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2021, 'GATE CE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-020', 'apsc-ae-civil', 20, 'Construction Management & CPM', 'Bar Charts & Milestones', 'Gantt Chart Limitations', 'Which of the following is a major limitation of a conventional Gantt Bar Chart that led to the development of Network Techniques (CPM/PERT)?', '[{"id":"A","text":"It cannot depict activity interdependencies, critical activities, or project float"},{"id":"B","text":"It cannot be displayed graphically on paper"},{"id":"C","text":"It can only be used for projects under ₹1 Lakh"},{"id":"D","text":"It requires complex computerized matrix inversion"}]'::jsonb, 'It cannot depict activity interdependencies, critical activities, or project float', 'It cannot be displayed graphically on paper', 'It can only be used for projects under ₹1 Lakh', 'It requires complex computerized matrix inversion', 'A', 'A traditional Gantt bar chart shows start and finish dates of tasks, but does not clearly show how activities depend on one another. If one task slips, it is impossible to see directly which other tasks are impacted or what the overall impact on the completion date will be. It also cannot identify critical activities or floats.', 'Gantt chart: shows time bars, but lacks interdependency & critical path', NULL, 'APSC AE Civil 2023', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'APSC AE Civil 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-021', 'upsc-ies-civil', 21, 'Construction Management & CPM', 'Crashing Sequence', 'Crashing Rules', 'When crashing a project network with multiple parallel critical paths, crashing must be performed on:', '[{"id":"A","text":"Any critical activity on any single path"},{"id":"B","text":"Either an activity common to all critical paths, or simultaneously on one activity in each parallel critical path such that the combined cost slope is minimized"},{"id":"C","text":"Non-critical activities with zero cost slope"},{"id":"D","text":"The longest non-critical path"}]'::jsonb, 'Any critical activity on any single path', 'Either an activity common to all critical paths, or simultaneously on one activity in each parallel critical path such that the combined cost slope is minimized', 'Non-critical activities with zero cost slope', 'The longest non-critical path', 'B', 'If a network has multiple parallel critical paths, crashing an activity on only one path does not reduce the project duration because the parallel critical path will still govern. Thus, one must either crash an activity common to all critical paths or simultaneously crash one activity on each parallel critical path, choosing the combination with the lowest aggregate cost slope.', 'Multiple critical paths: Crash common critical activity OR combination with lowest sum of cost slopes', NULL, 'UPSC ESE 2022 & Moder & Phillips', 'HARD', 'CONCEPTUAL', 'MODELLED', 2022, 'UPSC ESE 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-022', 'gate-ce', 22, 'Construction Management & CPM', 'Network Logic', 'Dangling and Looping', 'In project network construction:
(I) Dangling occurs when an activity disconnects from the network before reaching the final event.
(II) Looping (cycling) represents an endless cycle of dependencies and is strictly prohibited.', '[{"id":"A","text":"Only (I) is correct"},{"id":"B","text":"Only (II) is correct"},{"id":"C","text":"Both (I) and (II) are correct"},{"id":"D","text":"Neither (I) nor (II) is correct"}]'::jsonb, 'Only (I) is correct', 'Only (II) is correct', 'Both (I) and (II) are correct', 'Neither (I) nor (II) is correct', 'C', 'Both statements define fundamental network construction errors. Dangling occurs when an intermediate activity ends in a dead-end node that never connects to the final terminal event. Looping (or cycling) occurs when activities form a closed loop, implying that an activity must be finished before it can start, which is a logical impossibility.', 'Network errors: Looping (cyclic arrows), Dangling (dead-end activities not tied to end event)', NULL, 'GATE CE & B.C. Punmia', 'EASY', 'STATEMENT_BASED', 'MODELLED', 2023, 'GATE CE / State PSC AE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-023', 'apsc-ae-civil', 23, 'Construction Management & CPM', 'Economic Life of Construction Equipment', 'Optimum Replacement Time', 'The economic life of a construction equipment ends when:', '[{"id":"A","text":"The equipment completely breaks down and cannot be repaired"},{"id":"B","text":"The average annual cumulative cost (ownership + maintenance/operating) reaches its minimum"},{"id":"C","text":"The market scrap value of the equipment reaches zero"},{"id":"D","text":"The contractor pays off the bank loan on the equipment"}]'::jsonb, 'The equipment completely breaks down and cannot be repaired', 'The average annual cumulative cost (ownership + maintenance/operating) reaches its minimum', 'The market scrap value of the equipment reaches zero', 'The contractor pays off the bank loan on the equipment', 'B', 'As equipment ages, annual depreciation and capital ownership costs decrease, while maintenance, repair, downtime, and obsolescence costs increase sharply. The economic life is the age at which the total cumulative cost divided by operating hours/years is at an absolute minimum. Operating beyond this point results in economic loss.', 'Economic life = point where cumulative average cost per operating hour is minimized', NULL, 'Peurifoy Construction Planning & Equipment & APSC AE', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2024, 'APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-024', 'upsc-ies-civil', 24, 'Construction Management & CPM', 'Contracts & Valuation', 'Item Rate vs Lump Sum Contracts', 'For large-scale infrastructure civil engineering projects (such as highway and canal construction) where quantities of earthwork cannot be accurately predicted in advance, which type of contract is most suitable?', '[{"id":"A","text":"Lump-sum contract"},{"id":"B","text":"Unit price (Item rate / Schedule of rates) contract"},{"id":"C","text":"Cost plus fixed percentage contract"},{"id":"D","text":"Turnkey EPC contract without bills of quantities"}]'::jsonb, 'Lump-sum contract', 'Unit price (Item rate / Schedule of rates) contract', 'Cost plus fixed percentage contract', 'Turnkey EPC contract without bills of quantities', 'B', 'In an item rate (unit price) contract, the contractor quotes prices per unit measurement (e.g. per m³ of earthwork or per m³ of concrete). The owner pays based on actual measured field quantities. This is standard for earthwork, foundation, and infrastructure works where subterranean surprises make exact volume estimation beforehand impossible.', 'Item rate contract: Contractor quotes unit rates per item; payment based on actual measured quantities', NULL, 'CPWD Manual & UPSC ESE', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'UPSC ESE 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-025', 'gate-ce', 25, 'Construction Management & CPM', 'CPM Calculations', 'Activity Times & Slacks', 'An activity starts at Earliest Start Time EST = 10, has duration t = 6, and must finish by Latest Finish Time LFT = 22. What are its Earliest Finish Time (EFT) and Total Float (TF)?', '[{"id":"A","text":"EFT = 16, TF = 6"},{"id":"B","text":"EFT = 16, TF = 12"},{"id":"C","text":"EFT = 10, TF = 6"},{"id":"D","text":"EFT = 22, TF = 0"}]'::jsonb, 'EFT = 16, TF = 6', 'EFT = 16, TF = 12', 'EFT = 10, TF = 6', 'EFT = 22, TF = 0', 'A', 'Earliest Finish Time EFT = EST + t = 10 + 6 = 16. Total Float TF = LFT - EFT = 22 - 16 = 6 (or LST - EST = (22 - 6) - 10 = 16 - 10 = 6). The activity can be delayed by up to 6 days without extending the project end date.', 'EFT = EST + t = 10 + 6 = 16 ; Total Float = LFT - EFT = 22 - 16 = 6', NULL, 'GATE CE 2020', 'EASY', 'NUMERICAL', 'MODELLED', 2020, 'GATE CE 2020') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-026', 'apsc-ae-civil', 26, 'Construction Management & CPM', 'Safety & Quality Control', 'Six Sigma & ISO Standards', 'In modern construction quality management, ''Six Sigma'' quality level corresponds to a defect rate of not more than:', '[{"id":"A","text":"3.4 defects per million opportunities (DPMO)"},{"id":"B","text":"66,807 defects per million opportunities"},{"id":"C","text":"340 defects per million opportunities"},{"id":"D","text":"0.01% of total output"}]'::jsonb, '3.4 defects per million opportunities (DPMO)', '66,807 defects per million opportunities', '340 defects per million opportunities', '0.01% of total output', 'A', 'A Six Sigma process is one in which 99.99966% of all opportunities to produce some feature are statistically expected to be free of defects. This corresponds to 3.4 defect parts per million opportunities (DPMO) assuming a 1.5-sigma shift in the mean.', 'Six Sigma = 99.99966% defect-free = 3.4 DPMO', NULL, 'APSC AE Civil & ISO 9001', 'EASY', 'CONCEPTUAL', 'MODELLED', 2024, 'State AE / UPSC ESE') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-027', 'upsc-ies-civil', 27, 'Construction Management & CPM', 'Construction Equipment', 'Scraper Performance', 'Which machine performs digging, loading, hauling, dumping, and spreading of earth in a single continuous cycle over haul distances of 150 m to 1500 m?', '[{"id":"A","text":"Motor Grader"},{"id":"B","text":"Tractor-drawn or Motor Scraper"},{"id":"C","text":"Bulldozer"},{"id":"D","text":"Backhoe loader"}]'::jsonb, 'Motor Grader', 'Tractor-drawn or Motor Scraper', 'Bulldozer', 'Backhoe loader', 'B', 'A scraper is a unique multi-functional earthmoving machine capable of excavating a thin layer of soil, loading it into its bowl, transporting it economically over medium distances (150 m to 1500 m), and spreading it in uniform layers at the fill site.', 'Scraper: Digs, loads, hauls, and spreads in one self-contained unit', NULL, 'UPSC ESE 2021 & Peurifoy', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'UPSC ESE 2021') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-028', 'gate-ce', 28, 'Construction Management & CPM', 'PERT Statistical Analysis', 'Expected Time Formula Derivation', 'The formula for expected duration in PERT, te = (to + 4*tm + tp) / 6, is derived by assuming that the activity duration follows:', '[{"id":"A","text":"A standard normal distribution with mean tm"},{"id":"B","text":"A unimodal Beta distribution with modal value tm and spread (tp - to) equal to 6 standard deviations"},{"id":"C","text":"A uniform rectangular distribution"},{"id":"D","text":"An exponential decay distribution"}]'::jsonb, 'A standard normal distribution with mean tm', 'A unimodal Beta distribution with modal value tm and spread (tp - to) equal to 6 standard deviations', 'A uniform rectangular distribution', 'An exponential decay distribution', 'B', 'The PERT formula approximates the mean of a unimodal Beta probability density curve. Assuming that the standard deviation σ equals 1/6th of the range (tp - to) because virtually 99.7% of the area under a bell-shaped curve lies within ±3σ (a spread of 6σ), Simpson''s rule numerical integration yields the weighted average te = (to + 4*tm + tp) / 6.', 'te = ∫ t * f(t) dt ≈ (to + 4*tm + tp) / 6 ; Range (tp - to) ≈ 6σ', NULL, 'GATE CE 2022 & Moder & Phillips', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'GATE CE 2022') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-029', 'apsc-ae-civil', 29, 'Construction Management & CPM', 'Network Analysis', 'Free Float vs Total Float', 'If an activity has Total Float = 8 days and the succeeding event slack is 3 days, what is the Free Float of this activity?', '[{"id":"A","text":"5 days"},{"id":"B","text":"11 days"},{"id":"C","text":"8 days"},{"id":"D","text":"24 days"}]'::jsonb, '5 days', '11 days', '8 days', '24 days', 'A', 'Free Float (FF) is related to Total Float (TF) by the equation: FF = TF - Head Slack (Sj). Substituting the given values: FF = 8 - 3 = 5 days. This means the activity can be delayed by 5 days without delaying the start of any succeeding activity.', 'Free Float = Total Float - Head Event Slack = 8 - 3 = 5 days', NULL, 'APSC AE Civil 2024', 'EASY', 'NUMERICAL', 'MODELLED', 2024, 'APSC AE Civil 2024') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('cpm-pert-030', 'upsc-ies-civil', 30, 'Construction Management & CPM', 'Tender Process', 'Retention Money & Defect Liability Period', 'Retention money (or security deposit) deducted from a contractor''s interim running bills is refunded:', '[{"id":"A","text":"Immediately upon physical completion of the work"},{"id":"B","text":"After satisfactory completion of the Defect Liability Period (usually 6 to 12 months after handover)"},{"id":"C","text":"When the contractor signs the tender agreement"},{"id":"D","text":"At 50% physical completion of the work"}]'::jsonb, 'Immediately upon physical completion of the work', 'After satisfactory completion of the Defect Liability Period (usually 6 to 12 months after handover)', 'When the contractor signs the tender agreement', 'At 50% physical completion of the work', 'B', 'Retention money acts as a performance guarantee protecting the client against latent construction defects. As per CPWD and standard FIDIC conditions, it is retained throughout the Defect Liability Period (typically 6 months to 1 year) and refunded only after the engineer-in-charge issues a final defect-free completion certificate.', 'Retention money release = After Defect Liability Period (DLP) certification', NULL, 'CPWD Works Manual Clause 17 & UPSC ESE', 'EASY', 'CODE_RULE_BASED', 'MODELLED', 2023, 'UPSC ESE 2023') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-001', 'apsc-ae-civil', 1, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'The hydraulic head that would produce a quick condition in a sand stratum of thickness 1.5 m, specific gravity 2.67 and voids ratio 0.67 is equal to', '[{"id":"A","text":"1.0m"},{"id":"B","text":"1.5m"},{"id":"C","text":"2.0m"},{"id":"D","text":"3m"}]'::jsonb, '1.0m', '1.5m', '2.0m', '3m', 'B', 'According to standard Soil Mechanics principles (icr = (G - 1) / (1 + e) = γ_sub / γ_w), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'icr = (G - 1) / (1 + e) = γ_sub / γ_w', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-002', 'apsc-ae-civil', 2, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'Clay layer A with single drainage and coefficient of consolidation Cv takes 6 months to achieve 50% consolidation. The time taken by clay layer B of the same thickness with double drainage and coefficient of consolidation Cv/2 to achieve the same degree of consolidation is', '[{"id":"A","text":"3 months"},{"id":"B","text":"6 months"},{"id":"C","text":"12 months"},{"id":"D","text":"24 months"}]'::jsonb, '3 months', '6 months', '12 months', '24 months', 'A', 'According to standard Soil Mechanics principles (Tv = (Cv · t) / d²), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Tv = (Cv · t) / d²', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'NUMERICAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-003', 'apsc-ae-civil', 3, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'Degree of consolidation is', '[{"id":"A","text":"directly proportional to time and inversely proportional to drainage path"},{"id":"B","text":"directly proportional to time and inversely proportional to square of drainage path"},{"id":"C","text":"directly proportional to drainage path and inversely proportional to time"},{"id":"D","text":"directly proportional to square of drainage path and inversely proportional to time"}]'::jsonb, 'directly proportional to time and inversely proportional to drainage path', 'directly proportional to time and inversely proportional to square of drainage path', 'directly proportional to drainage path and inversely proportional to time', 'directly proportional to square of drainage path and inversely proportional to time', 'B', 'Solution: The degree of consolidation in soil mechanics is a measure of how much a soil sample has consolidated over time due to applied pressure. It is directly proportional to time because the consolidation process continues as time progresses. It is inversely proportional to the square of the drainage path because longer drainage paths result in slower consolidation. Therefore, Option B correctly describes the relationship between the degree of consolidation, time, and drainage path.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-004', 'apsc-ae-civil', 4, 'Geotechnical Engineering', 'Compaction & Field Control', 'Compaction Curves & Relative Density', 'Select the correct range of density index, I_D (density index)', '[{"id":"A","text":"I_D (density index) > 0"},{"id":"B","text":"I_D (density index) >= 0"},{"id":"C","text":"0 < I_D (density index) < 1"},{"id":"D","text":"0 <= I_D (density index) <= 1"}]'::jsonb, 'I_D (density index) > 0', 'I_D (density index) >= 0', '0 < I_D (density index) < 1', '0 <= I_D (density index) <= 1', 'D', 'According to standard Soil Mechanics principles (ID = (emax - e) / (emax - emin) · 100%), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'ID = (emax - e) / (emax - emin) · 100%', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-005', 'apsc-ae-civil', 5, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'For a loose sand sample and a dense sand sample consolidated to the same effective stress', '[{"id":"A","text":"ultimate strength is same and also peak strength is same"},{"id":"B","text":"ultimate strength is different but peak strength is same"},{"id":"C","text":"ultimate strength is same but peak strength of dense sand is greater than that of loose sand"},{"id":"D","text":"ultimate strength is same but peak"}]'::jsonb, 'ultimate strength is same and also peak strength is same', 'ultimate strength is different but peak strength is same', 'ultimate strength is same but peak strength of dense sand is greater than that of loose sand', 'ultimate strength is same but peak', 'C', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-006', 'apsc-ae-civil', 6, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'Within the consolidation process of a saturated clay', '[{"id":"A","text":"a gradual increase in neutral pressure and a gradual decrease in effective pressure takes place and sum of the two is constant"},{"id":"B","text":"a gradual decrease in neutral pressure and a gradual increase in effective pressure takes place and sum of the two is constant"},{"id":"C","text":"both neutral pressure and effective pressure decrease"},{"id":"D","text":"both neutral pressure and effective pressure increase"}]'::jsonb, 'a gradual increase in neutral pressure and a gradual decrease in effective pressure takes place and sum of the two is constant', 'a gradual decrease in neutral pressure and a gradual increase in effective pressure takes place and sum of the two is constant', 'both neutral pressure and effective pressure decrease', 'both neutral pressure and effective pressure increase', 'B', 'Solution: Understanding Consolidation in Saturated Clay: Imagine squeezing a sponge soaked in water. The water needs time to escape. Consolidation is similar; it''s the process of water slowly leaving saturated clay under pressure. Neutral pressure is the pressure of the water in the soil pores. Effective pressure is the pressure that the soil particles themselves carry. During consolidation, the total pressure stays the same. It''s like the total amount of water in the sponge plus the sponge itself. As the water escapes (reducing neutral pressure), the soil particles take on more of the load (increasing effective pressure). Therefore, the sum of neutral pressure and effective pressure remains constant. The Correct Answer: Based on the above explanation, option B is correct. It accurately describes the reduction in neutral pressure and corresponding increase in effective pressure during consolidation, while maintaining a constant sum.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-007', 'apsc-ae-civil', 7, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity', 'Rise of water table in cohesionless soils upto ground surface reduces the net ultimate bearing capacity approximately by', '[{"id":"A","text":"25%"},{"id":"B","text":"50%"},{"id":"C","text":"75%"},{"id":"D","text":"90%"}]'::jsonb, '25%', '50%', '75%', '90%', 'B', 'According to standard Soil Mechanics principles (qult = c·Nc + q·Nq + 0.5·γ·B·Nγ), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'qult = c·Nc + q·Nq + 0.5·γ·B·Nγ', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-008', 'apsc-ae-civil', 8, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity', 'Terzaghi’s bearing capacity factors N_c, N_q and N_γ are functions of', '[{"id":"A","text":"cohesion only"},{"id":"B","text":"angle of internal friction only"},{"id":"C","text":"both cohesion and angle of internal friction"},{"id":"D","text":"none of the above"}]'::jsonb, 'cohesion only', 'angle of internal friction only', 'both cohesion and angle of internal friction', 'none of the above', 'B', 'According to standard Soil Mechanics principles (qult = c·Nc + q·Nq + 0.5·γ·B·Nγ), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'qult = c·Nc + q·Nq + 0.5·γ·B·Nγ', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-009', 'apsc-ae-civil', 9, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'Valid range for S, the degree of saturation of soil in percentage is', '[{"id":"A","text":"S > 0"},{"id":"B","text":"S < 0"},{"id":"C","text":"0 < S < 100"},{"id":"D","text":"0 <= S <= 100"}]'::jsonb, 'S > 0', 'S < 0', '0 < S < 100', '0 <= S <= 100', 'D', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-010', 'apsc-ae-civil', 10, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'If the natural water content of soil mass lies between its liquid limit and plastic limit, the soil mass is said to be in', '[{"id":"A","text":"liquid state"},{"id":"B","text":"plastic state"},{"id":"C","text":"semi-solid state"},{"id":"D","text":"solid state"}]'::jsonb, 'liquid state', 'plastic state', 'semi-solid state', 'solid state', 'B', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-011', 'apsc-ae-civil', 11, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'The flownet for an earthen dam with 30 m water depth consists of 25 potential drops and 5 flow channels. The coefficient of permeability of dam material is 0.03 mm/sec. The discharge per meter length of dam is', '[{"id":"A","text":"0.00018 m³ /sec"},{"id":"B","text":"0.0045 m³ /sec"},{"id":"C","text":"0.18 m³ /sec"},{"id":"D","text":"0.1125 m³ /sec"}]'::jsonb, '0.00018 m³ /sec', '0.0045 m³ /sec', '0.18 m³ /sec', '0.1125 m³ /sec', 'A', 'According to standard Soil Mechanics principles (q = k · H · (Nf / Nd)), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'q = k · H · (Nf / Nd)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-012', 'apsc-ae-civil', 12, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'The average coefficient of permeability of natural deposits', '[{"id":"A","text":"Parallel to stratification is always greater than that perpendicular to stratification"},{"id":"B","text":"Parallel to stratification is always less than that perpendicular to stratification"},{"id":"C","text":"Is always same in both directions"},{"id":"D","text":"Parallel to stratification may or may not be greater than that perpendicular to stratification"}]'::jsonb, 'Parallel to stratification is always greater than that perpendicular to stratification', 'Parallel to stratification is always less than that perpendicular to stratification', 'Is always same in both directions', 'Parallel to stratification may or may not be greater than that perpendicular to stratification', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-013', 'apsc-ae-civil', 13, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'For proper field control, which of the following methods is best suited for quick determination of water content of a soil mass ?', '[{"id":"A","text":"oven drying method"},{"id":"B","text":"sand bath method"},{"id":"C","text":"alcohol method"},{"id":"D","text":"calcium carbide method"}]'::jsonb, 'oven drying method', 'sand bath method', 'alcohol method', 'calcium carbide method', 'D', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-014', 'apsc-ae-civil', 14, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'Which of the following methods is more suitable for the determination of permeability of clayey soil ?', '[{"id":"A","text":"constant head method"},{"id":"B","text":"falling head method"},{"id":"C","text":"horizontal permeability test"},{"id":"D","text":"none of the above"}]'::jsonb, 'constant head method', 'falling head method', 'horizontal permeability test', 'none of the above', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-015', 'apsc-ae-civil', 15, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'If the water content of a fully saturated soil mass is 100%, then the voids ratio of the sample is', '[{"id":"A","text":"less than specific gravity of soil"},{"id":"B","text":"equal to specific gravity of soil"},{"id":"C","text":"greater than specific gravity of soil"},{"id":"D","text":"independent of specific gravity of soil"}]'::jsonb, 'less than specific gravity of soil', 'equal to specific gravity of soil', 'greater than specific gravity of soil', 'independent of specific gravity of soil', 'B', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'FORMULA_RECALL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-016', 'apsc-ae-civil', 16, 'Geotechnical Engineering', 'Clay Mineralogy & Soil Structure', 'Mineral Lattice & Microstructure', 'Dispersed type of soil structure is an arrangement comprising particles having', '[{"id":"A","text":"face to face or parallel orientation"},{"id":"B","text":"edge to edge orientation"},{"id":"C","text":"edge to face orientation"},{"id":"D","text":"all of the above"}]'::jsonb, 'face to face or parallel orientation', 'edge to edge orientation', 'edge to face orientation', 'all of the above', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-017', 'apsc-ae-civil', 17, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'Physical properties of a permeant which influence permeability are', '[{"id":"A","text":"viscosity only"},{"id":"B","text":"unit weight only"},{"id":"C","text":"both viscosity and unit weight"},{"id":"D","text":"none of the above"}]'::jsonb, 'viscosity only', 'unit weight only', 'both viscosity and unit weight', 'none of the above', 'C', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-018', 'apsc-ae-civil', 18, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Failure Criterion', 'A cylindrical specimen of saturated soil failed under an axial vertical stress of 100 kN/m² when it was laterally un-confmed. The failure plane was inclined to the horizontal plane at an angle of 45°. The values of cohesion and angle of internal friction for the soil are respectively', '[{"id":"A","text":"0.5 N/mm² and 30°"},{"id":"B","text":"0.05 N/mm² and 0°"},{"id":"C","text":"0.2 N/mm² and 0°"},{"id":"D","text":"0.05 N/mm² and 45°"}]'::jsonb, '0.5 N/mm² and 30°', '0.05 N/mm² and 0°', '0.2 N/mm² and 0°', '0.05 N/mm² and 45°', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'NUMERICAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-019', 'apsc-ae-civil', 19, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'If the volume of voids is equal to the volume of solids in a soil mass, then the values of porosity and voids ratio respectively are', '[{"id":"A","text":"1.0 and 0.0"},{"id":"B","text":"0.0 and 1.0"},{"id":"C","text":"0.5 and 1.0"},{"id":"D","text":"1.0 and 0.5"}]'::jsonb, '1.0 and 0.0', '0.0 and 1.0', '0.5 and 1.0', '1.0 and 0.5', 'C', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-020', 'apsc-ae-civil', 20, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Unconfmed compressive strength test is', '[{"id":"A","text":"undrained test"},{"id":"B","text":"drained test"},{"id":"C","text":"consolidated undrained test"},{"id":"D","text":"consolidated drained test"}]'::jsonb, 'undrained test', 'drained test', 'consolidated undrained test', 'consolidated drained test', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-021', 'apsc-ae-civil', 21, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Failure Criterion', 'In a triaxial compression test when drainage is allowed during the first stage (i. e. application of cell pressure) only and not during the second stage (i.e. application of deviator stress at constant cell pressure), the test is known as', '[{"id":"A","text":"consolidated drained test"},{"id":"B","text":"consolidated undrained test"},{"id":"C","text":"unconsolidated drained test"},{"id":"D","text":"unconsolidated undrained test"}]'::jsonb, 'consolidated drained test', 'consolidated undrained test', 'unconsolidated drained test', 'unconsolidated undrained test', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-022', 'apsc-ae-civil', 22, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'A normally consolidated clay settled 10 mm when effective stress was increased from 100 kN/m² to 200 kN/m² . If the effective stress is further increased from²00 kN/m² to 400 kN/m² , then the settlement of the same clay is', '[{"id":"A","text":"10 mm"},{"id":"B","text":"20 mm"},{"id":"C","text":"40 mm"},{"id":"D","text":"none of the above"}]'::jsonb, '10 mm', '20 mm', '40 mm', 'none of the above', 'A', 'According to standard Soil Mechanics principles (ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'NUMERICAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-023', 'apsc-ae-civil', 23, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'The total discharge from two wells situated near to each other is', '[{"id":"A","text":"sum of the discharges from individual wells"},{"id":"B","text":"less than the sum of the discharges from individual wells"},{"id":"C","text":"greater than the sum of the discharges from individual wells"},{"id":"D","text":"equal to larger of the two discharges from individual wells"}]'::jsonb, 'sum of the discharges from individual wells', 'less than the sum of the discharges from individual wells', 'greater than the sum of the discharges from individual wells', 'equal to larger of the two discharges from individual wells', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-024', 'apsc-ae-civil', 24, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'Direct measurement of permeability of the specimen at any stage of loading can be made', '[{"id":"A","text":"only in fixed ring type consolido-meter"},{"id":"B","text":"only in floating ring type consolido-meter"},{"id":"C","text":"both (A) and (B)"},{"id":"D","text":"none of the above"}]'::jsonb, 'only in fixed ring type consolido-meter', 'only in floating ring type consolido-meter', 'both (A) and (B)', 'none of the above', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-025', 'apsc-ae-civil', 25, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity', 'The rise of water table below the foundation influences the bearing capacity of soil mainly by reducing', '[{"id":"A","text":"cohesion and effective angle of shearing resistance"},{"id":"B","text":"cohesion and effective unit weight of soil"},{"id":"C","text":"effective unit weight of soil and effective angle of shearing resistance"},{"id":"D","text":"effective angle of shearing resistance"}]'::jsonb, 'cohesion and effective angle of shearing resistance', 'cohesion and effective unit weight of soil', 'effective unit weight of soil and effective angle of shearing resistance', 'effective angle of shearing resistance', 'B', 'According to standard Soil Mechanics principles (qult = c·Nc + q·Nq + 0.5·γ·B·Nγ), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'qult = c·Nc + q·Nq + 0.5·γ·B·Nγ', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-026', 'apsc-ae-civil', 26, 'Geotechnical Engineering', 'Earth Pressure & Retaining Walls', 'Rankine and Coulomb Theories', 'A retaining wall 6m high supports a backfill with a surcharge angle of 10°. The back of the wall is inclined to the vertical at a positive batter angle of 5°. If the angle of wall friction is 7°, then the resultant active earth pressure will act at a distance of 2 m above the base and inclined to the horizontal at an angle of', '[{"id":"A","text":"7°"},{"id":"B","text":"10°"},{"id":"C","text":"12°"},{"id":"D","text":"17°"}]'::jsonb, '7°', '10°', '12°', '17°', 'C', 'According to standard Soil Mechanics principles (Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'NUMERICAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-027', 'apsc-ae-civil', 27, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'The total and effective stresses at a depth of 5 m below the top level of water in a swimming pool are respectively', '[{"id":"A","text":"Zero and zero"},{"id":"B","text":"0.5 kg/cm² and zero"},{"id":"C","text":"0.5 kg/cm² and 0.5 kg/cm²"},{"id":"D","text":"1.0 kg/cm² and 0.5 kg/cm²"}]'::jsonb, 'Zero and zero', '0.5 kg/cm² and zero', '0.5 kg/cm² and 0.5 kg/cm²', '1.0 kg/cm² and 0.5 kg/cm²', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-028', 'apsc-ae-civil', 28, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'Due to a rise in temperature, the viscosity and the unit weight of the percolating fluid are reduced to 60% and 90% respectively. If other things remain constant, the coefficient of permeability', '[{"id":"A","text":"increases by 25%"},{"id":"B","text":"increases by 50%"},{"id":"C","text":"increases by 33.3%"},{"id":"D","text":"decreases by 33.3%"}]'::jsonb, 'increases by 25%', 'increases by 50%', 'increases by 33.3%', 'decreases by 33.3%', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-029', 'apsc-ae-civil', 29, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'At liquid limit, all soils possess', '[{"id":"A","text":"same shear strength of small magnitude"},{"id":"B","text":"same shear strength of large magnitude"},{"id":"C","text":"different shear strengths of small magnitude"},{"id":"D","text":"different shear strengths of large magnitude"}]'::jsonb, 'same shear strength of small magnitude', 'same shear strength of large magnitude', 'different shear strengths of small magnitude', 'different shear strengths of large magnitude', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-030', 'apsc-ae-civil', 30, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Sensitivity of a soil can be defined as', '[{"id":"A","text":"percentage of volume change of soil under saturated condition"},{"id":"B","text":"ratio of compressive strength of unconfined undisturbed soil to that of soil in a remoulded state"},{"id":"C","text":"ratio of volume of voids to volume of solids"},{"id":"D","text":"none of the above"}]'::jsonb, 'percentage of volume change of soil under saturated condition', 'ratio of compressive strength of unconfined undisturbed soil to that of soil in a remoulded state', 'ratio of volume of voids to volume of solids', 'none of the above', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-031', 'apsc-ae-civil', 31, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Valid range for n, the percentage voids, is', '[{"id":"A","text":"0 < n < 100"},{"id":"B","text":"0 <= n <= 100"},{"id":"C","text":"n > 0"},{"id":"D","text":"n < 0"}]'::jsonb, '0 < n < 100', '0 <= n <= 100', 'n > 0', 'n < 0', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-032', 'apsc-ae-civil', 32, 'Geotechnical Engineering', 'Earth Pressure & Retaining Walls', 'Rankine and Coulomb Theories', 'Rankine’s theory of earth pressure assumes that the back of the wall is', '[{"id":"A","text":"plane and smooth"},{"id":"B","text":"plane and rough"},{"id":"C","text":"vertical and smooth"},{"id":"D","text":"vertical and rough"}]'::jsonb, 'plane and smooth', 'plane and rough', 'vertical and smooth', 'vertical and rough', 'C', 'According to standard Soil Mechanics principles (Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-033', 'apsc-ae-civil', 33, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'The most suitable method for drainage of fine grained cohesive soils is', '[{"id":"A","text":"well ppint system"},{"id":"B","text":"vacuum method"},{"id":"C","text":"deep well system"},{"id":"D","text":"electroosmosis method"}]'::jsonb, 'well ppint system', 'vacuum method', 'deep well system', 'electroosmosis method', 'D', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-034', 'apsc-ae-civil', 34, 'Geotechnical Engineering', 'Compaction & Field Control', 'Compaction Curves & Relative Density', 'With the increase in the amount of compaction energy', '[{"id":"A","text":"optimum water content increases but maximum dry density decreases"},{"id":"B","text":"optimum water content decreases but maximum dry density increases"},{"id":"C","text":"both optimum water content and maximum dry density increase"},{"id":"D","text":"both optimum water content and maximum dry density decrease[ES 93]"}]'::jsonb, 'optimum water content increases but maximum dry density decreases', 'optimum water content decreases but maximum dry density increases', 'both optimum water content and maximum dry density increase', 'both optimum water content and maximum dry density decrease[ES 93]', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-035', 'apsc-ae-civil', 35, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'In a deposit of normally consolidated clay', '[{"id":"A","text":"effective stress increases with depth but water content of soil and un-drained strength decrease with depth"},{"id":"B","text":"effective stress and water content increase with depth but undrained strength decreases with depth"},{"id":"C","text":"effective stress and undrained strength increase with depth but water content decreases with depth"},{"id":"D","text":"effective stress, water content and undrained strength decrease with depth"}]'::jsonb, 'effective stress increases with depth but water content of soil and un-drained strength decrease with depth', 'effective stress and water content increase with depth but undrained strength decreases with depth', 'effective stress and undrained strength increase with depth but water content decreases with depth', 'effective stress, water content and undrained strength decrease with depth', 'C', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-036', 'apsc-ae-civil', 36, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'Which of the following methods is most accurate for the determination of the water content of soil ?', '[{"id":"A","text":"oven drying method"},{"id":"B","text":"sand bath method"},{"id":"C","text":"calcium carbide method"},{"id":"D","text":"pycnometer method"}]'::jsonb, 'oven drying method', 'sand bath method', 'calcium carbide method', 'pycnometer method', 'A', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-037', 'apsc-ae-civil', 37, 'Geotechnical Engineering', 'Compaction & Field Control', 'Compaction Curves & Relative Density', 'The maximum dry density upto which any soil can be compacted depends upon', '[{"id":"A","text":"moisture content only"},{"id":"B","text":"amount of compaction energy only"},{"id":"C","text":"both moisture content and amount of compaction energy"},{"id":"D","text":"none of the above"}]'::jsonb, 'moisture content only', 'amount of compaction energy only', 'both moisture content and amount of compaction energy', 'none of the above', 'C', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-038', 'apsc-ae-civil', 38, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'Toughness index is defined as the ratio of', '[{"id":"A","text":"plasticity index to consistency index"},{"id":"B","text":"plasticity index to flow index"},{"id":"C","text":"liquidity index to flow index"},{"id":"D","text":"consistency index to liquidity index"}]'::jsonb, 'plasticity index to consistency index', 'plasticity index to flow index', 'liquidity index to flow index', 'consistency index to liquidity index', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'FORMULA_RECALL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-039', 'apsc-ae-civil', 39, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'The value of compression index for a remoulded sample whose liquid limit is 50% is', '[{"id":"A","text":"0.028"},{"id":"B","text":"0.28"},{"id":"C","text":"0.36"},{"id":"D","text":"0.036"}]'::jsonb, '0.028', '0.28', '0.36', '0.036', 'B', 'According to standard Soil Mechanics principles (ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-040', 'apsc-ae-civil', 40, 'Geotechnical Engineering', 'Compaction & Field Control', 'Compaction Curves & Relative Density', 'For better strength and stability, the fine grained soils and coarse grained soils are compacted respectively as', '[{"id":"A","text":"dry of OMC and wet of OMC"},{"id":"B","text":"wet of OMC and dry of OMC"},{"id":"C","text":"wet of OMC and wet of OMC"},{"id":"D","text":"dry of OMC and dry of OMC where OMC is optimum moisture content"}]'::jsonb, 'dry of OMC and wet of OMC', 'wet of OMC and dry of OMC', 'wet of OMC and wet of OMC', 'dry of OMC and dry of OMC where OMC is optimum moisture content', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-041', 'apsc-ae-civil', 41, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'If the permeability of a soil is 0.8 mm/sec, the type of soil is', '[{"id":"A","text":"gravel"},{"id":"B","text":"sand"},{"id":"C","text":"silt"},{"id":"D","text":"clay"}]'::jsonb, 'gravel', 'sand', 'silt', 'clay', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-042', 'apsc-ae-civil', 42, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Failure Criterion', 'A tri-axial shear test is preferred to direct shear test, because', '[{"id":"A","text":"It can be performed under all three drainage conditions with complete control"},{"id":"B","text":"Precise measurement of pore pressure and change in volume during test, is not possible"},{"id":"C","text":"Stress distribution on the failure plane, is non uniform"},{"id":"D","text":"None of these"}]'::jsonb, 'It can be performed under all three drainage conditions with complete control', 'Precise measurement of pore pressure and change in volume during test, is not possible', 'Stress distribution on the failure plane, is non uniform', 'None of these', 'A', 'According to standard Soil Mechanics principles (τf = c'' + σ'' tan φ'' ; qu = 2 · cu (for φ = 0)), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'τf = c'' + σ'' tan φ'' ; qu = 2 · cu (for φ = 0)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-043', 'apsc-ae-civil', 43, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity', 'Contact pressure beneath a rigid footing resting on cohesive soil is', '[{"id":"A","text":"less at edges compared to middle"},{"id":"B","text":"more at edges compared to middle"},{"id":"C","text":"uniform throughout"},{"id":"D","text":"none of the above"}]'::jsonb, 'less at edges compared to middle', 'more at edges compared to middle', 'uniform throughout', 'none of the above', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-044', 'apsc-ae-civil', 44, 'Geotechnical Engineering', 'Shear Strength of Soil', 'Mohr-Coulomb Failure Criterion', 'Select the incorrect statement. Effective angle of shearing resistance', '[{"id":"A","text":"increases as the size of particles increases"},{"id":"B","text":"increases as the soil gradation im-proves"},{"id":"C","text":"is limited to a maximum value of 45°"},{"id":"D","text":"is rarely more than 30° for fine grained soil"}]'::jsonb, 'increases as the size of particles increases', 'increases as the soil gradation im-proves', 'is limited to a maximum value of 45°', 'is rarely more than 30° for fine grained soil', 'C', 'According to standard Soil Mechanics principles (τf = c'' + σ'' tan φ'' ; qu = 2 · cu (for φ = 0)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'τf = c'' + σ'' tan φ'' ; qu = 2 · cu (for φ = 0)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'ASSERTION_REASON', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-045', 'apsc-ae-civil', 45, 'Geotechnical Engineering', 'Permeability & Seepage', 'Flow Nets & Darcy Flow', 'Which of the following methods is best suited for determination of permeability of coarse-grained soils ?', '[{"id":"A","text":"constant head method"},{"id":"B","text":"falling head method"},{"id":"C","text":"both the above"},{"id":"D","text":"none of the above"}]'::jsonb, 'constant head method', 'falling head method', 'both the above', 'none of the above', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-046', 'apsc-ae-civil', 46, 'Geotechnical Engineering', 'Compaction & Field Control', 'Compaction Curves & Relative Density', 'If the sand in-situ is in its densest state, then the relative density of sand is', '[{"id":"A","text":"zero"},{"id":"B","text":"1"},{"id":"C","text":"between 0 and 1"},{"id":"D","text":"greater than 1"}]'::jsonb, 'zero', '1', 'between 0 and 1', 'greater than 1', 'B', 'Solution: Relative Density is like a special scale that tells us how "compact" or "dense" sand is. It''s a very important property for sandy soils (soils without much clay) because it helps engineers know how stable the soil is. This special scale for Relative Density goes from 0 to 1 , representing the two extreme states of sand packing: 1. Zero (0): If the sand is in its absolute loosest state . This means the sand particles are as spread out as possible, with the maximum amount of empty space (voids) between them. In this scenario, the Relative Density is 0 . 2. One (1): If the sand is in its absolute densest state . This means the sand particles are packed together as tightly as possible, with the minimum amount of empty space (voids) between them. In this scenario, the Relative Density is 1 . 3. Between 0 and 1: If the sand is in any state somewhere between the loosest and densest conditions (which is typically what we find in nature), then its Relative Density will be a value between 0 and 1 (e.g., 0.3, 0.6, 0.8, etc.). Now, let''s look at our question: "If the sand in-situ is in its densest state ..." The question clearly states that the sand is already in its most densely packed possible state . As we just learned, when sand is in this extreme densest condition, its Relative Density is 1 . Therefore, the correct answer is Option B: 1 .', 'ID = (emax - e) / (emax - emin) · 100%', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-047', 'apsc-ae-civil', 47, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'A soil has a bulk density of 22 kN/m³ and water content 10%. The dry density of soil is', '[{"id":"A","text":"18.6 kN/m³"},{"id":"B","text":"20.0 kN/m³"},{"id":"C","text":"22.0 kN/m³"},{"id":"D","text":"23.2 kN/m³"}]'::jsonb, '18.6 kN/m³', '20.0 kN/m³', '22.0 kN/m³', '23.2 kN/m³', 'B', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-048', 'apsc-ae-civil', 48, 'Geotechnical Engineering', 'Earth Pressure & Retaining Walls', 'Rankine and Coulomb Theories', 'Coefficient of earth pressure at rest is', '[{"id":"A","text":"less than active earth pressure but greater than passive earth pressure"},{"id":"B","text":"greater than active earth pressure but less than passive earth pressure"},{"id":"C","text":"greater than both the active earth pressure and passive earth pressure"},{"id":"D","text":"less than both the active and passive earth pressures"}]'::jsonb, 'less than active earth pressure but greater than passive earth pressure', 'greater than active earth pressure but less than passive earth pressure', 'greater than both the active earth pressure and passive earth pressure', 'less than both the active and passive earth pressures', 'B', 'According to standard Soil Mechanics principles (Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Ka = (1 - sin φ) / (1 + sin φ) ; Kp = (1 + sin φ) / (1 - sin φ)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-049', 'apsc-ae-civil', 49, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'When the plastic limit of a soil is greater than the liquid limit, then the plasticity index is reported as', '[{"id":"A","text":"negative"},{"id":"B","text":"zero"},{"id":"C","text":"non-plastic (NP)"},{"id":"D","text":"1"}]'::jsonb, 'negative', 'zero', 'non-plastic (NP)', '1', 'C', 'Solution: Option A: negative This option is incorrect. The plasticity index cannot be negative. It is either zero or non-plastic (NP) in such cases. Option B: zero This option is incorrect. Zero is used when the plastic limit is equal to the liquid limit, not when it is greater. Option C: non-plastic (NP) This is the correct option. When the plastic limit exceeds the liquid limit, the soil is considered non-plastic, and the plasticity index is reported as NP. Option D: 1 This option is incorrect. The plasticity index is not arbitrarily set to 1 in any standard soil mechanics context. In conclusion, the correct answer is Option C: non-plastic (NP) , as this correctly represents the condition when the plastic limit is greater than the liquid limit in soil mechanics.', 'IP = wL - wP ; IT = IP / IF', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-050', 'apsc-ae-civil', 50, 'Geotechnical Engineering', 'Phase Relations & Soil Properties', 'Three Phase System (e, n, w, S, G)', 'Voids ratio of a soil mass can', '[{"id":"A","text":"never be greater than unity"},{"id":"B","text":"be zero"},{"id":"C","text":"take any value greater than zero"},{"id":"D","text":"take values between 0 and 1 only"}]'::jsonb, 'never be greater than unity', 'be zero', 'take any value greater than zero', 'take values between 0 and 1 only', 'C', 'According to standard Soil Mechanics principles (S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'S · e = w · G ; γd = γ / (1 + w) = (G · γw) / (1 + e)', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'FORMULA_RECALL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-051', 'apsc-ae-civil', 51, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Effective stress is', '[{"id":"A","text":"the stress at particles contact"},{"id":"B","text":"a physical parameter that can be measured"},{"id":"C","text":"important because it is a function of engineering properties of soil"},{"id":"D","text":"all of the above"}]'::jsonb, 'the stress at particles contact', 'a physical parameter that can be measured', 'important because it is a function of engineering properties of soil', 'all of the above', 'D', 'Solution: Effective stress: It is the stress transmitted through soil particles at their points of contact. This is critical in understanding the behavior of soils under load. A physical parameter that can be measured: Effective stress is a measurable quantity calculated as the total stress minus pore water pressure. Importance: Effective stress is a key parameter because it governs the engineering properties of soil, such as shear strength, compressibility, and permeability. Since all the statements are correct, Option D: all of the above is the correct answer.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-052', 'apsc-ae-civil', 52, 'Geotechnical Engineering', 'Shallow Foundations & Bearing Capacity', 'Terzaghi Bearing Capacity', 'In the plate loading test for determining the bearing capacity of soil, the size of square bearing plate should be', '[{"id":"A","text":"less than 300 mm"},{"id":"B","text":"between 300 mm and 750 mm"},{"id":"C","text":"between 750 mm and 1 m"},{"id":"D","text":"greater than 1 m"}]'::jsonb, 'less than 300 mm', 'between 300 mm and 750 mm', 'between 750 mm and 1 m', 'greater than 1 m', 'B', 'According to standard Soil Mechanics principles (qult = c·Nc + q·Nq + 0.5·γ·B·Nγ), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'qult = c·Nc + q·Nq + 0.5·γ·B·Nγ', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-053', 'apsc-ae-civil', 53, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'The clay mineral with the largest swelling and shrinkage characteristics is', '[{"id":"A","text":"kaolinite"},{"id":"B","text":"illite"},{"id":"C","text":"montmorillonite"},{"id":"D","text":"none of the above"}]'::jsonb, 'kaolinite', 'illite', 'montmorillonite', 'none of the above', 'C', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-054', 'apsc-ae-civil', 54, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'If the material of the base of the Casagrande liquid limit device on which the cup containing soil paste drops is softer than the standard hard rubber, then', '[{"id":"A","text":"The liquid limit of soil always increases"},{"id":"B","text":"The liquid limit of soil always decreases"},{"id":"C","text":"The liquid limit of soil may increase"},{"id":"D","text":"The liquid limit of soil may decrease"}]'::jsonb, 'The liquid limit of soil always increases', 'The liquid limit of soil always decreases', 'The liquid limit of soil may increase', 'The liquid limit of soil may decrease', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-055', 'apsc-ae-civil', 55, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'According to Atterberg, the soil is said to be of medium plasticity if the plasticity index PI is', '[{"id":"A","text":"0 < PI < 7"},{"id":"B","text":"7< PI < 17"},{"id":"C","text":"17 < PI < 27"},{"id":"D","text":"PI > 27"}]'::jsonb, '0 < PI < 7', '7< PI < 17', '17 < PI < 27', 'PI > 27', 'B', 'Solution: According to Atterberg, the soil is said to be of medium plasticity if the plasticity index (PI) is 7 < PI < 17 . The plasticity index (PI) is a measure of the plasticity of a soil and is calculated as the difference between the liquid limit (LL) and the plastic limit (PL). Soils with a PI between 7 and 17 are considered to have medium plasticity. This range indicates moderate changes in consistency with changes in moisture content. Therefore, the correct option is 7 < PI < 17 .', 'IP = wL - wP ; IT = IP / IF', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-056', 'apsc-ae-civil', 56, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Which of the following is a measure of particle size range ?', '[{"id":"A","text":"effective size"},{"id":"B","text":"uniformity coefficient"},{"id":"C","text":"coefficient of curvature"},{"id":"D","text":"none of the above"}]'::jsonb, 'effective size', 'uniformity coefficient', 'coefficient of curvature', 'none of the above', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-057', 'apsc-ae-civil', 57, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Sand particles are made of', '[{"id":"A","text":"rock minerals"},{"id":"B","text":"kaolinite"},{"id":"C","text":"illite"},{"id":"D","text":"montmorillonite"}]'::jsonb, 'rock minerals', 'kaolinite', 'illite', 'montmorillonite', 'A', 'Solution: Sand particles are made of rock minerals. Sand primarily consists of small fragments of weathered rock and minerals, predominantly quartz, which is a durable and resistant mineral. Kaolinite, illite, and montmorillonite are types of clay minerals, which are much finer in particle size compared to sand and have different properties and compositions. Therefore, the correct answer is that sand particles are composed of rock minerals.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-058', 'apsc-ae-civil', 58, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Uniformity coefficient of a soil is', '[{"id":"A","text":"always less than 1"},{"id":"B","text":"always equal to 1"},{"id":"C","text":"equal to or less than 1"},{"id":"D","text":"equal to or gi eater than 1"}]'::jsonb, 'always less than 1', 'always equal to 1', 'equal to or less than 1', 'equal to or gi eater than 1', 'D', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-059', 'apsc-ae-civil', 59, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'Coefficient of consolidation of a soil is affected by', '[{"id":"A","text":"compressibility"},{"id":"B","text":"permeability"},{"id":"C","text":"both compressibility and permeability"},{"id":"D","text":"none of the above"}]'::jsonb, 'compressibility', 'permeability', 'both compressibility and permeability', 'none of the above', 'C', 'Solution: The coefficient of consolidation of a soil is affected by both compressibility and permeability. The coefficient of consolidation ( C v ​) is a measure used in soil mechanics to describe how fast a soil consolidates under load. Compressibility influences how much volume change occurs in the soil when a load is applied. Permeability determines the rate at which water can flow through the soil pores, affecting how quickly excess pore water pressure dissipates. Therefore, the coefficient of consolidation is dependent on both these properties, making Option C the correct answer.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-060', 'apsc-ae-civil', 60, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'The ratio of volume of voids to the total volume of soil mass is called', '[{"id":"A","text":"air content"},{"id":"B","text":"porosity"},{"id":"C","text":"percentage air voids"},{"id":"D","text":"voids ratio"}]'::jsonb, 'air content', 'porosity', 'percentage air voids', 'voids ratio', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'FORMULA_RECALL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-061', 'apsc-ae-civil', 61, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'A grillage foundation', '[{"id":"A","text":"Is provided for heavily loaded isolated columns"},{"id":"B","text":"Is treated as spread foundation"},{"id":"C","text":"Consists of two sets of perpendicularly placed steel beams"},{"id":"D","text":"All the above"}]'::jsonb, 'Is provided for heavily loaded isolated columns', 'Is treated as spread foundation', 'Consists of two sets of perpendicularly placed steel beams', 'All the above', 'D', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (D) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-062', 'apsc-ae-civil', 62, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Residual soils are formed by', '[{"id":"A","text":"glaciers"},{"id":"B","text":"wind"},{"id":"C","text":"water"},{"id":"D","text":"none of the above"}]'::jsonb, 'glaciers', 'wind', 'water', 'none of the above', 'D', 'Solution: Residual soils are formed by the weathering and decomposition of rocks at the same place where they originally existed . They remain at their place of formation and are not transported by external agents. Agents such as glaciers, wind, and water are responsible for transporting soils from one location to another, producing transported soils rather than residual soils. Therefore, residual soils are not formed by glaciers, wind, or water , making Option D the correct answer.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-063', 'apsc-ae-civil', 63, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'A 600 mm square bearing plate settles by 15 mm in plate load test on a cohesionless soil under an intensity of loading of 0.2 N/ram² . The settlement of a prototype shallow footing 1 m square under the same intensity of loading is', '[{"id":"A","text":"15 mm"},{"id":"B","text":"Between 15 mm and 25 mm"},{"id":"C","text":"25 mm"},{"id":"D","text":"Greater than 25 mm"}]'::jsonb, '15 mm', 'Between 15 mm and 25 mm', '25 mm', 'Greater than 25 mm', 'B', 'According to standard Soil Mechanics principles (ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'NUMERICAL', 'MODELLED', 2022, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-064', 'apsc-ae-civil', 64, 'Geotechnical Engineering', 'Consolidation & Settlement', 'Terzaghi 1D Consolidation', 'A 300 mm square bearing plate settles by 15 mm in a plate load test on a cohesive soil when the intensity of loading is 0.2 N/mm² . The settlement of a prototype shallow footing 1 m square under the same intensity of loading is', '[{"id":"A","text":"15 mm"},{"id":"B","text":"30 mm"},{"id":"C","text":"50 mm"},{"id":"D","text":"167 mm"}]'::jsonb, '15 mm', '30 mm', '50 mm', '167 mm', 'C', 'According to standard Soil Mechanics principles (ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'ΔH = H0 · [Cc / (1 + e0)] · log10(σ1'' / σ0'')', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'EASY', 'NUMERICAL', 'MODELLED', 2021, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-065', 'apsc-ae-civil', 65, 'Geotechnical Engineering', 'Earth Pressure & Retaining Walls', 'Rankine and Coulomb Theories', 'The angle that Coulomb’s failure envelope makes with the horizontal is called', '[{"id":"A","text":"cohesion"},{"id":"B","text":"angle of internal friction"},{"id":"C","text":"angle of repose"},{"id":"D","text":"none of the above"}]'::jsonb, 'cohesion', 'angle of internal friction', 'angle of repose', 'none of the above', 'B', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (B) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2020, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-066', 'apsc-ae-civil', 66, 'Geotechnical Engineering', 'Soil Mechanics Principles', 'General Geotechnical Fundamentals', 'Which one of the following clays behaves like a dense sand ?', '[{"id":"A","text":"over-consolidated ciay with a high over-consolidation ratio"},{"id":"B","text":"over-consolidated clay with a low over-consolidation ratio"},{"id":"C","text":"normally consolidated clay"},{"id":"D","text":"under-consolidated clay"}]'::jsonb, 'over-consolidated ciay with a high over-consolidation ratio', 'over-consolidated clay with a low over-consolidation ratio', 'normally consolidated clay', 'under-consolidated clay', 'A', 'According to standard Soil Mechanics principles (Standard Soil Mechanics Relationship), Option (A) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'Standard Soil Mechanics Relationship', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'HARD', 'CONCEPTUAL', 'MODELLED', 2024, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('ev-soil-067', 'apsc-ae-civil', 67, 'Geotechnical Engineering', 'Soil Classification & Atterberg Limits', 'Atterberg Consistency Limits', 'Which of the following soils has more plasticity index ?', '[{"id":"A","text":"sand"},{"id":"B","text":"silt"},{"id":"C","text":"clay"},{"id":"D","text":"gravel"}]'::jsonb, 'sand', 'silt', 'clay', 'gravel', 'C', 'According to standard Soil Mechanics principles (IP = wL - wP ; IT = IP / IF), Option (C) is the correct statement/result for this condition under Indian Standard (IS) geotechnical specifications.', 'IP = wL - wP ; IT = IP / IF', NULL, 'ExamVeda Geotechnical Question Bank / IS 1498 & IS 6403', 'MEDIUM', 'CONCEPTUAL', 'MODELLED', 2023, 'ExamVeda / UPSC ESE / GATE Soil Mechanics') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
