INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q010', 'apsc-dwr-2026', 10, 'General Studies', 'Medieval Indian History', 'Akbar''s Administration & Conquests', 'Arrange the following in chronological order :
(i) Conquest of Orissa by Akbar
