INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q011', 'apsc-dwr-2026', 11, 'General Studies', 'Modern Indian History', 'Socio-Religious Reform', 'Ramakrishna Mission was founded in 1897 by', '[{"id":"A","text":"Swami Vivekananda"},{"id":"B","text":"Raja Ram Mohan Roy"},{"id":"C","text":"Dayanand Saraswati"},{"id":"D","text":"Sree Narayana Guru"}]'::jsonb, 'Swami Vivekananda', 'Raja Ram Mohan Roy', 'Dayanand Saraswati', 'Sree Narayana Guru', 'A', 'Swami Vivekananda founded the Ramakrishna Mission on 1 May 1897 at Belur Math near Calcutta, to propagate Practical Vedanta and carry out educational, medical, and relief work.', NULL, NULL, 'Modern India - Bipan Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q012', 'apsc-dwr-2026', 12, 'General Studies', 'Indian Art & Architecture', 'Dravidian Architecture', 'The style of temple architecture that came into vogue during the Cholas was', '[{"id":"A","text":"Nagara"},{"id":"B","text":"Vesara"},{"id":"C","text":"Hoysala"},{"id":"D","text":"Dravidian"}]'::jsonb, 'Nagara', 'Vesara', 'Hoysala', 'Dravidian', 'D', 'Dravidian style of temple architecture (distinguished by stepped pyramidal vimana, ornate gopurams, and enclosed temple courtyards) achieved its classic zenith under the Imperial Cholas.', NULL, NULL, 'NCERT Fine Arts / Percy Brown', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q013', 'apsc-dwr-2026', 13, 'General Studies', 'Indian National Movement', 'Revolutionary Nationalism', 'Abhinav Bharat, a secret society of revolutionaries was organized by', '[{"id":"A","text":"V. D. Savarkar"},{"id":"B","text":"Motilal Nehru"},{"id":"C","text":"B. R. Ambedkar"},{"id":"D","text":"Mahatma Gandhi"}]'::jsonb, 'V. D. Savarkar', 'Motilal Nehru', 'B. R. Ambedkar', 'Mahatma Gandhi', 'A', 'Abhinav Bharat Society (Young India Society) was organized in 1904 by Vinayak Damodar Savarkar and his brother Ganesh Damodar Savarkar to promote revolutionary armed resistance against British rule.', NULL, NULL, 'India''s Struggle for Independence - Bipan Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q014', 'apsc-dwr-2026', 14, 'General Studies', 'Medieval Indian History', 'Mughal Historiography', 'Ain-i-Akbari was written by', '[{"id":"A","text":"Akbar"},{"id":"B","text":"Abul Fazl"},{"id":"C","text":"Amir Khusrow"},{"id":"D","text":"Ziauddin Barani"}]'::jsonb, 'Akbar', 'Abul Fazl', 'Amir Khusrow', 'Ziauddin Barani', 'B', 'Ain-i-Akbari (Administration of Akbar) was authored in Persian by Abu''l-Fazl ibn Mubarak, Akbar''s grand vizier and court historian, as the third and concluding volume of the Akbarnama.', NULL, NULL, 'Medieval India - Satish Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
