INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q016', 'apsc-dwr-2026', 16, 'Assam Geography & Economy', 'Assam Economy & Agriculture', 'Tea Industry', 'The world''s first institute for research on tea was established in', '[{"id":"A","text":"Jorhat"},{"id":"B","text":"Sibsagar"},{"id":"C","text":"Golaghat"},{"id":"D","text":"Dibrugarh"}]'::jsonb, 'Jorhat', 'Sibsagar', 'Golaghat', 'Dibrugarh', 'A', 'The Tocklai Tea Research Institute, located in Jorhat, Assam, was founded in 1911 by the Indian Tea Association. It is recognized as the world''s oldest and pioneer experimental station for tea research and development.', NULL, NULL, 'Geography of Assam - Taher & Ahmed', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q017', 'apsc-dwr-2026', 17, 'Assam History & Culture', 'Assam History', 'Pre-Ahom Historiography', 'The author of Pre-Ahom Assam is', '[{"id":"A","text":"S. L. Baruah"},{"id":"B","text":"S. K. Bhuyan"},{"id":"C","text":"Nayanjot Lahiri"},{"id":"D","text":"Edward Gait"}]'::jsonb, 'S. L. Baruah', 'S. K. Bhuyan', 'Nayanjot Lahiri', 'Edward Gait', 'C', 'Prof. Nayanjot Lahiri authored ''Pre-Ahom Assam: Studies in the Inscriptions of Assam between the Fifth and the Thirteenth Centuries AD'' (1991), which provides an authoritative archaeological and epigraphical analysis of ancient Kamarupa.', NULL, NULL, 'Pre-Ahom Assam - Nayanjot Lahiri (1991)', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q018', 'apsc-dwr-2026', 18, 'Assam History & Culture', 'Assam History', 'Ancient Inscriptions', 'The earliest dated inscription of Ancient Assam is', '[{"id":"A","text":"Badaganga Epigraph"},{"id":"B","text":"Gachtal Copper Plate"},{"id":"C","text":"Nidhanpur Copper Plate"},{"id":"D","text":"Kanai Barasi Inscription"}]'::jsonb, 'Badaganga Epigraph', 'Gachtal Copper Plate', 'Nidhanpur Copper Plate', 'Kanai Barasi Inscription', 'A', 'The Badaganga Rock Inscription of King Bhutivarman of the Varman dynasty mentions the Gupta Era 234/244 (~554 CE), making it the earliest epigraphic record in Assam that bears an explicit chronological calendar date.', NULL, NULL, 'Inscriptions of Ancient Assam - P.C. Choudhury', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q019', 'apsc-dwr-2026', 19, 'Assam History & Culture', 'Assam Political History', 'Assam Accord', 'The historic Assam Accord was signed on', '[{"id":"A","text":"26th January, 1985"},{"id":"B","text":"18th September, 1985"},{"id":"C","text":"2nd October, 1985"},{"id":"D","text":"15th August, 1985"}]'::jsonb, '26th January, 1985', '18th September, 1985', '2nd October, 1985', '15th August, 1985', 'D', 'The Assam Accord (Memorandum of Settlement) was signed in New Delhi in the early hours of 15th August 1985 between leaders of AASU/AAGSP and the Government of India in the presence of Prime Minister Rajiv Gandhi, concluding the six-year-long Assam Movement.', NULL, NULL, 'Assam Movement and Accord - MHA Government of India', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q020', 'apsc-dwr-2026', 20, 'Assam History & Culture', 'Assam Literature & Chronicles', 'Sanskrit Chronicles of Assam', 'Choose the correct statement(s) about Hara-Gauri Sambada :
(i) It contains the genealogy of Ahom Rulers of Assam.
(ii) It contains the genealogy of the Rulers of Ancient Assam.
(iii) It contains the religious rituals of the Varman Rulers.
(iv) It contains the accounts of the foreign travellers who visited Assam.', '[{"id":"A","text":"(i) and (ii)"},{"id":"B","text":"(iii) and (iv)"},{"id":"C","text":"only (ii)"},{"id":"D","text":"All of the above"}]'::jsonb, '(i) and (ii)', '(iii) and (iv)', 'only (ii)', 'All of the above', 'A', 'Hara-Gauri Sambada is a medieval Sanskrit manuscript chronicle with Assamese translation that provides invaluable legendary chronicles and dynastic genealogies of both ancient Kamarupa monarchs and the later Ahom and Koch royal dynasties.', NULL, NULL, 'Sources of the History of Assam - H.K. Barpujari', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q021', 'apsc-dwr-2026', 21, 'Assam Geography & Economy', 'Assam Economic History', 'Industrial Heritage', 'The Assam Railways and Trading Company was formed in the year', '[{"id":"A","text":"1880"},{"id":"B","text":"1826"},{"id":"C","text":"1884"},{"id":"D","text":"1881"}]'::jsonb, '1880', '1826', '1884', '1881', 'D', 'The Assam Railways and Trading Company (AR&TC) was incorporated on 30 July 1881 in London to develop the Dibru-Sadiya metre-gauge railway, open the Ledo/Makum coalfields, and establish petroleum extraction in Digboi.', NULL, NULL, 'Economic History of Assam - Priyam Goswami', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q022', 'apsc-dwr-2026', 22, 'General Studies', 'Labour Laws & Welfare', 'Industrial Legislation', 'The Plantations Labour Act was passed in the year', '[{"id":"A","text":"1950"},{"id":"B","text":"1951"},{"id":"C","text":"1954"},{"id":"D","text":"1953"}]'::jsonb, '1950', '1951', '1954', '1953', 'B', 'The Plantations Labour Act (Act No. 69 of 1951) was enacted by the Indian Parliament on 2 November 1951 to regulate the welfare of plantation labor and mandate housing, medical facilities, water supply, and working hours for estate workers.', NULL, NULL, 'Indian Labour Laws - Ministry of Labour & Employment', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q023', 'apsc-dwr-2026', 23, 'General Studies', 'Indian National Movement', 'INC Sessions in Assam', 'The Pandu Session of Indian National Congress was presided over by', '[{"id":"A","text":"Motilal Nehru"},{"id":"B","text":"Subhas Chandra Bose"},{"id":"C","text":"M. A. Ansari"},{"id":"D","text":"S. Srinivasa Iyengar"}]'::jsonb, 'Motilal Nehru', 'Subhas Chandra Bose', 'M. A. Ansari', 'S. Srinivasa Iyengar', 'D', 'The 41st plenary session of the Indian National Congress took place in December 1926 at Pandu, Guwahati. The session was presided over by eminent jurist S. Srinivasa Iyengar, with Tarun Ram Phukan serving as Chairman of the Reception Committee.', NULL, NULL, 'Assam in the Freedom Movement - H.K. Barpujari', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q024', 'apsc-dwr-2026', 24, 'General Studies', 'Medieval Indian History', 'Mughal Mansabdari System', '''Du Aspa, Sih Aspa'' was introduced by', '[{"id":"A","text":"Jahangir"},{"id":"B","text":"Shah Jahan"},{"id":"C","text":"Akbar"},{"id":"D","text":"Aurangzeb"}]'::jsonb, 'Jahangir', 'Shah Jahan', 'Akbar', 'Aurangzeb', 'A', 'The ''Du-Aspa Sih-Aspa'' rank modification within the Mansabdari system was introduced by Emperor Jahangir. It allowed select nobles to double their quota of sawars and contingent size without increasing their base personal Zat rank or personal pay scale.', NULL, NULL, 'Medieval India - Satish Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q025', 'apsc-dwr-2026', 25, 'Assam History & Culture', 'Assam Culture & Heritage', 'Traditional Fairs & Festivals', 'Choose the incorrect statement(s) about Jonbeel Mela :
(i) It was organized by the Koch Rulers.
(ii) The Jonbeel Mela stands unique till date where Barter system still prevails.
(iii) The Jonbeel i.e., Jon and Beel are Assamese expressions for the moon and wetland respectively.
(iv) It is a three day annual fair of the indigenous Tiwa community.', '[{"id":"A","text":"Only (iv)"},{"id":"B","text":"(ii) and (iii)"},{"id":"C","text":"Only (i)"},{"id":"D","text":"(i) and (iv)"}]'::jsonb, 'Only (iv)', '(ii) and (iii)', 'Only (i)', '(i) and (iv)', 'C', 'Statement (i) is incorrect: Jonbeel Mela at Dayang Belguri near Jagiroad has been historically patronized by the Gobha Kingdom (Gobha Raja of the Tiwa community), NOT the Koch rulers. The traditional barter exchange between hills and plains tribes is still actively practiced. Thus, only (i) is incorrect.', NULL, NULL, 'Folk Culture of Assam - Birendranath Datta', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q026', 'apsc-dwr-2026', 26, 'Assam History & Culture', 'Ancient Indian Science & Assam', 'Veterinary Treatises', 'Hastyayurveda, a work on Veterinary Science was authored by', '[{"id":"A","text":"Varahamihira"},{"id":"B","text":"Kautilya"},{"id":"C","text":"Aryabhata"},{"id":"D","text":"Palkapya"}]'::jsonb, 'Varahamihira', 'Kautilya', 'Aryabhata', 'Palkapya', 'D', 'Sage Palakapya (Palkapya), who resided on the banks of the Brahmaputra in ancient Kamarupa, authored Hastyayurveda (or Gaja-Ayurveda), the monumental 160-chapter classical Sanskrit treatise on the management, anatomy, medicine, and surgery of elephants.', NULL, NULL, 'Cultural History of Assam - B.K. Barua', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q027', 'apsc-dwr-2026', 27, 'Assam History & Culture', 'Northeast Culture & Festivals', 'State Festivals', 'Choose the correct statement(s) from the options given below :
(i) The Dehing Patkai Festival was introduced by the Assam Government in the year 2002.
(ii) The Hornbill Festival is celebrated every year from 1st to 10th December in Mizoram.
(iii) The Manipur Sangai Festival is celebrated every year in the month of January.
(iv) The Ambubachi Mela is celebrated every year in Assam in the month of December.', '[{"id":"A","text":"(iii) and (iv)"},{"id":"B","text":"(i) only"},{"id":"C","text":"(ii) only"},{"id":"D","text":"(i), (ii), (iii) and (iv)"}]'::jsonb, '(iii) and (iv)', '(i) only', '(ii) only', '(i), (ii), (iii) and (iv)', 'B', '• (i) is correct: The Dehing Patkai Festival was initiated in 2002 at Lekhapani in Tinsukia by the Government of Assam.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q028', 'apsc-dwr-2026', 28, 'Assam History & Culture', 'Assam Freedom Movement', 'Swaraj Party', 'The President of Swaraj Party (1923) in Assam was', '[{"id":"A","text":"Gopinath Bordoloi"},{"id":"B","text":"Rohini Kumar Choudhary"},{"id":"C","text":"Tarun Ram Phukan"},{"id":"D","text":"Nabin Chandra Bordoloi"}]'::jsonb, 'Gopinath Bordoloi', 'Rohini Kumar Choudhary', 'Tarun Ram Phukan', 'Nabin Chandra Bordoloi', 'C', 'In 1923, following the formation of the Swaraj Party within the Indian National Congress, the Assam Provincial Swaraj Party was constituted with ''Deshabhakta'' Tarun Ram Phukan as its President and ''Karmavir'' Nabin Chandra Bordoloi as its Secretary.', NULL, NULL, 'History of the Freedom Movement in Assam - K.N. Dutt', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q029', 'apsc-dwr-2026', 29, 'General Studies', 'Medieval Indian History', 'Sur Empire & Sher Shah', 'Choose the incorrect statement(s) regarding Sher Shah''s contribution from the options given below :
(i) Sher Shah laid emphasis on the law and order, the length and breadth of his empire.
(ii) He built many roads and took stern actions against robbers and dacoits.
(iii) He built Sarais on the highway at a distance of two Karohs (4 miles).
(iv) He appointed revenue collectors to maintain road safety.', '[{"id":"A","text":"(i) and (ii)"},{"id":"B","text":"(iv) only"},{"id":"C","text":"All of the above"},{"id":"D","text":"None of the above"}]'::jsonb, '(i) and (ii)', '(iv) only', 'All of the above', 'None of the above', 'B', 'Statement (iv) is incorrect: Sher Shah enforced highway safety and peace through the principle of local collective responsibility placed on village headmen (Muqaddams) and zamindars, rather than revenue collectors (Amils / Shiqdars whose jurisdiction was revenue assessment and collection). Hence, (iv) only is incorrect.', NULL, NULL, 'Medieval India - Satish Chandra / Tarikh-i-Sher Shahi', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
