INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q031', 'apsc-dwr-2026', 31, 'General Studies', 'Medieval Indian Culture', 'Indian Classical Music', 'The best known musical work of Raja Man Singh of Gwalior was', '[{"id":"A","text":"Sangitasiromoni"},{"id":"B","text":"Baburnama"},{"id":"C","text":"Man Kautuhal"},{"id":"D","text":"Fatwa-e-Alamgiri"}]'::jsonb, 'Sangitasiromoni', 'Baburnama', 'Man Kautuhal', 'Fatwa-e-Alamgiri', 'C', 'Raja Man Singh Tomar of Gwalior was a great patron of the Dhrupad tradition of Hindustani classical music. He commissioned the seminal music treatise ''Man Kautuhal'', documenting ragas, compositions, and musical theories.', NULL, NULL, 'History of Indian Classical Music - S.C. Ghosh', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
