INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q033', 'apsc-dwr-2026', 33, 'General Studies', 'Ancient Indian History', 'Chronology & Eras', 'The Saka era was started in India by', '[{"id":"A","text":"Kanishka"},{"id":"B","text":"Vikramaditya"},{"id":"C","text":"Samudragupta"},{"id":"D","text":"Ashoka"}]'::jsonb, 'Kanishka', 'Vikramaditya', 'Samudragupta', 'Ashoka', 'A', 'The Saka Era began in 78 CE, founded by the Kushana Emperor Kanishka upon his accession. It was adopted by the Government of India as the National Calendar (Saka Samvat) alongside the Gregorian calendar in 1957.', NULL, NULL, 'NCERT Ancient India - R.S. Sharma', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q034', 'apsc-dwr-2026', 34, 'General Studies', 'Ancient Indian History', 'Historiography', 'The Wonder That Was India was written by', '[{"id":"A","text":"A. P. J. Abdul Kalam"},{"id":"B","text":"Sekhar Bandyopadhyay"},{"id":"C","text":"A. L. Basham"},{"id":"D","text":"Ruskin Bond"}]'::jsonb, 'A. P. J. Abdul Kalam', 'Sekhar Bandyopadhyay', 'A. L. Basham', 'Ruskin Bond', 'C', '''The Wonder That Was India'' is a classic and internationally acclaimed survey of Indian culture and civilization before the 13th century, authored in 1954 by British Indologist Arthur Llewellyn Basham (A. L. Basham).', NULL, NULL, 'Standard Historiography - A.L. Basham', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q035', 'apsc-dwr-2026', 35, 'General Studies', 'Modern Indian History', 'Economic Nationalism', 'The acknowledged propounder of ''Drain Theory'' was', '[{"id":"A","text":"R. C. Dutt"},{"id":"B","text":"Sachchidananda Sinha"},{"id":"C","text":"Mahatma Gandhi"},{"id":"D","text":"Dadabhai Naoroji"}]'::jsonb, 'R. C. Dutt', 'Sachchidananda Sinha', 'Mahatma Gandhi', 'Dadabhai Naoroji', 'D', 'Dadabhai Naoroji, known as the ''Grand Old Man of India'', systematically formulated the ''Drain of Wealth Theory'' in his pioneering work ''Poverty and Un-British Rule in India'' (1901), showing how Britain extracted wealth from India without economic return.', NULL, NULL, 'India''s Struggle for Independence - Bipan Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q036', 'apsc-dwr-2026', 36, 'General Studies', 'Modern Indian History', 'Advent of European Powers', 'The first to come and last to leave India were', '[{"id":"A","text":"the British"},{"id":"B","text":"the Portuguese"},{"id":"C","text":"the Dutch"},{"id":"D","text":"the French"}]'::jsonb, 'the British', 'the Portuguese', 'the Dutch', 'the French', 'B', 'The Portuguese were the first Europeans to arrive in India by sea route (Vasco da Gama reached Calicut in May 1498) and the last colonial power to depart (Goa, Daman and Diu were liberated by the Indian military in Operation Vijay in December 1961).', NULL, NULL, 'Modern India - Spectrum / Bipan Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q037', 'apsc-dwr-2026', 37, 'General Studies', 'Modern Indian History', 'Education Reforms', 'In which year J. E. D. Bethune founded the Bethune School in Calcutta?', '[{"id":"A","text":"1849"},{"id":"B","text":"1850"},{"id":"C","text":"1848"},{"id":"D","text":"1851"}]'::jsonb, '1849', '1850', '1848', '1851', 'A', 'John Elliot Drinkwater Bethune (Law Member of the Governor-General''s Council) founded the Calcutta Female School (later renamed Bethune School) in May 1849, pioneering formal secular schooling for girls in India.', NULL, NULL, 'History of Modern India - Bipan Chandra', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q038', 'apsc-dwr-2026', 38, 'Assam History & Culture', 'Tai-Ahom Religion & Culture', 'Deities of Tai-Ahom', 'The Goddess of learning of the Ahom is known as', '[{"id":"A","text":"Phrak-engniurg"},{"id":"B","text":"Phai"},{"id":"C","text":"Jasingpha"},{"id":"D","text":"Lengdon"}]'::jsonb, 'Phrak-engniurg', 'Phai', 'Jasingpha', 'Lengdon', 'C', 'In the traditional Tai-Ahom pantheon, Jasingpha is worshipped as the deity of wisdom, scholarship, knowledge, and learning (equivalent to Goddess Saraswati). Lengdon is the supreme Lord of Heaven, and Phai is the deity of fire.', NULL, NULL, 'Tai-Ahom Religion and Customs - Padmeswar Gogoi', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q039', 'apsc-dwr-2026', 39, 'Assam History & Culture', 'Assam Peasant Movements', 'British Resistance in Assam', 'The first peasant uprising against the British in Assam was', '[{"id":"A","text":"Battle of Itakhuli"},{"id":"B","text":"Phulaguri Dhawa"},{"id":"C","text":"Patharughat Raijmel"},{"id":"D","text":"None of the above"}]'::jsonb, 'Battle of Itakhuli', 'Phulaguri Dhawa', 'Patharughat Raijmel', 'None of the above', 'B', 'Phulaguri Dhawa, which erupted in October 1861 in the Nowgong (Nagaon) district among Tiwa and Lalung peasants against British taxation on betel-nut/tamul and proposed ban/tax on opium, was the first organized agrarian revolt in British Assam.', NULL, NULL, 'A Comprehensive History of Assam - H.K. Barpujari', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
