INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q041', 'apsc-dwr-2026', 41, 'General Studies', 'Indian Economy & Modern History', 'Commercial Institutions', 'The Federation of Indian Chambers of Commerce and Industry (FICCI) was formed in the year', '[{"id":"A","text":"1927"},{"id":"B","text":"1920"},{"id":"C","text":"1921"},{"id":"D","text":"1930"}]'::jsonb, '1927', '1920', '1921', '1930', 'A', 'FICCI (Federation of Indian Chambers of Commerce and Industry) was founded in 1927 upon the advice of Mahatma Gandhi by prominent business leaders G. D. Birla and Sir Purshottamdas Thakurdas to represent indigenous Indian commercial interests.', NULL, NULL, 'Indian Economy - Ramesh Singh', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q042', 'apsc-dwr-2026', 42, 'Assam History & Culture', 'Assam Heritage & UNESCO Sites', 'Charaideo Moidams', 'With reference to the Charaideo Maidam, consider the following statements :
(i) Charaideo Maidam is now a UNESCO World Heritage Site.
(ii) The first king to be buried here was Suhungmung.
(iii) These are located along the foothills of the Patkai range.
(iv) These Maidams contain the remains of the royalty of Pala Dynasty.
