INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q044', 'apsc-dwr-2026', 44, 'Assam History & Culture', 'Assam History', 'Ahom Administration', 'Habiyal Barua and Kathkatiya Barua were appointed by Ahom rulers to supervise', '[{"id":"A","text":"revenue"},{"id":"B","text":"judicial administration"},{"id":"C","text":"forest"},{"id":"D","text":"religious affairs"}]'::jsonb, 'revenue', 'judicial administration', 'forest', 'religious affairs', 'C', 'In the Ahom state administrative hierarchy, Habiyal Barua was the superintendent of forests, wild flora, and fauna, while Kathkatiya Barua oversaw the guild of woodcutters, timber dressers, and carpenters. Both officers supervised forest administration and natural resources.', NULL, NULL, 'Ahom Administration - S.L. Baruah', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q045', 'apsc-dwr-2026', 45, 'General Studies', 'Modern Indian History', 'Social Reforms', '''Sati Pratha'' was banned in 1829 by', '[{"id":"A","text":"Warren Hastings"},{"id":"B","text":"Lord Wellesley"},{"id":"C","text":"Lord William Bentinck"},{"id":"D","text":"Lord Dalhousie"}]'::jsonb, 'Warren Hastings', 'Lord Wellesley', 'Lord William Bentinck', 'Lord Dalhousie', 'C', 'Governor-General Lord William Bentinck promulgated the Bengal Sati Regulation XVII on 4 December 1829, declaring the practice of Sati illegal and culpable homicide, with active advocacy by Raja Ram Mohan Roy.', NULL, NULL, 'NCERT Modern India - Bipan Chandra', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
