INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q047', 'apsc-dwr-2026', 47, 'General Studies', 'Indian Polity & Governance', 'Civil Service Reforms', 'Which of the following Committees recommended on the design of the examination cycle of UPSC in 1976?', '[{"id":"A","text":"Bhagwati Committee"},{"id":"B","text":"D. S. Kothari Committee"},{"id":"C","text":"A. D. Gorwala Committee"},{"id":"D","text":"Santhanam Committee"}]'::jsonb, 'Bhagwati Committee', 'D. S. Kothari Committee', 'A. D. Gorwala Committee', 'Santhanam Committee', 'B', 'The Committee on Recruitment Policy and Selection Methods appointed under Dr. D. S. Kothari in 1974 submitted its landmark report in 1976. It recommended the unified 3-stage Civil Services Examination structure: CS Preliminary Examination, CS Main Examination, and Personality Test.', NULL, NULL, 'Indian Public Administration - Ramesh K. Arora', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q048', 'apsc-dwr-2026', 48, 'General Studies', 'Modern Indian History', 'Judicial Administration', 'The setting up of the High Courts of Calcutta, Madras, and Bombay in 1865 is associated with', '[{"id":"A","text":"Lord John Lawrence"},{"id":"B","text":"Lord Mayo"},{"id":"C","text":"Lord Canning"},{"id":"D","text":"Lord Ripon"}]'::jsonb, 'Lord John Lawrence', 'Lord Mayo', 'Lord Canning', 'Lord Ripon', 'A', 'While the Indian High Courts Act was enacted in 1861 during Lord Canning''s tenure, the definitive and revised Letters Patent officially reconstituting and consolidating the High Courts of Judicature at Fort William in Bengal (Calcutta), Madras, and Bombay were issued on 28 December 1865 under the viceroyalty of Lord John Lawrence (1864–1869).', NULL, NULL, 'Constitutional History of India - Keith / M.P. Jain', 'HARD', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
