INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q050', 'apsc-dwr-2026', 50, 'General Mental Ability', 'Reasoning & Mental Ability', 'Direction Sense', 'A man is facing North. He turns 45° clockwise, then 315° anti-clockwise, and then 135° clockwise. Which direction is he facing now?', '[{"id":"A","text":"South-West"},{"id":"B","text":"South-East"},{"id":"C","text":"North-East"},{"id":"D","text":"North-West"}]'::jsonb, 'South-West', 'South-East', 'North-East', 'North-West', 'A', 'Let North be 0°. Clockwise is positive (+), anti-clockwise is negative (-).
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q051', 'apsc-dwr-2026', 51, 'General Mental Ability', 'Quantitative Aptitude', 'Probability', 'In a Ludo game, a token needs 2 steps to reach home. A fair dice with six faces is rolled. What is the chance in percentage that the token reaches home in this turn?', '[{"id":"A","text":"16.66%"},{"id":"B","text":"33.33%"},{"id":"C","text":"50%"},{"id":"D","text":"0%"}]'::jsonb, '16.66%', '33.33%', '50%', '0%', 'A', 'A standard 6-faced die has outcomes {1, 2, 3, 4, 5, 6}, total = 6.
