INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q053', 'apsc-dwr-2026', 53, 'General Mental Ability', 'Quantitative Aptitude', 'Problems on Ages', 'A is twice as old as B. After 6 years, the sum of their ages will be 30. What are their current ages?', '[{"id":"A","text":"A is 20 years old, B is 10 years old"},{"id":"B","text":"A is 18 years old, B is 9 years old"},{"id":"C","text":"A is 10 years old, B is 5 years old"},{"id":"D","text":"A is 12 years old, B is 6 years old"}]'::jsonb, 'A is 20 years old, B is 10 years old', 'A is 18 years old, B is 9 years old', 'A is 10 years old, B is 5 years old', 'A is 12 years old, B is 6 years old', 'D', 'Let B''s present age be x, then A''s present age is 2x.
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q054', 'apsc-dwr-2026', 54, 'General Studies', 'Physical Geography', 'Longitudes and Time', 'The Earth rotates 360° in 24 hours. If the time is 11:00 a.m. at Greenwich, what will be the local time at 90° East longitude?', '[{"id":"A","text":"6 a.m."},{"id":"B","text":"6 p.m."},{"id":"C","text":"5 a.m."},{"id":"D","text":"5 p.m."}]'::jsonb, '6 a.m.', '6 p.m.', '5 a.m.', '5 p.m.', 'D', 'Earth rotates 360° in 24 hours => 15° = 1 hour (or 1° = 4 minutes).
