INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q057', 'apsc-dwr-2026', 57, 'General English', 'Vocabulary', 'Antonyms', 'Choose the correct pair of antonym from the following :', '[{"id":"A","text":"Boring : Stimulating"},{"id":"B","text":"Comfort : Comfortable"},{"id":"C","text":"Foreign : Distant"},{"id":"D","text":"Knowledge : Disinterest"}]'::jsonb, 'Boring : Stimulating', 'Comfort : Comfortable', 'Foreign : Distant', 'Knowledge : Disinterest', 'A', '''Boring'' (causing weariness or lack of interest) and ''Stimulating'' (animating, rousing, inspiring interest) are direct and exact antonyms.', NULL, NULL, 'Oxford Advanced Learner''s Dictionary', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
