INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q063', 'apsc-dwr-2026', 63, 'General Studies', 'Indian Polity & Constitution', 'Articles of the Constitution', 'At present, how many Articles are there in the Indian Constitution?', '[{"id":"A","text":"470"},{"id":"B","text":"448"},{"id":"C","text":"395"},{"id":"D","text":"277"}]'::jsonb, '470', '448', '395', '277', 'A', 'Although the Constitution was enacted with 395 Articles in 1949, successive amendments have added numerous articles (and repealed some), bringing the total to approximately 470 Articles arranged into 25 Parts.', NULL, NULL, 'Indian Polity - M. Laxmikanth', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q064', 'apsc-dwr-2026', 64, 'Assam & Northeast Development', 'Literature of Northeast India', 'Contemporary Authors', 'Which of the following is matched incorrectly?', '[{"id":"A","text":"Srutimala Duara—Travelling with Dreams"},{"id":"B","text":"Mamang Dai—The Blackhill"},{"id":"C","text":"Mina Phukan—Notes on Grief"},{"id":"D","text":"Arupa Patangia—The Story of Felanee"}]'::jsonb, 'Srutimala Duara—Travelling with Dreams', 'Mamang Dai—The Blackhill', 'Mina Phukan—Notes on Grief', 'Arupa Patangia—The Story of Felanee', 'C', '''Notes on Grief'' is the celebrated 2021 memoir written by Nigerian author Chimamanda Ngozi Adichie, NOT Mina Phukan. The other three works (''Travelling with Dreams'' by Srutimala Duara, ''The Black Hill'' by Mamang Dai, and ''The Story of Felanee'' by Arupa Patangia Kalita) are correctly matched.', NULL, NULL, 'Contemporary Indian Literature', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
