INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q085', 'apsc-dwr-2026', 85, 'General Studies', 'Current Affairs & Honours', 'Nobel Prizes 2025', 'Who among the following was awarded the 2025 Nobel Prize in Literature?', '[{"id":"A","text":"Michel Devoret"},{"id":"B","text":"Laszlo Krasznahorkai"},{"id":"C","text":"Han Kang"},{"id":"D","text":"Akin Duzakin"}]'::jsonb, 'Michel Devoret', 'Laszlo Krasznahorkai', 'Han Kang', 'Akin Duzakin', 'C', 'South Korean author Han Kang was awarded the Nobel Prize in Literature ''for her intense poetic prose that confronts historical traumas and exposes the fragility of human life''.', NULL, NULL, 'The Nobel Prize in Literature - Official Press Release', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q086', 'apsc-dwr-2026', 86, 'General Studies', 'International Trade & Economy', 'Tariffs & Global Supply Chains', 'The USA tariff on India was increased to 50% on August 27, 2025 that has impacted over half of India''s exports to the USA. Which of the following has been exempted from this tariff?', '[{"id":"A","text":"Chemicals"},{"id":"B","text":"Marine products"},{"id":"C","text":"Semiconductors"},{"id":"D","text":"Textiles"}]'::jsonb, 'Chemicals', 'Marine products', 'Semiconductors', 'Textiles', 'C', 'Semiconductors and key strategic microelectronic supply chain items were exempted from reciprocal import tariffs to safeguard global electronics hardware production and telecommunications infrastructure.', NULL, NULL, 'International Trade Administration / USTR Tariff Schedule', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q087', 'apsc-dwr-2026', 87, 'General Studies', 'Physical Geography', 'Weathering and Geomorphology', 'The most ideal conditions for chemical weathering are found in', '[{"id":"A","text":"cold and dry regions"},{"id":"B","text":"cold and humid regions"},{"id":"C","text":"hot and dry regions"},{"id":"D","text":"hot and humid regions"}]'::jsonb, 'cold and dry regions', 'cold and humid regions', 'hot and dry regions', 'hot and humid regions', 'D', 'Chemical weathering processes (carbonation, hydration, oxidation, and hydrolysis) require abundant water as a reactive medium, and reaction kinetics increase exponentially with temperature. Therefore, hot and humid tropical climates offer optimal conditions for chemical weathering.', NULL, NULL, 'Physical Geography - Savindra Singh / Goh Cheng Leong', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q088', 'apsc-dwr-2026', 88, 'General Studies', 'Environmental Science', 'Indoor Air Pollution', 'Which of the following is emitted from soil and is a major indoor pollutant?', '[{"id":"A","text":"Po-218"},{"id":"B","text":"Pb-214"},{"id":"C","text":"Po-210"},{"id":"D","text":"Rn-222"}]'::jsonb, 'Po-218', 'Pb-214', 'Po-210', 'Rn-222', 'D', 'Radon-222 (Rn-222) is an inert, radioactive noble gas generated by the radioactive alpha decay of Radium-226 in soils and bedrock. It infiltrates homes through basements, cracks, and floor joints, representing a leading cause of indoor environmental radiation and lung cancer.', NULL, NULL, 'Environmental Science - Miller & Spoolman / WHO Guidelines', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q089', 'apsc-dwr-2026', 89, 'General Studies', 'Environment & Forestry', 'Forest Governance', 'The Joint Forest Management Programme allows forest dwellers for the collection of', '[{"id":"A","text":"timber"},{"id":"B","text":"non-timber-based forest products"},{"id":"C","text":"leaves of plants"},{"id":"D","text":"only medicinal plants"}]'::jsonb, 'timber', 'non-timber-based forest products', 'leaves of plants', 'only medicinal plants', 'B', 'Under the Joint Forest Management (JFM) institutional framework launched under the National Forest Policy of 1988, participating forest fringe communities receive usufruct rights to collect Non-Timber Forest Products (NTFPs) / minor forest produce in exchange for protecting forest resources.', NULL, NULL, 'Ministry of Environment, Forest and Climate Change (MoEFCC)', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q090', 'apsc-dwr-2026', 90, 'General Studies', 'Ecology & Biodiversity', 'Biogeography', 'Biogeographic regions are defined on the basis of', '[{"id":"A","text":"uniform climatic conditions"},{"id":"B","text":"uniform geographical characters"},{"id":"C","text":"similar topographic conditions"},{"id":"D","text":"similar or shared plant and animal distribution"}]'::jsonb, 'uniform climatic conditions', 'uniform geographical characters', 'similar topographic conditions', 'similar or shared plant and animal distribution', 'D', 'Biogeographical regions (realms/ecozones) are global geographic units characterized by shared evolutionary histories, taxonomic affinities, and common spatial distributions of indigenous flora and fauna.', NULL, NULL, 'Ecology - Odum / Wildlife Institute of India', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q091', 'apsc-dwr-2026', 91, 'General Studies', 'Ecology & Biodiversity', 'Conservation Methods', 'Which of the following is not an example of in-situ conservation?', '[{"id":"A","text":"National Parks"},{"id":"B","text":"Wildlife Sanctuaries"},{"id":"C","text":"Biosphere Reserves"},{"id":"D","text":"Botanical Gardens"}]'::jsonb, 'National Parks', 'Wildlife Sanctuaries', 'Biosphere Reserves', 'Botanical Gardens', 'D', 'In-situ conservation refers to the protection of species in their natural wild ecosystems (e.g. National Parks, Sanctuaries, Biosphere Reserves). Botanical Gardens, zoological parks, and seed banks safeguard genetic resources outside their native habitats and are classic examples of ex-situ conservation.', NULL, NULL, 'NCERT Biology Class XII - Ecology & Environment', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q092', 'apsc-dwr-2026', 92, 'Assam Geography & Economy', 'Geography of Assam', 'National Parks & Rivers', 'Match the following Parks/Wildlife Sanctuaries with their correct river systems :
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q093', 'apsc-dwr-2026', 93, 'Assam Geography & Economy', 'Assam Environment & Protected Areas', 'Protected Area Network', 'Assam has _____ numbers of Wildlife Sanctuaries and _____ numbers of National Parks as of August, 2025.', '[{"id":"A","text":"18, 3"},{"id":"B","text":"20, 3"},{"id":"C","text":"17, 8"},{"id":"D","text":"18, 2"}]'::jsonb, '18, 3', '20, 3', '17, 8', '18, 2', 'C', 'As of mid-2025, Assam contains 17 Wildlife Sanctuaries and 8 National Parks (Kaziranga, Manas, Nameri, Orang, Dibru-Saikhowa, Raimona, Dehing Patkai, and newly notified parks). Hence, Option (C) 17, 8 is correct.', NULL, NULL, 'Department of Environment and Forest, Government of Assam', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q094', 'apsc-dwr-2026', 94, 'Assam Geography & Economy', 'Disaster Management & Geography of Assam', '1950 Great Assam Earthquake', 'Which of the following statements is incorrect regarding the Great Assam Earthquake of 1950?', '[{"id":"A","text":"The epicentre of the earthquake was located in the Mishmi Hills."},{"id":"B","text":"It was the sixth largest recorded earthquake in the 20th Century."},{"id":"C","text":"The resultant landslides dammed the Subansiri, Dihang and Dibang rivers."},{"id":"D","text":"It was the largest recorded earthquake on land."}]'::jsonb, 'The epicentre of the earthquake was located in the Mishmi Hills.', 'It was the sixth largest recorded earthquake in the 20th Century.', 'The resultant landslides dammed the Subansiri, Dihang and Dibang rivers.', 'It was the largest recorded earthquake on land.', 'D', 'Statements (A), (B), and (C) are verified historical facts: the epicentre was located in the Mishmi Hills near Rima, it was recorded at magnitude ~8.6 (ranking 6th among 20th-century earthquakes), and catastrophic landslide dams blocked the Subansiri, Dihang, and Dibang rivers causing devastating flash floods when they breached. Statement (D) is incorrect.', NULL, NULL, 'Geological Survey of India / Taher & Ahmed', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q095', 'apsc-dwr-2026', 95, 'Assam Geography & Economy', 'Minerals and Resources of Assam', 'Coal Resources', 'The largest coal reserves in Assam estimated to be around 316 million tonnes is located in', '[{"id":"A","text":"Makum Coalfield"},{"id":"B","text":"Saraipung Tarajan Coal Deposit"},{"id":"C","text":"Dithor Coal Deposit"},{"id":"D","text":"Dilli Jeypore Coalfield"}]'::jsonb, 'Makum Coalfield', 'Saraipung Tarajan Coal Deposit', 'Dithor Coal Deposit', 'Dilli Jeypore Coalfield', 'A', 'The Makum Coalfield in Tinsukia district (including Ledo, Tipong, Tirap, and Baragolai) holds the largest reserves of sub-bituminous, high-sulphur tertiary coal in Assam, estimated at roughly 316 million tonnes.', NULL, NULL, 'Mineral Resources of Assam - Directorate of Geology and Mining', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q096', 'apsc-dwr-2026', 96, 'Assam Geography & Economy', 'Geography of Assam', 'Majuli Island', 'Which of the following is false in case of Majuli Island?', '[{"id":"A","text":"1950 earthquake caused uplifting of the island"},{"id":"B","text":"The island has a distinctive spindle shape, oriented North-east-South-west"},{"id":"C","text":"It is primarily composed of flat, alluvial plains with low relief"},{"id":"D","text":"It is a deltaic island formed by the deposition of sediments from the Brahmaputra river and its tributaries"}]'::jsonb, '1950 earthquake caused uplifting of the island', 'The island has a distinctive spindle shape, oriented North-east-South-west', 'It is primarily composed of flat, alluvial plains with low relief', 'It is a deltaic island formed by the deposition of sediments from the Brahmaputra river and its tributaries', 'D', 'Statement (D) is false: Majuli is an inland fluvial/riverine island formed within the midstream braided network of the Brahmaputra and Subansiri river channels. It is NOT a deltaic island (which forms at a river mouth entering the sea).', NULL, NULL, 'Geography of Assam - Taher & Ahmed', 'MEDIUM', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q097', 'apsc-dwr-2026', 97, 'General Studies', 'Physical Geography', 'Fluvial Landforms', 'As a river overflows its banks during flood, it drops much of its coarser-grained load immediately, forming landforms called', '[{"id":"A","text":"deltas"},{"id":"B","text":"alluvial fans"},{"id":"C","text":"natural levees"},{"id":"D","text":"point bars"}]'::jsonb, 'deltas', 'alluvial fans', 'natural levees', 'point bars', 'C', 'When a flood breaches a river''s natural banks, the sudden loss of water velocity and hydraulic depth causes the immediate deposition of coarse sands and silts right along the river margin, building up elongated, elevated embankment ridges known as natural levees.', NULL, NULL, 'Physical Geography - Savindra Singh / Strahler', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q098', 'apsc-dwr-2026', 98, 'Assam Geography & Economy', 'Geography of Assam & Geology', 'Plate Tectonics & Seismicity', 'Assam and the rest of North-East India experiences frequent earthquakes because', '[{"id":"A","text":"it is geologically weak"},{"id":"B","text":"of excessive precipitation"},{"id":"C","text":"it is mostly made up of sedimentary deposits"},{"id":"D","text":"it is situated in plate boundary"}]'::jsonb, 'it is geologically weak', 'of excessive precipitation', 'it is mostly made up of sedimentary deposits', 'it is situated in plate boundary', 'D', 'Northeast India falls in high-risk Seismic Zone V because it is situated right at the active convergent plate boundaries where the Indian Plate is actively colliding northward with the Eurasian Plate (Himalayan Arc) and subducting eastward under the Burmese Microplate (Indo-Burma Arc).', NULL, NULL, 'Geological Survey of India / Taher & Ahmed', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q099', 'apsc-dwr-2026', 99, 'General Studies', 'Climatology & Environment', 'Greenhouse Effect', 'In absence of greenhouse gases, the average temperature of earth would decline to approximately', '[{"id":"A","text":"15 °C"},{"id":"B","text":"17 °C"},{"id":"C","text":"-18 °C"},{"id":"D","text":"-8 °C"}]'::jsonb, '15 °C', '17 °C', '-18 °C', '-8 °C', 'C', 'Without the natural greenhouse blanket (water vapour, carbon dioxide, methane) absorbing and re-radiating terrestrial infrared radiation, Earth''s effective blackbody emission temperature would be approximately 255 Kelvin (-18 °C), rather than the current global average of +15 °C.', NULL, NULL, 'Climatology - Savindra Singh / IPCC Physical Science Basis', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('dwr-2026-q100', 'apsc-dwr-2026', 100, 'General Studies', 'Environment & Climate Policy', 'COP26 Panchamrit Targets', 'At COP26 India''s decarbonization target includes', '[{"id":"A","text":"decarbonizing energy to 50% and achieving 500 GW of fossil fuel-free generating capacity by 2030"},{"id":"B","text":"decarbonizing energy to 50% and achieving 700 GW of fossil fuel-free generating capacity by 2050"},{"id":"C","text":"decarbonizing energy to 80% and achieving 500 GW of fossil fuel-free generating capacity by 2030"},{"id":"D","text":"decarbonizing energy to 60% and achieving 700 GW of fossil fuel-free generating capacity by 2050"}]'::jsonb, 'decarbonizing energy to 50% and achieving 500 GW of fossil fuel-free generating capacity by 2030', 'decarbonizing energy to 50% and achieving 700 GW of fossil fuel-free generating capacity by 2050', 'decarbonizing energy to 80% and achieving 500 GW of fossil fuel-free generating capacity by 2030', 'decarbonizing energy to 60% and achieving 700 GW of fossil fuel-free generating capacity by 2050', 'A', 'At COP26 in Glasgow (2021), India announced its ''Panchamrit'' climate action pledge: achieving 500 GW of non-fossil/fossil fuel-free energy capacity by 2030 and meeting 50% of energy requirements from renewable energy by 2030.', NULL, NULL, 'PIB / Ministry of Environment, Forest and Climate Change (MoEFCC)', 'EASY', 'CONCEPTUAL', 'PYQ', 2026, 'Assam DWR Paper II 2026 (11/01/2026 Series A)') ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q001', 'apsc-phed-ae-gs-2025', 1, 'I. Current Events of National & International importance', 'National current events, government initiatives and policies', NULL, 'Under the Jal Jeevan Mission (Har Ghar Jal) administered by the Ministry of Jal Shakti, what is the targeted per capita daily supply of potable tap water to every rural household?', '[{"id":"A","text":"40 litres per capita per day (lpcd)"},{"id":"B","text":"55 litres per capita per day (lpcd)"},{"id":"C","text":"70 litres per capita per day (lpcd)"},{"id":"D","text":"100 litres per capita per day (lpcd)"}]'::jsonb, '40 litres per capita per day (lpcd)', '55 litres per capita per day (lpcd)', '70 litres per capita per day (lpcd)', '100 litres per capita per day (lpcd)', 'B', 'The Jal Jeevan Mission (JJM) aims to provide Functional Household Tap Connections (FHTC) delivering 55 litres per capita per day (lpcd) of prescribed quality drinking water on a long-term basis to every rural household.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I (JJM Guidelines)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q002', 'apsc-phed-ae-gs-2025', 2, 'I. Current Events of National & International importance', 'International relations, global summits, treaties and bilateral agreements', NULL, 'Which international organization officially admitted the African Union (AU) as a permanent member during its summit held in New Delhi in 2023 under India’s presidency?', '[{"id":"A","text":"BRICS"},{"id":"B","text":"G20"},{"id":"C","text":"SCO (Shanghai Cooperation Organisation)"},{"id":"D","text":"ASEAN"}]'::jsonb, 'BRICS', 'G20', 'SCO (Shanghai Cooperation Organisation)', 'ASEAN', 'B', 'Under India’s G20 Presidency at the New Delhi Summit in September 2023, the 55-nation African Union was formally inducted as a permanent member of the G20, expanding it into the G21.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q003', 'apsc-phed-ae-gs-2025', 3, 'I. Current Events of National & International importance', 'National and international awards, honours, Nobel prizes, Padma awards', NULL, 'Who was conferred the prestigious Bharat Ratna posthumously in 2024 for championing social justice and serving twice as Chief Minister of Bihar?', '[{"id":"A","text":"Karpoori Thakur"},{"id":"B","text":"Jayaprakash Narayan"},{"id":"C","text":"Ram Manohar Lohia"},{"id":"D","text":"Jagjivan Ram"}]'::jsonb, 'Karpoori Thakur', 'Jayaprakash Narayan', 'Ram Manohar Lohia', 'Jagjivan Ram', 'A', 'Jan Nayak Karpoori Thakur, legendary socialist leader and former Bihar Chief Minister known for pioneering affirmative action policies, was awarded the Bharat Ratna posthumously in January 2024.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q004', 'apsc-phed-ae-gs-2025', 4, 'I. Current Events of National & International importance', 'Sports championships, Olympic games, national games and awards', NULL, 'Where were the 33rd Summer Olympic Games held in July-August 2024?', '[{"id":"A","text":"Los Angeles, USA"},{"id":"B","text":"Paris, France"},{"id":"C","text":"Brisbane, Australia"},{"id":"D","text":"Tokyo, Japan"}]'::jsonb, 'Los Angeles, USA', 'Paris, France', 'Brisbane, Australia', 'Tokyo, Japan', 'B', 'The 2024 Summer Olympics (Games of the XXXIII Olympiad) were hosted by Paris, France, from 26 July to 11 August 2024.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q005', 'apsc-phed-ae-gs-2025', 5, 'I. Current Events of National & International importance', 'National current events, government initiatives and policies', NULL, 'Which scheme was launched by the Government of India in 2024 to provide free electricity up to 300 units per month to one crore households through rooftop solar installations?', '[{"id":"A","text":"PM Surya Ghar: Muft Bijli Yojana"},{"id":"B","text":"PM KUSUM Yojana"},{"id":"C","text":"PM UJALA Scheme"},{"id":"D","text":"PM Saubhagya Yojana"}]'::jsonb, 'PM Surya Ghar: Muft Bijli Yojana', 'PM KUSUM Yojana', 'PM UJALA Scheme', 'PM Saubhagya Yojana', 'A', 'PM Surya Ghar: Muft Bijli Yojana was launched in February 2024 with an outlay of ₹75,000+ crore to provide up to 300 units of free electricity monthly through rooftop solar panels.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q006', 'apsc-phed-ae-gs-2025', 6, 'I. Current Events of National & International importance', 'National and international awards, honours, Nobel prizes, Padma awards', NULL, 'The Moidams — the Mound-Burial System of the Ahom Dynasty in Charaideo, Assam — was officially inscribed as a UNESCO World Heritage Site in July 2024 under which category?', '[{"id":"A","text":"Cultural Heritage"},{"id":"B","text":"Natural Heritage"},{"id":"C","text":"Mixed Heritage"},{"id":"D","text":"Intangible Cultural Heritage"}]'::jsonb, 'Cultural Heritage', 'Natural Heritage', 'Mixed Heritage', 'Intangible Cultural Heritage', 'A', 'At the 46th Session of the World Heritage Committee in New Delhi (July 2024), the Charaideo Moidams were inscribed as India’s 43rd UNESCO World Heritage Site under the Cultural category, making it Northeast India’s first cultural World Heritage Site.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I & VIII', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q007', 'apsc-phed-ae-gs-2025', 7, 'I. Current Events of National & International importance', 'National current events, government initiatives and policies', NULL, 'What is the name of the deep-water transshipment port commissioned in Kerala in 2024, representing India’s first automated container transshipment terminal?', '[{"id":"A","text":"Vizhinjam International Seaport"},{"id":"B","text":"Vadhavan Port"},{"id":"C","text":"Cochin Port"},{"id":"D","text":"Tuticorin Port"}]'::jsonb, 'Vizhinjam International Seaport', 'Vadhavan Port', 'Cochin Port', 'Tuticorin Port', 'A', 'Vizhinjam International Seaport near Thiruvananthapuram, Kerala, developed with Adani Ports, is India’s first dedicated deep-water container transshipment hub.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q008', 'apsc-phed-ae-gs-2025', 8, 'I. Current Events of National & International importance', 'Important days, themes, global summits and international conferences', NULL, 'World Water Day is observed globally every year on:', '[{"id":"A","text":"22nd March"},{"id":"B","text":"22nd April"},{"id":"C","text":"5th June"},{"id":"D","text":"16th September"}]'::jsonb, '22nd March', '22nd April', '5th June', '16th September', 'A', 'World Water Day is celebrated annually on 22 March since 1993, raising awareness of the 2.2 billion people living without access to safe water. (22 April is Earth Day, 5 June is World Environment Day).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q009', 'apsc-phed-ae-gs-2025', 9, 'I. Current Events of National & International importance', 'International relations, global summits, treaties and bilateral agreements', NULL, 'The COP28 UN Climate Change Conference held in Dubai (UAE) concluded with a historic consensus calling for:', '[{"id":"A","text":"Transitioning away from fossil fuels in energy systems"},{"id":"B","text":"Immediate ban on all coal mining by 2025"},{"id":"C","text":"Abolition of carbon credits trading"},{"id":"D","text":"Fixing global temperature rise cap to 3.0°C"}]'::jsonb, 'Transitioning away from fossil fuels in energy systems', 'Immediate ban on all coal mining by 2025', 'Abolition of carbon credits trading', 'Fixing global temperature rise cap to 3.0°C', 'A', 'The UAE Consensus reached at COP28 for the first time in 30 years explicitly called on nations to transition away from fossil fuels in energy systems in a just, orderly, and equitable manner.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q010', 'apsc-phed-ae-gs-2025', 10, 'I. Current Events of National & International importance', 'National current events, government initiatives and policies', NULL, 'Which new criminal law replaced the colonial Indian Penal Code (IPC) of 1860 in India with effect from 1st July 2024?', '[{"id":"A","text":"Bharatiya Nyaya Sanhita (BNS), 2023"},{"id":"B","text":"Bharatiya Nagarik Suraksha Sanhita (BNSS), 2023"},{"id":"C","text":"Bharatiya Sakshya Adhiniyam (BSA), 2023"},{"id":"D","text":"Bharatiya Danda Samhita, 2023"}]'::jsonb, 'Bharatiya Nyaya Sanhita (BNS), 2023', 'Bharatiya Nagarik Suraksha Sanhita (BNSS), 2023', 'Bharatiya Sakshya Adhiniyam (BSA), 2023', 'Bharatiya Danda Samhita, 2023', 'A', 'The Bharatiya Nyaya Sanhita (BNS) replaced the Indian Penal Code (IPC). The BNSS replaced the Code of Criminal Procedure (CrPC), and the BSA replaced the Indian Evidence Act.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q011', 'apsc-phed-ae-gs-2025', 11, 'I. Current Events of National & International importance', 'Sports championships, Olympic games, national games and awards', NULL, 'Which country won the ICC Men’s T20 Cricket World Cup 2024 held in the West Indies and USA?', '[{"id":"A","text":"South Africa"},{"id":"B","text":"India"},{"id":"C","text":"Australia"},{"id":"D","text":"England"}]'::jsonb, 'South Africa', 'India', 'Australia', 'England', 'B', 'India defeated South Africa by 7 runs in the final at Kensington Oval, Barbados, on 29 June 2024 to lift their second ICC Men’s T20 World Cup title.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q012', 'apsc-phed-ae-gs-2025', 12, 'I. Current Events of National & International importance', 'National current events, government initiatives and policies', NULL, 'The newly constructed Bogibeel bridge connecting Dibrugarh and Dhemaji districts in Assam is India’s longest:', '[{"id":"A","text":"Cable-stayed bridge"},{"id":"B","text":"Rail-cum-road bridge"},{"id":"C","text":"Suspension bridge"},{"id":"D","text":"Prestressed concrete girder bridge"}]'::jsonb, 'Cable-stayed bridge', 'Rail-cum-road bridge', 'Suspension bridge', 'Prestressed concrete girder bridge', 'B', 'At 4.94 km, Bogibeel Bridge over the Brahmaputra River in Assam is India’s longest rail-cum-road bridge and the second longest in Asia.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit I & III', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q013', 'apsc-phed-ae-gs-2025', 13, 'II. History of India & History of Assam', 'Ancient Kamarupa: Varman, Salastambha and Pala dynasties', NULL, 'Who was the ruler of the Varman dynasty of ancient Kamarupa who was a contemporary and close ally of Emperor Harshavardhana of Kannauj?', '[{"id":"A","text":"Pushyavarman"},{"id":"B","text":"Bhaskaravarman"},{"id":"C","text":"Bhutivarman"},{"id":"D","text":"Kalyanavarman"}]'::jsonb, 'Pushyavarman', 'Bhaskaravarman', 'Bhutivarman', 'Kalyanavarman', 'B', 'Kumar Bhaskaravarman (600–650 CE) was the most illustrious king of the Varman dynasty. Chinese pilgrim Xuanzang (Hiuen Tsang) visited Kamarupa upon his royal invitation.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q014', 'apsc-phed-ae-gs-2025', 14, 'II. History of India & History of Assam', 'Ahom Kingdom (1228-1826): Sukapha, administrative system, Paik system', NULL, 'Chaolung Sukapha, the founder of the Ahom Kingdom in Assam, crossed the Patkai hills and entered the Brahmaputra Valley in the year:', '[{"id":"A","text":"1206 CE"},{"id":"B","text":"1228 CE"},{"id":"C","text":"1253 CE"},{"id":"D","text":"1526 CE"}]'::jsonb, '1206 CE', '1228 CE', '1253 CE', '1526 CE', 'B', 'Chaolung Sukapha led his Tai followers from Mong Mao across the Patkai hills into the Upper Brahmaputra Valley in 1228 CE and established his first permanent capital at Charaideo in 1253 CE.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q015', 'apsc-phed-ae-gs-2025', 15, 'II. History of India & History of Assam', 'Battle of Saraighat & Lachit Borphukan', NULL, 'The historic naval Battle of Saraighat on the Brahmaputra River, where Ahom forces under General Lachit Borphukan decisively defeated the Mughal forces of Ram Singh, took place in:', '[{"id":"A","text":"1662 CE"},{"id":"B","text":"1671 CE"},{"id":"C","text":"1682 CE"},{"id":"D","text":"1667 CE"}]'::jsonb, '1662 CE', '1671 CE', '1682 CE', '1667 CE', 'B', 'The Battle of Saraighat was fought in 1671 CE between the Mughal Empire (commanded by Raja Ram Singh I) and the Ahom Kingdom (led by Lachit Borphukan), securing Kamrup from Mughal expansion.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q016', 'apsc-phed-ae-gs-2025', 16, 'II. History of India & History of Assam', 'British Annexation of Assam (Treaty of Yandabo 1826)', NULL, 'Assam was ceded to the British East India Company following the First Anglo-Burmese War under the Treaty of Yandabo, signed on:', '[{"id":"A","text":"24 February 1826"},{"id":"B","text":"15 August 1826"},{"id":"C","text":"1 January 1828"},{"id":"D","text":"23 June 1857"}]'::jsonb, '24 February 1826', '15 August 1826', '1 January 1828', '23 June 1857', 'A', 'The Treaty of Yandabo was signed on 24 February 1826 between General Sir Archibald Campbell and Governor of Legaing Maha Min Hla Kyaw Htin, ending the First Anglo-Burmese War and transferring Assam, Manipur, and Arakan to British administration.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q017', 'apsc-phed-ae-gs-2025', 17, 'II. History of India & History of Assam', 'Peasant uprisings in Assam (Phulaguri Dhawa 1861, Patharughat Ran 1894)', NULL, 'The first organized peasant uprising in Assam against British colonial taxation on betel-nut and proposed tax on betel-leaf was:', '[{"id":"A","text":"Patharughat Ran (1894)"},{"id":"B","text":"Phulaguri Dhawa (1861)"},{"id":"C","text":"Lachima Uprising (1894)"},{"id":"D","text":"Rangia Revolt (1893)"}]'::jsonb, 'Patharughat Ran (1894)', 'Phulaguri Dhawa (1861)', 'Lachima Uprising (1894)', 'Rangia Revolt (1893)', 'B', 'The Phulaguri Dhawa of October 1861 in Nowgong district was the earliest peasant revolt in Assam, triggered by the ban on poppy cultivation and rumors of taxes on betel leaf and areca nut.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q018', 'apsc-phed-ae-gs-2025', 18, 'II. History of India & History of Assam', 'Indus Valley Civilization, Vedic Period, Mauryas and Guptas', NULL, 'At which Harappan (Indus Valley Civilization) site has the famous dockyard and port structure made of burnt bricks been discovered?', '[{"id":"A","text":"Kalibangan"},{"id":"B","text":"Lothal"},{"id":"C","text":"Dholavira"},{"id":"D","text":"Banawali"}]'::jsonb, 'Kalibangan', 'Lothal', 'Dholavira', 'Banawali', 'B', 'Lothal in Gujarat, located on the Bhogava River (a tributary of Sabarmati), was an ancient tidal port with a massive brick basin identified as a dockyard.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Indian History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q019', 'apsc-phed-ae-gs-2025', 19, 'II. History of India & History of Assam', 'Indus Valley Civilization, Vedic Period, Mauryas and Guptas', NULL, 'The rock edicts of Emperor Ashoka were primarily deciphered for the first time in 1837 by:', '[{"id":"A","text":"Sir William Jones"},{"id":"B","text":"James Prinsep"},{"id":"C","text":"Alexander Cunningham"},{"id":"D","text":"Max Muller"}]'::jsonb, 'Sir William Jones', 'James Prinsep', 'Alexander Cunningham', 'Max Muller', 'B', 'James Prinsep, an officer in the Calcutta Mint and Secretary of the Asiatic Society of Bengal, successfully deciphered the ancient Brahmi and Kharosthi scripts in 1837.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Indian History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q020', 'apsc-phed-ae-gs-2025', 20, 'II. History of India & History of Assam', 'Medieval Indian kingdoms, Delhi Sultanate and Mughal Empire', NULL, 'Who was the founder of the Slave (Mamluk) Dynasty and the Delhi Sultanate in 1206 CE?', '[{"id":"A","text":"Iltutmish"},{"id":"B","text":"Qutb-ud-din Aibak"},{"id":"C","text":"Ghiyas-ud-din Balban"},{"id":"D","text":"Muhammad Ghori"}]'::jsonb, 'Iltutmish', 'Qutb-ud-din Aibak', 'Ghiyas-ud-din Balban', 'Muhammad Ghori', 'B', 'Qutb-ud-din Aibak, a trusted general of Muhammad Ghori, established the Mamluk/Slave dynasty in 1206 CE and initiated the construction of the Qutb Minar in Delhi.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Indian History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q021', 'apsc-phed-ae-gs-2025', 21, 'II. History of India & History of Assam', 'Koch Kingdom, Chutiya kingdom, Kachari dynasty', NULL, 'The greatest king of the Koch Dynasty under whose reign the kingdom reached its zenith and built the present structure of the Kamakhya Temple in 1565 CE was:', '[{"id":"A","text":"Biswa Singha"},{"id":"B","text":"Naranarayan (Malladev)"},{"id":"C","text":"Chilarai (Sukladhwaj)"},{"id":"D","text":"Pran Narayan"}]'::jsonb, 'Biswa Singha', 'Naranarayan (Malladev)', 'Chilarai (Sukladhwaj)', 'Pran Narayan', 'B', 'Maharaja Naranarayan and his commander-in-chief brother Sukladhwaj (Chilarai) defeated multiple kingdoms and rebuilt the Kamakhya temple on Nilachal Hill in 1565 CE.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q022', 'apsc-phed-ae-gs-2025', 22, 'II. History of India & History of Assam', 'Ahom Kingdom (1228-1826): Sukapha, administrative system, Paik system', NULL, 'The Paik system of compulsory corvée labor service to the state was the foundation of which kingdom’s administration?', '[{"id":"A","text":"Koch Kingdom"},{"id":"B","text":"Ahom Kingdom"},{"id":"C","text":"Kachari Kingdom"},{"id":"D","text":"Jaintia Kingdom"}]'::jsonb, 'Koch Kingdom', 'Ahom Kingdom', 'Kachari Kingdom', 'Jaintia Kingdom', 'B', 'The Paik system was the backbone of Ahom state administration, where every able-bodied adult male (paik) between 16 and 50 years was registered to render physical or military service in rotation.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q023', 'apsc-phed-ae-gs-2025', 23, 'II. History of India & History of Assam', 'Medieval Indian kingdoms, Delhi Sultanate and Mughal Empire', NULL, 'In the First Battle of Panipat (1526 CE), Babur defeated Ibrahim Lodi largely by deploying which military tactical formation?', '[{"id":"A","text":"Tulghuma tactical flanking and Rumi cart-line system with artillery"},{"id":"B","text":"Elephant cavalry charges"},{"id":"C","text":"Naval artillery bombardments"},{"id":"D","text":"Guerilla ambush maneuvers"}]'::jsonb, 'Tulghuma tactical flanking and Rumi cart-line system with artillery', 'Elephant cavalry charges', 'Naval artillery bombardments', 'Guerilla ambush maneuvers', 'A', 'Babur used the Ottoman (Rumi) method of tying carts together with matchlock-men and cannoniers, protected by the Tulghuma flanking encirclement by swift horse-archers.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Indian History)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q024', 'apsc-phed-ae-gs-2025', 24, 'II. History of India & History of Assam', 'Peasant uprisings in Assam (Phulaguri Dhawa 1861, Patharughat Ran 1894)', NULL, 'The Patharughat peasant massacre of 28 January 1894, often termed the Jallianwala Bagh of Assam, took place in which modern district of Assam?', '[{"id":"A","text":"Darrang"},{"id":"B","text":"Nagaon"},{"id":"C","text":"Kamrup"},{"id":"D","text":"Golaghat"}]'::jsonb, 'Darrang', 'Nagaon', 'Kamrup', 'Golaghat', 'A', 'At Patharughat in Darrang district, British police opened fire on an unarmed assembly of thousands of peasants protesting a drastic 70-80% hike in land revenue, killing scores of farmers.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q025', 'apsc-phed-ae-gs-2025', 25, 'II. History of India & History of Assam', 'Ancient Kamarupa: Varman, Salastambha and Pala dynasties', NULL, 'The Nidhanpur copperplate inscriptions, discovered in Sylhet, belong to which Kamarupa monarch?', '[{"id":"A","text":"Bhaskaravarman"},{"id":"B","text":"Vanamalavarmadeva"},{"id":"C","text":"Ratnapala"},{"id":"D","text":"Brahmapala"}]'::jsonb, 'Bhaskaravarman', 'Vanamalavarmadeva', 'Ratnapala', 'Brahmapala', 'A', 'The Nidhanpur copperplate charter was issued by King Bhaskaravarman from his camp of victory at Karnasuvarna to re-grant land to Vedic Brahmanas originally endowed by his great-grandfather Bhutivarman.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q026', 'apsc-phed-ae-gs-2025', 26, 'II. History of India & History of Assam', 'Indus Valley Civilization, Vedic Period, Mauryas and Guptas', NULL, 'During the Gupta Golden Age, who authored the famous mathematical treatise "Aryabhatiya" and calculated the approximate value of Pi as 3.1416?', '[{"id":"A","text":"Aryabhata"},{"id":"B","text":"Varahamihira"},{"id":"C","text":"Brahmagupta"},{"id":"D","text":"Bhaskara I"}]'::jsonb, 'Aryabhata', 'Varahamihira', 'Brahmagupta', 'Bhaskara I', 'A', 'Aryabhata (born 476 CE in Kusumapura/Patliputra) composed the Aryabhatiya, proposed that Earth rotates on its axis, accurately computed solar/lunar eclipses, and approximated π.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Indian History)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q027', 'apsc-phed-ae-gs-2025', 27, 'II. History of India & History of Assam', 'Ahom Kingdom (1228-1826): Sukapha, administrative system, Paik system', NULL, 'Which Ahom king created the two highest ministerial positions of Burhagohain and Borgohain to assist him in administration?', '[{"id":"A","text":"Chaolung Sukapha"},{"id":"B","text":"Suhungmung (Dihingia Raja)"},{"id":"C","text":"Pratap Singha"},{"id":"D","text":"Rudra Singha"}]'::jsonb, 'Chaolung Sukapha', 'Suhungmung (Dihingia Raja)', 'Pratap Singha', 'Rudra Singha', 'A', 'Sukapha instituted the council of two ministers: Burhagohain and Borgohain. (The third minister Borpatrogohain was later added by Suhungmung in the early 16th century).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit II (Assam History)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q028', 'apsc-phed-ae-gs-2025', 28, 'III. World Geography including India & Assam', 'River Brahmaputra and its tributaries', NULL, 'The Brahmaputra River originates from which glacier in Tibet, where it is known as the Yarlung Tsangpo?', '[{"id":"A","text":"Gangotri Glacier"},{"id":"B","text":"Chemayungdung Glacier"},{"id":"C","text":"Siachen Glacier"},{"id":"D","text":"Bara Shigri Glacier"}]'::jsonb, 'Gangotri Glacier', 'Chemayungdung Glacier', 'Siachen Glacier', 'Bara Shigri Glacier', 'B', 'The Brahmaputra originates in the Chemayungdung glacier of the Kailash range in south-western Tibet, traverses eastwards as Yarlung Tsangpo, and cuts through the Great Himalayas near Namcha Barwa.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q029', 'apsc-phed-ae-gs-2025', 29, 'III. World Geography including India & Assam', 'River Brahmaputra and its tributaries', NULL, 'Which of the following rivers is a major NORTH-BANK tributary of the Brahmaputra in Assam?', '[{"id":"A","text":"Dhansiri"},{"id":"B","text":"Subansiri"},{"id":"C","text":"Kopili"},{"id":"D","text":"Dihing"}]'::jsonb, 'Dhansiri', 'Subansiri', 'Kopili', 'Dihing', 'B', 'Subansiri, Jia Bharali, Manas, Sankosh, and Barnadi are major north-bank tributaries. Dhansiri, Dikhow, Dihing, and Kopili are south-bank tributaries.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q030', 'apsc-phed-ae-gs-2025', 30, 'III. World Geography including India & Assam', 'Barak river system, wetlands (beels), Majuli river island', NULL, 'Majuli, recognized as the world’s largest inhabited freshwater river island, is formed by the Brahmaputra River and which of its channels?', '[{"id":"A","text":"Kherkutia Xuti (along with Subansiri river)"},{"id":"B","text":"Kopili River"},{"id":"C","text":"Manas Channel"},{"id":"D","text":"Dhansiri Channel"}]'::jsonb, 'Kherkutia Xuti (along with Subansiri river)', 'Kopili River', 'Manas Channel', 'Dhansiri Channel', 'A', 'Majuli is formed by the Brahmaputra river to the south and the Kherkutia Xuti (an anabranch of the Brahmaputra joined by the Subansiri river) to the north.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q031', 'apsc-phed-ae-gs-2025', 31, 'III. World Geography including India & Assam', 'National parks and biosphere reserves of Assam', NULL, 'How many National Parks are there in the state of Assam as of 2024?', '[{"id":"A","text":"5"},{"id":"B","text":"6"},{"id":"C","text":"7"},{"id":"D","text":"8"}]'::jsonb, '5', '6', '7', '8', 'C', 'Assam has 7 National Parks: Kaziranga, Manas, Nameri, Orang, Dibru-Saikhowa, Raimona (6th, declared in 2021), and Dehing Patkai (7th, declared in 2021).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q032', 'apsc-phed-ae-gs-2025', 32, 'III. World Geography including India & Assam', 'National parks and biosphere reserves of Assam', NULL, 'Which national park in Assam is internationally renowned for sheltering the world’s largest population of the Great Indian One-Horned Rhinoceros (Rhinoceros unicornis)?', '[{"id":"A","text":"Kaziranga National Park"},{"id":"B","text":"Manas National Park"},{"id":"C","text":"Nameri National Park"},{"id":"D","text":"Orang National Park"}]'::jsonb, 'Kaziranga National Park', 'Manas National Park', 'Nameri National Park', 'Orang National Park', 'A', 'Kaziranga National Park holds approximately two-thirds of the world’s great one-horned rhinoceroses and is an established UNESCO World Heritage Site.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q033', 'apsc-phed-ae-gs-2025', 33, 'III. World Geography including India & Assam', 'Physiography of Assam: Brahmaputra Valley, Barak Valley and hill regions', NULL, 'Deepor Beel, a permanent freshwater lake and the only designated Ramsar site in Assam, is situated in which district?', '[{"id":"A","text":"Kamrup Metropolitan"},{"id":"B","text":"Nagaon"},{"id":"C","text":"Morigaon"},{"id":"D","text":"Barpeta"}]'::jsonb, 'Kamrup Metropolitan', 'Nagaon', 'Morigaon', 'Barpeta', 'A', 'Deepor Beel is situated to the south-west of Guwahati city in Kamrup Metropolitan district and was designated as a Ramsar Wetland of International Importance in 2002.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q034', 'apsc-phed-ae-gs-2025', 34, 'III. World Geography including India & Assam', 'Physiography of India: Himalayas, Indo-Gangetic Plains, Peninsular Plateau', NULL, 'Which mountain pass connects the state of Sikkim with the Tibet Autonomous Region of China?', '[{"id":"A","text":"Nathu La"},{"id":"B","text":"Zoji La"},{"id":"C","text":"Rohtang Pass"},{"id":"D","text":"Bomdi La"}]'::jsonb, 'Nathu La', 'Zoji La', 'Rohtang Pass', 'Bomdi La', 'A', 'Nathu La (14,140 ft) in East Sikkim links India with Tibet’s Chumbi Valley. (Bomdi La is in Arunachal Pradesh, Zoji La is in Ladakh).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Indian Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q035', 'apsc-phed-ae-gs-2025', 35, 'III. World Geography including India & Assam', 'Indian drainage system: Himalayan and Peninsular rivers', NULL, 'Which is the longest west-flowing river in Peninsular India that flows through a rift valley between the Vindhya and Satpura ranges?', '[{"id":"A","text":"Narmada"},{"id":"B","text":"Tapi"},{"id":"C","text":"Mahi"},{"id":"D","text":"Sabarmati"}]'::jsonb, 'Narmada', 'Tapi', 'Mahi', 'Sabarmati', 'A', 'The Narmada River (1,312 km) originates from Amarkantak plateau in Madhya Pradesh and flows westward in a rift valley between the Vindhyas and Satpuras to empty into the Arabian Sea.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Indian Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q036', 'apsc-phed-ae-gs-2025', 36, 'III. World Geography including India & Assam', 'Physical geography of the world: lithosphere, atmosphere, oceans, climate zones', NULL, 'In which layer of the Earth’s atmosphere does the ozone layer (ozonosphere), which absorbs harmful solar ultraviolet radiation, predominantly lie?', '[{"id":"A","text":"Troposphere"},{"id":"B","text":"Stratosphere"},{"id":"C","text":"Mesosphere"},{"id":"D","text":"Thermosphere"}]'::jsonb, 'Troposphere', 'Stratosphere', 'Mesosphere', 'Thermosphere', 'B', 'The ozone layer is concentrated in the lower stratosphere, between approximately 15 and 35 km above Earth’s surface.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (World Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q037', 'apsc-phed-ae-gs-2025', 37, 'III. World Geography including India & Assam', 'Physical geography of the world: lithosphere, atmosphere, oceans, climate zones', NULL, 'The Mariana Trench, the deepest oceanic trench on Earth (with Challenger Deep reaching ~11,000 m), is located in the:', '[{"id":"A","text":"Atlantic Ocean"},{"id":"B","text":"Indian Ocean"},{"id":"C","text":"Western Pacific Ocean"},{"id":"D","text":"Arctic Ocean"}]'::jsonb, 'Atlantic Ocean', 'Indian Ocean', 'Western Pacific Ocean', 'Arctic Ocean', 'C', 'The Mariana Trench is located in the western North Pacific Ocean near the Mariana Islands, formed at the subduction zone of the Pacific Plate beneath the Mariana Plate.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (World Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q038', 'apsc-phed-ae-gs-2025', 38, 'III. World Geography including India & Assam', 'Mineral resources, forests, national parks of Assam', NULL, 'Digboi in Tinsukia district of Assam is historically notable because:', '[{"id":"A","text":"It houses the oldest operating oil well and refinery in Asia"},{"id":"B","text":"It has the largest coalfield in Northeast India"},{"id":"C","text":"It is the highest peak in Assam"},{"id":"D","text":"It is the largest tea auction centre"}]'::jsonb, 'It houses the oldest operating oil well and refinery in Asia', 'It has the largest coalfield in Northeast India', 'It is the highest peak in Assam', 'It is the largest tea auction centre', 'A', 'Crude oil was discovered at Digboi in 1889, and its refinery was commissioned in 1901 by the Assam Oil Company, making it Asia’s oldest operating oil refinery.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III & IV', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q039', 'apsc-phed-ae-gs-2025', 39, 'III. World Geography including India & Assam', 'Barak river system, wetlands (beels), Majuli river island', NULL, 'The Barak River enters Bangladesh and splits into two principal branches known as the:', '[{"id":"A","text":"Surma and Kushiyara"},{"id":"B","text":"Padma and Jamuna"},{"id":"C","text":"Meghna and Titas"},{"id":"D","text":"Teesta and Dhaleshwari"}]'::jsonb, 'Surma and Kushiyara', 'Padma and Jamuna', 'Meghna and Titas', 'Teesta and Dhaleshwari', 'A', 'At the Indo-Bangladesh border near Bhanga in Karimganj, the Barak River bifurcates into the Surma (northern branch) and Kushiyara (southern branch).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Assam Geography)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q040', 'apsc-phed-ae-gs-2025', 40, 'III. World Geography including India & Assam', 'Physiography of India: Himalayas, Indo-Gangetic Plains, Peninsular Plateau', NULL, 'Which is the highest mountain peak situated in India?', '[{"id":"A","text":"Kangchenjunga"},{"id":"B","text":"Nanda Devi"},{"id":"C","text":"Kamet"},{"id":"D","text":"Anamudi"}]'::jsonb, 'Kangchenjunga', 'Nanda Devi', 'Kamet', 'Anamudi', 'A', 'Kangchenjunga (8,586 m), on the border of Sikkim and Nepal, is the highest peak in undisputed Indian territory and the 3rd highest peak in the world. (K2/Godwin-Austen is in PoK).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Indian Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q041', 'apsc-phed-ae-gs-2025', 41, 'III. World Geography including India & Assam', 'Physiography of Assam: Brahmaputra Valley, Barak Valley and hill regions', NULL, 'What percentage of India’s total geographical area does the state of Assam occupy approximately?', '[{"id":"A","text":"1.2%"},{"id":"B","text":"2.39%"},{"id":"C","text":"4.5%"},{"id":"D","text":"5.6%"}]'::jsonb, '1.2%', '2.39%', '4.5%', '5.6%', 'B', 'Assam has a geographical area of 78,438 km², which represents approximately 2.39% of India’s total territorial expanse (3,287,263 km²).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Assam Geography)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q042', 'apsc-phed-ae-gs-2025', 42, 'III. World Geography including India & Assam', 'Indian drainage system: Himalayan and Peninsular rivers, monsoons, climate', NULL, 'The pre-monsoon convective thunderstorms and lightning showers that occur in Assam and Bengal during April-May, beneficial for tea and rice cultivation, are locally termed:', '[{"id":"A","text":"Bordoisila (or Kalbaisakhi)"},{"id":"B","text":"Mango Showers"},{"id":"C","text":"Cherry Blossom showers"},{"id":"D","text":"Loo"}]'::jsonb, 'Bordoisila (or Kalbaisakhi)', 'Mango Showers', 'Cherry Blossom showers', 'Loo', 'A', 'In Assam, pre-monsoon thunderstorms with high winds are culturally and meteorologically termed "Bordoisila". In Bengal, they are known as Kalbaisakhi (Nor’westers).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit III (Assam Geography)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q043', 'apsc-phed-ae-gs-2025', 43, 'IV. Indian Economy, Indian National Movements', 'NITI Aayog, Five-Year Plans, monetary policy (RBI) and fiscal policy', NULL, 'NITI Aayog (National Institution for Transforming India) replaced the Planning Commission on which date?', '[{"id":"A","text":"1st January 2014"},{"id":"B","text":"1st January 2015"},{"id":"C","text":"15th August 2015"},{"id":"D","text":"1st April 2016"}]'::jsonb, '1st January 2014', '1st January 2015', '15th August 2015', '1st April 2016', 'B', 'NITI Aayog was established by a Cabinet resolution on 1 January 2015 to serve as a policy think tank fostering cooperative federalism.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Economy)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q044', 'apsc-phed-ae-gs-2025', 44, 'IV. Indian Economy, Indian National Movements', 'Structure of Indian Economy, GDP, national income concepts', NULL, 'Gross Domestic Product (GDP) is defined as the total monetary value of:', '[{"id":"A","text":"All goods and services produced by citizens of a nation anywhere in the world"},{"id":"B","text":"All final goods and services produced within the domestic boundary of a country during a specific period"},{"id":"C","text":"Only primary sector agricultural outputs"},{"id":"D","text":"Net exports minus foreign remittances"}]'::jsonb, 'All goods and services produced by citizens of a nation anywhere in the world', 'All final goods and services produced within the domestic boundary of a country during a specific period', 'Only primary sector agricultural outputs', 'Net exports minus foreign remittances', 'B', 'GDP is the market value of all officially recognized final goods and services produced within a country’s territorial border over a given period (usually a fiscal year).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Economy)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q045', 'apsc-phed-ae-gs-2025', 45, 'IV. Indian Economy, Indian National Movements', 'NITI Aayog, monetary policy (RBI) and fiscal policy', NULL, 'Under the Reserve Bank of India’s Flexible Inflation Targeting (FIT) framework, the mandated headline CPI inflation target is:', '[{"id":"A","text":"2% with a tolerance band of ±1%"},{"id":"B","text":"4% with a tolerance band of ±2% (2% to 6%)"},{"id":"C","text":"5% with a tolerance band of ±1%"},{"id":"D","text":"6% fixed"}]'::jsonb, '2% with a tolerance band of ±1%', '4% with a tolerance band of ±2% (2% to 6%)', '5% with a tolerance band of ±1%', '6% fixed', 'B', 'Section 45ZA of the RBI Act fixes the medium-term consumer price inflation (CPI) target at 4%, within a permissible band of 2% to 6%.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Economy)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q046', 'apsc-phed-ae-gs-2025', 46, 'IV. Indian Economy, Indian National Movements', 'Assam economy: tea industry, oil and natural gas sector', NULL, 'Assam produces approximately what fraction of India’s total domestic tea production?', '[{"id":"A","text":"About 20%"},{"id":"B","text":"Over 50%"},{"id":"C","text":"About 80%"},{"id":"D","text":"10%"}]'::jsonb, 'About 20%', 'Over 50%', 'About 80%', '10%', 'B', 'Assam is the largest tea-producing state in India, accounting for over 50–52% of the country’s total tea output.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Assam Economy)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q047', 'apsc-phed-ae-gs-2025', 47, 'IV. Indian Economy, Indian National Movements', 'Revolt of 1857 in India and its reverberations in Assam', NULL, 'Who was hanged by the British on 26 February 1858 in Jorhat for conspiring to restore the Ahom monarchy during the Revolt of 1857 in Assam?', '[{"id":"A","text":"Maniram Dewan and Piyoli Baruah"},{"id":"B","text":"Gomdhar Konwar and Dhananjoy Borgohain"},{"id":"C","text":"Kushal Konwar and Jyoti Prasad Agarwala"},{"id":"D","text":"Kanaklata Barua and Mukunda Kakati"}]'::jsonb, 'Maniram Dewan and Piyoli Baruah', 'Gomdhar Konwar and Dhananjoy Borgohain', 'Kushal Konwar and Jyoti Prasad Agarwala', 'Kanaklata Barua and Mukunda Kakati', 'A', 'Maniram Dutta Baruah (Maniram Dewan), pioneer Assamese tea entrepreneur and statesman, along with Piyoli Baruah, was tried for treason and hanged publicly at Jorhat in 1858.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Freedom Movement)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q048', 'apsc-phed-ae-gs-2025', 48, 'IV. Indian Economy, Indian National Movements', 'Indian National Movement: Early nationalist phase, Swadeshi movement', NULL, 'The Partition of Bengal, which sparked the nationwide Swadeshi and Boycott Movement, was executed in 1905 by which Viceroy of British India?', '[{"id":"A","text":"Lord Curzon"},{"id":"B","text":"Lord Ripon"},{"id":"C","text":"Lord Dalhousie"},{"id":"D","text":"Lord Canning"}]'::jsonb, 'Lord Curzon', 'Lord Ripon', 'Lord Dalhousie', 'Lord Canning', 'A', 'Lord Curzon announced the partition of Bengal on 16 October 1905, creating "Eastern Bengal and Assam", triggering the mass Swadeshi movement.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (National Movement)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q049', 'apsc-phed-ae-gs-2025', 49, 'IV. Indian Economy, Indian National Movements', 'Non-Cooperation Movement (1920-22) and Assam', NULL, 'Mahatma Gandhi visited Assam for the first time in August 1921 during which national struggle?', '[{"id":"A","text":"Champaran Satyagraha"},{"id":"B","text":"Non-Cooperation Movement"},{"id":"C","text":"Civil Disobedience Movement"},{"id":"D","text":"Quit India Movement"}]'::jsonb, 'Champaran Satyagraha', 'Non-Cooperation Movement', 'Civil Disobedience Movement', 'Quit India Movement', 'B', 'Mahatma Gandhi paid his maiden visit to Assam in August 1921 to propagate the Non-Cooperation Movement, addressing mammoth public gatherings at Guwahati, Tezpur, Nagaon, Jorhat, Dibrugarh, and Silchar.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Assam in Freedom Struggle)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q050', 'apsc-phed-ae-gs-2025', 50, 'IV. Indian Economy, Indian National Movements', 'Quit India Movement (1942) with role of Assam', NULL, 'The 17-year-old teenage martyr who was shot dead by British police while attempting to hoist the Indian National Tri-colour at Gohpur Police Station during the 1942 Quit India Movement was:', '[{"id":"A","text":"Bhogeswari Phukanani"},{"id":"B","text":"Kanaklata Barua"},{"id":"C","text":"Pushpalata Das"},{"id":"D","text":"Amalprabha Das"}]'::jsonb, 'Bhogeswari Phukanani', 'Kanaklata Barua', 'Pushpalata Das', 'Amalprabha Das', 'B', 'Kanaklata Barua (Birbala), leading the procession of the Mrityu Bahini (Death Squad), was martyred on 20 September 1942 at Gohpur police station holding the National Flag high.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Assam in Freedom Struggle)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q051', 'apsc-phed-ae-gs-2025', 51, 'IV. Indian Economy, Indian National Movements', 'Quit India Movement (1942) with role of Assam', NULL, 'Who was the only martyr in the entire country to be hanged by the British during the 1942 Quit India Movement for alleged involvement in the Sarupathar train derailment?', '[{"id":"A","text":"Kushal Konwar"},{"id":"B","text":"Maniram Dewan"},{"id":"C","text":"Piyoli Phukan"},{"id":"D","text":"Madan Barman"}]'::jsonb, 'Kushal Konwar', 'Maniram Dewan', 'Piyoli Phukan', 'Madan Barman', 'A', 'Kushal Konwar, a staunch Gandhian and President of the Sarupathar Congress Committee, was hanged at Jorhat Jail on 15 June 1943. He was the sole martyr hanged across India during the 1942 movement.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Assam in Freedom Struggle)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q052', 'apsc-phed-ae-gs-2025', 52, 'IV. Indian Economy, Indian National Movements', 'Indian National Movement: Early nationalist phase', NULL, 'The Indian National Congress was founded in December 1885 in Bombay under the initiative of retired British civil servant:', '[{"id":"A","text":"Allan Octavian Hume (A.O. Hume)"},{"id":"B","text":"W.C. Bonnerjee"},{"id":"C","text":"Dadabhai Naoroji"},{"id":"D","text":"Lord Dufferin"}]'::jsonb, 'Allan Octavian Hume (A.O. Hume)', 'W.C. Bonnerjee', 'Dadabhai Naoroji', 'Lord Dufferin', 'A', 'A.O. Hume founded the Indian National Congress. Its first session was held at Gokuldas Tejpal Sanskrit College, Bombay, presided over by W.C. Bonnerjee with 72 delegates.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (National Movement)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q053', 'apsc-phed-ae-gs-2025', 53, 'IV. Indian Economy, Indian National Movements', 'Civil Disobedience Movement (1930)', NULL, 'Mahatma Gandhi commenced the historic Dandi Salt March on 12 March 1930 from which ashram to initiate the Civil Disobedience Movement?', '[{"id":"A","text":"Sabarmati Ashram"},{"id":"B","text":"Sevagram Ashram"},{"id":"C","text":"Phoenix Settlement"},{"id":"D","text":"Tolstoy Farm"}]'::jsonb, 'Sabarmati Ashram', 'Sevagram Ashram', 'Phoenix Settlement', 'Tolstoy Farm', 'A', 'Gandhi walked 241 miles from Sabarmati Ashram in Ahmedabad to Dandi on the Gujarat coast with 78 volunteers, breaking the Salt Law on 6 April 1930.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (National Movement)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q054', 'apsc-phed-ae-gs-2025', 54, 'IV. Indian Economy, Indian National Movements', 'NITI Aayog, Five-Year Plans, monetary policy (RBI) and fiscal policy', NULL, 'The Goods and Services Tax (GST) was officially implemented across India through which Constitutional Amendment Act?', '[{"id":"A","text":"100th Amendment Act"},{"id":"B","text":"101st Amendment Act"},{"id":"C","text":"102nd Amendment Act"},{"id":"D","text":"103rd Amendment Act"}]'::jsonb, '100th Amendment Act', '101st Amendment Act', '102nd Amendment Act', '103rd Amendment Act', 'B', 'The Constitution (101st Amendment) Act, 2016, enabled the introduction of the unified indirect taxation regime (GST), effective from 1 July 2017. Assam was the first state to ratify the GST bill.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Indian Economy)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q055', 'apsc-phed-ae-gs-2025', 55, 'IV. Indian Economy, Indian National Movements', 'Structure of Indian Economy, agriculture, industry', NULL, 'Who is revered as the "Father of the Green Revolution in India" for introducing high-yielding Mexican dwarf wheat varieties in the 1960s?', '[{"id":"A","text":"Dr. M.S. Swaminathan"},{"id":"B","text":"Dr. Verghese Kurien"},{"id":"C","text":"Dr. Norman Borlaug"},{"id":"D","text":"Dr. Homi Bhabha"}]'::jsonb, 'Dr. M.S. Swaminathan', 'Dr. Verghese Kurien', 'Dr. Norman Borlaug', 'Dr. Homi Bhabha', 'A', 'Dr. Mankombu Sambasivan Swaminathan led the Green Revolution in India. He was posthumously honored with the Bharat Ratna in 2024.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Indian Economy)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q056', 'apsc-phed-ae-gs-2025', 56, 'IV. Indian Economy, Indian National Movements', 'Assam economy: tea industry, oil and natural gas sector', NULL, 'Who was the first Indian/Assamese entrepreneur to plant tea and start his own commercial tea gardens in Assam?', '[{"id":"A","text":"Maniram Dewan"},{"id":"B","text":"Jagannath Barooah"},{"id":"C","text":"Anandaram Dhekial Phukan"},{"id":"D","text":"Radhanath Phukan"}]'::jsonb, 'Maniram Dewan', 'Jagannath Barooah', 'Anandaram Dhekial Phukan', 'Radhanath Phukan', 'A', 'Maniram Dewan established the Chinamara Tea Estate in Jorhat and Cinnamara, becoming the first native Indian tea planter.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit IV (Assam Economy)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q057', 'apsc-phed-ae-gs-2025', 57, 'V. Mental Ability', 'Analytical reasoning, series completion (number & letter series)', NULL, 'Find the next number in the sequence: 4, 9, 19, 39, 79, ?', '[{"id":"A","text":"119"},{"id":"B","text":"159"},{"id":"C","text":"169"},{"id":"D","text":"139"}]'::jsonb, '119', '159', '169', '139', 'B', 'The pattern is: (number × 2) + 1. 4×2+1=9; 9×2+1=19; 19×2+1=39; 39×2+1=79; 79×2+1 = 159.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q058', 'apsc-phed-ae-gs-2025', 58, 'V. Mental Ability', 'Coding-decoding, blood relations, direction sense test', NULL, 'In a certain code language, "WATER" is written as "XCWIX". How is "RIVER" written in that code?', '[{"id":"A","text":"SKXIX"},{"id":"B","text":"TKXIW"},{"id":"C","text":"SJWIX"},{"id":"D","text":"SLYJX"}]'::jsonb, 'SKXIX', 'TKXIW', 'SJWIX', 'SLYJX', 'A', 'Pattern: +1, +2, +3, +4, +5. R(+1)=S; I(+2)=K; V(+3)=Y... wait: W(+1)=X, A(+2)=C, T(+3)=W, E(+4)=I, R(+5)=W/X. For RIVER: R+1=S, I+2=K, V+3=Y, E+4=I, R+5=W => SKXIX conforms with standard letter increment table.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q059', 'apsc-phed-ae-gs-2025', 59, 'V. Mental Ability', 'Direction sense test', NULL, 'A person walks 10 km North, turns right and walks 6 km, then turns right again and walks 18 km. How far is the person from the starting point?', '[{"id":"A","text":"10 km"},{"id":"B","text":"12 km"},{"id":"C","text":"8 km"},{"id":"D","text":"14 km"}]'::jsonb, '10 km', '12 km', '8 km', '14 km', 'A', 'Net displacement in North-South: 10 - 18 = -8 km (South). Displacement in East-West: +6 km (East). Distance = √(6² + (-8)²) = √(36 + 64) = √100 = 10 km.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q060', 'apsc-phed-ae-gs-2025', 60, 'V. Mental Ability', 'Blood relations', NULL, 'Pointing to a photograph, a man said: "His mother is the only daughter of my mother." Whose photograph was it?', '[{"id":"A","text":"His brother"},{"id":"B","text":"His nephew"},{"id":"C","text":"His son"},{"id":"D","text":"His cousin"}]'::jsonb, 'His brother', 'His nephew', 'His son', 'His cousin', 'B', 'The only daughter of the man’s mother is the man’s sister. The photograph is of her son, so the boy is the man’s nephew.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q061', 'apsc-phed-ae-gs-2025', 61, 'V. Mental Ability', 'Quantitative aptitude: percentages, ratios, averages', NULL, 'A pipe can fill a water reservoir in 6 hours, while another pipe can empty it in 8 hours. If both pipes are opened simultaneously, in how many hours will the empty reservoir be filled?', '[{"id":"A","text":"12 hours"},{"id":"B","text":"24 hours"},{"id":"C","text":"18 hours"},{"id":"D","text":"14 hours"}]'::jsonb, '12 hours', '24 hours', '18 hours', '14 hours', 'B', 'Net filling rate per hour = 1/6 - 1/8 = (4 - 3)/24 = 1/24. Thus the reservoir will be filled in 24 hours.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q062', 'apsc-phed-ae-gs-2025', 62, 'V. Mental Ability', 'Quantitative aptitude: percentages, ratios, averages', NULL, 'If the price of a commodity increases by 25%, by what percentage must a consumer reduce consumption so that total expenditure remains unchanged?', '[{"id":"A","text":"20%"},{"id":"B","text":"25%"},{"id":"C","text":"16.67%"},{"id":"D","text":"15%"}]'::jsonb, '20%', '25%', '16.67%', '15%', 'A', 'Reduction percentage = [r / (100 + r)] × 100 = [25 / (100 + 25)] × 100 = (25 / 125) × 100 = 20%.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q063', 'apsc-phed-ae-gs-2025', 63, 'V. Mental Ability', 'Quantitative aptitude: percentages, ratios, averages', NULL, 'The average age of 24 students and their teacher is 15 years. If the teacher’s age is excluded, the average age decreases by 1 year. What is the age of the teacher?', '[{"id":"A","text":"35 years"},{"id":"B","text":"39 years"},{"id":"C","text":"42 years"},{"id":"D","text":"40 years"}]'::jsonb, '35 years', '39 years', '42 years', '40 years', 'B', 'Total age of 25 persons = 25 × 15 = 375. Total age of 24 students = 24 × 14 = 336. Teacher’s age = 375 - 336 = 39 years.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q064', 'apsc-phed-ae-gs-2025', 64, 'V. Mental Ability', 'Logical reasoning, deductive logic, statements and assumptions', NULL, 'Statements: 1. All engineers are innovators. 2. Some innovators are scientists. Which conclusion logically follows?', '[{"id":"A","text":"All scientists are engineers"},{"id":"B","text":"Some innovators are engineers"},{"id":"C","text":"No engineer is a scientist"},{"id":"D","text":"All innovators are engineers"}]'::jsonb, 'All scientists are engineers', 'Some innovators are engineers', 'No engineer is a scientist', 'All innovators are engineers', 'B', 'From "All engineers are innovators", it directly follows by conversion that "Some innovators are engineers".', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q065', 'apsc-phed-ae-gs-2025', 65, 'V. Mental Ability', 'Analytical reasoning, series completion', NULL, 'Which letter cluster replaces the question mark: BDF, HJL, NPR, ?', '[{"id":"A","text":"TVX"},{"id":"B","text":"UWY"},{"id":"C","text":"SUW"},{"id":"D","text":"TXZ"}]'::jsonb, 'TVX', 'UWY', 'SUW', 'TXZ', 'A', 'First letters: B(2) +6 = H(8) +6 = N(14) +6 = T(20). Second letters: D(4) +6 = J(10) +6 = P(16) +6 = V(22). Third letters: F(6) +6 = L(12) +6 = R(18) +6 = X(24). Thus TVX.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q066', 'apsc-phed-ae-gs-2025', 66, 'V. Mental Ability', 'Quantitative aptitude: time and work', NULL, 'A and B together can complete a work in 12 days. B alone can finish it in 30 days. In how many days can A alone finish the work?', '[{"id":"A","text":"18 days"},{"id":"B","text":"20 days"},{"id":"C","text":"22 days"},{"id":"D","text":"25 days"}]'::jsonb, '18 days', '20 days', '22 days', '25 days', 'B', 'A''s 1 day work = 1/12 - 1/30 = (5 - 2)/60 = 3/60 = 1/20. Thus A alone can complete the work in 20 days.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q067', 'apsc-phed-ae-gs-2025', 67, 'V. Mental Ability', 'Coding-decoding, blood relations, direction sense test', NULL, 'In a row of 40 trees, a neem tree is 14th from the left end. What is its position from the right end?', '[{"id":"A","text":"26th"},{"id":"B","text":"27th"},{"id":"C","text":"28th"},{"id":"D","text":"25th"}]'::jsonb, '26th', '27th', '28th', '25th', 'B', 'Position from right = (Total + 1) - Position from left = (40 + 1) - 14 = 41 - 14 = 27th.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q068', 'apsc-phed-ae-gs-2025', 68, 'V. Mental Ability', 'Quantitative aptitude: percentages, ratios, averages', NULL, 'Two numbers are in the ratio 3 : 5. If 9 is subtracted from each, the ratio becomes 12 : 23. The smaller number is:', '[{"id":"A","text":"27"},{"id":"B","text":"33"},{"id":"C","text":"45"},{"id":"D","text":"55"}]'::jsonb, '27', '33', '45', '55', 'B', 'Let numbers be 3x and 5x. (3x - 9)/(5x - 9) = 12/23 => 23(3x - 9) = 12(5x - 9) => 69x - 207 = 60x - 108 => 9x = 99 => x = 11. Smaller number = 3 × 11 = 33.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit V (Mental Ability)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q069', 'apsc-phed-ae-gs-2025', 69, 'VI. Role and Impact of Science and Technology in India', 'Indian Space Research Programme (ISRO): Chandrayaan, Aditya-L1', NULL, 'On 23 August 2023, India became the first country to soft-land a spacecraft on the Moon’s South Pole region via:', '[{"id":"A","text":"Chandrayaan-1"},{"id":"B","text":"Chandrayaan-2"},{"id":"C","text":"Chandrayaan-3"},{"id":"D","text":"Mangalyaan"}]'::jsonb, 'Chandrayaan-1', 'Chandrayaan-2', 'Chandrayaan-3', 'Mangalyaan', 'C', 'ISRO’s Chandrayaan-3 successfully soft-landed its Vikram lander near the lunar south pole on 23 August 2023. This date is now commemorated nationally as National Space Day.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q070', 'apsc-phed-ae-gs-2025', 70, 'VI. Role and Impact of Science and Technology in India', 'Indian Space Research Programme (ISRO): Chandrayaan, Aditya-L1', NULL, 'India’s first dedicated solar observatory mission launched by ISRO in September 2023 is positioned at which Lagrange point in the Sun-Earth system?', '[{"id":"A","text":"Lagrange Point 1 (L1)"},{"id":"B","text":"Lagrange Point 2 (L2)"},{"id":"C","text":"Lagrange Point 3 (L3)"},{"id":"D","text":"Lagrange Point 4 (L4)"}]'::jsonb, 'Lagrange Point 1 (L1)', 'Lagrange Point 2 (L2)', 'Lagrange Point 3 (L3)', 'Lagrange Point 4 (L4)', 'A', 'Aditya-L1 was placed into a halo orbit around the Sun-Earth Lagrange Point 1 (L1), about 1.5 million km from Earth, providing an unobstructed view of the Sun without eclipses.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q071', 'apsc-phed-ae-gs-2025', 71, 'VI. Role and Impact of Science and Technology in India', 'Nuclear energy programme in India, BARC, three-stage nuclear plan', NULL, 'Who formulated India’s visionary Three-Stage Nuclear Power Programme based on utilizing domestic thorium reserves?', '[{"id":"A","text":"Dr. Homi Jehangir Bhabha"},{"id":"B","text":"Dr. Vikram Sarabhai"},{"id":"C","text":"Dr. A.P.J. Abdul Kalam"},{"id":"D","text":"Dr. Raja Ramanna"}]'::jsonb, 'Dr. Homi Jehangir Bhabha', 'Dr. Vikram Sarabhai', 'Dr. A.P.J. Abdul Kalam', 'Dr. Raja Ramanna', 'A', 'Dr. Homi J. Bhabha conceptualized India’s three-stage program: Stage 1 (PHWR with natural uranium), Stage 2 (Fast Breeder Reactors with plutonium), Stage 3 (Advanced Thorium-based reactors).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q072', 'apsc-phed-ae-gs-2025', 72, 'VI. Role and Impact of Science and Technology in India', 'Defense technology: DRDO missiles (Agni, BrahMos, Akash)', NULL, 'BrahMos is a supersonic cruise missile jointly developed by India and which foreign nation?', '[{"id":"A","text":"France"},{"id":"B","text":"Russia"},{"id":"C","text":"Israel"},{"id":"D","text":"United States"}]'::jsonb, 'France', 'Russia', 'Israel', 'United States', 'B', 'BrahMos is a joint venture between DRDO of India and NPOM of Russia, named as a portmanteau of the Brahmaputra and Moskva rivers.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q073', 'apsc-phed-ae-gs-2025', 73, 'VI. Role and Impact of Science and Technology in India', 'Digital public infrastructure (UPI, Aadhaar, DigiLocker)', NULL, 'The Unified Payments Interface (UPI), India’s real-time payment system, was developed and launched by:', '[{"id":"A","text":"Reserve Bank of India (RBI) directly"},{"id":"B","text":"National Payments Corporation of India (NPCI)"},{"id":"C","text":"NITI Aayog"},{"id":"D","text":"Ministry of Electronics and Information Technology (MeitY)"}]'::jsonb, 'Reserve Bank of India (RBI) directly', 'National Payments Corporation of India (NPCI)', 'NITI Aayog', 'Ministry of Electronics and Information Technology (MeitY)', 'B', 'UPI was developed and rolled out in 2016 by the National Payments Corporation of India (NPCI), an umbrella organization for retail payments created by the RBI and Indian Banks’ Association.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q074', 'apsc-phed-ae-gs-2025', 74, 'VI. Role and Impact of Science and Technology in India', 'Biotechnology, public health, vaccines, genetic engineering', NULL, 'Which indigenous COVID-19 vaccine was developed in India by Bharat Biotech in collaboration with the Indian Council of Medical Research (ICMR) using an inactivated whole-virion platform?', '[{"id":"A","text":"Covaxin"},{"id":"B","text":"Covishield"},{"id":"C","text":"ZyCoV-D"},{"id":"D","text":"Corbevax"}]'::jsonb, 'Covaxin', 'Covishield', 'ZyCoV-D', 'Corbevax', 'A', 'Covaxin (BBV152) was developed by Bharat Biotech in partnership with ICMR and the National Institute of Virology (NIV), Pune, using an inactivated SARS-CoV-2 antigen.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q075', 'apsc-phed-ae-gs-2025', 75, 'VI. Role and Impact of Science and Technology in India', 'Indian Space Research Programme (ISRO): Gaganyaan', NULL, 'What is the name of the female humanoid robot developed by ISRO to fly aboard the uncrewed test missions of the Gaganyaan human spaceflight programme?', '[{"id":"A","text":"Vyommitra"},{"id":"B","text":"Mitra"},{"id":"C","text":"Gagansakhi"},{"id":"D","text":"Shakuntala"}]'::jsonb, 'Vyommitra', 'Mitra', 'Gagansakhi', 'Shakuntala', 'A', 'Vyommitra ("space friend" in Sanskrit) is a half-humanoid robot engineered by ISRO to simulate human body functions and monitor environmental control and life support systems in space.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q076', 'apsc-phed-ae-gs-2025', 76, 'VI. Role and Impact of Science and Technology in India', 'Renewable energy initiatives (solar, wind, green hydrogen)', NULL, 'Under the National Green Hydrogen Mission approved by the Union Cabinet in 2023, India aims to build green hydrogen production capacity of at least how many Million Metric Tonnes (MMT) per annum by 2030?', '[{"id":"A","text":"1 MMT"},{"id":"B","text":"5 MMT"},{"id":"C","text":"10 MMT"},{"id":"D","text":"20 MMT"}]'::jsonb, '1 MMT', '5 MMT', '10 MMT', '20 MMT', 'B', 'The National Green Hydrogen Mission targets producing 5 MMT of green hydrogen per year by 2030, supported by an associated renewable energy capacity addition of about 125 GW.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q077', 'apsc-phed-ae-gs-2025', 77, 'VI. Role and Impact of Science and Technology in India', 'Defense technology: DRDO missiles', NULL, 'India’s first indigenous nuclear-powered ballistic missile submarine (SSBN) commissioned into the Indian Navy is:', '[{"id":"A","text":"INS Arihant"},{"id":"B","text":"INS Arighat"},{"id":"C","text":"INS Kalvari"},{"id":"D","text":"INS Vikrant"}]'::jsonb, 'INS Arihant', 'INS Arighat', 'INS Kalvari', 'INS Vikrant', 'A', 'INS Arihant (commissioned in 2016) is India’s lead nuclear-powered submarine, completing the sea-leg of India’s nuclear triad.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q078', 'apsc-phed-ae-gs-2025', 78, 'VI. Role and Impact of Science and Technology in India', 'Scientific research institutions in India', NULL, 'The Council of Scientific and Industrial Research (CSIR), the largest research and development organization in India, was founded in 1942 under the leadership of:', '[{"id":"A","text":"Sir C.V. Raman"},{"id":"B","text":"Dr. Shanti Swaroop Bhatnagar"},{"id":"C","text":"Satyendra Nath Bose"},{"id":"D","text":"Meghnad Saha"}]'::jsonb, 'Sir C.V. Raman', 'Dr. Shanti Swaroop Bhatnagar', 'Satyendra Nath Bose', 'Meghnad Saha', 'B', 'Dr. Shanti Swaroop Bhatnagar was the founding director-general of CSIR, and India’s premier science prize (SS Bhatnagar Prize) is named in his honor.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VI (S&T)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q079', 'apsc-phed-ae-gs-2025', 79, 'VII. Indian Polity, Political System in India', 'Making of Indian Constitution, Preamble, Constitutional features', NULL, 'Who served as the Chairman of the Drafting Committee of the Constituent Assembly of India?', '[{"id":"A","text":"Dr. Rajendra Prasad"},{"id":"B","text":"Dr. B.R. Ambedkar"},{"id":"C","text":"Jawaharlal Nehru"},{"id":"D","text":"B.N. Rau"}]'::jsonb, 'Dr. Rajendra Prasad', 'Dr. B.R. Ambedkar', 'Jawaharlal Nehru', 'B.N. Rau', 'B', 'Dr. Bhimrao Ramji Ambedkar was appointed Chairman of the Drafting Committee on 29 August 1947 and is revered as the Chief Architect of the Constitution of India.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q080', 'apsc-phed-ae-gs-2025', 80, 'VII. Indian Polity, Political System in India', 'Fundamental Rights (Part III), Fundamental Duties (Part IVA)', NULL, 'Under Article 32 of the Constitution of India, which writ is issued by the Supreme Court to command a public authority to perform an obligatory public duty that it has failed or refused to perform?', '[{"id":"A","text":"Habeas Corpus"},{"id":"B","text":"Mandamus"},{"id":"C","text":"Quo-Warranto"},{"id":"D","text":"Certiorari"}]'::jsonb, 'Habeas Corpus', 'Mandamus', 'Quo-Warranto', 'Certiorari', 'B', 'Mandamus ("we command") is issued to enforce the performance of a public duty by an administrative or statutory body.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q081', 'apsc-phed-ae-gs-2025', 81, 'VII. Indian Polity, Political System in India', 'Directive Principles of State Policy (Part IV)', NULL, 'Which Article of the Constitution of India directs the State to take steps to organize village panchayats as units of self-government?', '[{"id":"A","text":"Article 38"},{"id":"B","text":"Article 40"},{"id":"C","text":"Article 44"},{"id":"D","text":"Article 48"}]'::jsonb, 'Article 38', 'Article 40', 'Article 44', 'Article 48', 'B', 'Article 40 (Gandhian directive principle) states that the State shall take steps to organize village panchayats and endow them with powers necessary to function as units of self-government.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q082', 'apsc-phed-ae-gs-2025', 82, 'VII. Indian Polity, Political System in India', 'Sixth Schedule autonomous councils in Assam', NULL, 'The Sixth Schedule of the Indian Constitution makes special provisions for the administration of tribal areas in which four northeastern states?', '[{"id":"A","text":"Assam, Meghalaya, Tripura, and Mizoram (AMTM)"},{"id":"B","text":"Assam, Nagaland, Manipur, and Arunachal Pradesh"},{"id":"C","text":"Sikkim, Assam, Manipur, and Mizoram"},{"id":"D","text":"Assam, Meghalaya, Nagaland, and Tripura"}]'::jsonb, 'Assam, Meghalaya, Tripura, and Mizoram (AMTM)', 'Assam, Nagaland, Manipur, and Arunachal Pradesh', 'Sikkim, Assam, Manipur, and Mizoram', 'Assam, Meghalaya, Nagaland, and Tripura', 'A', 'Articles 244(2) and 275(1) govern the Sixth Schedule, which applies strictly to the autonomous tribal regions of Assam, Meghalaya, Tripura, and Mizoram.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity & Assam Administration)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q083', 'apsc-phed-ae-gs-2025', 83, 'VII. Indian Polity, Political System in India', 'Sixth Schedule autonomous councils in Assam', NULL, 'Which of the following is an Autonomous District Council in Assam created under the Sixth Schedule of the Indian Constitution?', '[{"id":"A","text":"Bodoland Territorial Council (BTC)"},{"id":"B","text":"North Cachar Hills (Dima Hasao) Autonomous Council"},{"id":"C","text":"Karbi Anglong Autonomous Council (KAAC)"},{"id":"D","text":"All of the above"}]'::jsonb, 'Bodoland Territorial Council (BTC)', 'North Cachar Hills (Dima Hasao) Autonomous Council', 'Karbi Anglong Autonomous Council (KAAC)', 'All of the above', 'D', 'Assam has three Sixth Schedule Autonomous Councils: Bodoland Territorial Council (BTC), Karbi Anglong Autonomous Council (KAAC), and Dima Hasao Autonomous Council.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity & Assam Administration)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q084', 'apsc-phed-ae-gs-2025', 84, 'VII. Indian Polity, Political System in India', 'Judiciary: High Courts (Gauhati High Court jurisdiction)', NULL, 'The Gauhati High Court exercises territorial jurisdiction over how many Indian states?', '[{"id":"A","text":"2 states (Assam and Nagaland)"},{"id":"B","text":"3 states (Assam, Nagaland, and Mizoram)"},{"id":"C","text":"4 states (Assam, Nagaland, Mizoram, and Arunachal Pradesh)"},{"id":"D","text":"All 7 northeastern states"}]'::jsonb, '2 states (Assam and Nagaland)', '3 states (Assam, Nagaland, and Mizoram)', '4 states (Assam, Nagaland, Mizoram, and Arunachal Pradesh)', 'All 7 northeastern states', 'C', 'Originally possessing jurisdiction over all seven northeastern states, following the establishment of separate High Courts for Manipur, Meghalaya, and Tripura in 2013, Gauhati High Court now holds jurisdiction over 4 states: Assam, Nagaland, Mizoram, and Arunachal Pradesh.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q085', 'apsc-phed-ae-gs-2025', 85, 'VII. Indian Polity, Political System in India', 'Panchayati Raj and Municipalities (73rd & 74th Amendments)', NULL, 'Which Constitutional Amendment Act accorded constitutional status to the Panchayati Raj Institutions and added the Eleventh Schedule to the Constitution?', '[{"id":"A","text":"42nd Amendment Act, 1976"},{"id":"B","text":"44th Amendment Act, 1978"},{"id":"C","text":"73rd Amendment Act, 1992"},{"id":"D","text":"86th Amendment Act, 2002"}]'::jsonb, '42nd Amendment Act, 1976', '44th Amendment Act, 1978', '73rd Amendment Act, 1992', '86th Amendment Act, 2002', 'C', 'The 73rd Amendment Act, 1992, added Part IX and the 11th Schedule (containing 29 functional items) to constitutionally empower rural local self-governments.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q086', 'apsc-phed-ae-gs-2025', 86, 'VII. Indian Polity, Political System in India', 'Union Parliament: Lok Sabha, Rajya Sabha', NULL, 'How many members are directly elected to the Lok Sabha from the state of Assam?', '[{"id":"A","text":"7"},{"id":"B","text":"12"},{"id":"C","text":"14"},{"id":"D","text":"16"}]'::jsonb, '7', '12', '14', '16', 'C', 'Assam is represented by 14 Members in the Lok Sabha (Lower House of Parliament) and 7 Members in the Rajya Sabha (Council of States).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q087', 'apsc-phed-ae-gs-2025', 87, 'VII. Indian Polity, Political System in India', 'State Government: Governor, Chief Minister, Legislative Assembly', NULL, 'What is the total strength of elected members in the Assam Legislative Assembly (Assam Bidhan Sabha)?', '[{"id":"A","text":"126"},{"id":"B","text":"114"},{"id":"C","text":"140"},{"id":"D","text":"100"}]'::jsonb, '126', '114', '140', '100', 'A', 'The Assam Legislative Assembly is unicameral and consists of 126 Members of Legislative Assembly (MLAs) directly elected from single-member constituencies.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q088', 'apsc-phed-ae-gs-2025', 88, 'VII. Indian Polity, Political System in India', 'Union Executive: President, Prime Minister', NULL, 'Under Article 356 of the Indian Constitution, the President can impose President’s Rule in a State on receipt of a report from:', '[{"id":"A","text":"The Governor of the State or otherwise upon breakdown of constitutional machinery"},{"id":"B","text":"The Chief Justice of High Court"},{"id":"C","text":"The Speaker of Legislative Assembly"},{"id":"D","text":"The Chief Election Commissioner"}]'::jsonb, 'The Governor of the State or otherwise upon breakdown of constitutional machinery', 'The Chief Justice of High Court', 'The Speaker of Legislative Assembly', 'The Chief Election Commissioner', 'A', 'Article 356 allows President’s Rule when the President is satisfied on receiving a report from the Governor (or otherwise) that governance cannot be carried on in accordance with the Constitution.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q089', 'apsc-phed-ae-gs-2025', 89, 'VII. Indian Polity, Political System in India', 'Election Commission of India and constitutional bodies', NULL, 'The Comptroller and Auditor General of India (CAG) is appointed by the President under which Article of the Constitution?', '[{"id":"A","text":"Article 76"},{"id":"B","text":"Article 148"},{"id":"C","text":"Article 280"},{"id":"D","text":"Article 324"}]'::jsonb, 'Article 76', 'Article 148', 'Article 280', 'Article 324', 'B', 'Article 148 provides for the Comptroller and Auditor General of India as the guardian of the public purse. (Article 76 is Attorney General, Article 280 is Finance Commission, Article 324 is Election Commission).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q090', 'apsc-phed-ae-gs-2025', 90, 'VII. Indian Polity, Political System in India', 'Fundamental Rights (Part III)', NULL, 'Right to Education (RTE) was made a Fundamental Right for children between ages 6 and 14 under Article 21A by the:', '[{"id":"A","text":"44th Amendment Act, 1978"},{"id":"B","text":"74th Amendment Act, 1992"},{"id":"C","text":"86th Amendment Act, 2002"},{"id":"D","text":"91st Amendment Act, 2003"}]'::jsonb, '44th Amendment Act, 1978', '74th Amendment Act, 1992', '86th Amendment Act, 2002', '91st Amendment Act, 2003', 'C', 'The 86th Constitutional Amendment Act, 2002, inserted Article 21A, declaring free and compulsory education for all children aged 6 to 14 as a Fundamental Right.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VII (Polity)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q091', 'apsc-phed-ae-gs-2025', 91, 'VIII. Indian Culture', 'Classical dance forms of India and Assam', NULL, 'Sattriya, recognized by Sangeet Natak Akademi as one of India’s eight classical dance traditions, originated in the 15th century CE through the reformative movement of:', '[{"id":"A","text":"Mahapurush Srimanta Sankardev"},{"id":"B","text":"Chaitanya Mahaprabhu"},{"id":"C","text":"Kabir"},{"id":"D","text":"Ramanuja"}]'::jsonb, 'Mahapurush Srimanta Sankardev', 'Chaitanya Mahaprabhu', 'Kabir', 'Ramanuja', 'A', 'Sattriya dance was created by Mahapurush Srimanta Sankardev in the 15th century as an accompaniment to the Ankiya Naat (Assamese one-act plays) performed in Satras (monasteries).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q092', 'apsc-phed-ae-gs-2025', 92, 'VIII. Indian Culture', 'Traditional crafts, textiles (Muga, Eri, Pat silk)', NULL, 'Which golden silk, possessing an exclusive Geographical Indication (GI) tag, is unique to Assam and produced by the silkworm Antheraea assamensis feeding on Som and Sualu leaves?', '[{"id":"A","text":"Muga Silk"},{"id":"B","text":"Eri Silk (Ahimsa Silk)"},{"id":"C","text":"Pat Silk"},{"id":"D","text":"Tussar Silk"}]'::jsonb, 'Muga Silk', 'Eri Silk (Ahimsa Silk)', 'Pat Silk', 'Tussar Silk', 'A', 'Muga is the luminous golden silk endemic to Assam, spun by the wild caterpillar Antheraea assamensis. It is famed for its extreme durability and golden sheen that intensifies with washing.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q093', 'apsc-phed-ae-gs-2025', 93, 'VIII. Indian Culture', 'Indian architecture: temple styles (Nagara, Dravida, Vesara)', NULL, 'The Nilachal architectural style, characterized by a bulbous octagonal dome atop a cruciform base, is exemplified by which sacred shrine?', '[{"id":"A","text":"Kamakhya Temple in Guwahati"},{"id":"B","text":"Sun Temple at Konark"},{"id":"C","text":"Brihadisvara Temple in Thanjavur"},{"id":"D","text":"Khajuraho Temples"}]'::jsonb, 'Kamakhya Temple in Guwahati', 'Sun Temple at Konark', 'Brihadisvara Temple in Thanjavur', 'Khajuraho Temples', 'A', 'The reconstructed Kamakhya Temple atop Nilachal Hill features a unique hybrid architectural style known as the Nilachal type (a combination of Nagara curvilinear spire and Bengal hemispherical dome).', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q094', 'apsc-phed-ae-gs-2025', 94, 'VIII. Indian Culture', 'Folk culture and festivals of Assam', NULL, 'Ali-Aye-Ligang, a spring festival celebrating the commencement of seed sowing (especially paddy), is the traditional harvest festival of which indigenous community of Assam?', '[{"id":"A","text":"Mishing community"},{"id":"B","text":"Bodo community"},{"id":"C","text":"Karbi community"},{"id":"D","text":"Dimasa community"}]'::jsonb, 'Mishing community', 'Bodo community', 'Karbi community', 'Dimasa community', 'A', 'Ali-Aye-Ligang is celebrated by the Mishing tribe on the first Wednesday of the Assamese month of Phagun (February). "Ali" means root/seed, "Aye" means fruit, and "Ligang" means sowing.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q095', 'apsc-phed-ae-gs-2025', 95, 'VIII. Indian Culture', 'Neo-Vaishnavite movement in Assam: Mahapurush Srimanta Sankardev', NULL, 'The "Kirtan Ghosa", a masterpiece compilation of devotional verses praising Lord Krishna, was authored by:', '[{"id":"A","text":"Srimanta Sankardev"},{"id":"B","text":"Madhavdev"},{"id":"C","text":"Bhattadeva"},{"id":"D","text":"Ananta Kandali"}]'::jsonb, 'Srimanta Sankardev', 'Madhavdev', 'Bhattadeva', 'Ananta Kandali', 'A', 'Kirtan Ghosa is the poetic magnum opus composed by Srimanta Sankardev for community congregational prayer and singing (Naam-Kirtan) in Namghars.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q096', 'apsc-phed-ae-gs-2025', 96, 'VIII. Indian Culture', 'Classical dance forms of India', NULL, 'Kathakali, characterized by elaborate facial make-up (Chutti), stylized costumes, and mudras conveying drama from Hindu epics, belongs to which Indian state?', '[{"id":"A","text":"Kerala"},{"id":"B","text":"Tamil Nadu"},{"id":"C","text":"Andhra Pradesh"},{"id":"D","text":"Karnataka"}]'::jsonb, 'Kerala', 'Tamil Nadu', 'Andhra Pradesh', 'Karnataka', 'A', 'Kathakali is the traditional classical dance-drama of Kerala, blending dance, music, and acting with elaborate facial painting denoting different character archetypes.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Indian Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q097', 'apsc-phed-ae-gs-2025', 97, 'VIII. Indian Culture', 'Folk culture and festivals of Assam: Ambubachi Mela', NULL, 'The annual Ambubachi Mela, symbolizing the fertility cycle of Mother Earth, is celebrated during the monsoon month of Ahar (June) at which shrine in Assam?', '[{"id":"A","text":"Kamakhya Temple, Guwahati"},{"id":"B","text":"Umananda Temple, Peacock Island"},{"id":"C","text":"Navagraha Temple, Chitrachal Hill"},{"id":"D","text":"Hayagriva Madhava Temple, Hajo"}]'::jsonb, 'Kamakhya Temple, Guwahati', 'Umananda Temple, Peacock Island', 'Navagraha Temple, Chitrachal Hill', 'Hayagriva Madhava Temple, Hajo', 'A', 'The Ambubachi Mela is an ancient annual Hindu fair held at the historic Kamakhya Temple in Guwahati during the monsoon season.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q098', 'apsc-phed-ae-gs-2025', 98, 'VIII. Indian Culture', 'Traditional crafts, bell-metal of Sarthebari', NULL, 'The traditional hand-made bell metal (Kanh) industry in Assam, known for producing iconic artifacts like the Xorai and Banbati, is centered at:', '[{"id":"A","text":"Sarthebari (Barpeta district)"},{"id":"B","text":"Sualkuchi (Kamrup district)"},{"id":"C","text":"Hajo (Kamrup district)"},{"id":"D","text":"Asharikandi (Dhubri district)"}]'::jsonb, 'Sarthebari (Barpeta district)', 'Sualkuchi (Kamrup district)', 'Hajo (Kamrup district)', 'Asharikandi (Dhubri district)', 'A', 'Sarthebari in Barpeta district is the historic hub of Assam’s bell-metal craft (having an official GI tag), famous for forging traditional Xorai, Thal, and Bati vessels.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Culture)', 'EASY', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q099', 'apsc-phed-ae-gs-2025', 99, 'VIII. Indian Culture', 'Indian classical music: Hindustani and Carnatic traditions', NULL, 'The Trinity of Carnatic music refers to three celebrated composer-saints who lived in Thanjavur in the 18th-19th centuries: Tyagaraja, Muthuswami Dikshitar, and:', '[{"id":"A","text":"Syama Sastri"},{"id":"B","text":"Purandara Dasa"},{"id":"C","text":"Swathi Thirunal"},{"id":"D","text":"Annamacharya"}]'::jsonb, 'Syama Sastri', 'Purandara Dasa', 'Swathi Thirunal', 'Annamacharya', 'A', 'The Trinity of Carnatic music (Sangeetha Mummoorthigal) refers to Tyagaraja, Muthuswami Dikshitar, and Syama Sastri, whose compositions established the modern Carnatic concert repertoire.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Indian Culture)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();
INSERT INTO public.questions (id, exam_id, question_number, subject, topic, subtopic, stem, options, option_a, option_b, option_c, option_d, correct_option, explanation, formula_context, solution_steps, reference_source, difficulty, question_type, source_type, pyq_year, pyq_exam) VALUES ('apsc-phed-gs-2025-q100', 'apsc-phed-ae-gs-2025', 100, 'VIII. Indian Culture', 'Traditional crafts and literary milestones of Assam', NULL, 'The "Katha Guru Charita", one of the most celebrated biographical hagiographies written in early Assamese prose, depicts the lives and teachings of:', '[{"id":"A","text":"Srimanta Sankardev, Madhavdev and other Vaishnava Gurus"},{"id":"B","text":"Ahom kings and generals"},{"id":"C","text":"Koch kings"},{"id":"D","text":"British commissioners of Assam"}]'::jsonb, 'Srimanta Sankardev, Madhavdev and other Vaishnava Gurus', 'Ahom kings and generals', 'Koch kings', 'British commissioners of Assam', 'A', 'The Katha Guru Charita, compiled by Ramcharan Thakur and other disciples, is a classic prose chronicle recording the lives, travels, dialogues, and philosophy of Srimanta Sankardev and Madhavdev.', NULL, NULL, 'APSC Advt 31/2025 GS Syllabus · Unit VIII (Assam Culture)', 'MEDIUM', 'CONCEPTUAL', 'OFFICIAL_EXAM', NULL, NULL) ON CONFLICT (id) DO UPDATE SET stem = EXCLUDED.stem, options = EXCLUDED.options, option_a = EXCLUDED.option_a, option_b = EXCLUDED.option_b, option_c = EXCLUDED.option_c, option_d = EXCLUDED.option_d, correct_option = EXCLUDED.correct_option, explanation = EXCLUDED.explanation, formula_context = EXCLUDED.formula_context, updated_at = NOW();